                  <Box>
                    <Typography variant="h6" sx={{ mb: 3, fontWeight: 700 }}>
                      جميع المرفقات ({getTotalFiles(selectedAchievement)})
                    </Typography>

                    {getTotalFiles(selectedAchievement) > 0 ? (
                      <Grid container spacing={2}>
                        {selectedAchievement.items?.map((item) =>
