                  <Typography>تاريخ: {f.createdAt?.split('T')[0]}</Typography>
                  <Typography>ملاحظة: {f.note || 'بدون ملاحظات'}</Typography>
                </Box>
              ))
            )}
          </DialogContent>
        </Dialog>
      </Box>
    </Box></NavigationShell>
  );
}

