              sx={{
                width: 38,
                height: 38,
                bgcolor: "rgba(128,180,158,0.18)",
                color: "#d8fff0",
                border: "1px solid rgba(128,180,158,0.35)",
              }}
            >
              {icon}
            </Avatar>

            <Box>
              <Typography sx={{ color: MUTED, fontWeight: 800, fontSize: "0.9rem" }}>{title}</Typography>

              {isMoney ? (
                <AnimatedMoney value={value} />
