                <Typography sx={{ color: "white", fontWeight: 950, fontSize: "1.35rem", mt: 0.3 }}>
                  {Number(value || 0)}
                </Typography>
              )}
            </Box>
          </Stack>

          <Box sx={{ color: accent }}>
            <Sparkline data={spark} />
          </Box>
        </Stack>

        <Box
