    </Card>
  );

  const billsCount = bills?.length || 0;

  // ✅ Counts inside the selected period
const incomeBillsCount = useMemo(() => {
  return (bills || []).reduce((c, b) => c + (billFlow(b).isRefund ? 0 : 1), 0);
}, [bills]);

const refundBillsCount = useMemo(() => {
