                        border: `1px solid ${colorPalette.primaryLighter}`,
                        borderRadius: 2,
                        backgroundColor: 'white',
                        position: 'relative'
                      }}
                    >
                      {/* Status badge */}
                      <Box sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        backgroundColor: statusColor,
                        color: 'white',
                        px: 2,
                        py: 0.5,
                        borderRadius: '0 0 4px 0',
                        fontSize: '0.8rem',
                        fontWeight: 'bold',
                      }}>
                        {statusText}
                      </Box>

                      <Box sx={{ mt: 3 }}>
                        <Typography variant="subtitle1" fontWeight="bold" sx={{ color: colorPalette.textDark }}>
