import * as uiLayout from '../common/uiLayout';
import React from 'react';
import { 
  TextField, 
  Box, 
  CircularProgress, 
  Typography, 
  Avatar,
  Card,
  Fade
} from '@mui/material';
import { Assignment, PersonSearch } from '@mui/icons-material';
import GradientButton from '../common/GradientButton';

const StudentSearchForm = ({ 
  studentId, 
  setStudentId, 
  loading, 
  handleAttendance 
}) => {
  return (
    <Fade in={true} timeout={800}>
      <Card
        sx={{
          p: 4,
          borderRadius: 3,
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
          background: 'linear-gradient(135deg, #ffffff 0%, #f8fbfa 100%)',
          border: '1px solid rgba(128, 180, 158, 0.2)',
          position: 'relative',
          overflow: 'hidden',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            right: 0,
            width: '100%',
            height: '4px',
            background: 'linear-gradient(90deg, #80b49e 0%, #9bc8b8 100%)',
          }
        }}
      >
        <Box sx={{ textAlign: "center", mb: 4 }}>
          <Avatar
            sx={{
              width: 90,
              height: 90,
              margin: '0 auto 20px',
              background: 'linear-gradient(135deg, #80b49e 0%, #9bc8b8 100%)',
              boxShadow: '0 6px 20px rgba(128, 180, 158, 0.3)',
              transition: 'transform 0.3s ease',
              '&:hover': {
                transform: 'scale(1.05)'
              }
            }}
          >
            <PersonSearch sx={{ fontSize: 44 }} />
          </Avatar>
          
          <Typography 
            variant="h4"
            sx={{ 
              fontWeight: 800,
              color: "#2c3e50",
              position: "relative",
              mb: 3,
              "&:after": {
                content: '""',
                display: "block",
                width: "100px",
                height: "5px",
                background: "linear-gradient(90deg, #80b49e, #9bc8b8)",
                margin: "20px auto 0",
                borderRadius: "10px",
                opacity: 0.8
              }
            }}
          >
            تسجيل الحضور
          </Typography>
          
          <Typography 
            variant="body1" 
            sx={{ 
              color: "#5d6d7e",
              fontSize: "1.1rem",
              lineHeight: 1.6,
              mb: 1
            }}
          >
            أدخل رقم الهوية الوطنية للطالب للبحث عن بياناته
          </Typography>
          <Typography 
            variant="body2" 
            sx={{ 
              color: "#80b49e",
              fontSize: "0.9rem",
              fontWeight: 600
            }}
          >
            يجب أن يكون الرقم مكون من 10 أرقام
          </Typography>
        </Box>

        <Box sx={{ position: 'relative', mb: 4 }}>
          <TextField
            label="رقم الهوية الوطنية"
            variant="outlined"
            fullWidth
            inputProps={{ dir: "ltr" }}
            value={studentId}
            placeholder="أدخل 10 أرقام فقط"
            onChange={(e) => {
              const value = e.target.value;
              const isValid = /^[1-9][0-9]{0,9}$/.test(value) && value.length <= 10;
              if (isValid || value === "") {
                setStudentId(value);
              }
            }}
            sx={uiLayout.withUiSx({
              "& .MuiOutlinedInput-root": {
                borderRadius: 2,
                "& fieldset": {
                  borderColor: "#e0e0e0",
                  borderWidth: 2,
                },
                "&:hover fieldset": {
                  borderColor: "#80b49e",
                },
                "&.Mui-focused fieldset": {
                  borderColor: "#80b49e",
                  borderWidth: 2,
                },
                "& input": {
                  textAlign: "center",
                  fontWeight: 600,
                  letterSpacing: "1px"
                }
              },
              "& .MuiInputLabel-root": {
                "&.Mui-focused": {
                  color: "#80b49e",
                }
              }
            }, uiLayout.formFieldSx)}
            InputProps={{
              style: {
                fontSize: "1.2rem",
                fontFamily: '"Cairo", sans-serif',
                height: '60px'
              },
              startAdornment: (
                <Box 
                  sx={{ 
                    color: '#80b49e',
                    marginInlineEnd: 2,
                    display: 'flex',
                    alignItems: 'center'
                  }}
                >
                  <Assignment />
                </Box>
              )
            }}
            InputLabelProps={{
              style: {fontFamily: '"Cairo", sans-serif'},
              shrink: true
            }}
          />
          
          {studentId && (
            <Typography 
              variant="caption" 
              sx={{
                position: 'absolute',
                insetInlineStart: 0,
                bottom: -25,
                color: studentId.length === 10 ? '#80b49e' : '#e74c3c',
                fontWeight: 600,
                fontSize: '0.8rem'
              }}
            >
              {studentId.length}/10 أرقام
            </Typography>
          )}
        </Box>

        <GradientButton
          fullWidth
          onClick={handleAttendance}
          disabled={loading || studentId.length !== 10}
          sx={{
            height: '56px',
            borderRadius: 2,
            fontSize: '1.1rem',
            fontWeight: 700,
            boxShadow: '0 4px 15px rgba(128, 180, 158, 0.3)',
            transition: 'all 0.3s ease',
            '&:hover': {
              transform: 'translateY(-2px)',
              boxShadow: '0 6px 20px rgba(128, 180, 158, 0.4)',
            },
            '&:disabled': {
              background: '#e0e0e0',
              color: '#9e9e9e'
            }
          }}
        >
          {loading ? (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <CircularProgress size={24} color="inherit" />
              <span>جاري البحث...</span>
            </Box>
          ) : (
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
              <PersonSearch />
              <span>عرض بيانات الطالب</span>
            </Box>
          )}
        </GradientButton>

        {studentId.length > 0 && studentId.length < 10 && (
          <Typography 
            variant="caption" 
            sx={{
              display: 'block',
              textAlign: 'center',
              mt: 2,
              color: '#e74c3c',
              fontWeight: 600,
              fontSize: '0.8rem'
            }}
          >
            ⚠️ رقم الهوية يجب أن يكون 10 أرقام
          </Typography>
        )}
      </Card>
    </Fade>
  );
};

export default StudentSearchForm;

src\\components\\BranchesDashboard.js:
import * as uiLayout from './common/uiLayout';
import React, { useEffect, useRef, useState } from "react";
import {
  Box, Typography, Card, Button, CircularProgress
} from "@mui/material";
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import DateRangeIcon from '@mui/icons-material/DateRange';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import PrintIcon from '@mui/icons-material/Print';
import LocationOnIcon from '@mui/icons-material/LocationOn'; // الأيقونة الجديدة
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { DataGrid } from "@mui/x-data-grid";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import dayjs from "dayjs";
import { useNavigate } from "react-router-dom";
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

const COLORS = [
  "#1976d2", "#fbc02d", "#00bfae", "#ef5350", "#8e24aa", "#43a047",
  "#ff9800", "#c62828", "#0088FE", "#00C49F", "#FFBB28", "#FF8042",
  "#5C6BC0", "#00897B", "#D84315", "#7E57C2", "#3949AB", "#00838F", "#F4511E"
];

const BranchesDashboardReport = () => {
  const [fromDate, setFromDate] = useState(dayjs().startOf('month'));
  const [toDate, setToDate] = useState(dayjs());
  const [branches, setBranches] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const reportRef = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    setLoading(true);
    setBranches([]);
    const from = fromDate.format("YYYY-MM-DD");
    const to = toDate.format("YYYY-MM-DD");
    fetch(
      `https://api3.sstli.com/api/Trainer/BranchBocketMoney?fromDate=${from}&toDate=${to}`
    )
      .then(res => res.json())
      .then(result => {
        if (Array.isArray(result)) {
          setBranches(result.map((row, idx) => ({
            ...row,
            id: idx + 1,
            comm_Case1: Number(row.daen_Case1 || 0) * 0.005,
            comm_Case2: Number(row.daen_Case2 || 0) * 0.005,
          })));
        } else {
          setBranches([]);
        }
        setLoading(false);
      })
      .catch(() => {
        setBranches([]);
        setLoading(false);
      });
  }, [fromDate, toDate]);

  // رسم الألوان حسب الفرع
  const colorMap = {};
  branches.forEach((b, i) => {
    colorMap[b.brEName] = COLORS[i % COLORS.length];
  });

  // إجمالي التحصيل من كل الفروع (مجموع المدين للحالتين)
  const totalAllDaen = branches.reduce(
    (acc, row) => acc + (Number(row.daen_Case1) || 0) + (Number(row.daen_Case2) || 0),
    0
  );

  const columns = [
    {
      field: "brEName",
      headerName: "اسم الفرع",
      flex: 2.2,
      minWidth: 280,
      renderCell: (params) => (
        <Box display="flex" alignItems="center" gap={1}>
          <LocationOnIcon sx={{ color: colorMap[params.value] || "#1976d2", fontSize: 28 }} />
          <Typography fontWeight={700}>{params.value}</Typography>
        </Box>
      )
      // لا تضيف align هنا (سيبه left أو default)
    },
    {
      field: "students_Case1",
      headerName: "عدد المستمرين",
      flex: 1,
      minWidth: 120,
      align: "center",
      headerAlign: "center",
    },
    {
      field: "daen_Case1",
      headerName: "تحصيل المستمرين",
      flex: 1.3,
      minWidth: 150,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (params.value ? Number(params.value).toLocaleString("ar-EG") + " ريال" : "—"),
    },
    // {
    //   field: "comm_Case1",
    //   headerName: "عمولة المستمرين",
    //   flex: 1.1,
    //   minWidth: 120,
    //   align: "center",
    //   headerAlign: "center",
    //   renderCell: (params) => (params.value ? Number(params.value).toLocaleString("ar-EG") + " ريال" : "—"),
    // },
    {
      field: "students_Case2",
      headerName: "عدد الخريجين",
      flex: 1,
      minWidth: 120,
      align: "center",
      headerAlign: "center",
    },
    {
      field: "daen_Case2",
      headerName: "تحصيل الخريجين",
      flex: 1.3,
      minWidth: 150,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (params.value ? Number(params.value).toLocaleString("ar-EG") + " ريال" : "—"),
    },
    // {
    //   field: "comm_Case2",
    //   headerName: "عمولة الخريجين",
    //   flex: 1.1,
    //   minWidth: 120,
    //   align: "center",
    //   headerAlign: "center",
    //   renderCell: (params) => (params.value ? Number(params.value).toLocaleString("ar-EG") + " ريال" : "—"),
    // },
    {
      field: "percentage",
      headerName: "نسبة تحصيل الفرع من الإجمالي",
      flex: 1.2,
      minWidth: 155,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => {
        const row = params.row || params;
        const branchTotal = Number(row.daen_Case1 || 0) + Number(row.daen_Case2 || 0);
        if (!totalAllDaen || totalAllDaen === 0) return "0%";
        const percent = (branchTotal / totalAllDaen) * 100;
        return percent.toFixed(2) + "%";
      }
    }
  ];
  

  // جرافيك الأعمدة: إجمالي تحصيل كل فرع (مستمرين + خريجين)
  const chartData = branches.map(b => ({
    name: b.brEName,
    total: (Number(b.daen_Case1) || 0) + (Number(b.daen_Case2) || 0)
  }));

  // PDF
  const handleDownloadPdf = async () => {
    setIsGenerating(true);
    try {
      const element = reportRef.current;
      const canvas = await html2canvas(element, {
        scale: 2,
        scrollY: -window.scrollY,
        useCORS: true,
        allowTaint: true,
        logging: true,
        windowWidth: element.scrollWidth,
        windowHeight: element.scrollHeight
      });

      const imgData = canvas.toDataURL('image/png', 1.0);
      const pdf = new jsPDF('p', 'mm', 'a4');

      pdf.setProperties({
        title: 'تقرير تحصيلات الفروع',
        subject: 'إحصائيات الفروع',
        author: 'نظام الإدارة',
        keywords: 'تقرير, فروع, تحصيلات',
        creator: 'شركتك'
      });

      const imgWidth = pdf.internal.pageSize.getWidth();
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      let heightLeft = imgHeight;
      let position = 0;
      const pageHeight = pdf.internal.pageSize.getHeight() - 20;

      while (heightLeft >= 0) {
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
        position -= pageHeight;

        if (heightLeft > 0) {
          pdf.addPage();
        }
      }

      pdf.save('تقرير-الفروع.pdf');
    } catch (error) {
      console.error('Error generating PDF:', error);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDayjs}>
      <Box sx={{
        minHeight: "100vh",
        background: "#f7f9fa",
        py: 4,
        px: { xs: 2, sm: 4, md: 8 }, // وسع العرض هنا
        width: "100%",
        position: "relative"
      }}>
        {/* Report Content */}
        <Box ref={reportRef} sx={{
          background: "#fff",
          borderRadius: 3,
          p: 3.5,
          boxShadow: 4,
          mb: 4,
          overflow: "auto",
          width: "100%",
          minWidth: "1300px",  // توسعة زيادة للجدول والرسومات
          maxWidth: "99vw",
          height: "auto",
          "@media print": {
            boxShadow: "none",
            borderRadius: 0
          }
        }}>
          {/* Header */}
          <Card elevation={0} sx={{
            mb: 3, mx: "auto", px: 4, py: 2.5,
            borderRadius: 3, boxShadow: 0, display: "flex",
            alignItems: "center", gap: 4, justifyContent: "space-between",
            flexWrap: "wrap", background: "#fff",
            minWidth: 1100
          }}>
            <Box flex={2} sx={{ minWidth: 220 }}>
              <Typography fontWeight="bold" color="primary.main" fontSize={30} mb={0.2}>
                <AttachMoneyIcon sx={{ fontSize: 35, mb: -0.7, color: "#1976d2" }} /> تقرير تحصيلات جميع الفروع
              </Typography>
              <Typography fontSize={19} color="text.secondary" mt={1.5}>
                اجمالي تحصيل الفروع:&nbsp;
                <span style={{ color: "#1976d2", fontWeight: 700 }}>
                  {totalAllDaen?.toLocaleString("ar-EG", { maximumFractionDigits: 2 })} ريال
                </span>
              </Typography>
            </Box>
            <Box sx={uiLayout.formGridSx} flex={1.4} display="flex" alignItems="center" gap={2} justifyContent="center" flexWrap="wrap">
              <DatePicker
                label="من تاريخ"
                value={fromDate}
                onChange={setFromDate}
                slotProps={{
                  textField: { variant: "outlined", size: "small", sx: { minWidth: 120, bgcolor: "#fff" } },
                }}
              />
              <DatePicker
                label="إلى تاريخ"
                value={toDate}
                onChange={setToDate}
                slotProps={{
                  textField: { variant: "outlined", size: "small", sx: { minWidth: 120, bgcolor: "#fff" } },
                }}
              />
            </Box>
          </Card>

          {/* Legend */}
          <Box
            display="flex"
            flexWrap="wrap"
            gap={2}
            justifyContent="center"
            alignItems="center"
            mb={2}
          >
            {branches.map((b, i) => (
              <Box key={b.brEName} display="flex" alignItems="center" gap={1}>
                <LocationOnIcon sx={{ color: colorMap[b.brEName] }} />
                <Typography fontSize={16}>{b.brEName}</Typography>
              </Box>
            ))}
          </Box>

          {/* Chart */}
          <Box
            sx={{
              width: "99%",
              minWidth: "1200px",
              maxWidth: "2000px",
              mx: "auto",
              mt: 2,
              mb: 5,
              background: "#fff",
              borderRadius: 4,
              boxShadow: 1,
              p: 2.5,
            }}
          >
            <Typography align="center" fontWeight="bold" mb={2} fontSize={22} color="primary">
              ترتيب ومساهمة الفروع حسب التحصيل (ريال)
            </Typography>
            <ResponsiveContainer width="100%" height={430}>
              <BarChart
                data={[...chartData].sort((a, b) => b.total - a.total)}
                margin={{ top: 30, right: 30, left: 30, bottom: 80 }}
                barSize={37}
              >
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis
                  dataKey="name"
                  type="category"
                  interval={0}
                  tick={({ x, y, payload }) => {
                    const words = payload.value.split(" ");
                    return (
                      <g transform={`translate(${x},${y + 10})`}>
                        {words.map((word, idx) => (
                          <text
                            key={idx}
                            x={0}
                            y={idx * 15}
                            textAnchor="middle"
                            fontSize={14}
                            fontWeight={700}
                            fill="#222"
                            style={{ pointerEvents: "none" }}
                          >
                            {word}
                          </text>
                        ))}
                      </g>
                    );
                  }}
                  height={85}
                />
                <YAxis
                  type="number"
                  tickFormatter={v => v.toLocaleString("ar-EG")}
                  style={{ fontSize: 16 }}
                />
                <Tooltip
                  formatter={v => `${Number(v).toLocaleString("ar-EG")} ريال`}
                  labelFormatter={label => `فرع: ${label}`}
                />
                <Bar
                  dataKey="total"
                  isAnimationActive={false}
                  radius={[8, 8, 0, 0]}
                  fill="#1976d2"
                  label={false}
                >
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={colorMap[entry.name]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </Box>

          {/* Table */}
          <Box
            sx={uiLayout.withUiSx({
              mt: 5, width: "100%", minWidth: 1300, maxWidth: 1800, mx: "auto",
              bgcolor: "#fff", borderRadius: 4, boxShadow: 1, p: 2.5,
            }, uiLayout.tableContainerSx)}
          >
            <Typography
              variant="h6"
              align="center"
              mb={2}
              fontWeight="bold"
              color="primary"
            >
              جدول تحصيلات جميع الفروع
            </Typography>
            <DataGrid
              rows={branches}
              columns={columns}
              autoHeight
              disableRowSelectionOnClick
              loading={loading}
              sx={uiLayout.withUiSx({
                fontFamily: "inherit",
                background: "#fff",
                "& .MuiDataGrid-columnHeaderTitle": { fontWeight: "bold" },
                "& .MuiDataGrid-cell": { fontSize: 17 },
                direction: "rtl",
                minWidth: 1300
              }, uiLayout.dataGridSx)}
              localeText={{
                noRowsLabel: "لا توجد بيانات",
              }}
            />
          </Box>
        </Box>

        {/* Actions Footer - لن يظهر في التقرير المطبوع */}
        <Box sx={uiLayout.withUiSx({
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mt: 2,
          maxWidth: 1700,
          mx: "auto",
          "@media print": {
            display: "none !important"
          }
        }, uiLayout.actionBarSx)}>
          <Button
            variant="contained"
            onClick={() => navigate("/dashboard")}
            startIcon={<ArrowBackIcon />}
            sx={uiLayout.withUiSx({
              fontWeight: "bold",
              backgroundColor: "#1976d2",
              "&:hover": { backgroundColor: "#1565c0" }
            }, uiLayout.buttonSx)}
          >
            رجوع
          </Button>

          <Button
            onClick={handleDownloadPdf}
            color="primary"
            variant="contained"
            disabled={isGenerating}
            sx={uiLayout.withUiSx({
              fontWeight: "bold",
              gap: 1,
              px: 3,
              backgroundColor: "#4caf50",
              "&:hover": { backgroundColor: "#388e3c" },
              "&:disabled": { backgroundColor: "#81c784" }
            }, uiLayout.buttonSx)}
            startIcon={isGenerating ? <CircularProgress size={20} color="inherit" /> : <PrintIcon />}
          >
            {isGenerating ? 'جاري التصدير...' : 'طباعة التقرير PDF'}
          </Button>
        </Box>
      </Box>
    </LocalizationProvider>
  );
};

