              sx={{
                py: isPhone
                  ? 2
                  : isTablet
                    ? 3
                    : 5,

                textAlign: "center"
              }}
            >
              <CircularProgress
                size={
                  isPhone
                    ? 22
                    : isTablet
                      ? 28
                      : 40
                }
              />
            </Box>
          ) : statuses.length === 0 ? (
            <Typography
              sx={{
                py: isPhone
                  ? 2
                  : isTablet
                    ? 3
                    : 4,

                textAlign: "center",
                color: "#777",
                fontWeight: 800,

                fontSize: isPhone
                  ? "0.75rem"
                  : isTablet
                    ? "0.75rem"
                    : undefined
              }}
