          ) : (
            <List
              disablePadding
              sx={{
                p: isCompact
                  ? 0.2
                  : 0
              }}
            >
              {statuses.map((status) => (
                <ListItemButton
                  key={status.guid}
                  selected={
                    selectedGuid === status.guid
                  }
                  onClick={() =>
                    setSelectedGuid(status.guid)
                  }
                  sx={{
                    minHeight: isPhone
                      ? 32
                      : isTablet
                        ? 36
                        : 48,

                    py: isPhone
                      ? 0.3
                      : isTablet
                        ? 0.4
                        : 0.75,

                    px: isPhone
                      ? 0.65
                      : isTablet
                        ? 0.85
                        : 1.5,

                    mb: isCompact
                      ? 0.15
                      : 0,

                    borderRadius: isCompact
                      ? 1
                      : 0,

                    borderBottom:
                      "1px solid #edf1ef",

                    "&.Mui-selected": {
                      backgroundColor:
                        "#e6f3ee"
                    },

                    "&.Mui-selected:hover": {
                      backgroundColor:
                        "#d9eee5"
                    }
                  }}
                >
                  <ListItemText
                    primary={status.name}
                    secondary={`الكود: ${status.code}`}
                    primaryTypographyProps={{
                      fontWeight: 950,
                      textAlign: "right",

                      fontSize: isPhone
                        ? "0.5rem"
                        : isTablet
                          ? "0.58rem"
                          : undefined,

                      lineHeight: 1.15
                    }}
                    secondaryTypographyProps={{
                      textAlign: "right",

                      fontSize: isPhone
                        ? "0.4rem"
                        : isTablet
                          ? "0.47rem"
                          : undefined,

                      lineHeight: 1.1
                    }}
                  />
                </ListItemButton>
              ))}
            </List>
          )}
        </Paper>

        <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
          fullWidth
          multiline
          minRows={
            isPhone
              ? 2
              : isTablet
                ? 2
                : 3
          }
          label="سبب التغيير / ملاحظة"
          value={reason}
          onChange={(event) =>
            setReason(event.target.value)
          }
          inputProps={{
            maxLength: 1000
          }}
          helperText={`${reason.length}/1000`}
        />

        {selectedStatus ? (
          <Alert
            severity="info"
            sx={{
              mt: isCompact
                ? 0.4
                : 2,

