                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  variant="outlined"
                  value={complaint}
                  onChange={(e) => handleComplaintChange(index, e.target.value)}
                  placeholder="أدخل الشكوى"
                  size="small"
                />
                <Box style={{display:"flex"}} marginLeft={2}>
                  {index === localData.complaints.length - 1 && (
                    <IconButton 
                      onClick={addComplaint} 
                      color="primary"
                      size="small"
                      sx={{ 
                        marginRight: 1,
                        backgroundColor: alpha(theme.palette.primary.main, 0.1),
                        '&:hover': { 
                          backgroundColor: alpha(theme.palette.primary.main, 0.2) 
                        }
                      }}
                    >
                      <AddCircleOutline fontSize="small" />
                    </IconButton>
                  )}
                  <IconButton 
                    onClick={() => removeComplaint(index)} 
                    color="error"
                    size="small"
                    sx={{ 
                      backgroundColor: alpha(theme.palette.error.main, 0.1),
                      '&:hover': { 
                        backgroundColor: alpha(theme.palette.error.main, 0.2) 
                      }
                    }}
                  >
                    <RemoveCircleOutline fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
            </ListItem>
          ))}
        </List>
      </Box>

      {/* Suggestions Section */}
      <Box>
        <Typography variant="h6" gutterBottom fontWeight="bold" color="primary" sx={{ mb: 3 }}>
          المقترحات
        </Typography>
        
        <List sx={{ padding: 0 }}>
          {localData.suggestions.map((suggestion, index) => (
            <ListItem 
              key={`suggestion-${index}`} 
              sx={{ 
                padding: 0,
                marginBottom: 2,
                alignItems: 'flex-start'
              }}
            >
              <Box display="flex" width="100%" alignItems="center">
                <Box 
                  display="flex" 
                  alignItems="center" 
                  justifyContent="center"
                  minWidth={36}
                  height={36}
                  borderRadius="50%"
                  bgcolor={alpha(theme.palette.success.main, 0.1)}
                  color={theme.palette.success.dark}
                  marginRight={2}
                  sx={{
                    fontWeight: 600,
                    fontSize: '0.875rem'
                  }}
                >
                  {index + 1}
                </Box>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  variant="outlined"
                  value={suggestion}
                  onChange={(e) => handleSuggestionChange(index, e.target.value)}
                  placeholder="أدخل المقترح"
                  size="small"
                />
                <Box style={{display:"flex"}} marginLeft={2}>
                  {index === localData.suggestions.length - 1 && (
                    <IconButton 
                      onClick={addSuggestion} 
                      color="primary"
                      size="small"
                      sx={{ 
                        marginRight: 1,
                        backgroundColor: alpha(theme.palette.primary.main, 0.1),
                        '&:hover': { 
                          backgroundColor: alpha(theme.palette.primary.main, 0.2) 
                        }
                      }}
                    >
                      <AddCircleOutline fontSize="small" />
                    </IconButton>
                  )}
                  <IconButton 
                    onClick={() => removeSuggestion(index)} 
                    color="error"
                    size="small"
                    sx={{ 
                      backgroundColor: alpha(theme.palette.error.main, 0.1),
                      '&:hover': { 
                        backgroundColor: alpha(theme.palette.error.main, 0.2) 
                      }
                    }}
                  >
                    <RemoveCircleOutline fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
            </ListItem>
          ))}
        </List>
      </Box>
    </Box>
  );
};

