import React from "react";
import { Card, Tabs, Tab, Box, Badge, useTheme, useMediaQuery } from "@mui/material";
import { alpha } from "@mui/material/styles";
import {
  Dashboard,
  Work,
  EmojiEvents,
  Announcement,
  MeetingRoom,
} from "@mui/icons-material";

const COLOR_SCHEME = {
  primary: "#057546",
  primaryDark: "#034d31",
  primaryLight: "#e6f3ee",
  accent: "#ae1e21",
  white: "#fefefe",
  text: "#1f2d3d",
};

const DashboardTabs = ({
  activeTab,
  setActiveTab,
  isHRUser,
  isSupervisor,
  pendingRequestsCount = 0,
  unseenPostsCount = 0,
}) => {
  const theme = useTheme();
  const isPhone = useMediaQuery(theme.breakpoints.down("sm"));
  const isCompact = useMediaQuery(theme.breakpoints.down("lg"));

  const userData = JSON.parse(localStorage.getItem("user") || "{}");
  const userJob = userData?.userJop;
  const isSupervisorLocal = isSupervisor || userJob === 9;
  const isHRLocal = !!isHRUser;

  const tabs = [
    {
      id: 0,
      label: "نظرة عامة",
      icon: <Dashboard />,
      visible: true,
    },
    {
      id: 1,
      label: "المهام والأداء",
      icon: <Work />,
      visible: true,
    },
    {
      id: 3,
      label: "غرفة الاجتماعات",
      icon: <MeetingRoom />,
      visible: true,
    },
    {
      id: 4,
      label: "الإعلانات والمنشورات",
      icon: (
        <>
          <Announcement />
        </>
      ),
      visible: true,
    },
    {
      id: 6,
      label: "موظف الشهر والتقييمات",
      icon: <EmojiEvents />,
      visible: isSupervisorLocal,
    },
  ];

  const visibleTabs = tabs.filter((tab) => tab.visible);

  return (
    <Card
      sx={{
        mt: { xs: 1, sm: 1.4, md: 2 },
        mb: { xs: 1.2, sm: 1.8, md: 2.5 },
