const DiscountOrderDialog = ({
  open,
  student,
  apiBaseUrl,
  onClose,
  onSaved
}) => {
  const theme = useTheme();
  const isPhone = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery("(min-width:600px) and (max-width:1599px)");
  const isCompact = isPhone || isTablet;

  const currentUser = useMemo(() => getCurrentUser(), []);
  const userGuid = getUserGuid(currentUser);

  const accountGuid = readValue(
    student,
    "accountGuid",
    "AccountGuid"
  );

  const studentName = readValue(
    student,
    "studentName",
    "StudentName"
  );

  const nationalId = readValue(
    student,
    "nationalId",
    "NationalId"
  );

  const studentTel = readValue(
    student,
    "studentTel",
    "tel",
    "StudentTel"
  );

  const [types, setTypes] = useState([]);
  const [history, setHistory] = useState([]);
  const [selectedGuid, setSelectedGuid] = useState("");
  const [attachment, setAttachment] = useState(null);
  const [requesterNote, setRequesterNote] = useState("");
  const [promoStudents, setPromoStudents] = useState([]);
  const [promoOpen, setPromoOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [promoDetailsOpen, setPromoDetailsOpen] = useState(false);
  const [promoDetailsGuid, setPromoDetailsGuid] = useState("");

  const selectedType = useMemo(
    () => types.find((item) => item.guid === selectedGuid) || null,
    [types, selectedGuid]
  );

  const discountAmount = selectedType?.isPromo
    ? promoStudents.length * 250
    : Number(selectedType?.amount || 0);

  const loadData = async () => {
    if (!accountGuid) {
      setLoadError("رقم حساب الطالب غير موجود");
      return;
    }

    try {
      setLoading(true);
      setLoadError("");

      const [typesResponse, historyResponse] = await Promise.all([
        fetch(
          `${apiBaseUrl}/api/discount-orders/types?accountGuid=${encodeURIComponent(
            accountGuid
          )}`
        ),
        fetch(
          `${apiBaseUrl}/api/discount-orders/history?accountGuid=${encodeURIComponent(
            accountGuid
          )}`
        )
      ]);

      const typesResult = await typesResponse.json().catch(() => null);
      const historyResult = await historyResponse.json().catch(() => null);

      if (!typesResponse.ok) {
        throw new Error(
          typesResult?.error ||
            typesResult?.message ||
            "فشل تحميل أنواع الخصم"
        );
      }

      if (!historyResponse.ok) {
        throw new Error(
          historyResult?.error ||
            historyResult?.message ||
            "فشل تحميل طلبات الخصم السابقة"
        );
      }

      setTypes(Array.isArray(typesResult?.data) ? typesResult.data : []);
      setHistory(
        Array.isArray(historyResult?.data) ? historyResult.data : []
      );
    } catch (error) {
      setTypes([]);
      setHistory([]);
      setLoadError(error.message || "حدث خطأ أثناء تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!open) return;

    setSelectedGuid("");
    setAttachment(null);
    setRequesterNote("");
    setPromoStudents([]);
    setPromoOpen(false);
    loadData();
  }, [open, accountGuid]);

  const handleTypeChange = (event) => {
    const guid = event.target.value;
    const type = types.find((item) => item.guid === guid);

    setSelectedGuid(guid);
    setAttachment(null);
    setPromoStudents([]);

    if (type?.isPromo) {
      setPromoOpen(true);
    }
  };

  const handleSave = async () => {
    if (!selectedType) {
      showWarning("برجاء اختيار الخصم أولاً");
      return;
    }

    if (!userGuid) {
      showWarning("بيانات المستخدم غير موجودة");
      return;
    }

    if (selectedType.requiresAttachment && !attachment) {
      showWarning("هذا الخصم يتطلب ملف مرفق");
      return;
    }

    if (selectedType.isPromo && promoStudents.length === 0) {
      showWarning(
        "خصم ترويجي يتطلب إدخال الطلاب المسجلين عن طريق صاحب الخصم"
      );
      setPromoOpen(true);
      return;
    }

    if (requesterNote.length > 1000) {
      showWarning("ملاحظة مقدم الطلب يجب ألا تتجاوز 1000 حرف");
      return;
    }

    try {
      setSaving(true);

      const formData = new FormData();

      formData.append("accountGuid", accountGuid);
      formData.append("nationalId", nationalId);
      formData.append("discountGuid", selectedType.guid);
      formData.append("userGuid", userGuid);
      formData.append("requesterNote", requesterNote.trim());
      formData.append("isUse", "true");

      formData.append(
        "promoNationalIdsJson",
        JSON.stringify(
          promoStudents.map((item) => item.nationalId)
        )
      );

      if (attachment) {
        formData.append("attachment", attachment);
      }

      const response = await fetch(
        `${apiBaseUrl}/api/discount-orders`,
        {
          method: "POST",
          body: formData
        }
      );

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.error ||
            result?.message ||
            "فشل حفظ طلب الخصم"
        );
      }

      await showSuccess(
        result?.message || "تم حفظ طلب الخصم بنجاح"
      );

      await loadData();

      setSelectedGuid("");
      setAttachment(null);
      setRequesterNote("");
      setPromoStudents([]);

      onSaved?.(result?.data);
    } catch (error) {
      showError(error.message || "حدث خطأ أثناء حفظ طلب الخصم");
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <style>
        {`
          @media (max-width: 1599px) {
            .sstli-discount-swal {
              max-width: 420px !important;
              border-radius: 14px !important;
              font-family: Cairo, Arial, sans-serif !important;
            }
            .sstli-discount-swal-icon {
              width: 3.4em !important;
              height: 3.4em !important;
              margin: 0.6em auto 0.25em !important;
            }
            .sstli-discount-swal-icon .swal2-icon-content {
              font-size: 2.3em !important;
            }
            .sstli-discount-swal-title {
              font-size: 0.95rem !important;
              line-height: 1.2 !important;
              padding-top: 0.2em !important;
            }
            .sstli-discount-swal-text {
              font-size: 0.68rem !important;
              line-height: 1.4 !important;
              padding: 0 0.75em !important;
            }
            .sstli-discount-swal-actions {
              margin-top: 0.65em !important;
            }
            .sstli-discount-swal-confirm,
            .sstli-discount-swal-cancel {
              min-width: 76px !important;
              min-height: 31px !important;
              padding: 0.38rem 0.75rem !important;
              margin: 0 !important;
              font-size: 0.66rem !important;
              border-radius: 8px !important;
              font-weight: 900 !important;
            }
          }

          @media (max-width: 599px) {
            .sstli-discount-swal {
              width: 82vw !important;
              max-width: 300px !important;
              border-radius: 12px !important;
            }
            .sstli-discount-swal-icon {
              width: 3em !important;
              height: 3em !important;
              margin: 0.5em auto 0.2em !important;
            }
            .sstli-discount-swal-icon .swal2-icon-content {
              font-size: 2em !important;
            }
            .sstli-discount-swal-title {
              font-size: 0.8rem !important;
            }
            .sstli-discount-swal-text {
              font-size: 0.57rem !important;
              padding: 0 0.5em !important;
            }
            .sstli-discount-swal-confirm,
            .sstli-discount-swal-cancel {
              min-width: 64px !important;
              min-height: 28px !important;
              padding: 0.32rem 0.55rem !important;
              font-size: 0.56rem !important;
            }
          }
        `}
      </style>

      <Dialog
        open={open}
        onClose={saving ? undefined : onClose}
        maxWidth="xl"
        fullWidth
        fullScreen={isPhone}
        dir="rtl"
        sx={uiLayout.withUiSx({
          "& .MuiDialog-container": {
            pt: isPhone ? "58px" : isTablet ? "64px" : 1.5,
            px: isPhone ? 0 : isTablet ? 0.5 : 1.5,
            pb: isPhone ? 0 : isTablet ? 0.5 : 1.5,
            alignItems: isPhone ? "stretch" : "center"
          }
        }, uiLayout.dialogLayoutSx)}
        PaperProps={{
          sx: {
            width: isPhone ? "100vw" : isTablet ? "96vw" : "94vw",
            maxWidth: isPhone ? "100vw" : isTablet ? "1180px" : "1500px",
            height: isPhone ? "calc(100dvh - 58px)" : isTablet ? "calc(100dvh - 72px)" : "88vh",
            maxHeight: isPhone ? "calc(100dvh - 58px)" : isTablet ? "calc(100dvh - 72px)" : "88vh",
            minHeight: 0,
            m: 0,
            borderRadius: isPhone ? 0 : isTablet ? 2 : 3,
            overflow: "hidden",
            display: "flex",
            flexDirection: "column"
          }
        }}
      >
        <DialogTitle
          sx={{
            fontWeight: 950,
            color: primaryColor,
            display: "flex",
            alignItems: "center",
            gap: isCompact ? 0.35 : 1,
            py: isPhone ? 0.5 : isTablet ? 0.7 : 1.5,
            px: isPhone ? 0.65 : isTablet ? 0.9 : 2,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.8rem" : undefined,
            flexShrink: 0
          }}
        >
          <DiscountIcon sx={{ fontSize: isPhone ? 16 : isTablet ? 19 : undefined }} />
          نموذج طلب خصم
        </DialogTitle>

        <DialogContent
          dividers
          sx={{
            p: isPhone ? 0.3 : isTablet ? 0.55 : 2,
            overflowY: "auto",
            flex: 1,
            minHeight: 0,
            "& .MuiInputLabel-root": {
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
            },
            "& .MuiInputBase-input, & .MuiSelect-select": {
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
              py: isPhone ? 0.5 : isTablet ? 0.65 : undefined
            },
            "& .MuiOutlinedInput-root": {
              minHeight: isPhone ? 31 : isTablet ? 35 : undefined,
              borderRadius: isCompact ? 1.25 : undefined
            },
            "& .MuiFormHelperText-root": {
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
            }
          }}
        >
          {loadError ? (
            <Alert severity="error" sx={{ mb: isCompact ? 0.35 : 2, py: isCompact ? 0.15 : undefined, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>
              {loadError}
            </Alert>
          ) : null}

          <Paper variant="outlined" sx={{ p: isPhone ? 0.4 : isTablet ? 0.6 : 2, mb: isCompact ? 0.45 : 2, borderRadius: isCompact ? 1.4 : undefined }}>
            <Grid container spacing={isPhone ? 0.35 : isTablet ? 0.55 : 1.5}>
              <Grid item xs={12} sm={6} md={4}>
                <StudentField
                  label="اسم الطالب"
                  value={studentName}
                />
              </Grid>

              <Grid item xs={6} sm={3} md={4}>
                <StudentField
                  label="رقم الهوية"
                  value={nationalId}
                />
              </Grid>

              <Grid item xs={6} sm={3} md={4}>
                <StudentField
                  label="رقم الجوال"
                  value={studentTel}
                />
              </Grid>
            </Grid>
          </Paper>

          {loading ? (
            <Box sx={{ py: isPhone ? 2.5 : isTablet ? 3.5 : 5, textAlign: "center" }}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <Grid container spacing={isPhone ? 0.35 : isTablet ? 0.55 : 2}>
                <Grid item xs={12} sm={6} md={6}>
                  <FormControl sx={uiLayout.formFieldSx} fullWidth>
                    <InputLabel>نوع الخصم</InputLabel>

                    <Select
                      value={selectedGuid}
                      label="نوع الخصم"
                      onChange={handleTypeChange}
                      MenuProps={{
                        anchorOrigin: {
                          vertical: "bottom",
                          horizontal: "right"
                        },
                        transformOrigin: {
                          vertical: "top",
                          horizontal: "right"
                        },
                        MenuListProps: {
                          dense: true,
                          sx: {
                            p: isCompact ? 0.25 : 0.75
                          }
                        },
                        PaperProps: {
                          sx: {
                            width: isPhone
                              ? "min(300px, calc(100vw - 20px))"
                              : isTablet
                                ? "min(420px, calc(100vw - 32px))"
                                : undefined,
                            maxHeight: isPhone ? 180 : isTablet ? 220 : 320,
                            mt: 0.35,
                            borderRadius: isCompact ? 1.25 : 2,
                            boxShadow: "0 10px 26px rgba(31,45,61,0.16)",
                            "& .MuiMenuItem-root": {
  minHeight: isPhone ? 30 : isTablet ? 34 : 40,

  py: isPhone ? 0.35 : isTablet ? 0.48 : 0.75,

  pr: isPhone ? 0.7 : isTablet ? 0.9 : 1.5,

  // الزقة اللي إنت عايزها
  pl: isPhone ? 2.2 : isTablet ? 2.8 : 2,

  borderRadius: isCompact ? 0.9 : 0,
  mb: isCompact ? 0.12 : 0,

  fontSize: isPhone
    ? "0.48rem"
    : isTablet
      ? "0.56rem"
      : "0.875rem",

  fontWeight: 850,
  lineHeight: 1.15,
  whiteSpace: "normal",
}
                          }
                        }
                      }}
                    >
                      {types.map((type) => (
                        <MenuItem
                          key={type.guid}
                          value={type.guid}
                        >
                          {type.name}
                          {type.requiresAttachment
                            ? " — يتطلب مرفق"
                            : ""}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>

                  {types.length === 0 && !loadError ? (
                    <Alert severity="warning" sx={{ mt: 1 }}>
                      لا توجد أنواع خصم متاحة لقطاع هذا الطالب
                    </Alert>
                  ) : null}
                </Grid>

                <Grid item xs={12} sm={3} md={3}>
                  <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                    fullWidth
                    label={
                      selectedType?.isPromo
                        ? "إجمالي الخصم الترويجي"
                        : "قيمة الخصم"
                    }
                    value={discountAmount.toFixed(2)}
                    InputProps={{ readOnly: true }}
                  />
                </Grid>

                <Grid item xs={6} sm={3} md={3}>
                  <Button
                    component="label"
                    fullWidth
                    variant="outlined"
                    startIcon={<AttachFileIcon />}
                    disabled={!selectedType}
                    sx={uiLayout.withUiSx({
                      height: isPhone ? 31 : isTablet ? 35 : 56,
                      fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                      px: isPhone ? 0.45 : isTablet ? 0.65 : undefined,
                      color: selectedType?.requiresAttachment
                        ? accentColor
                        : primaryColor,
                      borderColor: selectedType?.requiresAttachment
                        ? accentColor
                        : primaryColor
                    }, uiLayout.buttonSx)}
                  >
                    {attachment
                      ? attachment.name
                      : selectedType?.requiresAttachment
                      ? "إرفاق مستند إجباري"
                      : "إرفاق مستند اختياري"}

                    <input
                      hidden
                      type="file"
                      onChange={(event) =>
                        setAttachment(
                          event.target.files?.[0] || null
                        )
                      }
                    />
                  </Button>
                </Grid>
              </Grid>

              {selectedType?.isPromo ? (
                <Alert
                  severity="info"
                  action={
                    <Button sx={uiLayout.buttonSx}
                      color="inherit"
                      size="small"
                      onClick={() => setPromoOpen(true)}
                    >
                      تعديل الطلاب
                    </Button>
                  }
                  sx={{
                    mt: isCompact ? 0.4 : 2,
                    py: isCompact ? 0.15 : undefined,
                    fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                    "& .MuiAlert-action": {
                      pt: isCompact ? 0 : undefined,
                      alignItems: "center"
                    },
                    "& .MuiButton-root": {
                      minWidth: isPhone ? 58 : isTablet ? 68 : undefined,
                      fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
                    }
                  }}
                >
                  عدد طلاب الخصم الترويجي: {promoStudents.length}،
                  إجمالي الخصم:{" "}
                  {(promoStudents.length * 250).toFixed(2)} ريال
                </Alert>
              ) : null}

              <TextField InputLabelProps={{ shrink: true }}
                fullWidth
                multiline
                minRows={isPhone ? 2 : isTablet ? 2 : 4}
                label="ملاحظة مقدم الطلب"
                value={requesterNote}
                onChange={(event) =>
                  setRequesterNote(
                    event.target.value.slice(0, 1000)
                  )
                }
                helperText={`${requesterNote.length}/1000`}
                sx={uiLayout.withUiSx({ mt: isCompact ? 0.45 : 2 }, uiLayout.formFieldSx)}
              />

              <Divider sx={{ my: isCompact ? 0.5 : 2 }}>
                <Typography
                  sx={{
                    fontWeight: 950,
                    color: primaryColor,
                    fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
                  }}
                >
                  طلبات الخصم السابقة
                </Typography>
              </Divider>

              <TableContainer
                component={Paper}
                variant="outlined"
                sx={uiLayout.withUiSx({
                  borderRadius: isCompact ? 1.3 : undefined,
                  overflowX: "auto",
                  maxHeight: isPhone ? "40dvh" : isTablet ? "42dvh" : undefined,
                  "& .MuiTableCell-root": {
                    py: isPhone ? 0.4 : isTablet ? 0.55 : undefined,
                    px: isPhone ? 0.28 : isTablet ? 0.45 : undefined,
                    fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                    whiteSpace: "nowrap"
                  }
                }, uiLayout.tableContainerSx)}
              >
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell align="center">التاريخ</TableCell>
                      <TableCell align="center" sx={{ display: isPhone ? "none" : "table-cell" }}>
                        مقدم الطلب
                      </TableCell>
                      <TableCell align="center">
                        نوع الخصم
                      </TableCell>
                      <TableCell align="center">الحالة</TableCell>
                      <TableCell align="center" sx={{ display: isCompact ? "none" : "table-cell" }}>البيان</TableCell>
                      <TableCell align="center">طلاب الخصم</TableCell>
                    </TableRow>
                  </TableHead>

                  <TableBody>
                    {history.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={isPhone ? 4 : isTablet ? 5 : 6} align="center">
                          لا توجد طلبات خصم سابقة
                        </TableCell>
                      </TableRow>
                    ) : (
                      history.map((item, index) => (
                        <TableRow
                          key={item.guid || index}
                          hover
                        >
                          <TableCell align="center">
                            {item.orderDate || "-"}
                          </TableCell>

                          <TableCell align="center" sx={{ display: isPhone ? "none" : "table-cell" }}>
                            {item.requestedBy || "-"}
                          </TableCell>

                          <TableCell align="center">
                            {item.discountName || "-"}
                          </TableCell>

                          <TableCell align="center">
                            {item.statusName || "-"}
                          </TableCell>

                          <TableCell align="center" sx={{ display: isCompact ? "none" : "table-cell" }}>
                            {item.notes || "-"}
                          </TableCell>

                          <TableCell align="center">
                            {item.hasPromoStudents ? (
                              <Button
                                variant="contained"
                                size="small"
                                startIcon={<VisibilityIcon />}
                                onClick={() => {
                                  setPromoDetailsGuid(item.guid);
                                  setPromoDetailsOpen(true);
                                }}
                                sx={uiLayout.withUiSx({
                                  backgroundColor: primaryColor,
                                  minWidth: isPhone ? 46 : isTablet ? 56 : 90,
                                  px: isPhone ? 0.35 : isTablet ? 0.5 : undefined,
                                  fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
                                }, uiLayout.buttonSx)}
                              >
                                عرض
                              </Button>
                            ) : (
                              "-"
                            )}
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </>
          )}
        </DialogContent>

        <DialogActions sx={uiLayout.withUiSx({ px: isPhone ? 0.35 : isTablet ? 0.55 : 3, py: isPhone ? 0.28 : isTablet ? 0.42 : 2, gap: isCompact ? 0.35 : 1, flexShrink: 0 }, uiLayout.dialogActionsSx)}>
          <Button
            onClick={handleSave}
            disabled={
              saving ||
              loading ||
              !selectedType ||
              Boolean(loadError)
            }
            variant="contained"
            startIcon={
              saving ? (
                <CircularProgress size={18} color="inherit" />
              ) : (
                <SaveIcon />
              )
            }
            sx={uiLayout.withUiSx({
              backgroundColor: primaryColor,
              minWidth: isPhone ? 90 : isTablet ? 110 : 140,
              minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
              px: isPhone ? 0.8 : isTablet ? 1.1 : undefined,
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
            }, uiLayout.buttonSx)}
          >
            حفظ الطلب
          </Button>

          <Button
            onClick={onClose}
            disabled={saving}
            sx={uiLayout.withUiSx({
              color: "#333",
              minWidth: isPhone ? 64 : isTablet ? 74 : 90,
              minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
              px: isPhone ? 0.7 : isTablet ? 1 : undefined,
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
              fontWeight: 900
            }, uiLayout.buttonSx)}
          >
            إغلاق
          </Button>
        </DialogActions>
      </Dialog>

      <PromoDetailsDialog
        open={promoDetailsOpen}
        apiBaseUrl={apiBaseUrl}
        discountOrderGuid={promoDetailsGuid}
        onClose={() => {
          setPromoDetailsOpen(false);
          setPromoDetailsGuid("");
        }}
      />

      <PromoStudentsDialog
        open={promoOpen}
        apiBaseUrl={apiBaseUrl}
        ownerAccountGuid={accountGuid}
        initialStudents={promoStudents}
        onClose={() => {
          setPromoOpen(false);

          if (promoStudents.length === 0) {
            setSelectedGuid("");
          }
        }}
        onConfirm={(students) => {
          setPromoStudents(students);
          setPromoOpen(false);
        }}
      />
    </>
  );
};

export default DiscountOrderDialog;

src\\components\\DocumentHistoryDialog.j:
import * as uiLayout from './common/uiLayout';
import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Typography
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";

import CloseIcon from "@mui/icons-material/Close";
import HistoryIcon from "@mui/icons-material/History";

const primaryColor = "#057546";
const accentColor = "#ae1e21";

const DocumentHistoryDialog = ({
  open,
  onClose,
  actionGuid,
  documentNo,
  apiBaseUrl
}) => {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open || !actionGuid) return undefined;

    const controller = new AbortController();

    const loadHistory = async () => {
      try {
        setLoading(true);
        setError("");
        setRows([]);

        const params = new URLSearchParams({ actionGuid });

        const response = await fetch(
          `${apiBaseUrl}/api/reception-office/student-statement/document-history?${params.toString()}`,
          { signal: controller.signal }
        );

        const result = await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
              result?.error ||
              "تعذر تحميل سجل العمليات"
          );
        }

        setRows(Array.isArray(result?.data) ? result.data : []);
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(err.message || "حدث خطأ أثناء تحميل العمليات");
        }
      } finally {
        setLoading(false);
      }
    };

    loadHistory();

    return () => controller.abort();
  }, [open, actionGuid, apiBaseUrl]);

  const columns = [
    {
      field: "userName",
      headerName: "اسم المستخدم",
      flex: 1,
      minWidth: 180,
      align: "center",
      headerAlign: "center"
    },
    {
      field: "actionDate",
      headerName: "تاريخ العملية",
      flex: 1,
      minWidth: 180,
      align: "center",
      headerAlign: "center"
    },
    {
      field: "actionName",
      headerName: "العملية",
      flex: 1,
      minWidth: 150,
      align: "center",
      headerAlign: "center"
    },
    {
      field: "notes",
      headerName: "ملاحظات",
      flex: 1.5,
      minWidth: 220,
      align: "center",
      headerAlign: "center"
    }
  ];

  return (
    <Dialog sx={uiLayout.dialogLayoutSx}
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="md"
      dir="rtl"
      PaperProps={{
        sx: {
          borderRadius: 3,
          overflow: "hidden"
        }
      }}
    >
      <DialogTitle
        sx={{
          backgroundColor: primaryColor,
          color: "#fff",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          py: 1.5
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <HistoryIcon />

          <Box>
            <Typography sx={{ fontWeight: 950 }}>
              العمليات التي تمت على المستند
            </Typography>

            <Typography sx={{ fontSize: "0.78rem", opacity: 0.9 }}>
              رقم المستند: {documentNo || "-"}
            </Typography>
          </Box>
        </Box>

        <IconButton onClick={onClose} sx={{ color: "#fff" }}>
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 2 }}>
        {loading ? (
          <Box
            sx={{
              height: 280,
              display: "flex",
              alignItems: "center",
              justifyContent: "center"
            }}
          >
            <CircularProgress />
          </Box>
        ) : error ? (
          <Box
            sx={{
              minHeight: 200,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: accentColor,
              fontWeight: 900
            }}
          >
            {error}
          </Box>
        ) : (
          <Box sx={uiLayout.withUiSx({ height: 360, mt: 1 }, uiLayout.tableContainerSx)}>
            <DataGrid
              rows={rows}
              columns={columns}
              disableRowSelectionOnClick
              pageSizeOptions={[10, 25, 50]}
              initialState={{
                pagination: {
                  paginationModel: {
                    pageSize: 10,
                    page: 0
                  }
                }
              }}
              localeText={{
                noRowsLabel: "لا توجد عمليات مسجلة"
              }}
              sx={uiLayout.withUiSx({
                borderRadius: 2,
                direction: "rtl",
                "& .MuiDataGrid-columnHeaders": {
                  backgroundColor: "#f7ead0",
                  color: "#1f2d3d",
                  fontWeight: 950
                },
                "& .MuiDataGrid-columnHeaderTitle": {
                  fontWeight: 950
                },
                "& .MuiDataGrid-cell": {
                  textAlign: "center",
                  fontWeight: 750
                }
              }, uiLayout.dataGridSx)}
            />
          </Box>
        )}
      </DialogContent>

      <DialogActions sx={uiLayout.withUiSx({ px: 2, pb: 2 }, uiLayout.dialogActionsSx)}>
        <Button
          variant="outlined"
          color="error"
          onClick={onClose}
          sx={uiLayout.withUiSx({ minWidth: 110, fontWeight: 900 }, uiLayout.buttonSx)}
        >
          إغلاق
        </Button>
      </DialogActions>
    </Dialog>
  );
};

