              التقييم الحالي خاص بشهر {evalMonth}/{evalYear} فقط.
            </Typography>
          </Alert>
        </CardContent>
      </Card>

      {/* رسائل الخطأ والنجاح */}
      {evaluationError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {evaluationError}
        </Alert>
      )}

      {evaluationSuccess && (
        <Alert severity="success" sx={{ mb: 2 }}>
          {evaluationSuccess}
        </Alert>
      )}

