                      borderRadius: 2,
                      fontWeight: 700,
                      bgcolor: BRAND,
                      "&:hover": { bgcolor: BRAND_DARK },
                      boxShadow: `0 4px 12px ${alpha(BRAND, 0.3)}`,
                    }, uiLayout.buttonSx)}
                  >
                    {evaluationLoading ? (
                      <CircularProgress size={20} sx={{ color: "white" }} />
                    ) : currentEvaluation ? (
                      "حفظ التعديلات"
                    ) : (
                      "حفظ التقييم"
                    )}
                  </Button>
                </Box>
              </Grid>
            )}
          </Grid>
        </CardContent>
      </Card>

      {/* تاريخ التقييمات السابقة - كل التقييمات */}
      {sortedEvaluations.length > 0 && (
        <Card sx={{ borderRadius: 2, border: `1px solid ${alpha("#e0e0e0", 0.5)}` }}>
          <CardContent>
            <Typography variant="h6" sx={{ mb: 2, fontWeight: 700, color: "#666" }}>
              <History sx={{ marginInlineEnd: 1, verticalAlign: "middle" }} />
              سجل التقييمات الكامل ({sortedEvaluations.length})
            </Typography>
            
            <TableContainer sx={uiLayout.tableContainerSx}>
              <Table size="small">
                <TableHead>
                  <TableRow sx={{ backgroundColor: alpha("#f5f5f5", 0.5) }}>
                    <TableCell sx={{ fontWeight: 700 }}>الشهر/السنة</TableCell>
                    <TableCell align="center" sx={{ fontWeight: 700 }}>التقييم</TableCell>
                    <TableCell sx={{ fontWeight: 700 }}>ملاحظات</TableCell>
                    <TableCell sx={{ fontWeight: 700 }}>التوصيات</TableCell>
                    <TableCell sx={{ fontWeight: 700 }}>تاريخ الإضافة</TableCell>
                    {/* <TableCell sx={{ fontWeight: 700 }}>الحالة</TableCell> */}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {sortedEvaluations.map((evalItem) => {
                    const isCurrentMonth = 
                      parseInt(evalItem.evaluation_month) === parseInt(evalMonth) && 
                      parseInt(evalItem.evaluation_year) === parseInt(evalYear);
                    
                    return (
                      <TableRow
                        key={evalItem.id}
                        sx={{
                          backgroundColor: isCurrentMonth ? alpha("#4caf50", 0.1) : 'transparent',
                          '&:hover': { backgroundColor: alpha("#f5f5f5", 0.3) },
                        }}
                      >
                        <TableCell>
                          <Box sx={{ display: "flex", alignItems: "center" }}>
                            <Typography sx={{ fontWeight: isCurrentMonth ? 800 : 400 }}>
                              {evalItem.evaluation_month}/{evalItem.evaluation_year}
                            </Typography>
                            {isCurrentMonth && (
                              <Chip 
                                label="الحالي" 
                                size="small" 
                                sx={{ 
                                  marginInlineStart: 1, 
                                  bgcolor: '#4caf50', 
                                  color: 'white',
                                  fontWeight: 700,
                                  fontSize: "0.75rem"
                                }} 
                              />
                            )}
                          </Box>
                        </TableCell>
                        <TableCell align="center">
                          <Box sx={{ display: "flex", justifyContent: "center" }}>
                            <Rating
                              value={evalItem.rating}
                              readOnly
                              size="small"
                              icon={<Star fontSize="inherit" sx={{ color: "#ff9800" }} />}
                              emptyIcon={<StarBorder fontSize="inherit" sx={{ color: "#ddd" }} />}
                            />
                            <Typography variant="body2" sx={{ marginInlineStart: 1, fontWeight: 600 }}>
                              ({evalItem.rating})
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Tooltip title={evalItem.notes || "لا توجد ملاحظات"}>
                            <Typography
                              variant="body2"
                              sx={{
                                maxWidth: 180,
                                overflow: "hidden",
                                textOverflow: "ellipsis",
                                whiteSpace: "nowrap",
                              }}
                            >
                              {evalItem.notes || "—"}
                            </Typography>
                          </Tooltip>
                        </TableCell>
                        <TableCell>
                          <Tooltip title={evalItem.hr_recommendations || "لا توجد توصيات"}>
                            <Typography
                              variant="body2"
                              sx={{
                                maxWidth: 180,
                                overflow: "hidden",
                                textOverflow: "ellipsis",
                                whiteSpace: "nowrap",
                              }}
                            >
                              {evalItem.hr_recommendations || "—"}
                            </Typography>
                          </Tooltip>
                        </TableCell>
                        <TableCell>
                          {formatDate(evalItem.created_at)}
                        </TableCell>
                        {/* <TableCell>
                          {isCurrentMonth ? (
                            <Chip 
                              label="شهر التقييم" 
                              size="small" 
                              color="success" 
                              variant="outlined"
                            />
                          ) : (
                            <Chip 
                              label="تاريخي" 
                              size="small" 
                              color="default" 
                              variant="outlined"
                            />
                          )}
                        </TableCell> */}
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

  const months = [
    { v: 1, n: "يناير" },
    { v: 2, n: "فبراير" },
    { v: 3, n: "مارس" },
    { v: 4, n: "أبريل" },
    { v: 5, n: "مايو" },
    { v: 6, n: "يونيو" },
    { v: 7, n: "يوليو" },
    { v: 8, n: "أغسطس" },
    { v: 9, n: "سبتمبر" },
    { v: 10, n: "أكتوبر" },
    { v: 11, n: "نوفمبر" },
    { v: 12, n: "ديسمبر" },
  ];

  const years = useMemo(() => {
    const y = now.getFullYear();
    return [y - 1, y, y + 1];
  }, [now]);

  return (
    <NavigationShell variant="standard" ><Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f6f7fb" }}>
      

      <Box
        sx={{
          flex: 1,
          direction: "rtl",
          p: {
            xs: 2,
            md: 3
          },
          "& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline": {
            borderColor: BRAND
          },
          "& .MuiInputLabel-root.Mui-focused": {
            color: BRAND_DARK
          },
          ...navigationContentSx
        }}
      >
        <Container maxWidth="xl">
          {/* Header */}
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 2,
              mb: 2,
              flexWrap: "wrap",
            }}
          >
            <Box>
              <Typography sx={{ fontSize: 24, fontWeight: 900, color: "#0f172a" }}>
                تقييم الموظفين
              </Typography>
              <Typography sx={{ opacity: 0.75, mt: 0.5 }}>
                الشهر المحدد: {evalMonth}/{evalYear}
              </Typography>
            </Box>

            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
              <ToggleButtonGroup
                value={viewMode}
                exclusive
                onChange={(_, v) => v && setViewMode(v)}
                size="small"
                sx={{
                  borderRadius: 2,
                  overflow: "hidden",
                  border: `1px solid ${alpha(BRAND, 0.25)}`,
                  "& .MuiToggleButton-root": {
                    border: 0,
                    borderRadius: 0,
                    px: 1.25,
                    fontWeight: 900,
                  },
                  "& .Mui-selected": {
                    bgcolor: alpha(BRAND, 0.14),
                    color: BRAND_DARK,
                  },
                }}
              >
                <ToggleButton value="cards">
                  <ViewModuleIcon sx={{ marginInlineEnd: 0.75, fontSize: 18 }} />
                  Cards
                </ToggleButton>
              </ToggleButtonGroup>

              <Tooltip title="تحديث البيانات">
                <IconButton
                  onClick={fetchAll}
                  sx={{
                    borderRadius: 2,
                    border: `1px solid ${alpha(BRAND, 0.25)}`,
                    "&:hover": { bgcolor: alpha(BRAND, 0.08) },
                  }}
                >
                  <RefreshIcon />
                </IconButton>
              </Tooltip>

              <Tooltip title="مسح الفلاتر">
                <IconButton
                  onClick={resetFilters}
                  sx={{
                    borderRadius: 2,
                    border: `1px solid ${alpha(BRAND, 0.25)}`,
                    "&:hover": { bgcolor: alpha(BRAND, 0.08) },
                  }}
                >
                  <FilterAltOffIcon />
                </IconButton>
              </Tooltip>
            </Stack>
          </Box>

          {/* ✅ Month/Year Filter */}
          <Card
            sx={{
              borderRadius: 3,
              boxShadow: "0 10px 30px rgba(0,0,0,0.06)",
              mb: 2,
              border: `1px solid ${alpha(BRAND, 0.18)}`,
            }}
          >
            <CardContent sx={{ p: 2.5 }}>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth sx={uiLayout.withUiSx({ direction: "rtl" }, uiLayout.formFieldSx)}>
                    <InputLabel>شهر التقييم</InputLabel>
                    <Select
                      value={evalMonth}
                      label="شهر التقييم"
                      onChange={(e) => setEvalMonth(Number(e.target.value))}
                      sx={{ borderRadius: 2 }}
                    >
                      {months.map((m) => (
                        <MenuItem key={m.v} value={m.v}>
                          {m.n}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth sx={uiLayout.withUiSx({ direction: "rtl" }, uiLayout.formFieldSx)}>
                    <InputLabel>سنة التقييم</InputLabel>
                    <Select
                      value={evalYear}
                      label="سنة التقييم"
                      onChange={(e) => setEvalYear(Number(e.target.value))}
                      sx={{ borderRadius: 2 }}
                    >
                      {years.map((y) => (
                        <MenuItem key={y} value={y}>
                          {y}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
              </Grid>
              
              <Grid container spacing={2} sx={{ mt: 2 }}>
                <Grid item xs={12} md={3}>
                  <Alert severity="info" sx={{ borderRadius: 2 }}>
                    <Typography fontWeight={700}>السداد والتحصيل:</Typography>
                    <Typography variant="body2">من 15 الشهر إلى 14 الشهر التالي</Typography>
                  </Alert>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Alert severity="info" sx={{ borderRadius: 2 }}>
                    <Typography fontWeight={700}>التسجيلات:</Typography>
                    <Typography variant="body2">من أول الشهر إلى آخره</Typography>
                  </Alert>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Alert severity="info" sx={{ borderRadius: 2 }}>
                    <Typography fontWeight={700}>الإنتاجية:</Typography>
                    <Typography variant="body2">من أول الشهر إلى آخره</Typography>
                  </Alert>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Alert severity="info" sx={{ borderRadius: 2 }}>
                    <Typography fontWeight={700}>المهام:</Typography>
                    <Typography variant="body2">من أول الشهر إلى آخره</Typography>
                  </Alert>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          {/* Filters and Sorting */}
          <Card
            sx={{
              borderRadius: 3,
              boxShadow: "0 10px 30px rgba(0,0,0,0.06)",
              mb: 2,
              border: `1px solid ${alpha(BRAND, 0.18)}`,
            }}
          >
            <CardContent sx={{ p: 2.5 }}>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={4}>
                  <TextField InputLabelProps={{ shrink: true }}
                    fullWidth
                    value={q}
                    onChange={(e) => setQ(e.target.value)}
                    placeholder="ابحث بالاسم أو اسم المستخدم..."
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <SearchIcon />
                        </InputAdornment>
                      ),
                    }}
                    sx={uiLayout.withUiSx({
                      "& .MuiInputBase-root": { borderRadius: 2 },
                      direction: "rtl",
                    }, uiLayout.formFieldSx)}
                  />
                </Grid>

                <Grid item xs={12} md={3}>
                  <FormControl fullWidth sx={uiLayout.withUiSx({ direction: "rtl" }, uiLayout.formFieldSx)}>
                    <InputLabel>الفرع</InputLabel>
                    <Select
                      value={branchGuid}
                      label="الفرع"
                      onChange={(e) => setBranchGuid(e.target.value)}
                      sx={{ borderRadius: 2 }}
                      MenuProps={{ PaperProps: { sx: { borderRadius: 2 } } }}
                    >
                      <MenuItem value="all">كل الفروع</MenuItem>
                      {branchOptions.map((b) => (
                        <MenuItem key={b.guid} value={b.guid}>
                          {b.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={3}>
                  <FormControl fullWidth sx={uiLayout.withUiSx({ direction: "rtl" }, uiLayout.formFieldSx)}>
                    <InputLabel>ترتيب حسب</InputLabel>
                    <Select
                      value={sortBy}
                      label="ترتيب حسب"
                      onChange={(e) => setSortBy(e.target.value)}
                      sx={{ borderRadius: 2 }}
                    >
                      <MenuItem value="registrations">الاسم</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={2}>
                  <FormControl fullWidth sx={uiLayout.withUiSx({ direction: "rtl" }, uiLayout.formFieldSx)}>
                    <InputLabel>الترتيب</InputLabel>
                    <Select
                      value={sortOrder}
                      label="الترتيب"
                      onChange={(e) => setSortOrder(e.target.value)}
                      sx={{ borderRadius: 2 }}
                    >
                      <MenuItem value="desc">تنازلي</MenuItem>
                      <MenuItem value="asc">تصاعدي</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
              </Grid>

              <Divider sx={{ my: 2 }} />

              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 2,
                  flexWrap: "wrap",
                }}
              >
                <Stack direction="row" spacing={1} sx={{ flexWrap: "wrap" }}>
                  <Chip
                    icon={<PersonIcon />}
                    label={`عدد الموظفين: ${employees.length}`}
                    sx={[hrChipSx(), { fontWeight: 700 }]}
                  />
                  <Chip
                    icon={<ApartmentIcon />}
                    label={
                      branchGuid === "all"
                        ? "فرع: الكل"
                        : `فرع: ${getBranchName(branchGuid)}`
                    }
                    sx={[hrChipSx(), { fontWeight: 700 }]}
                  />
                  <Chip
                    icon={<CheckCircleIcon />}
                    label="الحالة: نشط فقط"
                    sx={[hrChipSx(), {
                      fontWeight: 800,
                      bgcolor: alpha(BRAND, 0.14),
                      color: BRAND_DARK,
                      border: `1px solid ${alpha(BRAND, 0.25)}`,
                    }]}
                  />
                  <Chip
                    label={`نتائج: ${filteredAndSorted.length}`}
                    sx={{
                      fontWeight: 900,
                      bgcolor: alpha(BRAND, 0.12),
                      color: BRAND_DARK,
                      border: `1px solid ${alpha(BRAND, 0.25)}`,
                    }}
                  />
                </Stack>

                <Stack sx={uiLayout.filterBarSx} direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                  <FormControl size="small" sx={uiLayout.withUiSx({ minWidth: 140 }, uiLayout.formFieldSx)}>
                    <InputLabel>عدد بالصفحة</InputLabel>
                    <Select
                      value={pageSize}
                      label="عدد بالصفحة"
                      onChange={(e) => setPageSize(Number(e.target.value))}
                      sx={{ borderRadius: 2 }}
                    >
                      <MenuItem value={8}>8</MenuItem>
                      <MenuItem value={12}>12</MenuItem>
                      <MenuItem value={16}>16</MenuItem>
                      <MenuItem value={24}>24</MenuItem>
                    </Select>
                  </FormControl>

                  <Button
                    variant="outlined"
                    onClick={resetFilters}
                    sx={uiLayout.withUiSx({
                      borderRadius: 2,
                      borderColor: alpha(BRAND, 0.5),
                      color: BRAND_DARK,
                      "&:hover": {
                        borderColor: BRAND,
                        bgcolor: alpha(BRAND, 0.08),
                      },
                    }, uiLayout.buttonSx)}
                  >
                    إعادة ضبط
                  </Button>
                </Stack>
              </Box>
            </CardContent>
          </Card>

          {/* States */}
          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          {loading ? (
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                py: 8,
              }}
            >
              <CircularProgress sx={{ color: BRAND }} />
            </Box>
          ) : filteredAndSorted.length === 0 ? (
            <Card sx={{ borderRadius: 3 }}>
              <CardContent>
                <Typography sx={{ fontWeight: 800 }}>
                  مفيش موظفين مطابقين للفلاتر الحالية.
                </Typography>
                <Typography sx={{ opacity: 0.8, mt: 1 }}>
                  جرّب تغيّر الفرع أو امسح البحث.
                </Typography>
              </CardContent>
            </Card>
          ) : (
            <>
              {/* Cards */}
              <Grid container spacing={2}>
                {pagedCards.map((u) => {
                  const branchName = getBranchName(u?.branchForWork);
                  const stats = getEmployeeStats(u);

                  return (
                    <Grid item xs={12} sm={6} md={4} lg={3} key={u.guid || u.id}>
                      <Card
                        sx={{
                          height: "100%",
                          borderRadius: 3,
                          boxShadow: "0 10px 30px rgba(0,0,0,0.06)",
                          border: `1px solid ${alpha(BRAND, 0.15)}`,
                          transition: "transform 0.15s ease, box-shadow 0.15s ease",
                          display: "flex",
                          flexDirection: "column",
                          "&:hover": {
                            transform: "translateY(-4px)",
                            boxShadow: "0 14px 40px rgba(0,0,0,0.10)",
                          },
                        }}
                      >
                        <CardContent sx={{ pb: 1.5, flexGrow: 1 }}>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "flex-start",
                              justifyContent: "space-between",
                              gap: 1,
                            }}
                          >
                            <Box sx={{ flex: 1, minWidth: 0 }}>
                              <Typography
                                sx={{ fontWeight: 900, fontSize: 16, ...clamp1 }}
                                title={u?.fullName || u?.userName || "—"}
                              >
                                {u?.fullName || u?.userName || "—"}
                              </Typography>

                              <Typography
                                sx={{ opacity: 0.75, mt: 0.25, ...clamp1 }}
                                title={`@${u?.userName || "—"}`}
                              >
                                @{u?.userName || "—"}
                              </Typography>
                            </Box>

                            <Chip
                              size="small"
                              icon={<CheckCircleIcon />}
                              label="نشط"
                              sx={[hrChipSx("small"), {
                                fontWeight: 800,
                                bgcolor: alpha(BRAND, 0.14),
                                color: BRAND_DARK,
                                border: `1px solid ${alpha(BRAND, 0.25)}`,
                                flexShrink: 0,
                              }]}
                            />
                          </Box>

                          <Divider sx={{ my: 1.5 }} />

                          <Box sx={{ minHeight: 56 }}>
                            <Typography sx={{ fontWeight: 900 }}>
                              الفرع:{" "}
                              <Typography
                                component="span"
                                sx={{ fontWeight: 700, color: BRAND_DARK }}
                                title={branchName}
                              >
                                {branchName}
                              </Typography>
                            </Typography>
                          </Box>

                          <Box sx={{ mt: 1.25, display: "flex", flexDirection: "column", gap: 1 }}>
                            <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}>
                              {stats.hasTrainerGuid && (
                                <Chip
                                  size="small"
                                  label="لديه تحصيل"
                                  sx={{
                                    fontWeight: 900,
                                    bgcolor: alpha(BRAND, 0.12),
                                    color: BRAND_DARK,
                                    border: `1px solid ${alpha(BRAND, 0.25)}`,
                                  }}
                                />
                              )}
                              {stats.hasSellerGuid && (
                                <Chip
                                  size="small"
                                  label="مندوب مبيعات"
                                  sx={{
                                    fontWeight: 900,
                                    bgcolor: alpha("#1976d2", 0.12),
                                    color: "#1976d2",
                                    border: `1px solid ${alpha("#1976d2", 0.25)}`,
                                  }}
                                />
                              )}
                              {stats.hasUserGuid && (
                                <Chip
                                  size="small"
                                  label="لديه إنتاجية"
                                  sx={{
                                    fontWeight: 900,
                                    bgcolor: alpha("#9c27b0", 0.12),
                                    color: "#9c27b0",
                                    border: `1px solid ${alpha("#9c27b0", 0.25)}`,
                                  }}
                                />
                              )}
                              <Chip
                                size="small"
                                label="لديه مهام"
                                sx={{
                                  fontWeight: 900,
                                  bgcolor: alpha("#ff9800", 0.12),
                                  color: "#ff9800",
                                  border: `1px solid ${alpha("#ff9800", 0.25)}`,
                                }}
                              />
                            </Box>
                            <Typography variant="caption" color="textSecondary" sx={{ textAlign: "center" }}>
                              اضغط "تقييم شامل" لعرض التفاصيل
                            </Typography>
                          </Box>
                        </CardContent>

                        <CardActions
                          sx={{
                            px: 2,
                            pb: 2,
                            pt: 0,
                            display: "flex",
                            justifyContent: "space-between",
                            gap: 1,
                          }}
                        >
                          <Button
                            fullWidth
                            variant="contained"
                            sx={uiLayout.withUiSx({
                              borderRadius: 2,
                              fontWeight: 900,
                              bgcolor: BRAND,
                              "&:hover": { bgcolor: BRAND_DARK },
                              boxShadow: `0 10px 20px ${alpha(BRAND, 0.25)}`,
                              textTransform: "none",
                            }, uiLayout.buttonSx)}
                            onClick={() => openEmployeeDialog(u)}
                            endIcon={<ArrowForwardIosIcon />}
                          >
                            تقييم شامل
                          </Button>

                          <Tooltip title="تفاصيل">
                            <IconButton
                              onClick={() => openEmployeeDialog(u)}
                              sx={{
                                border: `1px solid ${alpha(BRAND, 0.25)}`,
                                borderRadius: 2,
                                "&:hover": { bgcolor: alpha(BRAND, 0.08) },
                              }}
                            >
                              <PersonIcon />
                            </IconButton>
                          </Tooltip>
                        </CardActions>
                      </Card>
                    </Grid>
                  );
                })}
              </Grid>

              {/* Pagination for cards */}
              <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
                <Pagination
                  count={totalPages}
                  page={page}
                  onChange={(_, v) => setPage(v)}
                  shape="rounded"
                />
              </Box>
            </>
          )}

          {/* Dialog (Details + Evaluation container) */}
          <Dialog sx={uiLayout.dialogLayoutSx}
            open={openDialog}
            onClose={closeEmployeeDialog}
            fullWidth
            maxWidth="md"
            PaperProps={{ sx: { borderRadius: 3, maxHeight: "90vh" } }}
          >
            <DialogTitle sx={{ fontWeight: 900, pb: 1 }}>
              <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <span>تفاصيل الموظف + التقييم</span>
                <Tabs value={dialogTab} onChange={handleDialogTabChange} size="small">
                  <Tab label="الملخص" />
                  <Tab label="السداد" />
                  <Tab label="التسجيلات" />
                  <Tab label="الإنتاجية" />
                  <Tab label="المهام" />
                  <Tab label="تقييم الموارد البشرية" />
                </Tabs>
              </Box>
            </DialogTitle>

            <DialogContent dividers sx={{ minHeight: 400, maxHeight: "70vh", overflow: "auto" }}>
              {!selectedUser ? (
                <Typography sx={{ opacity: 0.8 }}>—</Typography>
              ) : dialogLoading ? (
                <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", py: 4 }}>
                  <CircularProgress sx={{ color: BRAND, mb: 2 }} />
                  <Typography>جاري تحميل بيانات الموظف...</Typography>
                </Box>
              ) : dialogError ? (
                <Alert severity="error" sx={{ mb: 2 }}>
                  {dialogError}
                </Alert>
              ) : (
                <Box>
                  {/* Tab 0: Summary */}
                  {dialogTab === 0 && (
                    <Box>
                      <Card sx={{ borderRadius: 2, mb: 2, border: `1px solid ${alpha(BRAND, 0.2)}` }}>
                        <CardContent>
                          <Box sx={{ display: "flex", alignItems: "center", gap: 2, mb: 2 }}>
                            <Avatar sx={{ bgcolor: BRAND, width: 56, height: 56 }}>
                              <PersonIcon />
                            </Avatar>
                            <Box>
                              <Typography variant="h6" sx={{ fontWeight: 900 }}>
                                {selectedUser?.fullName || selectedUser?.userName || "—"}
                              </Typography>
                              <Typography sx={{ opacity: 0.8 }}>
                                @{selectedUser?.userName || "—"}
                              </Typography>
                              <Typography variant="body2" color="textSecondary">
                                الفرع: {getBranchName(selectedUser?.branchForWork)}
                              </Typography>
                            </Box>
                          </Box>

                          <Divider sx={{ my: 2 }} />

                          <Grid container spacing={2}>
                            <Grid item xs={12} md={3}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha(BRAND, 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: BRAND_DARK }}>
                                  {(() => {
                                    const key = buildPayKey(selectedUser);
                                    const st = payStats.get(key);
                                    return st?.status === "done" ? st.percent : 0;
                                  })()}%
                                </Typography>
                                <Typography variant="body2">نسبة التحصيل</Typography>
                              </Box>
                            </Grid>
                            <Grid item xs={12} md={3}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#1976d2", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#1976d2" }}>
                                  {(() => {
                                    const key = buildRegKey(selectedUser);
                                    const st = regStats.get(key);
                                    return st?.status === "done" ? st.totalRegistrations : 0;
                                  })()}
                                </Typography>
                                <Typography variant="body2">إجمالي التسجيلات</Typography>
                              </Box>
                            </Grid>
                            <Grid item xs={12} md={3}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#9c27b0", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#9c27b0" }}>
                                  {(() => {
                                    const key = buildProdKey(selectedUser);
                                    const st = productivityStats.get(key);
                                    return st?.status === "done" ? st.summary?.avgProgress || 0 : 0;
                                  })()}%
                                </Typography>
                                <Typography variant="body2">متوسط الإنتاجية</Typography>
                              </Box>
                            </Grid>
                            <Grid item xs={12} md={3}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#ff9800", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#ff9800" }}>
                                  {(() => {
                                    const key = buildTasksKey(selectedUser);
                                    const st = tasksStats.get(key);
                                    return st?.status === "done" ? st.summary?.totalTasks || 0 : 0;
                                  })()}
                                </Typography>
                                <Typography variant="body2">عدد المهام</Typography>
                              </Box>
                            </Grid>
                          </Grid>

                          <Grid container spacing={2} sx={{ mt: 2 }}>
                            <Grid item xs={12} md={4}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#4caf50", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#4caf50" }}>
                                  {hrStats.average_rating ? parseFloat(hrStats.average_rating).toFixed(1) : "0.0"}
                                </Typography>
                                <Typography variant="body2">معدل التقييم</Typography>
                              </Box>
                            </Grid>
                            <Grid item xs={12} md={4}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#2196f3", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#2196f3" }}>
                                  {hrStats.total_evaluations || 0}
                                </Typography>
                                <Typography variant="body2">عدد التقييمات</Typography>
                              </Box>
                            </Grid>
                            <Grid item xs={12} md={4}>
                              <Box sx={{ textAlign: "center", p: 2, bgcolor: alpha("#9c27b0", 0.08), borderRadius: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 900, color: "#9c27b0" }}>
                                  {currentEvaluation ? "✓" : "✗"}
                                </Typography>
                                <Typography variant="body2">تقييم الشهر</Typography>
                              </Box>
                            </Grid>
                          </Grid>

                          <Alert severity="info" sx={{ borderRadius: 2, mt: 2 }}>
                            <Typography fontWeight={700}>فترة التقييم:</Typography>
                            <Typography>الشهر: {evalMonth}/{evalYear}</Typography>
                            <Typography variant="body2">
                              اضغط على التبويبات لعرض التفاصيل الكاملة لكل قسم
                            </Typography>
                          </Alert>
                        </CardContent>
                      </Card>
                    </Box>
                  )}

                  {/* Tab 1: Payments */}
                  {dialogTab === 1 && (
                    <Box>
                      <Alert severity="info" sx={{ mb: 2, borderRadius: 2 }}>
                        <Typography fontWeight={700}>فترة السداد والتحصيل:</Typography>
                        <Typography>من 15/{evalMonth}/{evalYear} إلى 14/{evalMonth + 1 > 12 ? 1 : evalMonth + 1}/{evalMonth + 1 > 12 ? evalYear + 1 : evalYear}</Typography>
                      </Alert>
                      {renderPayChip(selectedUser)}
                    </Box>
                  )}

                  {/* Tab 2: Registrations */}
                  {dialogTab === 2 && (
                    <Box>
                      <Alert severity="info" sx={{ mb: 2, borderRadius: 2 }}>
                        <Typography fontWeight={700}>فترة التسجيلات:</Typography>
                        <Typography>من أول {evalMonth}/{evalYear} إلى آخر الشهر</Typography>
                      </Alert>
                      {renderRegDetails(selectedUser)}
                    </Box>
                  )}

                  {/* Tab 3: Productivity */}
                  {dialogTab === 3 && (
                    <Box>
                      <Alert severity="info" sx={{ mb: 2, borderRadius: 2 }}>
                        <Typography fontWeight={700}>فترة الإنتاجية:</Typography>
                        <Typography>من أول {evalMonth}/{evalYear} إلى آخر الشهر</Typography>
                      </Alert>
                      <Typography variant="h6" sx={{ mb: 2, fontWeight: 700, color: "#9c27b0" }}>
                        <EmojiEventsIcon sx={{ marginInlineEnd: 1, verticalAlign: "middle" }} />
                        الإنتاجية الأسبوعية
                      </Typography>
                      {renderProdDetails(selectedUser)}
                    </Box>
                  )}

                  {/* Tab 4: Tasks */}
                  {dialogTab === 4 && (
                    <Box>
                      <Alert severity="info" sx={{ mb: 2, borderRadius: 2 }}>
                        <Typography fontWeight={700}>فترة المهام:</Typography>
                        <Typography>من أول {evalMonth}/{evalYear} إلى آخر الشهر</Typography>
                      </Alert>
                      <Typography variant="h6" sx={{ mb: 2, fontWeight: 700, color: "#ff9800" }}>
                        <AssignmentIcon sx={{ marginInlineEnd: 1, verticalAlign: "middle" }} />
                        المهام المخصصة
                      </Typography>
                      {renderTasksDetails(selectedUser)}
                    </Box>
                  )}

                  {/* Tab 5: HR Evaluation */}
                  {dialogTab === 5 && (
                    <Box>
                      <Alert severity="info" sx={{ mb: 2, borderRadius: 2 }}>
                        <Typography fontWeight={700}>فترة تقييم الموارد البشرية:</Typography>
                        <Typography>شهر {evalMonth} سنة {evalYear}</Typography>
                        <Typography variant="body2">
                          التقييم من 1 إلى 5 نجوم مع إمكانية إضافة ملاحظات وتوصيات
                        </Typography>
                      </Alert>
                      <Typography variant="h6" sx={{ mb: 2, fontWeight: 700, color: "#4caf50" }}>
                        <RateReview sx={{ marginInlineEnd: 1, verticalAlign: "middle" }} />
                        تقييم الموارد البشرية
                      </Typography>
                      {renderHREvaluationDetails()}
                    </Box>
                  )}
                </Box>
              )}
            </DialogContent>

            <DialogActions sx={uiLayout.withUiSx({ p: 2 }, uiLayout.dialogActionsSx)}>
              <Button
                onClick={closeEmployeeDialog}
                variant="outlined"
                sx={uiLayout.withUiSx({
                  borderRadius: 2,
                  borderColor: alpha(BRAND, 0.5),
                  color: BRAND_DARK,
                  "&:hover": {
                    borderColor: BRAND,
                    bgcolor: alpha(BRAND, 0.08),
                  },
                }, uiLayout.buttonSx)}
              >
                إغلاق
              </Button>

              <Button
                variant="contained"
                sx={uiLayout.withUiSx({
                  borderRadius: 2,
                  fontWeight: 900,
                  bgcolor: BRAND,
                  "&:hover": { bgcolor: BRAND_DARK },
                  boxShadow: `0 10px 20px ${alpha(BRAND, 0.25)}`,
                }, uiLayout.buttonSx)}
                onClick={() => {
                  console.log("Save evaluation for", selectedUser, {
                    evalMonth,
                    evalYear,
                    fromDate,
                    toDate,
                    regFromDate,
                    regToDate,
                    tasksFromDate,
                    tasksToDate,
                  });
                }}
              >
                حفظ التقييم
              </Button>
            </DialogActions>
          </Dialog>
        </Container>
      </Box>
    </Box></NavigationShell>
  );
};

export default EmployeeEvaluationPage;

src\\components\\EmployeeInfoCard.js:
import { hrChipSx } from "./hrControlStyles";
import React, { useEffect, useRef, useState } from "react";
import {
  Alert,
  Avatar,
  Box,
  Card,
  Chip,
  CircularProgress,
  IconButton,
  Menu,
  MenuItem,
  Snackbar,
  Stack,
  Typography
} from "@mui/material";
import { alpha } from "@mui/material/styles";
import { motion } from "framer-motion";
import {
  CalendarMonth,
  CameraAlt,
  Delete,
  Edit,
  InfoOutlined as Notifications,
  Security,
  Work
} from "@mui/icons-material";

const COLOR_SCHEME = {
  primary: "#057546",
  primaryDark: "#034d31",
  primaryLight: "#e6f3ee",
  accent: "#ae1e21",
  white: "#fefefe",
  text: "#1f2d3d",
  muted: "#6f8a81",
  gold: "#f4b740"
};

const API_BASE_URL = "https://filesregsiteration.sstli.com/erp/image_api.php";

const fadeIn = {
  hidden: { opacity: 0, y: 28, scale: 0.985 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.55, ease: "easeOut" }
  }
};

const glassChipSx = {
  color: COLOR_SCHEME.white,
  fontWeight: 900,
  borderRadius: 999,
  background: "rgba(255,255,255,0.16)",
  border: "1px solid rgba(255,255,255,0.28)",
  backdropFilter: "blur(10px)",
  fontSize: { xs: "0.62rem", sm: "0.7rem", md: "0.78rem" },
  height: { xs: 26, sm: 29, md: 32 },
  "& .MuiChip-label": { px: { xs: 0.8, sm: 1 } },
  "& .MuiChip-icon": {
    color: COLOR_SCHEME.white,
    fontSize: { xs: 15, sm: 17, md: 19 }
  }
};

const EmployeeInfoCard = ({ user, isHRUser, isHRManager }) => {
  const [imageUrl, setImageUrl] = useState(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success"
  });

  const fileInputRef = useRef(null);

  const displayName = user?.fullName || user?.FullName || "اسم الموظف";
  const userName = user?.userName || user?.UserName || "اسم المستخدم";
  const department = user?.userDepart || user?.UserDepart || user?.departName || "القسم";
  const employeeCode = user?.code || user?.Code || "غير محدد";
  const isActive = Boolean(user?.staut_ ?? user?.staut ?? user?.Staut);
  const firstLetter = displayName && displayName !== "اسم الموظف" ? displayName.charAt(0) : "U";

  useEffect(() => {
    if (user?.guid || user?.Guid) {
      fetchUserImage();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.guid, user?.Guid]);

  useEffect(() => {
    return () => {
      if (imageUrl) URL.revokeObjectURL(imageUrl);
    };
  }, [imageUrl]);

  const getUserGuid = () => user?.guid || user?.Guid || "";

  const fetchUserImage = async () => {
    const userGuid = getUserGuid();
    if (!userGuid) return;

    try {
      setImageLoading(true);
      const timestamp = new Date().getTime();
      const response = await fetch(
        `${API_BASE_URL}?action=get&userGuid=${encodeURIComponent(userGuid)}&t=${timestamp}`
      );

      if (response.ok) {
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        setImageUrl((oldUrl) => {
          if (oldUrl) URL.revokeObjectURL(oldUrl);
          return url;
        });
      } else {
        setImageUrl(null);
      }
    } catch (error) {
      console.error("Error while fetching image:", error);
      setImageUrl(null);
    } finally {
      setImageLoading(false);
    }
  };

  const handleMenuOpen = (event) => setAnchorEl(event.currentTarget);
  const handleMenuClose = () => setAnchorEl(null);

  const handleImageUpload = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const userGuid = getUserGuid();
    if (!userGuid) {
      setSnackbar({ open: true, message: "لا يمكن قراءة المستخدم الحالي", severity: "error" });
      return;
    }

    try {
      setImageLoading(true);
      const formData = new FormData();
      formData.append("file", file);
      formData.append("userGuid", userGuid);

      const response = await fetch(`${API_BASE_URL}?action=upload`, {
        method: "POST",
        body: formData
      });

      const textResult = await response.text();
      let result;

      try {
        result = JSON.parse(textResult);
      } catch {
        result = { message: "Invalid server response" };
      }

      if (response.ok) {
        setSnackbar({
          open: true,
          message: result.message || "تم رفع الصورة بنجاح",
          severity: "success"
        });
        await fetchUserImage();
      } else {
        setSnackbar({
          open: true,
          message: result.message || "فشل في رفع الصورة",
          severity: "error"
        });
      }
    } catch (error) {
      console.error("Error during upload:", error);
      setSnackbar({ open: true, message: "حدث خطأ أثناء رفع الصورة", severity: "error" });
    } finally {
      setImageLoading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
      handleMenuClose();
    }
  };

  const handleDeleteImage = async () => {
    const userGuid = getUserGuid();
    if (!userGuid) {
      setSnackbar({ open: true, message: "لا يمكن قراءة المستخدم الحالي", severity: "error" });
      return;
    }

    try {
      setImageLoading(true);
      const response = await fetch(`${API_BASE_URL}?action=delete`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userGuid })
      });

      const textResult = await response.text();
      let result;

      try {
        result = JSON.parse(textResult);
      } catch {
        result = { message: "Invalid delete response" };
      }

      if (response.ok) {
        setSnackbar({
          open: true,
          message: result.message || "تم حذف الصورة بنجاح",
          severity: "success"
        });
        setImageUrl((oldUrl) => {
          if (oldUrl) URL.revokeObjectURL(oldUrl);
          return null;
        });
      } else {
        setSnackbar({
          open: true,
          message: result.message || "فشل في حذف الصورة",
          severity: "error"
        });
      }
    } catch (error) {
      console.error("Error during delete:", error);
      setSnackbar({ open: true, message: "حدث خطأ أثناء حذف الصورة", severity: "error" });
    } finally {
      setImageLoading(false);
      handleMenuClose();
    }
  };

  const handleSnackbarClose = () => setSnackbar((prev) => ({ ...prev, open: false }));

  return (
    <motion.div variants={fadeIn} initial="hidden" animate="visible">
      <Card
        sx={{
          p: { xs: 1.25, sm: 1.7, md: 2.2, lg: 3 },
          borderRadius: { xs: 3, sm: 4, md: 5 },
          background: `linear-gradient(135deg, ${COLOR_SCHEME.primary} 0%, ${COLOR_SCHEME.primaryDark} 100%)`,
          color: COLOR_SCHEME.white,
          boxShadow: `0 24px 60px ${alpha(COLOR_SCHEME.primary, 0.28)}`,
          position: "relative",
          overflow: "hidden",
          mb: { xs: 1.2, sm: 1.8, md: 2.4 },
          border: "1px solid rgba(255,255,255,0.18)",
          "&:before": {
            content: '""',
            position: "absolute",
            width: 260,
            height: 260,
            borderRadius: "50%",
            background: "rgba(255,255,255,0.10)",
            top: -110,
            right: -70
          },
          "&:after": {
            content: '"SSTLI"',
            position: "absolute",
            right: 24,
            bottom: 10,
            fontWeight: 1000,
            fontSize: { xs: 40, md: 72 },
            letterSpacing: 5,
            color: "rgba(255,255,255,0.055)",
            pointerEvents: "none"
          }
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignItems: { xs: "center", sm: "center" },
            flexDirection: { xs: "column", sm: "row" },
            gap: { xs: 1.2, sm: 1.8, md: 2.4 },
            position: "relative",
            zIndex: 2
          }}
        >
          <Box sx={{ position: "relative", alignSelf: "center" }}>
            <Box
              sx={{
                p: 0.8,
                borderRadius: "50%",
                background: "rgba(255,255,255,0.16)",
                border: "1px solid rgba(255,255,255,0.24)",
                boxShadow: "0 16px 32px rgba(0,0,0,0.14)"
              }}
            >
              {imageLoading ? (
                <Box
                  sx={{
                    width: { xs: 66, sm: 82, md: 96, lg: 108 },
                    height: { xs: 66, sm: 82, md: 96, lg: 108 },
                    borderRadius: "50%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    background: "rgba(255,255,255,0.10)",
                    border: "4px solid rgba(255,255,255,0.35)"
                  }}
                >
                  <CircularProgress size={34} sx={{ color: COLOR_SCHEME.white }} />
                </Box>
              ) : (
                <Avatar
                  sx={{
                    width: { xs: 66, sm: 82, md: 96, lg: 108 },
                    height: { xs: 66, sm: 82, md: 96, lg: 108 },
                    border: "4px solid rgba(255,255,255,0.34)",
                    fontSize: { xs: "1.7rem", sm: "2rem", md: "2.3rem" },
                    fontWeight: 1000,
                    background: imageUrl
                      ? "transparent"
                      : `linear-gradient(135deg, ${COLOR_SCHEME.white} 0%, ${COLOR_SCHEME.primaryLight} 100%)`,
                    color: COLOR_SCHEME.primary
                  }}
                  src={imageUrl || undefined}
                >
                  {!imageUrl && firstLetter}
                </Avatar>
              )}
            </Box>

            <IconButton
              sx={{
                position: "absolute",
                bottom: { xs: 1, sm: 3, md: 5 },
                right: { xs: 1, sm: 3, md: 5 },
                width: { xs: 28, sm: 32, md: 36 },
                height: { xs: 28, sm: 32, md: 36 },
                background: COLOR_SCHEME.accent,
                color: COLOR_SCHEME.white,
                border: "3px solid rgba(255,255,255,0.95)",
                boxShadow: "0 8px 18px rgba(0,0,0,0.20)",
                "&:hover": {
                  background: "#8f171a",
                  transform: "scale(1.04)"
                },
                transition: "all 0.2s ease"
              }}
              size="small"
              onClick={handleMenuOpen}
              disabled={imageLoading}
            >
              <Edit fontSize="small" />
            </IconButton>
          </Box>

          <Box sx={{ flex: 1, width: "100%", textAlign: { xs: "center", sm: "start" } }}>
            <Typography
              variant="h4"
              sx={{
                fontWeight: 1000,
                mb: 0.8,
                letterSpacing: "0.2px",
                fontSize: { xs: "1.18rem", sm: "1.4rem", md: "1.72rem", lg: "1.95rem" }
              }}
            >
              {displayName}
            </Typography>

            <Typography variant="h6" sx={{ opacity: 0.92, mb: 0.45, fontWeight: 850, fontSize: { xs: '0.78rem', sm: '0.9rem', md: '1.02rem' } }}>
              {userName}
            </Typography>

            <Typography variant="body1" sx={{ opacity: 0.84, fontWeight: 750, fontSize: { xs: "0.75rem", sm: '0.78rem', md: '0.88rem' } }}>
              {department} • {employeeCode}
            </Typography>

            {isHRUser && (
              <Stack
                direction="row"
                gap={1}
                flexWrap="wrap"
                justifyContent={{ xs: "center", sm: "flex-start" }}
                sx={{ mt: { xs: 1, sm: 1.4 } }}
              >
                <Chip
                  label={isHRManager ? "مدير موارد بشرية" : "موظف موارد بشرية"}
                  size="small"
                  sx={{
                    background: COLOR_SCHEME.white,
                    color: COLOR_SCHEME.primary,
                    fontWeight: 1000,
                    borderRadius: 999
                  }}
                />
                <Chip
                  label="إدارة الطلبات"
                  size="small"
                  sx={{
                    ...glassChipSx,
                    borderColor: "rgba(255,255,255,0.42)"
                  }}
                />
              </Stack>
            )}
          </Box>

          <Box
            sx={{
              minWidth: { xs: "100%", sm: 150, md: 175 },
              textAlign: "center",
              p: { xs: 0.8, sm: 1.05, md: 1.35 },
              borderRadius: { xs: 2.4, sm: 3, md: 4 },
              background: "rgba(255,255,255,0.12)",
              border: "1px solid rgba(255,255,255,0.18)",
              backdropFilter: "blur(10px)"
            }}
          >
            <Typography variant="body1" sx={{ opacity: 0.92, mb: 0.7, fontWeight: 900, fontSize: { xs: "0.75rem", sm: '0.76rem', md: '0.84rem' } }}>
              {new Date().toLocaleDateString("ar-EG", {
                day: "numeric",
                month: "long",
                year: "numeric"
              })}
            </Typography>
            <Chip
              icon={<CalendarMonth />}
              label={isActive ? "الحالة: نشط" : "الحالة: غير نشط"}
              sx={[hrChipSx(), {
                ...glassChipSx,
                background: isActive ? "rgba(255,255,255,0.18)" : alpha(COLOR_SCHEME.accent, 0.22)
              }]}
            />
          </Box>
        </Box>

        <Stack
          direction="row"
          flexWrap="wrap"
          gap={{ xs: 0.6, sm: 0.8, md: 1.1 }}
          sx={{ mt: { xs: 1.2, sm: 1.7, md: 2.3 }, position: "relative", zIndex: 2 }}
        >
