            flexDirection: { xs: "column", md: "row" },
            gap: { xs: 0.5, md: 0.7 },
            position: "relative",
            zIndex: 2
          }}
        >
          <Box sx={{ position: "relative", alignSelf: { xs: "center", md: "auto" } }}>
            <Box
              sx={{
                p: 0.45,
                borderRadius: "50%",
                background: "rgba(255,255,255,0.16)",
                border: "1px solid rgba(255,255,255,0.24)",
                boxShadow: "0 16px 32px rgba(0,0,0,0.14)"
              }}
            >
              {imageLoading ? (
                <Box
                  sx={{
