import * as uiLayout from './common/uiLayout';
import React, { useEffect, useMemo, useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  CircularProgress,
  Alert,
  TextField,
  Chip,
  Stack,
  Divider,
  Checkbox,
  FormControlLabel,
  alpha,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from "@mui/material";
import { DatePicker } from "@mui/x-date-pickers";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { ar } from "date-fns/locale";
import { format, parseISO, isValid } from "date-fns";
import Autocomplete from "@mui/material/Autocomplete";
import DescriptionIcon from "@mui/icons-material/Description";
import CloudDownloadIcon from "@mui/icons-material/CloudDownload";
import BusinessIcon from "@mui/icons-material/Business";
import DeleteSweepIcon from "@mui/icons-material/DeleteSweep";
import HtmlIcon from "@mui/icons-material/Html";
import PictureAsPdfIcon from "@mui/icons-material/PictureAsPdf";

// ===== Helpers =====
const safeParseReportDate = (val) => {
  if (!val) return null;

  try {
    const isoTry = parseISO(val);
    if (isValid(isoTry)) return isoTry;
  } catch {}

  try {
    const fixed = val.replace(" ", "T");
    const d = parseISO(fixed);
    if (isValid(d)) return d;
  } catch {}

  return null;
};

const inRange = (d, from, to) => {
  if (!d || !from || !to) return false;
  const t = d.getTime();
  return t >= from.getTime() && t <= to.getTime();
};

const statusLabel = (status) => {
  const map = {
    present: "حاضر",
    absent: "غائب",
    permission: "استئذان",
    leave: "إجازة",
  };
  return map[status] || "غير محدد";
};

const getStatusColor = (status) => {
  const colors = {
    present: "#4caf50",
    absent: "#f44336",
    permission: "#ff9800",
    leave: "#2196f3",
    "غير محدد": "#9e9e9e",
  };
  return colors[status] || "#9e9e9e";
};

const countAttendance = (employeeAttendance = []) => {
  const res = { حاضر: 0, غائب: 0, استئذان: 0, "إجازة": 0, "غير محدد": 0 };
  for (const e of employeeAttendance) {
    res[statusLabel(e.status)] = (res[statusLabel(e.status)] || 0) + 1;
  }
  return res;
};

const formatArabicDate = (date) => {
  return format(date, "yyyy/MM/dd");
};

// ===== HTML Report Generator =====
const generateHTMLReport = ({ from, to, branchesPayload, includeDetails, theme }) => {
  const primaryColor = theme?.palette?.primary?.main || "#80b49e";
  const secondaryColor = theme?.palette?.secondary?.main || "#607d8b";
  
  const html = `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>تقارير الفروع ${formatArabicDate(from)} - ${formatArabicDate(to)}</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800&display=swap');
        
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        
        body {
            font-family: 'Cairo', sans-serif;
            line-height: 1.8;
            color: #333;
            background: #f9f9f9;
            padding: 20px;
            direction: rtl;
        }
        
        .report-container {
            max-width: 1200px;
            margin: 0 auto;
            background: white;
            border-radius: 20px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
            overflow: hidden;
            border: 1px solid #eaeaea;
        }
        
        .header {
            background: linear-gradient(135deg, ${primaryColor}, ${secondaryColor});
            color: white;
            padding: 40px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }
        
        .header::before {
            content: '';
            position: absolute;
            top: -50%;
            right: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(255,255,255,0.1) 1px, transparent 1px);
            background-size: 30px 30px;
            opacity: 0.2;
        }
        
        .header h1 {
