                                `).join('')}
                            </tbody>
                        </table>
                        
                        ${question.type === 'radio' || question.type === 'checkbox' ? `
                            <div style="margin-top: 20px; padding: 15px; background: #f8fbfa; border-radius: 8px;">
                                <h4 style="color: #6a9a87; margin-bottom: 10px;">📈 تحليل الإجابات:</h4>
