            value={isExternal ? externalSurvey.max_responses : survey.max_responses}
            onChange={(e) => isExternal ?
              setExternalSurvey(prev => ({ ...prev, max_responses: e.target.value })) :
              setSurvey(prev => ({ ...prev, max_responses: e.target.value }))
