            sx={uiLayout.withUiSx(fieldStyle, uiLayout.formFieldSx)}
            variant="outlined"
           inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
        </Grid>
      </Grid>
    </Fade>
  );

  const renderRecipientsStep = () => (
