              </TableCell>
              <TableCell sx={{ fontFamily: '"Cairo", sans-serif' }}>
                {survey.target_users?.length || 0} موظف
              </TableCell>
              <TableCell sx={{ fontFamily: '"Cairo", sans-serif' }}>
                {surveyResponses[survey.id]?.length || 0} رد
              </TableCell>
              <TableCell>
  <Box
    sx={uiLayout.withUiSx({
      display: 'flex',
      gap: 1,
      flexDirection: 'column',
      minWidth: 150
    }, uiLayout.actionBarSx)}
  >
    <Button
      variant="outlined"
      size="small"
      startIcon={<Visibility />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: primaryColor,
        color: primaryDark,
        '&:hover': {
          borderColor: primaryDark,
          backgroundColor: `${primaryColor}10`
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleViewResponses(survey, false)}
    >
      عرض الردود
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<Edit />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: primaryColor,
        color: primaryDark,
        '&:hover': {
          borderColor: primaryDark,
          backgroundColor: `${primaryColor}10`
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleEditSurvey(survey)}
    >
      تعديل
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<ContentCopy />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: '#1976d2',
        color: '#1976d2',
        '&:hover': {
          borderColor: '#115293',
          backgroundColor: 'rgba(25, 118, 210, 0.08)'
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleDuplicateSurvey(survey, false)}
    >
      نسخ
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<Delete />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: '#d32f2f',
        color: '#d32f2f',
        '&:hover': {
          borderColor: '#b71c1c',
          backgroundColor: 'rgba(211, 47, 47, 0.08)'
