                  </Typography>

                  {survey.description && (
                    <Typography
                      variant="caption"
                      sx={{
                        fontFamily: '"Cairo", sans-serif',
                        color: '#666',
                        display: 'block',
                        maxWidth: 260,
                        overflow: 'hidden',
