                    {diplomaNames.length > 2 && (
                      <Chip
                        label={`+${diplomaNames.length - 2} دبلومات`}
                        size="small"
                        sx={primaryChipStyle}
                      />
                    )}
                  </Box>
                </Box>
              </TableCell>

              {/* عدد الردود */}
              <TableCell
                sx={{
                  fontFamily: '"Cairo", sans-serif',
                  textAlign: 'center',
                  fontWeight: 'bold'
                }}
