              {/* لينكات الاستبيان */}
              <TableCell sx={{ minWidth: 380 }}>
                {survey.is_trainer_survey && getSurveyTrainers(survey).length > 0 ? (
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                    {getSurveyTrainers(survey).map((trainer) => {
