                      return (
                        <Box
  key={trainer.trainerGuid}
  sx={uiLayout.withUiSx({
    p: 1,
    border: `1px solid ${primaryLight}`,
    borderRadius: 2,
    backgroundColor: '#fff',
    display: 'grid',
    gridTemplateColumns: '1fr auto auto auto',
    alignItems: 'center',
    gap: 1
  }, uiLayout.actionBarSx)}
>
  <Chip
    label={trainerName}
    size="small"
    sx={{
      ...primaryChipStyle,
      maxWidth: 170,
      '& .MuiChip-label': {
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap'
      }
    }}
  />

  <Button
    variant="contained"
    size="small"
    sx={uiLayout.withUiSx({
      backgroundColor: '#2196f3',
      color: 'white',
      fontFamily: '"Cairo", sans-serif',
      fontSize: "0.75rem",
      minWidth: 80,
      '&:hover': {
        backgroundColor: '#1976d2'
      }
    }, uiLayout.buttonSx)}
    onClick={() => copySurveyLink(trainerSurveyLink)}
  >
    نسخ
  </Button>

  <IconButton
    size="small"
    onClick={() =>
      exportSurveyQrCode(
        trainerSurveyLink,
        survey.title,
        trainerName
      )
    }
    sx={{
      border: `1px solid ${primaryLight}`,
      color: primaryDark,
      backgroundColor: '#f8fbfa',
      '&:hover': {
        backgroundColor: '#e8f5f1'
      }
    }}
    title="تصدير QR Code"
  >
    <QrCode2 fontSize="small" />
  </IconButton>

  <Button
    variant="outlined"
    size="small"
    sx={uiLayout.withUiSx({
      fontFamily: '"Cairo", sans-serif',
      fontSize: "0.75rem",
      borderColor: primaryColor,
      color: primaryDark,
      minWidth: 95,
      '&:hover': {
        borderColor: primaryDark,
        backgroundColor: `${primaryColor}10`
      }
    }, uiLayout.buttonSx)}
    onClick={() => handleViewResponses(survey, true, trainer)}
  >
    عرض الردود
  </Button>
</Box>
                      );
                    })}
                  </Box>
                ) : (
                  <Box
                    sx={{
                      display: 'grid',
                      gridTemplateColumns: '1fr auto auto',
                      alignItems: 'center',
                      gap: 1,
                      minWidth: 320
                    }}
                  >
                    <Typography
                      variant="caption"
                      sx={{
                        color: primaryDark,
                        fontFamily: '"Cairo", sans-serif',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}
                      title={surveyLink}
                    >
                      {surveyLink}
                    </Typography>

                    <Button
                      variant="contained"
                      size="small"
                      sx={uiLayout.withUiSx({
                        backgroundColor: '#2196f3',
                        color: 'white',
                        fontFamily: '"Cairo", sans-serif',
                        fontSize: '0.75rem',
                        minWidth: 80,
                        '&:hover': {
                          backgroundColor: '#1976d2'
                        }
                      }, uiLayout.buttonSx)}
                      onClick={() => copySurveyLink(surveyLink)}
                    >
                      نسخ
                    </Button>

                    <IconButton
                      size="small"
                      onClick={() => exportSurveyQrCode(surveyLink, survey.title)}
                      sx={{
                        border: `1px solid ${primaryLight}`,
                        color: primaryDark,
                        backgroundColor: '#f8fbfa',
                        '&:hover': {
                          backgroundColor: '#e8f5f1'
                        }
                      }}
                      title="تصدير QR Code"
                    >
                      <QrCode2 fontSize="small" />
                    </IconButton>
                  </Box>
                )}
              </TableCell>

              {/* الإجراءات */}
              <TableCell>
  <Box
    sx={uiLayout.withUiSx({
      display: 'flex',
      gap: 1,
      flexDirection: 'column',
      minWidth: 150
    }, uiLayout.actionBarSx)}
  >
    <Button
      variant="outlined"
      size="small"
      startIcon={<Visibility />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: primaryColor,
        color: primaryDark,
        '&:hover': {
          borderColor: primaryDark,
          backgroundColor: `${primaryColor}10`
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleViewResponses(survey, true)}
    >
      عرض كل الردود
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<Edit />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: primaryColor,
        color: primaryDark,
        '&:hover': {
          borderColor: primaryDark,
          backgroundColor: `${primaryColor}10`
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleEditExternalSurvey(survey)}
    >
      تعديل
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<ContentCopy />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: '#1976d2',
        color: '#1976d2',
        '&:hover': {
          borderColor: '#115293',
          backgroundColor: 'rgba(25, 118, 210, 0.08)'
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleDuplicateSurvey(survey, true)}
    >
      نسخ
    </Button>

    <Button
      variant="outlined"
      size="small"
      startIcon={<Delete />}
      sx={uiLayout.withUiSx({
        fontFamily: '"Cairo", sans-serif',
        fontSize: '0.75rem',
        borderColor: '#d32f2f',
        color: '#d32f2f',
        '&:hover': {
          borderColor: '#b71c1c',
          backgroundColor: 'rgba(211, 47, 47, 0.08)'
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleDeleteSurvey(survey.id, true)}
    >
      حذف
    </Button>

    <Button
      startIcon={<Download />}
      variant="contained"
      size="small"
      sx={uiLayout.withUiSx({
        backgroundColor: '#28a745',
        color: 'white',
        fontFamily: '"Cairo", sans-serif',
        '&:hover': {
          backgroundColor: '#218838'
        }
      }, uiLayout.buttonSx)}
      onClick={() => handleExportReport(survey, true)}
      disabled={
        !externalSurveyResponses[survey.id] ||
        externalSurveyResponses[survey.id].length === 0
      }
    >
      تصدير التقرير
    </Button>
  </Box>
</TableCell>
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  </TableContainer>
);

  const renderResponsesView = () => (
    <Box>
      <Typography variant="h6" gutterBottom sx={{ color: primaryDark, fontFamily: '"Cairo", sans-serif', mb: 3 }}>
        الردود على الاستبيانات الداخلية
      </Typography>
      {allSurveys.map((survey) => (
        <Card key={survey.id} sx={{ ...cardStyle, mb: 3 }}>
          <CardContent>
            <Box sx={uiLayout.withUiSx({ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }, uiLayout.pageHeaderSx)}>
              <Typography variant="h6" sx={{ color: primaryDark, fontFamily: '"Cairo", sans-serif' }}>
                {survey.title}
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                <Chip 
                  label={`${surveyResponses[survey.id]?.length || 0} رد`}
                  color="primary"
                />
                <Button
                  startIcon={<Download />}
                  variant="contained"
                  size="small"
                  sx={uiLayout.withUiSx({
                    backgroundColor: '#28a745',
                    color: 'white',
                    fontFamily: '"Cairo", sans-serif',
                    '&:hover': {
                      backgroundColor: '#218838',
                    }
                  }, uiLayout.buttonSx)}
                  onClick={() => handleExportReport(survey, false)}
                  disabled={!surveyResponses[survey.id] || surveyResponses[survey.id].length === 0}
                >
                  تصدير التقرير
                </Button>
              </Box>
            </Box>
            
            {surveyResponses[survey.id]?.map((response, index) => (
              <Accordion key={index} sx={{ mb: 2, border: `1px solid ${primaryLight}`, borderRadius: '8px !important' }}>
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                    <EmployeeAvatar 
                      userGuid={response.employee_guid} 
                      employeeName={response.employee_name} 
                    />
                    <Box sx={{ flexGrow: 1 }}>
                      <Typography sx={{ fontWeight: 'bold', fontFamily: '"Cairo", sans-serif' }}>
                        {response.employee_name}
                      </Typography>
                      <Typography variant="body2" sx={{ color: primaryDark, fontFamily: '"Cairo", sans-serif' }}>
                        {response.department} - {formatDate(response.submitted_at)}
                      </Typography>
                    </Box>
                  </Box>
                </AccordionSummary>
                <AccordionDetails>
                  {renderResponseDetails(response, survey.questions || [], false)}
                </AccordionDetails>
