        </Stack>}
      </DialogContent>
      <DialogActions sx={uiLayout.dialogActionsSx}><Button sx={uiLayout.buttonSx} onClick={()=>setOpen(false)}>إغلاق</Button></DialogActions>
    </Dialog>
  </>;
}

