                        />
                      </TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell sx={{ fontWeight: 'bold', color: primaryDark }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
