                        borderRadius: isCompact ? 1.35 : 2,
                        overflowX: "hidden",
                        boxShadow: "0 10px 28px rgba(31,45,61,0.18)",

                       "& .MuiMenuItem-root": {
  minHeight: isPhone ? 38 : isTablet ? 44 : 46,

