                                {invoice.isReturned ? " • تم استرجاعها" : ""}
                              </Typography>
                            </Box>

                            {isTablet && (
                              <Typography
                                sx={{
                                  fontSize: "0.75rem",
                                  fontWeight: 900,
                                  color: invoice.isReturned
                                    ? accentColor
                                    : primaryColor,
                                  whiteSpace: "nowrap"
                                }}
                              >
                                {invoice.isReturned ? "مسترجعة" : "متاحة"}
                              </Typography>
                            )}
                          </>
                        ) : (
                          <>
                            رقم {invoice.code} — {invoice.date} —{" "}
                            {invoice.documentType}
                            {invoice.isReturned
                              ? " — تم استرجاعها"
                              : ""}
