                <Select
                  value={selectedDocGuid}
                  label="نوع المستند"
                  onChange={(event) =>
                    setSelectedDocGuid(event.target.value)
                  }
                  MenuProps={{
                    anchorOrigin: {
                      vertical: "bottom",
                      horizontal: "right"
                    },
                    transformOrigin: {
                      vertical: "top",
                      horizontal: "right"
                    },
                    MenuListProps: {
                      dense: true,
                      sx: { p: isCompact ? 0.25 : 0.75 }
                    },
                    PaperProps: {
                      sx: {
                        width: isPhone
                          ? "min(260px, calc(100vw - 20px))"
                          : isTablet
                            ? "min(360px, calc(100vw - 32px))"
