                          py: isPhone ? 0.35 : isTablet ? 0.48 : 0.75,
                          px: isPhone ? 0.65 : isTablet ? 0.85 : 1.5,
                          borderRadius: isCompact ? 0.9 : 0,
                          mb: isCompact ? 0.15 : 0,
                          fontSize: isPhone ? "0.48rem" : isTablet ? "0.56rem" : "0.875rem",
