                      <TableCell
                        align="center"
                        sx={{ fontWeight: 950 }}
                      >
                        الكمية
                      </TableCell>

                      <TableCell
                        align="center"
                        sx={{ fontWeight: 950 }}
                      >
                        التكلفة
                      </TableCell>

                      <TableCell
                        align="center"
                        sx={{ fontWeight: 950 }}
                      >
                        الضريبة %
                      </TableCell>

                      <TableCell
                        align="center"
                        sx={{
                          fontWeight: 950,
                          display: isPhone ? "none" : "table-cell"
