                            fontWeight: 850,
                            maxWidth: isPhone ? 110 : isTablet ? 180 : undefined,
                            whiteSpace: "nowrap",
                            overflow: "hidden",
                            textOverflow: "ellipsis"
                          }}
                        >
                          {item.name}
