                                index,
                                "cost",
                                event.target.value
                              )
                            }
                            inputProps={{
                              min: 0,
                              step: "0.01",
                              style: {
                                textAlign: "center"
                              , direction: "ltr", unicodeBidi: "isolate" }
                            , dir: "ltr" }}
                            sx={uiLayout.withUiSx({ width: 120 }, uiLayout.formFieldSx)}
                          />
                        </TableCell>

                        <TableCell align="center">
                          <TextField InputLabelProps={{ shrink: true }}
                            size="small"
                            type="number"
                            value={item.taxRate}
                            onChange={(event) =>
                              updateItem(
                                index,
                                "taxRate",
                                event.target.value
                              )
                            }
                            inputProps={{
                              min: 0,
                              step: "0.01",
                              style: {
                                textAlign: "center"
                              , direction: "ltr", unicodeBidi: "isolate" }
                            , dir: "ltr" }}
                            sx={uiLayout.withUiSx({ width: 100 }, uiLayout.formFieldSx)}
                          />
                        </TableCell>

                        <TableCell
                          align="center"
                          sx={{ display: isPhone ? "none" : "table-cell" }}
                        >
                          {money(item.tax)}
                        </TableCell>

                        <TableCell
                          align="center"
                          sx={{ fontWeight: 900 }}
                        >
                          {money(item.subTotal)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>

              <Grid container spacing={isPhone ? 0.35 : isTablet ? 0.55 : 2}>
                <Grid item xs={4} sm={4} md={4}>
                  <Paper
                    variant="outlined"
                    sx={{
                      p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                      minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                      borderRadius: isCompact ? 1.3 : undefined,
                      textAlign: "center"
                    }}
                  >
                    <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>
                      الإجمالي
                    </Typography>

                    <Typography
                      sx={{
                        color: "#d71920",
                        fontSize: isPhone ? 14 : isTablet ? 17 : 25,
                        fontWeight: 950
                      }}
                    >
                      {money(totals.total)}
                    </Typography>
                  </Paper>
                </Grid>

                <Grid item xs={4} sm={4} md={4}>
                  <Paper
                    variant="outlined"
                    sx={{
                      p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                      minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                      borderRadius: isCompact ? 1.3 : undefined,
                      textAlign: "center"
                    }}
                  >
                    <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>
                      الضريبة
                    </Typography>

                    <Typography
                      sx={{
                        color: "#d71920",
                        fontSize: isPhone ? 14 : isTablet ? 17 : 25,
                        fontWeight: 950
                      }}
                    >
                      {money(totals.tax)}
                    </Typography>
                  </Paper>
                </Grid>

                <Grid item xs={4} sm={4} md={4}>
                  <Paper
                    variant="outlined"
                    sx={{
                      p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                      minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                      borderRadius: isCompact ? 1.3 : undefined,
                      textAlign: "center"
                    }}
                  >
                    <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>
                      الصافي
                    </Typography>

                    <Typography
                      sx={{
                        color: "#d71920",
                        fontSize: isPhone ? 14 : isTablet ? 17 : 25,
                        fontWeight: 950
                      }}
                    >
                      {money(totals.subTotal)}
                    </Typography>
                  </Paper>
                </Grid>
              </Grid>
            </>
          ) : null}
        </Stack>
      </DialogContent>

      <DialogActions
        sx={uiLayout.withUiSx({
          px: isPhone ? 0.35 : isTablet ? 0.55 : 3,
          py: isPhone ? 0.28 : isTablet ? 0.42 : 2,
          gap: isCompact ? 0.35 : 1,
          flexShrink: 0
        }, uiLayout.dialogActionsSx)}
      >
        <Button
          variant="contained"
          onClick={save}
          disabled={
            saving ||
            loadingContext ||
            !context
          }
          startIcon={
            saving ? (
              <CircularProgress
                size={18}
                color="inherit"
              />
            ) : (
              <SaveIcon />
            )
          }
          sx={uiLayout.withUiSx({
            backgroundColor: primaryColor,
            minWidth: isPhone ? 92 : isTablet ? 110 : 140,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.8 : isTablet ? 1.1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          حفظ
        </Button>

        <Button
          onClick={onClose}
          disabled={saving}
          sx={uiLayout.withUiSx({
            color: accentColor,
            fontWeight: 900,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.8 : isTablet ? 1.1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          إغلاق
        </Button>
      </DialogActions>
    </Dialog>
    </>
  );
}

