                    </Box>
                    <Typography variant="h5" fontWeight={600} sx={{ color: colorPalette.textDark, fontFamily: '"Cairo", sans-serif', fontSize: { xs: '0.82rem', sm: '0.95rem', md: '1.08rem' } }} gutterBottom>
                      مهمة عامة
