                        color: 'white',
                        fontFamily: '"Cairo", sans-serif',
                        '&:hover': {
                          backgroundColor: colorPalette.primaryDark
                        }
                      }}
                    />
                  </Paper>
                </motion.div>
              </Grid>
            
            {/* Private Task Option */}
            {/* <Grid item xs={12} md={5}>
              <motion.div 
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.98 }}
              >
                <Paper
                  onClick={handlePrivateSelect}
                  elevation={0}
                  sx={{ 
                    p: 4, 
                    cursor: "pointer", 
                    textAlign: "center", 
                    backgroundColor: "#f3e5f5",
                    borderRadius: '16px',
