                  label="اسم الطالب"
                  value={studentName}
                  isPhone={isPhone}
                  isTablet={isTablet}
                />
              </Grid>

              {/* الهوية والجوال جنب بعض */}
              <Grid
                item
                xs={6}
                sm={3}
                md={4}
              >
                <StudentField
                  label="رقم الهوية"
                  value={nationalId}
                  isPhone={isPhone}
                  isTablet={isTablet}
                />
              </Grid>

              <Grid
                item
                xs={6}
                sm={3}
                md={4}
              >
                <StudentField
                  label="رقم الجوال"
                  value={studentTel}
                  isPhone={isPhone}
                  isTablet={isTablet}
                />
              </Grid>
            </Grid>
          </Paper>

          <TextField InputLabelProps={{ shrink: true }}
            fullWidth
            multiline
            minRows={
              isPhone
                ? 3
                : isTablet
                  ? 4
                  : 8
            }
            label="سبب الاسترداد"
            value={notes}
            onChange={(event) =>
              setNotes(event.target.value)
            }
            inputProps={{
              maxLength: 2000
            }}
            helperText={`${notes.length}/2000`}
            sx={uiLayout.withUiSx({
              mb: isPhone
                ? 0.7
                : isTablet
                  ? 0.9
                  : 2,

              "& .MuiInputLabel-root": {
                fontSize: isPhone
                  ? "0.75rem"
                  : isTablet
                    ? "0.75rem"
                    : undefined
              },

              "& .MuiInputBase-input": {
                fontSize: isPhone
                  ? "0.75rem"
                  : isTablet
                    ? "0.75rem"
                    : undefined,

                lineHeight: 1.4
              },

              "& .MuiFormHelperText-root": {
                fontSize: isPhone
                  ? "0.75rem"
                  : isTablet
                    ? "0.75rem"
                    : undefined
              }
            }, uiLayout.formFieldSx)}
          />

          <Button
            component="label"
            fullWidth
            variant="outlined"
            startIcon={
              <AttachFileIcon
                sx={{
                  fontSize: isPhone
                    ? 15
                    : isTablet
                      ? 18
                      : undefined
                }}
              />
            }
            sx={uiLayout.withUiSx({
              minHeight: isPhone
                ? 34
                : isTablet
                  ? 38
                  : 58,

              color: accentColor,
              borderColor: accentColor,
              fontWeight: 950,

              fontSize: isPhone
                ? "0.75rem"
                : isTablet
                  ? "0.75rem"
                  : undefined,

              borderRadius: isCompact
                ? 1.3
                : undefined,

              px: isPhone
                ? 0.6
                : isTablet
                  ? 0.8
                  : undefined,

              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap"
            }, uiLayout.buttonSx)}
          >
            {ibanFile
              ? ibanFile.name
              : "إرفاق ملف الآيبان — إجباري"}

            <input
              hidden
              type="file"
              accept=".pdf,.jpg,.jpeg,.png"
              onChange={(event) =>
                setIbanFile(
                  event.target.files?.[0] || null
                )
              }
            />
          </Button>
        </DialogContent>

        <DialogActions
          sx={uiLayout.withUiSx({
            px: isPhone
              ? 0.6
              : isTablet
                ? 0.8
                : 3,

            py: isPhone
              ? 0.3
              : isTablet
                ? 0.45
                : 2,

            gap: isCompact
              ? 0.4
              : 1,

            flexShrink: 0
          }, uiLayout.dialogActionsSx)}
        >
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={saving}
            startIcon={
              saving ? (
                <CircularProgress
                  size={
                    isPhone ? 14 : 18
                  }
                  color="inherit"
                />
              ) : (
                <SaveIcon
                  sx={{
                    fontSize: isPhone
                      ? 14
                      : undefined
                  }}
                />
              )
            }
            sx={uiLayout.withUiSx({
              backgroundColor: primaryColor,

              minWidth: isPhone
                ? 95
                : isTablet
                  ? 115
                  : 150,

              minHeight: isPhone
                ? 30
                : isTablet
                  ? 34
                  : undefined,

              fontSize: isPhone
                ? "0.75rem"
                : isTablet
                  ? "0.75rem"
                  : undefined
            }, uiLayout.buttonSx)}
          >
            حفظ الطلب
          </Button>

          <Button
            onClick={onClose}
            disabled={saving}
            sx={uiLayout.withUiSx({
              color: accentColor,
              fontWeight: 900,

              minWidth: isPhone
                ? 65
                : isTablet
                  ? 75
                  : 90,

              minHeight: isPhone
                ? 30
                : isTablet
                  ? 34
                  : undefined,

              fontSize: isPhone
                ? "0.75rem"
                : isTablet
                  ? "0.75rem"
                  : undefined
            }, uiLayout.buttonSx)}
          >
            إغلاق
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default RefundRequestDialog;

import * as uiLayout from './common/uiLayout';
import { DESKTOP_BREAKPOINT } from '../config/sidebarLayout';
import React, { useEffect, useRef, useState } from "react";
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  useMediaQuery,
  useTheme
} from "@mui/material";

import CloseIcon from "@mui/icons-material/Close";
import PrintIcon from "@mui/icons-material/Print";
import PictureAsPdfIcon from "@mui/icons-material/PictureAsPdf";
import ReceiptLongIcon from "@mui/icons-material/ReceiptLong";

const logoImage = new URL(
  `${process.env.PUBLIC_URL || ""}/logo.jpg`,
  window.location.origin
).href;

const primaryColor = "#057546";
const accentColor = "#ae1e21";

const REFUND_POLICY_URL =
  "https://sstli.com/%d8%b3%d9%8a%d8%a7%d8%b3%d9%8a%d8%a9-%d8%a7%d9%84%d8%a5%d8%b3%d8%aa%d8%b1%d8%af%d8%a7%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d9%84%d9%8a/";

const REFUND_POLICY_QR =
  `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(
    REFUND_POLICY_URL
  )}`;

const REGISTER_VERIFICATION_PAGE_URL =
  "https://filesregsiteration.sstli.com/erp/auth.php";

const COMPANY_NAME = "شركة معهد السعودي المتخصص العالي للتدريب";
const COMPANY_TAX_NO = "312191561600003";
const COMPANY_PHONE = "920012673";
const COMPANY_CR_NO = "2050163983";

const formatMoney = (value) => {
