  return new Intl.NumberFormat("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(number);
};

const InfoField = ({ label, value }) => (
  <Box
    sx={{
      display: "grid",
      gridTemplateColumns: "125px 1fr",
