);

const RegisterDocumentDialog = ({
  open,
  onClose,
  docGuid,
  documentNo,
  apiBaseUrl
}) => {
  const theme = useTheme();
  const isPhone = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery(
    `(min-width:600px) and (max-width:${DESKTOP_BREAKPOINT - 0.05}px)`,
    { noSsr: true }
  );
  const isDesktop = useMediaQuery(
    `(min-width:${DESKTOP_BREAKPOINT}px)`,
    { noSsr: true }
  );
  const previewScale = isPhone ? 0.40 : isTablet ? 0.72 : 1;

  const [documentData, setDocumentData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const printRef = useRef(null);

  const verificationDocumentGuid =
    documentData?.guid ||
    documentData?.docGuid ||
    documentData?.regDocGuid ||
    docGuid ||
    "";

  const verificationDocumentNo =
    documentData?.documentNo ||
    documentData?.code ||
    documentNo ||
    "";

  const verificationPageUrl =
    `${REGISTER_VERIFICATION_PAGE_URL}?guid=${encodeURIComponent(
      verificationDocumentGuid
    )}&code=${encodeURIComponent(
      verificationDocumentNo
    )}`;

  const verificationQrUrl =
    `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(
      verificationPageUrl
    )}`;

  useEffect(() => {
    if (!open || !docGuid) return undefined;

    const controller = new AbortController();

    const loadDocument = async () => {
      try {
        setLoading(true);
        setError("");
        setDocumentData(null);

        const params = new URLSearchParams({ docGuid });

        const response = await fetch(
          `${apiBaseUrl}/api/reception-office/student-statement/register-document?${params.toString()}`,
          { signal: controller.signal }
        );

        const result = await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
              result?.error ||
              "تعذر تحميل استمارة التسجيل"
          );
        }

        setDocumentData(result?.data || null);
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(
            err.message ||
              "حدث خطأ أثناء تحميل استمارة التسجيل"
          );
        }
      } finally {
        setLoading(false);
      }
    };

    loadDocument();

    return () => controller.abort();
  }, [open, docGuid, apiBaseUrl]);

  const openPrintWindow = () => {
    if (!printRef.current || !documentData) return;

    const printWindow = window.open(
      "",
      "_blank",
      "width=1000,height=900"
    );

    if (!printWindow) {
      setError("المتصفح منع نافذة الطباعة، برجاء السماح بالنوافذ المنبثقة");
      return;
    }

    /*
      في نسخة الـ production الخاصة بـ MUI / Emotion يتم وضع التنسيقات
      داخل CSSStyleSheet وليس كنص داخل style tag، لذلك نسخ outerHTML
      الخاص بالـ styles يعمل في localhost وقد يفشل بعد build.

      الحل: ننسخ عنصر الاستمارة ثم نثبت الـ computed styles على كل عنصر
      كـ inline styles، وبذلك تكون نافذة الطباعة مستقلة تمامًا عن ملفات CSS.
    */
    const sourceRoot = printRef.current;
    const clonedRoot = sourceRoot.cloneNode(true);

    const sourceElements = [sourceRoot, ...sourceRoot.querySelectorAll("*")];
    const clonedElements = [clonedRoot, ...clonedRoot.querySelectorAll("*")];

    sourceElements.forEach((sourceElement, index) => {
      const clonedElement = clonedElements[index];
      if (!clonedElement) return;

      const computedStyle = window.getComputedStyle(sourceElement);
      let inlineCss = "";

      for (let i = 0; i < computedStyle.length; i += 1) {
        const propertyName = computedStyle[i];
        const propertyValue = computedStyle.getPropertyValue(propertyName);
        const propertyPriority = computedStyle.getPropertyPriority(propertyName);

        inlineCss += `${propertyName}:${propertyValue}${
          propertyPriority ? " !important" : ""
        };`;
      }

      clonedElement.setAttribute("style", inlineCss);
    });

    // تثبيت مقاس صفحة الطباعة بعد نسخ الـ computed styles.
    clonedRoot.classList.add("print-page");
    clonedRoot.style.setProperty("position", "relative", "important");
    clonedRoot.style.setProperty("display", "block", "important");
    clonedRoot.style.setProperty("width", "210mm", "important");
    clonedRoot.style.setProperty("height", "297mm", "important");
    clonedRoot.style.setProperty("min-height", "297mm", "important");
    clonedRoot.style.setProperty("max-height", "297mm", "important");
    clonedRoot.style.setProperty("margin", "0", "important");
    clonedRoot.style.setProperty("padding", "10mm", "important");
    clonedRoot.style.setProperty("overflow", "hidden", "important");
    clonedRoot.style.setProperty("border", "0", "important");
    clonedRoot.style.setProperty("border-radius", "0", "important");
    clonedRoot.style.setProperty("box-shadow", "none", "important");
    clonedRoot.style.setProperty("background", "#ffffff", "important");
    clonedRoot.style.setProperty("box-sizing", "border-box", "important");
    clonedRoot.style.setProperty("transform", "none", "important");
    clonedRoot.style.setProperty("transform-origin", "top left", "important");
    clonedRoot.style.setProperty("top", "auto", "important");
    clonedRoot.style.setProperty("left", "auto", "important");
    clonedRoot.style.setProperty("right", "auto", "important");

    // عناصر العرض التفاعلية مثل TableContainer تستخدم overflow-x:auto.
    // في نسخة الطباعة نلغي أي scroll/min-width حتى يطبع الجدول داخل A4 بالكامل.
    const printableTableContainer = clonedRoot.querySelector(".items-table");
    if (printableTableContainer) {
      printableTableContainer.style.setProperty("width", "100%", "important");
      printableTableContainer.style.setProperty("max-width", "100%", "important");
      printableTableContainer.style.setProperty("min-width", "0", "important");
      printableTableContainer.style.setProperty("overflow", "visible", "important");
      printableTableContainer.style.setProperty("overflow-x", "visible", "important");
      printableTableContainer.style.setProperty("overflow-y", "visible", "important");

      const printableTable = printableTableContainer.querySelector("table");
      if (printableTable) {
        printableTable.style.setProperty("width", "100%", "important");
        printableTable.style.setProperty("max-width", "100%", "important");
        printableTable.style.setProperty("min-width", "0", "important");
        printableTable.style.setProperty("table-layout", "fixed", "important");
      }
    }

    const printableHtml = `
      <!DOCTYPE html>
      <html lang="ar" dir="rtl">
        <head>
          <meta charset="UTF-8" />
          <meta
            name="viewport"
            content="width=device-width, initial-scale=1.0"
          />
          <title>استمارة تسجيل ${
            documentData.documentNo || documentNo || ""
          }</title>

          <style>
            @page {
              size: A4 portrait;
              margin: 0;
            }

            * {
              box-sizing: border-box;
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }

            html,
            body {
              width: 210mm !important;
              min-width: 210mm !important;
              height: 297mm !important;
              min-height: 297mm !important;
              max-height: 297mm !important;
              margin: 0 !important;
              padding: 0 !important;
              background: #ffffff !important;
              direction: rtl !important;
              overflow: hidden !important;
              font-family: Cairo, Arial, Tahoma, sans-serif !important;
            }

            body {
              display: block !important;
            }

            .print-page {
              page-break-before: avoid !important;
              page-break-after: avoid !important;
              page-break-inside: avoid !important;
              break-before: avoid-page !important;
              break-after: avoid-page !important;
              break-inside: avoid-page !important;
              transform: none !important;
              transform-origin: top left !important;
            }

            .print-page .items-table,
            .print-page .MuiTableContainer-root {
              width: 100% !important;
              max-width: 100% !important;
              min-width: 0 !important;
              overflow: visible !important;
              overflow-x: visible !important;
              overflow-y: visible !important;
            }

            .print-page .items-table table,
            .print-page .MuiTable-root {
              width: 100% !important;
              max-width: 100% !important;
              min-width: 0 !important;
              table-layout: fixed !important;
            }

            .print-page .items-table th,
            .print-page .items-table td {
              min-width: 0 !important;
              max-width: none !important;
              overflow: visible !important;
              text-overflow: clip !important;
              white-space: normal !important;
              word-break: normal !important;
            }

            .print-page .items-table::-webkit-scrollbar,
            .print-page .MuiTableContainer-root::-webkit-scrollbar {
              display: none !important;
              width: 0 !important;
              height: 0 !important;
            }

            @media print {
              html,
              body,
              .print-page {
                width: 210mm !important;
                height: 297mm !important;
                min-height: 297mm !important;
                max-height: 297mm !important;
                overflow: hidden !important;
                transform: none !important;
              }
            }
          </style>
        </head>

        <body>
          ${clonedRoot.outerHTML}

          <script>
            (function () {
              function waitForImages() {
                var images = Array.prototype.slice.call(document.images || []);

                return Promise.all(
                  images.map(function (image) {
                    if (image.complete) return Promise.resolve();

                    return new Promise(function (resolve) {
                      image.onload = resolve;
                      image.onerror = resolve;
                    });
                  })
                );
              }

              window.addEventListener("load", function () {
                var fontsReady = document.fonts && document.fonts.ready
                  ? document.fonts.ready
                  : Promise.resolve();

                Promise.all([fontsReady, waitForImages()]).then(function () {
                  window.focus();
                  window.setTimeout(function () {
                    window.print();
                  }, 350);
                });
              });
            })();
          <\/script>
        </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(printableHtml);
    printWindow.document.close();
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullScreen
      dir="rtl"
      sx={uiLayout.withUiSx({
        // لازم استمارة التسجيل تظهر فوق كشف الحساب المفتوح تحتها.
        zIndex: 1800
      }, uiLayout.dialogLayoutSx)}
    >
      <DialogTitle
        className="no-print"
        sx={{
          backgroundColor: primaryColor,
          color: "#fff",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          py: isPhone ? 0.5 : isTablet ? 0.7 : 1.3,
          px: isPhone ? 0.65 : isTablet ? 0.9 : 2
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <ReceiptLongIcon />

          <Box>
            <Typography sx={{ fontWeight: 950, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>
              عرض استمارة التسجيل
            </Typography>

            <Typography sx={{ fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : "0.78rem", opacity: 0.9 }}>
              رقم المستند:{" "}
              {documentData?.documentNo || documentNo || "-"}
            </Typography>
          </Box>
        </Box>

        <IconButton onClick={onClose} sx={{ color: "#fff" }}>
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent
        sx={{
          backgroundColor: "#eeeeee",
          p: isPhone ? 0.25 : isTablet ? 0.5 : 1.5,
          overflow: "auto",
          "& > .MuiBox-root": {
            marginInline: "auto"
          }
        }}
      >
        {loading ? (
          <Box
            sx={{
              height: "75vh",
              display: "flex",
              alignItems: "center",
              justifyContent: "center"
            }}
          >
            <CircularProgress />
          </Box>
        ) : error ? (
          <Box
            sx={{
              height: "70vh",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: accentColor,
              fontWeight: 950
            }}
          >
            {error}
          </Box>
        ) : documentData ? (
          <Box
            sx={{
              width: `${210 * previewScale}mm`,
              height: `${297 * previewScale}mm`,
              mx: "auto",
              position: "relative",
              flexShrink: 0,
              display: "flex",
              justifyContent: "center",
              alignItems: "flex-start",
              overflow: "visible"
            }}
          >
          <Paper
            ref={printRef}
            className="print-page"
            elevation={3}
            sx={{
              position: "relative",
              width: "210mm",
              height: "297mm",
              minHeight: "297mm",
              maxHeight: "297mm",
              m: 0,
              p: "10mm",
              overflow: "hidden",
              backgroundColor: "#fff",
              color: "#111",
              position: previewScale === 1 ? "relative" : "absolute",
              top: 0,
              left: previewScale === 1 ? "auto" : "50%",
              transform:
                previewScale === 1
                  ? "none"
                  : `translateX(-50%) scale(${previewScale})`,
              transformOrigin: "top center"
            }}
          >
            {/* Header */}
            <Box
              className="company-header"
              sx={{
                display: "grid",
                gridTemplateColumns: "430px 1fr 150px",
                gap: 2.5,
                alignItems: "center",
                borderBottom: "3px solid #111",
                pb: 1.8,
                mb: 2.2,
                direction: "rtl"
              }}
            >
              {/* بيانات الشركة ناحية اليمين */}
              <Box
                className="company-info"
                sx={{
                  textAlign: "start",
                  direction: "rtl",
                  alignSelf: "stretch",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  minWidth: 0
                }}
              >
                <Typography
                  className="title"
                  sx={{
                    fontWeight: 950,
                    fontSize: 17,
                    lineHeight: 1.4,
                    mb: 0.6,
                    whiteSpace: "nowrap"
                  }}
                >
                  {COMPANY_NAME}
                </Typography>

                <Typography
                  className="branch"
                  sx={{
                    fontSize: 15,
