                    <Divider sx={{ my: 1, borderColor: colorPalette.primaryLighter }} />
                    <Row label="العمولة" value={data[K.devCommission]} color={colorPalette.primary} isCurrency />
                  </Panel>
                </Grid>
              </Grid>
            </>
          )}

          {/* ===================== Details Dialog ===================== */}
          <Dialog
            open={openDetails}
