                sx={{
                  mb: isPhone ? 0.65 : 2,
                  fontFamily: "Cairo",
                  fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                  py: isPhone ? 0.25 : undefined
                }}
