                    InputProps={{ readOnly: true }}
                   inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
                </Grid>
              </Grid>
            </Paper>

            <Grid container spacing={isPhone ? 0.35 : isTablet ? 0.55 : 2}>
              <Grid item xs={12} sm={6} md={4}>
                <TextField sx={uiLayout.formFieldSx}
                  fullWidth
                  type="datetime-local"
                  label="التاريخ"
                  value={returnDate}
                  onChange={(e) => setReturnDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                 inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
              </Grid>

              <Grid item xs={12} sm={6} md={4}>
                <FormControl sx={uiLayout.formFieldSx} fullWidth disabled={loadingDocs}>
                  <InputLabel>نوع المستند</InputLabel>
                  <Select
                    value={selectedDocGuid}
                    label="نوع المستند"
                    onChange={(e) => setSelectedDocGuid(e.target.value)}
                    MenuProps={{
                      PaperProps: {
                        sx: {
                          maxHeight: isPhone ? 180 : isTablet ? 220 : 320,
                          mt: 0.25,
                          borderRadius: isCompact ? 1.2 : 2,
                          "& .MuiMenuItem-root": {
                            minHeight: isPhone ? 29 : isTablet ? 33 : 40,
                            py: isPhone ? 0.35 : isTablet ? 0.5 : 0.75,
                            px: isPhone ? 0.65 : isTablet ? 0.85 : 1.5,
                            fontSize: isPhone ? "0.5rem" : isTablet ? "0.58rem" : "0.875rem",
                            lineHeight: 1.2
                          }
                        }
                      }
                    }}
                  >
                    {documents.map((item) => (
                      <MenuItem key={item.guid} value={item.guid}>
                        {item.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} sm={12} md={4}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="مندوب البيع"
                  value={context?.salesManName || ""}
                  InputProps={{ readOnly: true }}
                />
              </Grid>
            </Grid>

            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              fullWidth
              multiline
              minRows={isPhone ? 2 : isTablet ? 2 : 3}
              label="ملاحظات"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />

            <TableContainer
              component={Paper}
              variant="outlined"
              sx={uiLayout.withUiSx({
                borderRadius: isCompact ? 1.3 : undefined,
                overflowX: "auto",
                "& .MuiTableCell-root": {
                  py: isPhone ? 0.45 : isTablet ? 0.6 : undefined,
                  px: isPhone ? 0.35 : isTablet ? 0.55 : undefined,
                  fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                  whiteSpace: "nowrap"
                },
                "& .MuiTableHead-root .MuiTableCell-root": {
                  fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
                  lineHeight: 1.1
                }
              }, uiLayout.tableContainerSx)}
            >
              <Table size="small">
                <TableHead>
                  <TableRow sx={{ backgroundColor: "#f7d38a" }}>
                    <TableCell align="right" sx={{ fontWeight: 950 }}>
                      الدبلوم - الدورة
                    </TableCell>
                    <TableCell
                      align="center"
                      sx={{
                        fontWeight: 950,
                        display: isPhone ? "none" : "table-cell"
                      }}
                    >
                      الوحدة
                    </TableCell>
                    <TableCell align="center" sx={{ fontWeight: 950 }}>
                      الكمية
                    </TableCell>
                    <TableCell align="center" sx={{ fontWeight: 950 }}>
                      التكلفة
                    </TableCell>
                    <TableCell
                      align="center"
                      sx={{
                        fontWeight: 950,
                        display: isPhone ? "none" : "table-cell"
                      }}
                    >
                      الضريبة
                    </TableCell>
                    <TableCell align="center" sx={{ fontWeight: 950 }}>
                      الصافي
                    </TableCell>
                  </TableRow>
                </TableHead>

                <TableBody>
                  {details.map((item, index) => (
                    <TableRow key={`${item.diplomGuid}-${index}`}>
                      <TableCell align="right" sx={{ fontWeight: 800 }}>
                        {item.name}
                      </TableCell>
                      <TableCell
                        align="center"
                        sx={{ display: isPhone ? "none" : "table-cell" }}
                      >
                        {item.unit || item.unit_ || "-"}
                      </TableCell>
                      <TableCell align="center">
                        {Number(item.qty || 0)}
                      </TableCell>
                      <TableCell align="center">{money(item.cost)}</TableCell>
                      <TableCell
                        align="center"
                        sx={{ display: isPhone ? "none" : "table-cell" }}
                      >
                        {money(item.tax)}
                      </TableCell>
                      <TableCell align="center">{money(item.subTotal)}</TableCell>
                    </TableRow>
                  ))}

                  {details.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={6} align="center">
                        لا توجد تفاصيل في استمارة التسجيل
                      </TableCell>
                    </TableRow>
                  ) : null}
                </TableBody>
              </Table>
            </TableContainer>

            <Grid container spacing={isPhone ? 0.35 : isTablet ? 0.55 : 2}>
              <Grid item xs={4} sm={4} md={4}>
                <Paper
                  variant="outlined"
                  sx={{
                    p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                    minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                    borderRadius: isCompact ? 1.3 : undefined,
                    textAlign: "center"
                  }}
                >
                  <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>الإجمالي</Typography>
                  <Typography sx={{ color: "#d71920", fontSize: isPhone ? 14 : isTablet ? 17 : 25, fontWeight: 950 }}>
                    {money(totals.total)}
                  </Typography>
                </Paper>
              </Grid>

              <Grid item xs={4} sm={4} md={4}>
                <Paper
                  variant="outlined"
                  sx={{
                    p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                    minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                    borderRadius: isCompact ? 1.3 : undefined,
                    textAlign: "center"
                  }}
                >
                  <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>الضريبة</Typography>
                  <Typography sx={{ color: "#d71920", fontSize: isPhone ? 14 : isTablet ? 17 : 25, fontWeight: 950 }}>
                    {money(totals.tax)}
                  </Typography>
                </Paper>
              </Grid>

              <Grid item xs={4} sm={4} md={4}>
                <Paper
                  variant="outlined"
                  sx={{
                    p: isPhone ? 0.45 : isTablet ? 0.65 : 2,
                    minHeight: isPhone ? 54 : isTablet ? 60 : undefined,
                    borderRadius: isCompact ? 1.3 : undefined,
                    textAlign: "center"
                  }}
                >
                  <Typography sx={{ fontWeight: 900, fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined }}>الصافي</Typography>
                  <Typography sx={{ color: "#d71920", fontSize: isPhone ? 14 : isTablet ? 17 : 25, fontWeight: 950 }}>
                    {money(totals.subTotal)}
                  </Typography>
                </Paper>
              </Grid>
            </Grid>
          </Stack>
        )}
      </DialogContent>

      <DialogActions
        sx={uiLayout.withUiSx({
          px: isPhone ? 0.35 : isTablet ? 0.55 : 3,
          py: isPhone ? 0.28 : isTablet ? 0.42 : 2,
          gap: isCompact ? 0.35 : 1,
          flexShrink: 0
        }, uiLayout.dialogActionsSx)}
      >
        <Button
          variant="contained"
          onClick={save}
          disabled={saving || loading || !context}
          startIcon={
            saving ? (
              <CircularProgress size={18} color="inherit" />
            ) : (
              <SaveIcon />
            )
          }
          sx={uiLayout.withUiSx({
            backgroundColor: primaryColor,
            minWidth: isPhone ? 92 : isTablet ? 110 : 140,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.8 : isTablet ? 1.1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          حفظ
        </Button>

        <Button
          onClick={onClose}
          disabled={saving}
          sx={uiLayout.withUiSx({
            color: accentColor,
            fontWeight: 900,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.8 : isTablet ? 1.1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          إغلاق
        </Button>
      </DialogActions>
    </Dialog>
    </>
  );
}

src\\components\\ReportList.jsx:
import * as uiLayout from './common/uiLayout';
import React from 'react';
import { 
  Box, 
  Typography, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow,
  Paper,
  Chip,
  Button,
  TablePagination,
  Skeleton
} from '@mui/material';
import { format, parseISO } from 'date-fns';
import { ar } from 'date-fns/locale';

const ReportList = ({ reports = [], onSelectReport, selectedDate, loading }) => {
  const [page, setPage] = React.useState(0);
  const [rowsPerPage, setRowsPerPage] = React.useState(10);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  if (reports.length === 0 && !loading) {
    return (
      <Box sx={styles.emptyState}>
        <Typography variant="h6" color="textSecondary">
          {selectedDate 
            ? 'لا توجد تقارير متاحة للتاريخ المحدد'
            : 'لا توجد تقارير متاحة'}
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom sx={styles.sectionTitle}>
        {selectedDate 
          ? `التقارير بتاريخ ${format(selectedDate, 'yyyy-MM-dd', { locale: ar })}`
          : 'جميع التقارير'}
      </Typography>
      
      <TableContainer component={Paper} sx={uiLayout.withUiSx(styles.tableContainer, uiLayout.tableContainerSx)}>
        <Table sx={styles.table}>
          <TableHead sx={styles.tableHead}>
            <TableRow>
              <TableCell sx={styles.headerCell}>رقم التقرير</TableCell>
              <TableCell sx={styles.headerCell}>تاريخ الإنشاء</TableCell>
              <TableCell sx={styles.headerCell}>عدد الموظفين</TableCell>
              <TableCell sx={styles.headerCell}>المهام اليومية</TableCell>
              <TableCell sx={styles.headerCell}>الزيارات الإشرافية</TableCell>
              <TableCell sx={styles.headerCell}>الإجراءات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              Array.from(new Array(rowsPerPage)).map((_, index) => (
                <TableRow key={index}>
                  {Array.from(new Array(6)).map((_, i) => (
                    <TableCell key={i}>
                      <Skeleton variant="text" width="80%" />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              reports
                .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                .map((report) => (
                  <TableRow key={report.report_info.id} hover>
                    <TableCell>{report.report_info.id}</TableCell>
                    <TableCell>
                      {format(parseISO(report.report_info.created_at), 'yyyy-MM-dd HH:mm', { locale: ar })}
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={report.employee_attendance.length} 
                        color="primary" 
                        size="small" 
                        sx={styles.chip}
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={report.daily_tasks.length} 
                        color="secondary" 
                        size="small" 
                        sx={styles.chip}
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={report.supervisory_visits.length} 
                        color="info" 
                        size="small" 
                        sx={styles.chip}
                      />
                    </TableCell>
                    <TableCell>
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={() => onSelectReport(report)}
                        sx={uiLayout.withUiSx(styles.detailsButton, uiLayout.buttonSx)}
                      >
                        عرض التفاصيل
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
            )}
          </TableBody>
        </Table>
      </TableContainer>
      
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={reports.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        labelRowsPerPage="عدد الصفوف:"
        labelDisplayedRows={({ from, to, count }) => `${from}-${to} من ${count}`}
        sx={uiLayout.withUiSx(styles.pagination, uiLayout.tablePaginationSx)}
      />
    </Box>
  );
};

const styles = {
  emptyState: {
    textAlign: 'center',
    py: 6
  },
  sectionTitle: {
    mb: 2,
    color: 'text.primary',
    fontWeight: '600'
  },
  tableContainer: {
    borderRadius: '12px',
    overflow: 'hidden',
    boxShadow: 'none',
    border: '1px solid',
    borderColor: 'divider'
  },
  table: {
    minWidth: 650
  },
  tableHead: {
    backgroundColor: 'background.paper'
  },
  headerCell: {
    fontWeight: 'bold',
    color: 'text.secondary',
    borderBottom: '2px solid',
    borderColor: 'divider'
  },
  chip: {
    fontWeight: '500',
    minWidth: '60px'
  },
  detailsButton: {
    borderRadius: '8px',
    textTransform: 'none',
    fontWeight: '500'
  },
  pagination: {
    border: 'none',
    '& .MuiTablePagination-toolbar': {
      paddingLeft: 0
    }
  }
};

export default ReportList;

src\\components\\ReportViewer.jsx:
import * as uiLayout from './common/uiLayout';
import React from 'react';
import { 
  Box, 
  Typography, 
  Paper, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Chip,
  Divider,
  List,
  ListItem,
  ListItemText,
  Grid,
  Stack,
  Button,
  Skeleton
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { 
  People as PeopleIcon,
  Assignment as AssignmentIcon,
  School as SchoolIcon,
  Engineering as EngineeringIcon,
  Task as TaskIcon,
  Lightbulb as LightbulbIcon,
  Checklist as DiplomaIcon,
  ArrowBack as BackIcon
} from '@mui/icons-material';

const ReportViewer = ({ report, onBack }) => {
  const renderStatusChip = (status) => {
    const statusMap = {
      present: { label: 'حاضر', color: 'success' },
      absent: { label: 'غائب', color: 'error' },
      permission: { label: 'استئذان', color: 'warning' },
      leave: { label: 'إجازة', color: 'info' }
    };

    return (
      <Chip 
        label={statusMap[status]?.label || 'غير محدد'} 
        color={statusMap[status]?.color || 'default'} 
        size="small"
        sx={styles.chip}
      />
    );
  };

  const renderEmployeeSection = () => (
    <Accordion defaultExpanded sx={styles.accordion}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Stack direction="row" alignItems="center" spacing={1}>
          <PeopleIcon color="primary" />
          <Typography variant="h6">حضور الموظفين ({report.employee_attendance?.length || 0})</Typography>
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        <TableContainer component={Paper} sx={uiLayout.withUiSx(styles.tableContainer, uiLayout.tableContainerSx)}>
          <Table size="small">
            <TableHead sx={styles.tableHead}>
              <TableRow>
                <TableCell width="70%">اسم الموظف</TableCell>
                <TableCell width="30%">الحالة</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {report.employee_attendance?.map((emp, index) => (
                <TableRow key={index} hover>
                  <TableCell>{emp.employee_name}</TableCell>
                  <TableCell>{renderStatusChip(emp.status)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </AccordionDetails>
    </Accordion>
  );

  const renderListSection = (title, items = [], icon) => (
    <Accordion defaultExpanded sx={styles.accordion}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Stack direction="row" alignItems="center" spacing={1}>
          {icon}
          <Typography variant="h6">{title} ({items.length})</Typography>
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        {items.length > 0 ? (
          <List dense sx={styles.list}>
            {items.map((item, index) => (
              <ListItem key={index} sx={styles.listItem}>
                <ListItemText 
                  primary={`${index + 1}. ${item.item_text || item.visit_text || item.task_text}`}
                  primaryTypographyProps={{ variant: 'body1' }}
                />
              </ListItem>
            ))}
          </List>
        ) : (
          <Typography variant="body2" color="textSecondary" sx={styles.noItems}>
            لا توجد عناصر متاحة
          </Typography>
        )}
      </AccordionDetails>
    </Accordion>
  );

  const renderDiplomaStats = () => (
    <Paper sx={styles.sectionPaper}>
      <Box sx={styles.sectionHeader}>
        <Stack direction="row" alignItems="center" spacing={1}>
          <DiplomaIcon color="primary" />
          <Typography variant="h5">إحصائيات الدبلومات</Typography>
        </Stack>
      </Box>

      <Grid container spacing={3} sx={styles.gridContainer}>
        <Grid item xs={12} md={4}>
          <Paper sx={styles.diplomaCard}>
            <Typography variant="h6" gutterBottom sx={styles.diplomaTitle}>
              التسجيلات
            </Typography>
            {report.diploma_registrations?.map((item, index) => (
              <Box key={index} sx={styles.diplomaItem}>
                <Typography variant="subtitle1">{item.diploma_name}</Typography>
                <Stack direction="row" spacing={2} sx={styles.diplomaStats}>
                  <Chip label={`العدد: ${item.count}`} size="small" />
                  <Chip label={`الدفعة: ${item.batch}`} size="small" color="info" />
                </Stack>
              </Box>
            ))}
          </Paper>
        </Grid>

        <Grid item xs={12} md={4}>
          <Paper sx={styles.diplomaCard}>
            <Typography variant="h6" gutterBottom sx={{ ...styles.diplomaTitle, color: 'success.main' }}>
              الحضور
            </Typography>
            {report.diploma_attendance?.map((item, index) => (
              <Box key={index} sx={styles.diplomaItem}>
                <Typography variant="subtitle1">{item.diploma_name}</Typography>
                <Chip 
                  label={`العدد: ${item.count}`} 
                  size="small" 
                  sx={styles.attendanceChip} 
                  color="success"
                />
              </Box>
            ))}
          </Paper>
        </Grid>

        <Grid item xs={12} md={4}>
          <Paper sx={styles.diplomaCard}>
            <Typography variant="h6" gutterBottom sx={{ ...styles.diplomaTitle, color: 'warning.main' }}>
              الموافقات
            </Typography>
            {report.diploma_approvals?.map((item, index) => (
              <Box key={index} sx={styles.diplomaItem}>
                <Typography variant="subtitle1">{item.diploma_name}</Typography>
                <Stack direction="row" spacing={2} sx={styles.diplomaStats}>
                  <Chip label={`العدد: ${item.count}`} size="small" />
                  <Chip label={`الدفعة: ${item.batch}`} size="small" color="warning" />
                </Stack>
              </Box>
            ))}
          </Paper>
        </Grid>
      </Grid>
    </Paper>
  );

  const renderFeedbackSection = () => (
    <Paper sx={styles.sectionPaper}>
      <Box sx={styles.sectionHeader}>
        <Stack direction="row" alignItems="center" spacing={1}>
          <LightbulbIcon color="primary" />
          <Typography variant="h5">الشكاوي والمقترحات</Typography>
        </Stack>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Paper sx={styles.feedbackCard}>
            <Typography variant="h6" gutterBottom sx={styles.complaintTitle}>
              الشكاوي ({report.complaints?.length || 0})
            </Typography>
            <List dense>
              {report.complaints?.map((item, index) => (
                <ListItem key={index} sx={styles.feedbackItem}>
                  <ListItemText 
                    primary={`${index + 1}. ${item.complaint_text}`}
                    primaryTypographyProps={{ variant: 'body1' }}
                  />
                </ListItem>
              ))}
            </List>
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={styles.feedbackCard}>
            <Typography variant="h6" gutterBottom sx={styles.suggestionTitle}>
              المقترحات ({report.suggestions?.length || 0})
            </Typography>
            <List dense>
              {report.suggestions?.map((item, index) => (
                <ListItem key={index} sx={styles.feedbackItem}>
                  <ListItemText 
                    primary={`${index + 1}. ${item.suggestion_text}`}
                    primaryTypographyProps={{ variant: 'body1' }}
                  />
                </ListItem>
              ))}
            </List>
          </Paper>
        </Grid>
      </Grid>
    </Paper>
  );

  if (!report) {
    return (
      <Box sx={styles.loadingContainer}>
        <Skeleton variant="rectangular" width="100%" height={200} />
        <Skeleton variant="rectangular" width="100%" height={400} sx={{ mt: 3 }} />
