            <th>المستخدم</th>
            <th>اسم الطالب</th>
            <th>رقم الجوال</th>
            <th>النوع</th>
            <th>البرنامج</th>
            <th>الموضوع</th>
            <th>الملاحظات</th>
            <th>الحالة</th>
          </tr>
        </thead>
        <tbody>
          ${filteredCalls
            .filter(call => call.status === 'متابعة لاحقة')
