              const callFollowUps = followUpsByCall[call.guid] || [];
              return `
                <tr>
                  <td>${call.date}</td>
                  <td>${call.user}</td>
                  <td>${call.studentName}</td>
                  <td>${call.studentTel}</td>
                  <td>
                    <span class="type-badge ${call.type === 'استفسار عام' ? 'type-general' : 
