        PaperProps={{
          sx: {
            borderRadius: isPhone ? 0 : 3,
            overflow: "hidden",
            width: isPhone
              ? "100%"
              : isTablet
                ? "calc(100vw - 28px)"
                : "min(1180px, calc(100vw - 56px))",
            maxWidth: "none",
            maxHeight: isPhone
              ? "100dvh"
              : "calc(100dvh - 28px)",
            m: isPhone ? 0 : 1.75
          }
        }}
      >
        <DialogTitle
          sx={{
            color: primaryColor,
            fontWeight: 950,
