            px: isPhone ? 1.2 : 2.5,
            py: isPhone ? 1 : 1.5,
            "& .MuiStack-root": {
              minWidth: 0
            },
            "& span": {
              fontSize: isPhone ? 14 : 18,
              lineHeight: 1.45,
