                    }}
                  >
                    <thead>
                      <tr>
                        <th>البيان</th>
                        <th>الوحدة</th>
                        <th>الكمية</th>
                        <th>السعر</th>
                        <th>الضريبة %</th>
                        <th>مبلغ الضريبة</th>
                        <th>الصافي</th>
                      </tr>
                    </thead>

                    <tbody>
                      {items.length ? (
                        items.map((item, index) => (
                          <tr key={`${item.diplomName}-${index}`}>
                            <td>{item.diplomName || ""}</td>
                            <td>{item.unit || "PCS"}</td>
                            <td>{item.qty ?? ""}</td>
                            <td>{money(item.cost)}</td>
                            <td>{item.taxValue ?? ""}</td>
                            <td>{money(item.tax)}</td>
                            <td>{money(item.subTotal)}</td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan={7}>
                            لا توجد تفاصيل للفاتورة
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </Box>
                </Box>
              )}

              <Grid container spacing={1.5}>
                {[
                  ["الإجمالي", totals.total],
                  ["الضريبة", totals.tax],
                  ["الصافي", totals.subTotal]
                ].map(([label, value]) => (
                  <Grid item xs={12} sm={4} key={label}>
                    <Paper
                      variant="outlined"
                      sx={{
                        p: 1.5,
                        borderRadius: 3,
                        textAlign: "center"
                      }}
                    >
                      <Typography sx={{ fontWeight: 900 }}>
                        {label}
                      </Typography>
                      <Typography
                        variant="h6"
                        sx={{
                          color: accentColor,
                          fontWeight: 950,
                          mt: 0.5
                        }}
                      >
                        {money(value)}
                      </Typography>
                    </Paper>
                  </Grid>
                ))}
              </Grid>
            </Stack>
          ) : null}
        </DialogContent>

        <DialogActions
          sx={uiLayout.withUiSx({
            px: isPhone ? 1 : 3,
            py: isPhone ? 1 : 2,
            gap: 1,
            flexDirection: isPhone
              ? "column"
              : "row",
            alignItems: "stretch",
            bgcolor: "#fff"
          }, uiLayout.dialogActionsSx)}
        >
          <Button
            variant="contained"
            onClick={printInvoice}
            disabled={loading || printing || !data}
            startIcon={
              printing
                ? <CircularProgress size={18} color="inherit" />
                : <PrintIcon />
            }
            sx={uiLayout.withUiSx({
              minWidth: isPhone ? "100%" : 145,
              minHeight: isPhone ? 44 : undefined,
