import * as uiLayout from './common/uiLayout';
import React, { useEffect, useMemo, useState } from "react";
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Typography,
  useMediaQuery,
  useTheme
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";

import CloseIcon from "@mui/icons-material/Close";
import HistoryIcon from "@mui/icons-material/History";

const primaryColor = "#057546";
const primaryLight = "#e6f3ee";
const accentColor = "#ae1e21";
const textColor = "#1f2d3d";

const StudentOperationsDialog = ({
  open,
  onClose,
  student,
  apiBaseUrl
}) => {
  const theme = useTheme();

  const isPhone = useMediaQuery(
    theme.breakpoints.down("sm")
  );

  const isTablet = useMediaQuery(
    "(min-width:600px) and (max-width:1599px)"
  );

  const isCompact = isPhone || isTablet;

  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const actionGuid =
    student?.actionHistoryGuid ||
    student?.ActionHistoryGuid ||
    student?.raw?.__index_10 ||
    student?.accountGuid ||
    "";

  useEffect(() => {
    if (!open || !actionGuid) return undefined;

    const controller = new AbortController();

    const loadOperations = async () => {
      try {
        setLoading(true);
        setError("");
        setRows([]);

        const params = new URLSearchParams({
          actionGuid
        });

        const response = await fetch(
          `${apiBaseUrl}/api/reception-office/students/operations?${params.toString()}`,
          {
            signal: controller.signal
          }
        );

        const result =
          await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
              result?.error ||
              "تعذر تحميل عمليات الطالب"
          );
        }

        setRows(
          Array.isArray(result?.data)
            ? result.data
            : []
        );
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(
            err.message ||
              "حدث خطأ أثناء تحميل عمليات الطالب"
          );
        }
      } finally {
        setLoading(false);
      }
    };

    loadOperations();

    return () => controller.abort();
  }, [open, actionGuid, apiBaseUrl]);

  /*
   * على الموبايل نخفي عمود الملاحظات،
   * ونركز على:
   * المستخدم + العملية + التاريخ
   *
