    let subTotal = toNumber(row.subTotal);

    if (changedField === "subTotal") {
      if (subTotal > 0) {
        cost = subTotal / (1 + taxPercent / 100);
        tax = subTotal - cost;
      }
    } else {
      const baseTotal = qty * cost;
      tax = baseTotal * (taxPercent / 100);
      subTotal = baseTotal + tax;
    }

    return {
      ...row,
      qty: round2(qty),
