      field: "costCenter",
      headerName: "مركز التكلفة",
      flex: 1,
      minWidth: 180,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (
        <EllipsisText value={params.value} align="center" direction="rtl" />
