      row?.billGuid ||
      row?.BillGuid ||
      row?.guid ||
      row?.Guid ||
      row?.actionGuid ||
      "";

    if (!billGuid) {
      setError("تعذر قراءة رقم الفاتورة الداخلي");
      return;
    }

    setSelectedSalesInvoice({
      ...row,
      billGuid
    });

    setSalesInvoiceOpen(true);
  };

