    {
      field: "actions",
      headerName: "عرض",
      width: 90,
      sortable: false,
      filterable: false,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (
        <Button
          size="small"
          variant="outlined"
          onClick={() => openSalesInvoice(params.row)}
          sx={uiLayout.withUiSx({
            borderRadius: 2,
            fontWeight: 900,
            color: primaryColor,
            borderColor: primaryLight,
            backgroundColor: whiteColor,
            "&:hover": {
              borderColor: primaryColor,
              backgroundColor: "#f0faf5"
            }
          }, uiLayout.buttonSx)}
        >
          عرض
        </Button>
      )
    },
    {
      field: "date",
      headerName: "التاريخ الميلادي",
      width: 130,
      align: "center",
      headerAlign: "center",
      valueFormatter: (params) =>
        formatGregorianDate(
          params && typeof params === "object" && "value" in params
            ? params.value
            : params
        )
    },
    {
      field: "invoiceNo",
      headerName: "رقم الفاتورة",
      width: 150,
      align: "center",
      headerAlign: "center"
    },
    {
      field: "notes",
      headerName: "ملاحظات",
      flex: 1,
      minWidth: 330,
      renderCell: (params) => <EllipsisText value={params.value} />
    },
    {
      field: "total",
      headerName: "الإجمالي",
      width: 130,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => <MoneyCell value={params.row?.total} />
    },
    {
      field: "collector",
      headerName: "المحصل",
      width: 240,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (
