            borderRadius: 2,
            fontWeight: 900,
            color: accentColor,
            borderColor: "#f3c6c7",
            backgroundColor: whiteColor,
            "&:hover": {
              borderColor: accentColor,
              backgroundColor: "#fff4f4"
            }
          }, uiLayout.buttonSx)}
        >
          عرض
        </Button>
      )
    },
    {
      field: "date",
      headerName: "التاريخ الميلادي",
      width: 130,
      align: "center",
      headerAlign: "center",
