    {
      field: "notes",
      headerName: "ملاحظات",
      flex: 1,
      minWidth: 330,
      renderCell: (params) => <EllipsisText value={params.value} />
    },
    {
      field: "total",
      headerName: "الإجمالي",
      width: 130,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => <MoneyCell value={params.row?.total} />
    },
    {
      field: "collector",
      headerName: "المحصل",
      width: 240,
      align: "center",
      headerAlign: "center",
      renderCell: (params) => (
        <EllipsisText value={params.value} align="center" direction="rtl" />
