                  width: isPhone ? 25 : isTablet ? 28 : undefined,
                  height: isPhone ? 25 : isTablet ? 28 : undefined,
                  p: isCompact ? 0.25 : undefined,
                  "& svg": {
                    fontSize: isPhone ? 15 : isTablet ? 17 : undefined
                  }
