          display: "flex",
          flexDirection: "column",
          minHeight: 0
        }}
      >
        <Stack
          direction="row"
          spacing={isCompact ? 0.35 : 1.5}
          flexWrap="nowrap"
          sx={{ mb: isCompact ? 0.45 : 2 }}
