                  noRowsLabel: "لا توجد بيانات",
                  footerRowSelected: (count) => `${count} صف محدد`,
                  MuiTablePagination: {
                    labelRowsPerPage: "عدد الصفوف"
                  }
                }}
                sx={uiLayout.withUiSx(gridSx, uiLayout.dataGridSx)}
