            color: whiteColor,
            direction: "rtl",
            textAlign: "center",
            background: `linear-gradient(135deg, ${primaryColor}, ${primaryDark})`,
            py: isPhone ? 0.45 : isTablet ? 0.65 : 1.4,
            px: isPhone ? 0.55 : isTablet ? 0.8 : 2,
