            >
              كشف حساب سابق
            </Typography>

            <Tooltip title="تصدير كشف الحساب السابق PDF">
              <span>
                <IconButton
                  onClick={exportOldStatementToPdf}
                  disabled={oldStatementLoading || !oldStatementData}
                  sx={{
                    color: whiteColor,
                    width: isPhone ? 25 : isTablet ? 28 : 36,
                    height: isPhone ? 25 : isTablet ? 28 : 36,
                    p: isCompact ? 0.25 : 0.7,
                    "& svg": {
                      fontSize: isPhone ? 15 : isTablet ? 17 : 21
                    },
                    "&.Mui-disabled": {
                      color: "rgba(255,255,255,0.45)"
                    }
                  }}
                >
                  <PrintIcon />
                </IconButton>
              </span>
            </Tooltip>
          </Stack>
        </DialogTitle>

        <DialogContent
          dividers
          sx={{
            direction: "rtl",
            p: isPhone ? 0.4 : isTablet ? 0.7 : 2
          }}
        >
          {oldStatementLoading ? (
            <Stack alignItems="center" spacing={2} sx={{ py: 8 }}>
              <CircularProgress />
              <Typography sx={{ fontWeight: 900 }}>
                جاري تحميل كشف الحساب السابق...
              </Typography>
            </Stack>
          ) : oldStatementError ? (
            <Alert severity="error" sx={{ fontWeight: 900 }}>
              {oldStatementError}
            </Alert>
          ) : oldStatementData ? (
            <Stack sx={uiLayout.tableContainerSx} spacing={2}>
              <Stack direction="row" spacing={isCompact ? 0.3 : 1} flexWrap="nowrap">
                <SummaryCard
                  label="مدين"
                  value={oldStatementData?.summary?.debit || 0}
                />
                <SummaryCard
                  label="دائن"
                  value={oldStatementData?.summary?.credit || 0}
                />
                <SummaryCard
                  label="الرصيد"
                  value={oldStatementData?.summary?.balance || 0}
                  color={
                    toNumber(oldStatementData?.summary?.balance) > 0
                      ? accentColor
                      : primaryColor
                  }
                />
                <SummaryCard
                  label="افتتاحي مدين"
                  value={oldStatementData?.opening?.debit || 0}
                />
                <SummaryCard
                  label="افتتاحي دائن"
                  value={oldStatementData?.opening?.credit || 0}
                />
              </Stack>

              <Typography sx={{ fontWeight: 1000, color: primaryColor }}>
                استمارات التسجيل
              </Typography>

              <DataGrid
                rows={oldStatementRows(oldStatementData?.registrations || [])}
                columns={isCompact ? compactOldRegistrationColumns.map(compactGridColumn) : oldRegistrationColumns}
                disableRowSelectionOnClick
                autoHeight
                pageSizeOptions={[30, 60, 100]}
                initialState={{
                  pagination: {
                    paginationModel: { pageSize: 30, page: 0 }
                  }
                }}
                sx={uiLayout.withUiSx(gridSx, uiLayout.dataGridSx)}
              />

              <Typography sx={{ fontWeight: 1000, color: primaryColor }}>
                الحركات النقدية
              </Typography>

              <DataGrid
                rows={oldStatementRows(oldStatementData?.cashMovements || [])}
                columns={isCompact ? compactOldCashColumns.map(compactGridColumn) : oldCashColumns}
                disableRowSelectionOnClick
                autoHeight
                pageSizeOptions={[30, 60, 100]}
                initialState={{
                  pagination: {
                    paginationModel: { pageSize: 30, page: 0 }
                  }
                }}
                sx={uiLayout.withUiSx(gridSx, uiLayout.dataGridSx)}
              />
            </Stack>
          ) : null}
        </DialogContent>

        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button
            onClick={() => setOldStatementOpen(false)}
            disabled={oldStatementLoading}
            sx={uiLayout.withUiSx({ color: accentColor, fontWeight: 900 }, uiLayout.buttonSx)}
          >
            إغلاق
          </Button>
        </DialogActions>
      </Dialog>

      <SalesInvoiceDialog
        open={salesInvoiceOpen}
        onClose={() => {
          setSalesInvoiceOpen(false);
          setSelectedSalesInvoice(null);
        }}
        invoice={selectedSalesInvoice}
        apiBaseUrl={apiBaseUrl}
      />
    </Dialog>
  );
};

export default StudentStatementDialog2

import * as uiLayout from './common/uiLayout';
import React, { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  Paper,
  Stack,
  TextField,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import FolderSharedIcon from "@mui/icons-material/FolderShared";
import AttachFileIcon from "@mui/icons-material/AttachFile";
import RefreshIcon from "@mui/icons-material/Refresh";
import SchoolIcon from "@mui/icons-material/School";
import GroupsIcon from "@mui/icons-material/Groups";
import EventIcon from "@mui/icons-material/Event";
import NotesIcon from "@mui/icons-material/Notes";
import Swal from "sweetalert2";
import "sweetalert2/dist/sweetalert2.min.css";

const primaryColor = "#057546";
const primaryDark = "#034d31";
const primaryLight = "#e6f3ee";
const accentColor = "#ae1e21";
const whiteColor = "#fefefe";
const softBg = "#fefefe";
const textColor = "#1f2d3d";
const dangerColor = accentColor;
const warningColor = accentColor;
const noGuid = "00000000-0000-0000-0000-000000000000";

const safeText = (value) => {
  if (value === null || value === undefined || value === "") return "-";
  return String(value);
};

const pick = (obj, ...names) => {
  for (const name of names) {
    const value = obj?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== "") return value;
  }
  return "";
};

const showWarning = (message) =>
  Swal.fire({
    icon: "warning",
    title: "تنبيه",
    text: message,
    confirmButtonText: "حسناً",
    confirmButtonColor: warningColor
  });

const showError = (message) =>
  Swal.fire({
    icon: "error",
    title: "خطأ",
    text: message,
    confirmButtonText: "حسناً",
    confirmButtonColor: accentColor
  });

const showSuccess = (message) =>
  Swal.fire({
    icon: "success",
    title: "تم بنجاح",
    text: message,
    confirmButtonText: "حسناً",
    confirmButtonColor: primaryColor
  });

const FieldBox = ({ label, value, icon, strong = false, color = textColor }) => (
  <Paper
    elevation={0}
    sx={{
      p: 1.4,
      borderRadius: 3,
      "@media (max-width:1599px)": {
        p: 0.5,
        borderRadius: 1.35,
        minHeight: 48
      },
      "@media (max-width:599px)": {
        p: 0.35,
        minHeight: 44
      },
      border: `1px solid ${primaryLight}`,
      background: strong
        ? `linear-gradient(135deg, #fff6f6 0%, ${whiteColor} 100%)`
        : `linear-gradient(135deg, #f4fbf7 0%, ${whiteColor} 100%)`,
      height: "100%",
      position: "relative",
      overflow: "hidden"
    }}
  >
    <Stack
      direction="row"
      spacing={0.8}
      alignItems="center"
      sx={{
        mb: 0.7,
        "@media (max-width:1599px)": { mb: 0.18, gap: "4px !important" }
      }}
    >
      {icon}
      <Typography
        sx={{
          color: primaryColor,
          fontWeight: 950,
          fontSize: "0.78rem",
          lineHeight: 1.1,
          "@media (max-width:1599px)": { fontSize: "0.75rem" },
          "@media (max-width:599px)": { fontSize: "0.75rem" }
        }}
      >
        {label}
      </Typography>
    </Stack>
    <Tooltip title={safeText(value)} arrow>
      <Typography
        sx={{
          color,
          fontWeight: strong ? 1000 : 950,
          fontSize: strong ? "1rem" : "0.92rem",
          lineHeight: 1.7,
          "@media (max-width:1599px)": {
            fontSize: strong ? "0.75rem" : "0.75rem",
            lineHeight: 1.2
          },
          "@media (max-width:599px)": {
            fontSize: strong ? "0.75rem" : "0.75rem"
          },
          textAlign: "start",
          direction: "rtl",
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis"
        }}
      >
        <bdi dir="auto">{safeText(value)}</bdi>
      </Typography>
    </Tooltip>
  </Paper>
);

const statusChipSx = (value) => {
  const text = String(value || "");

  if (text.includes("مستمر") || text.includes("نشط")) {
    return { color: primaryColor, backgroundColor: "#e6f3ee" };
  }

  if (text.includes("موقوف") || text.includes("منتهي") || text.includes("منتهى")) {
    return { color: dangerColor, backgroundColor: "#fff4f4" };
  }

  return { color: warningColor, backgroundColor: "#fff4f4" };
};

const StudentStudyFileDialog = ({ open, onClose, student, apiBaseUrl }) => {
  const theme = useTheme();
  const isPhone = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery("(min-width:600px) and (max-width:1599px)");
  const isCompact = isPhone || isTablet;

  const [loading, setLoading] = useState(false);
  const [savingClass, setSavingClass] = useState(false);
  const [studyInfo, setStudyInfo] = useState(null);
  const [manualClassGuid, setManualClassGuid] = useState("");

  const getResponsiveSwalOptions = () => {
    if (!isCompact) return {};

    return {
      width: isPhone ? "82vw" : "420px",
      padding: isPhone ? "0.65rem" : "0.85rem",
      customClass: {
        popup: "sstli-study-swal",
        icon: "sstli-study-swal-icon",
        title: "sstli-study-swal-title",
        htmlContainer: "sstli-study-swal-text",
        actions: "sstli-study-swal-actions",
        confirmButton: "sstli-study-swal-confirm",
        cancelButton: "sstli-study-swal-cancel"
      }
    };
  };

  const studentGuid = useMemo(
    () => pick(student, "accountGuid", "AccountGuid", "studentGuid", "StudentGuid"),
    [student]
  );
  const diplomGuid = useMemo(() => pick(student, "diplomGuid", "DiplomGuid"), [student]);
  const branchGuid = useMemo(
    () => pick(student, "branchGuid", "BranchGuid", "studyBranchGuid", "StudyBranchGuid"),
    [student]
  );
  const nationalId = useMemo(() => pick(student, "nationalId", "NationalId"), [student]);

  const canLoad = Boolean(studentGuid && diplomGuid && branchGuid);

  const loadStudyInfo = async () => {
    if (!open || !student) return;

    if (!canLoad) {
      setStudyInfo(null);
      showWarning("لا يمكن قراءة بيانات الملف التدريبي: ناقص حساب الطالب أو الدبلوم أو الفرع.");
      return;
    }

    try {
      setLoading(true);
      setStudyInfo(null);

      const params = new URLSearchParams({
        studentGuid,
        diplomGuid,
        branchGuid
      });

      const response = await fetch(`${apiBaseUrl}/api/student-study-file/info?${params.toString()}`);
      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.message || result?.error || "تعذر تحميل الملف التدريبي");
      }

      setStudyInfo(result?.data || null);
      setManualClassGuid(result?.data?.classGuid || "");
    } catch (error) {
      showError(error.message || "حدث خطأ أثناء تحميل الملف التدريبي");
      setStudyInfo(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (open) loadStudyInfo();
    else {
      setStudyInfo(null);
      setManualClassGuid("");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, studentGuid, diplomGuid, branchGuid]);

  const openAttachments = async () => {
    const id = String(nationalId || "").trim();

    if (!id) {
      showWarning("برجاء اختيار الطالب أولاً.");
      return;
    }

    if (!/^\d+$/.test(id)) {
      showWarning("رقم الهوية غير صحيح.");
      return;
    }

    try {
      const params = new URLSearchParams({ nationalId: id });
      const response = await fetch(`${apiBaseUrl}/api/student-study-file/attachments-url?${params.toString()}`);
      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.message || result?.error || "تعذر تجهيز رابط المرفقات");
      }

      const url = result?.url;
      if (!url) {
        showWarning("لم يتم تجهيز رابط المرفقات.");
        return;
      }

      window.open(url, "_blank", "noopener,noreferrer");
    } catch (error) {
      showError(error.message || "حدث خطأ أثناء عرض المرفقات");
    }
  };

  const updateClass = async () => {
    const regType = String(studyInfo?.regType ?? "");

    if (regType !== "0") {
      showWarning("الملف التدريبي للطالب غير مسموح له ربط بشعبة.");
      return;
    }

    const classGuid = String(manualClassGuid || "").trim();

    if (!studyInfo?.guid || studyInfo.guid === noGuid) {
      showWarning("لا يمكن قراءة Guid الملف التدريبي.");
      return;
    }

    if (!classGuid || classGuid === noGuid) {
      showWarning("برجاء إدخال ClassGuid للشعبة المراد ربطها.");
      return;
    }

    const confirm = await Swal.fire({
      ...getResponsiveSwalOptions(),
      icon: "question",
      title: "ربط المتدرب بشعبة",
      text: "هل تريد ربط الطالب بالشعبة المحددة؟",
      showCancelButton: true,
      confirmButtonText: "نعم، ربط",
      cancelButtonText: "تراجع",
      confirmButtonColor: primaryColor,
      cancelButtonColor: "#777",
      reverseButtons: true
    });

    if (!confirm.isConfirmed) return;

    try {
      setSavingClass(true);

      const response = await fetch(`${apiBaseUrl}/api/student-study-file/class`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          guid: studyInfo.guid,
          classGuid,
          isReg: true
        })
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.message || result?.error || "تعذر ربط الطالب بالشعبة");
      }

      await showSuccess(result?.message || "تم ربط الطالب بالشعبة بنجاح");
      await loadStudyInfo();
    } catch (error) {
      showError(error.message || "حدث خطأ أثناء ربط الطالب بالشعبة");
    } finally {
      setSavingClass(false);
    }
  };

  return (
    <>
      <style>
        {`
          @media (max-width: 1599px) {
            .sstli-study-swal {
              max-width: 420px !important;
              border-radius: 14px !important;
              font-family: Cairo, Arial, sans-serif !important;
            }
            .sstli-study-swal-icon {
              width: 3.4em !important;
              height: 3.4em !important;
              margin: 0.6em auto 0.25em !important;
            }
            .sstli-study-swal-icon .swal2-icon-content {
              font-size: 2.3em !important;
            }
            .sstli-study-swal-title {
              font-size: 0.95rem !important;
              line-height: 1.2 !important;
              padding-top: 0.2em !important;
            }
            .sstli-study-swal-text {
              font-size: 0.68rem !important;
              line-height: 1.4 !important;
              padding: 0 0.75em !important;
            }
            .sstli-study-swal-actions {
              margin-top: 0.65em !important;
              gap: 0.35rem !important;
            }
            .sstli-study-swal-confirm,
            .sstli-study-swal-cancel {
              min-width: 76px !important;
              min-height: 31px !important;
              padding: 0.38rem 0.75rem !important;
              margin: 0 !important;
              font-size: 0.66rem !important;
              border-radius: 8px !important;
              font-weight: 900 !important;
            }
          }

          @media (max-width: 599px) {
            .sstli-study-swal {
