            .student-table {
              width: 100%;
              border-collapse: collapse;
              table-layout: fixed;
              margin-bottom: 8px;
              font-size: 13px;
            }

            .student-table td {
              border: 1px solid #111;
              padding: 6px 5px;
              text-align: center;
              vertical-align: middle;
              font-weight: 700;
            }

            .greeting {
              margin: 8px 0 2px;
              text-align: center;
              font-size: 15px;
              font-weight: 700;
              line-height: 1.9;
            }

            .separator {
              width: 100%;
              margin: 7px 0 10px;
              border-top: 1px solid #111;
            }

            .approval-body {
              width: 100%;
              margin: 0 auto;
              text-align: center;
              font-size: 14px;
              font-weight: 700;
              line-height: 2.48;
              letter-spacing: -0.08px;
            }

            .closing-text {
              margin: 10px 0 0;
              text-align: center;
              font-size: 15px;
              font-weight: 700;
            }

            .auth-section {
              width: 94%;
              margin: 82px 0 0;
              display: grid;
              grid-template-columns: 1.7fr 0.7fr;
              gap: 24px;
              align-items: start;
              direction: ltr;
            }

            .signature-area {
              direction: rtl;
              justify-self: start;
              width: 365px;
              max-width: 100%;
              margin-left: 0;
              padding-left: 0;
              transform: translateX(-24px);
            }

            .institute-name {
              width: 100%;
              margin-bottom: 7px;
              text-align: right;
              font-size: 15px;
              font-weight: 700;
            }

            .signature-line,
            .stamp-line {
              direction: rtl;
              display: flex;
              flex-direction: row;
              align-items: center;
              justify-content: flex-start;
              gap: 10px;
              width: 100%;
              text-align: right;
            }

            .signature-line {
              margin-top: 2px;
            }

            .stamp-line {
              margin-top: -5px;
            }

            .signature-line img {
              display: block;
              width: 132px;
              height: 52px;
              object-fit: contain;
              object-position: left center;
            }

            .stamp-line img {
              display: block;
              width: 162px;
              height: 96px;
              object-fit: contain;
              object-position: left center;
            }

            .signature-label,
            .stamp-label {
              width: 78px;
              min-width: 78px;
              text-align: right;
              direction: rtl;
              font-size: 15px;
              font-weight: 700;
              white-space: nowrap;
            }

            .verification-area {
              direction: rtl;
              text-align: center;
              align-self: start;
              padding-bottom: 0;
              transform: translateY(4px);
            }

            .verification-area img {
              display: block;
              width: 108px;
              height: 108px;
              margin: 0 auto 5px;
            }

            .verification-caption {
              font-size: 12px;
              font-weight: 700;
            }

            .footer-image {
              position: absolute;
              left: 0;
              right: 0;
              bottom: 0;
              z-index: 1;
              display: block;
              width: 100%;
              height: auto;
              margin: 0;
            }

            @media print {
              html,
              body {
                width: 210mm;
                height: 297mm;
                margin: 0;
                padding: 0;
                background: #fff;
                overflow: hidden;
              }

              .page {
                width: 210mm;
                height: 297mm;
                min-height: 297mm;
                max-height: 297mm;
                margin: 0;
                overflow: hidden;
                page-break-inside: avoid;
                break-inside: avoid-page;
              }
            }
          </style>
        </head>

        <body>
          <div class="page">
            <div class="watermark">
              <img src="${watermarkUrl}" alt="" />
            </div>

            <img
              class="header-image"
              src="${headerUrl}"
              alt="رأس الخطاب"
            />

            <main class="content">
              <div class="issue-date">
                تاريخ إصدار الموافقة:
                ${new Date().toLocaleDateString("ar-SA")} هـ
              </div>

              <div class="document-title">طلب موافقة</div>

              <table class="student-table">
                <tr>
                  <td>الاسم</td>
                  <td>رقم السجل المدني</td>
                  <td>طلب موافقة (${approvalType})</td>
                </tr>
                <tr>
                  <td>${studentName}</td>
                  <td>${nationalId}</td>
                  <td>${displayProgramName}</td>
                </tr>
              </table>

              <div class="greeting">
                السلام عليكم ورحمة الله وبركاته<br />
                تحية طيبة وبعد ،،،،
              </div>

              <div class="separator"></div>

              <div class="approval-body">
                نفيد سعادتكم بأن الموضح بياناته أعلاه لا مانع لدينا من تسجيله في
                ${displayProgramName}، والمعتمد من المؤسسة العامة للتدريب التقني والمهني،
                وبعدد ساعات (${hours}) ${hoursLabel}، ${studyLine}
                وعدد الساعات حتى تاريخه صفر، وفي حال الموافقة تكون الدراسة ابتداءً من
                <span style="white-space: nowrap">${startDateLine}</span>،
                وتكون نهاية الدراسة المتوقعة بتاريخ
                <span style="white-space: nowrap">${endDateLine}</span>،
                وقد أُعطي هذا المشهد بناءً على طلبه، دون أدنى مسؤولية على المعهد.
              </div>

              <div class="separator"></div>

              <div class="closing-text">
                هذا لإحاطة سعادتكم، والله ولي التوفيق
              </div>

              <section class="auth-section">
                <div class="signature-area">
                  <div class="institute-name">
                    المعهد السعودي المتخصص العالي للتدريب
                  </div>

                  <div class="signature-line">
                    <span class="signature-label"> التوقيع :</span>
                    <img src="${signUrl}" alt="التوقيع" />
                  </div>

                  <div class="stamp-line">
                    <span class="stamp-label"> الـخـتـم :  </span>
                    <img src="${stampUrl}" alt="الختم" />
                  </div>
                </div>

                <div class="verification-area">
                  <img
                    src="https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(
                      qrUrl
                    )}"
                    alt="رمز التحقق"
                  />
                  <div class="verification-caption">
                    فحص موثوقية الموافقة
                  </div>
                </div>
              </section>
            </main>

            <img
              class="footer-image"
              src="${footerUrl}"
              alt="تذييل الخطاب"
            />
          </div>

          <script>
            (function () {
              function waitForImages() {
                var images = Array.prototype.slice.call(document.images || []);

                return Promise.all(
                  images.map(function (image) {
                    if (image.complete && image.naturalWidth > 0) {
                      return Promise.resolve();
                    }

                    return new Promise(function (resolve) {
                      var finish = function () { resolve(); };
                      image.onload = finish;
                      image.onerror = finish;
                      window.setTimeout(finish, 5000);
                    });
                  })
                );
              }

              window.addEventListener("load", function () {
                var fontsReady =
                  document.fonts && document.fonts.ready
                    ? document.fonts.ready
                    : Promise.resolve();

                Promise.all([fontsReady, waitForImages()]).then(function () {
                  window.focus();
                  window.setTimeout(function () {
                    window.print();
                  }, 250);
                });
              });
            })();
          </script>
        </body>
        </html>
      `);

      printWindow.document.close();
    } catch (e) {
      setError(e.message || "تعذر طباعة الموافقة");
    }
  };

  return (
    <Dialog
      open={open}
      onClose={saving ? undefined : onClose}
      maxWidth="xl"
      fullWidth
      fullScreen={isPhone}
      dir="rtl"
      sx={uiLayout.withUiSx({
        "& .MuiDialog-container": {
          pt: isPhone ? "58px" : isTablet ? "58px" : 1.25,
          px: isPhone ? 0 : isTablet ? 0.5 : 1.25,
          pb: isPhone ? 0 : isTablet ? 0.5 : 1.25,
          alignItems: isPhone ? "stretch" : "center"
        }
      }, uiLayout.dialogLayoutSx)}
      PaperProps={{
        sx: {
          width: isPhone ? "100vw" : isTablet ? "96vw" : "min(96vw, 1500px)",
          maxWidth: isPhone ? "100vw" : isTablet ? "1100px" : "1500px",
          height: isPhone
            ? "calc(100dvh - 58px)"
            : isTablet
              ? "calc(100dvh - 72px)"
              : "90vh",
          maxHeight: isPhone
            ? "calc(100dvh - 58px)"
            : isTablet
              ? "calc(100dvh - 72px)"
              : "90vh",
          minHeight: 0,
          m: 0,
          borderRadius: isPhone ? 0 : isTablet ? 2 : 3,
          overflow: "hidden",
          overflowX: "hidden",
          display: "flex",
          flexDirection: "column"
        }
      }}
    >
      <DialogTitle
        sx={{
          fontWeight: 950,
          color: primaryColor,
          display: "flex",
          alignItems: "center",
          gap: 1
        }}
      >
        <SchoolIcon sx={{ fontSize: isPhone ? 14 : isTablet ? 17 : undefined }} />
        {editMode
          ? `تعديل موافقة دراسية رقم ${
              currentOrderCode ||
              orderCode ||
              ""
            }`
          : "طلب موافقة دراسية"}
      </DialogTitle>

      <DialogContent
        dividers
        sx={{
          px: isPhone ? 1.2 : isTablet ? 1.5 : 1.75,
          py: isPhone ? 0.8 : isTablet ? 1 : 1.35,
          overflowY: "auto",
          overflowX: "hidden",
          flex: 1,
          minHeight: 0,

          // MUI Grid spacing can add negative side margins / calc(100% + gap),
          // which creates a useless horizontal scrollbar inside the dialog.
          // Keep every form row inside the actual content width.
          "& .MuiGrid-container": {
            width: "100%",
            maxWidth: "100%",
            ml: 0,
            mr: 0,
            boxSizing: "border-box"
          },

          "& .MuiGrid-item": {
            minWidth: 0,
            boxSizing: "border-box"
          },

          "& .MuiInputLabel-root": {
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          },
          "& .MuiInputBase-input, & .MuiSelect-select": {
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
            py: isPhone ? 0.5 : isTablet ? 0.65 : undefined
          },
          "& .MuiOutlinedInput-root": {
            minHeight: isPhone ? 31 : isTablet ? 35 : undefined,
            borderRadius: isCompact ? 1.2 : undefined
          },
          "& .MuiFormLabel-root": {
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
            fontWeight: 900,
            mb: isPhone ? 0.35 : isTablet ? 0.45 : undefined
          },
          "& .MuiFormControlLabel-label": {
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined,
            fontWeight: 800
          },
          "& .MuiRadio-root": {
            p: isPhone ? 0.35 : isTablet ? 0.5 : undefined
          },
          "& .MuiRadio-root svg": {
            fontSize: isPhone ? 17 : isTablet ? 19 : undefined
          },

          "& .MuiFormControl-root": {
            mb: isPhone ? 0.25 : isTablet ? 0.35 : undefined
          },

          "& .MuiTextField-root": {
            mt: isPhone ? 0.05 : isTablet ? 0.08 : undefined
          }
        }}
      >
        {error ? (
          <Alert
            severity="error"
            sx={{
              mb: isCompact ? 0.4 : 2,
              py: isCompact ? 0.15 : undefined,
              fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
            }}
          >
            {error}
          </Alert>
        ) : null}

        {loadingLookups || loadingOrder ? (
          <Box sx={{ py: 8, textAlign: "center" }}>
            <CircularProgress />
          </Box>
        ) : (
          <Stack
            spacing={isPhone ? 0.9 : isTablet ? 1.1 : 1.35}
            sx={{
              minWidth: 0,
              width: "100%",
              alignItems: "stretch"
            }}
          >
            <Grid container spacing={isPhone ? 0.75 : isTablet ? 0.95 : 1.5}>
              <Grid item xs={12} sm={6} md={4}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="اسم الطالب"
                  value={studentName}
                  InputProps={{ readOnly: true }}
                />
              </Grid>

              <Grid item xs={12} sm={3} md={4}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="رقم الهوية"
                  value={nationalId}
                  InputProps={{ readOnly: true }}
                 inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
              </Grid>

              <Grid item xs={12} sm={3} md={4}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="رقم الجوال"
                  value={studentTel}
                  InputProps={{ readOnly: true }}
                 inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
              </Grid>
            </Grid>

            <Grid container spacing={isPhone ? 0.75 : isTablet ? 0.9 : 1.25}>
              <Grid item xs={12} md={6}>
                <FormControl
                  fullWidth
                  sx={uiLayout.withUiSx(
                    {
                      minWidth: 0
                    },
                    uiLayout.formFieldSx
                  )}
                >
                  <FormLabel>نوع البرنامج</FormLabel>

                  <RadioGroup
                    sx={uiLayout.radioGroupSx}
                    row
                    value={programType}
                    onChange={(e) => setProgramType(Number(e.target.value))}
                  >
                    {approvalTypes.map((item) => (
                      <FormControlLabel
                        key={item.value}
                        value={item.value}
                        control={<Radio />}
                        label={item.label}
                      />
                    ))}
                  </RadioGroup>
                </FormControl>
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl
                  fullWidth
                  sx={uiLayout.withUiSx(
                    {
                      minWidth: 0
                    },
                    uiLayout.formFieldSx
                  )}
                >
                  <FormLabel>نوع الدراسة</FormLabel>

                  <RadioGroup
                    sx={uiLayout.radioGroupSx}
                    row
                    value={studyType}
                    onChange={(e) => setStudyType(Number(e.target.value))}
                  >
                    <FormControlLabel
                      value={0}
                      control={<Radio />}
                      label="حضوري"
                    />

                    <FormControlLabel
                      value={1}
                      control={<Radio />}
                      label="عن بعد"
                    />
                  </RadioGroup>
                </FormControl>
              </Grid>
            </Grid>

            <Grid container spacing={isPhone ? 0.8 : isTablet ? 1 : 2}>
              <Grid item xs={12} sm={6} md={6}>
                <FormControl sx={uiLayout.formFieldSx} fullWidth>
                  <InputLabel>فرع الدراسة</InputLabel>
                  <Select
                    value={branchGuid}
                    label="فرع الدراسة"
                    onChange={(e) => setBranchGuid(e.target.value)}
                    MenuProps={compactMenuProps}
                  >
                    {branches.map((item) => (
                      <MenuItem key={item.guid} value={item.guid}>
                        {item.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} sm={6} md={6}>
                <FormControl sx={uiLayout.formFieldSx} fullWidth>
                  <InputLabel>القطاع التابع له المتدرب</InputLabel>
                  <Select
                    value={sectorGuid}
                    label="القطاع التابع له المتدرب"
                    onChange={(e) => setSectorGuid(e.target.value)}
                    MenuProps={compactMenuProps}
                  >
                    {sectors.map((item) => (
                      <MenuItem key={item.guid} value={item.guid}>
                        {item.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              {programType === 0 ? (
                <>
                  <Grid item xs={12} sm={6} md={6}>
                    <FormControl sx={uiLayout.formFieldSx} fullWidth>
                      <InputLabel>البرنامج المراد التسجيل به</InputLabel>
                      <Select
                        value={diplomGuid}
                        label="البرنامج المراد التسجيل به"
                        onChange={(e) => setDiplomGuid(e.target.value)}
                        MenuProps={compactMenuProps}
                        disabled={!branchGuid}
                      >
                        {programs.map((item) => (
                          <MenuItem key={item.guid} value={item.guid}>
                            {item.name}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>

                  <Grid item xs={12} sm={6} md={6}>
                    <FormControl sx={uiLayout.formFieldSx} fullWidth>
                      <InputLabel>الدفعة</InputLabel>
                      <Select
                        value={batchGuid}
                        label="الدفعة"
                        onChange={(e) => setBatchGuid(e.target.value)}
                        MenuProps={compactMenuProps}
                        disabled={!branchGuid}
                      >
                        {batches.map((item) => {
                          const remaining = Number(
                            item.remainingApprovals ?? item.available ?? 0
                          );

                          return (
                            <MenuItem
                              key={item.guid}
                              value={item.guid}
                              disabled={remaining <= 0}
                            >
                              {item.name} — الموافقات: {item.totalApprovals || 0}
                              {` | المستخدم: ${item.usedApprovals || 0}`}
                              {` | المتبقي: ${remaining}`}
                            </MenuItem>
                          );
                        })}
                      </Select>
                    </FormControl>
                  </Grid>
                </>
              ) : programType === 1 ? (
                <>
                  <Grid item xs={12} sm={6} md={6}>
                    <FormControl sx={uiLayout.formFieldSx} fullWidth>
                      <InputLabel>الدفعة</InputLabel>
                      <Select
                        value={batchGuid}
                        label="الدفعة"
                        onChange={(e) => setBatchGuid(e.target.value)}
                        MenuProps={compactMenuProps}
                        disabled={!branchGuid}
                      >
                        {batches.map((item) => {
                          const remaining = Number(
                            item.remainingApprovals ?? item.available ?? 0
                          );

                          return (
                            <MenuItem
                              key={item.guid}
                              value={item.guid}
                              disabled={remaining <= 0}
                            >
                              {item.name} — الموافقات: {item.totalApprovals || 0}
                              {` | المستخدم: ${item.usedApprovals || 0}`}
                              {` | المتبقي: ${remaining}`}
                            </MenuItem>
                          );
                        })}
                      </Select>
                    </FormControl>
                  </Grid>

                  <Grid item xs={12} sm={6} md={6}>
                    <FormControl sx={uiLayout.formFieldSx} fullWidth>
                      <InputLabel>البرنامج المراد التسجيل به</InputLabel>
                      <Select
                        value={diplomGuid}
                        label="البرنامج المراد التسجيل به"
                        onChange={(e) => setDiplomGuid(e.target.value)}
                        MenuProps={compactMenuProps}
                        disabled={!branchGuid || !batchGuid}
                      >
                        {programs.map((item) => (
                          <MenuItem key={item.guid} value={item.guid}>
                            {item.name}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                </>
              ) : (
                <Grid item xs={12} sm={6} md={6}>
                  <FormControl sx={uiLayout.formFieldSx} fullWidth>
                    <InputLabel>البرنامج المراد التسجيل به</InputLabel>
                    <Select
                      value={diplomGuid}
                      label="البرنامج المراد التسجيل به"
                      onChange={(e) => setDiplomGuid(e.target.value)}
                      MenuProps={compactMenuProps}
                      disabled={!branchGuid}
                    >
                      {programs.map((item) => (
                        <MenuItem key={item.guid} value={item.guid}>
                          {item.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
              )}

              {programType !== 2 && selectedBatch ? (
                <Grid item xs={12}>
                  <Alert
                    severity={selectedBatchRemaining > 0 ? "success" : "error"}
                  >
                    الدفعة: <strong>{selectedBatch.name}</strong>
                    {" — "}الموافقات المحددة: {selectedBatch.totalApprovals || 0}
                    {" — "}المستخدمة: {selectedBatch.usedApprovals || 0}
                    {" — "}المتبقية: <strong>{selectedBatchRemaining}</strong>
                  </Alert>
                </Grid>
              ) : null}

              <Grid item xs={12} sm={6} md={4}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="القائم بالتسجيل"
                  value={currentUserFullName || selectedSeller?.name || ""}
                  InputProps={{ readOnly: true }}
                />
              </Grid>

              <Grid item xs={12} sm={6} md={2}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="تاريخ بدء الدراسة هـ"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  InputProps={{
                    readOnly: programType !== 2
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6} md={2}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  label="تاريخ نهاية الدراسة هـ"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  InputProps={{
                    readOnly: programType !== 2
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6} md={2}>
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  fullWidth
                  type="number"
                  label="عدد الساعات"
                  value={hours}
                  onChange={(e) => setHours(e.target.value)}
                 inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />
              </Grid>

              <Grid
                item
                xs={12}
                sm={6}
                md={2}
                sx={{
                  minWidth: 0,
                  display: "flex",
                  alignItems: "flex-end"
                }}
              >
                <FormControlLabel
                  sx={{
                    ...uiLayout.checkboxFieldSx,
                    width: "100%",
                    marginTop: 0,
                    alignItems: "center"
                  }}
                  control={
                    <Radio
                      checked={showGregorian}
                      onClick={() => setShowGregorian((v) => !v)}
                    />
                  }
                  label="إظهار الميلادي في الموافقة"
                />
              </Grid>
            </Grid>

            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              fullWidth
              multiline
              minRows={isPhone ? 2 : isTablet ? 3 : 3}
              label="ملاحظات"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />

            {savedOrder ? (
              <Alert severity="success">
                تم حفظ الموافقة رقم {savedOrder.code}
              </Alert>
            ) : null}
          </Stack>
        )}
      </DialogContent>

      <DialogActions
        sx={uiLayout.withUiSx({
          px: isPhone ? 0.35 : isTablet ? 0.55 : 3,
          py: isPhone ? 0.28 : isTablet ? 0.42 : 2,
          gap: isCompact ? 0.35 : 1,
          flexShrink: 0
        }, uiLayout.dialogActionsSx)}
      >
        <Button
          variant="contained"
          onClick={save}
          disabled={saving || loadingLookups || loadingOrder}
          startIcon={
            saving ? (
              <CircularProgress size={18} color="inherit" />
            ) : (
              <SaveIcon />
            )
          }
          sx={uiLayout.withUiSx({
            backgroundColor: primaryColor,
            minWidth: isPhone ? 90 : isTablet ? 108 : 140,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.7 : isTablet ? 1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          {editMode ? "تعديل" : "حفظ"}
        </Button>

        <Button
          variant="outlined"
          onClick={print}
          disabled={!savedOrder?.orderGuid}
          startIcon={<PrintIcon />}
          sx={uiLayout.withUiSx({
            color: primaryColor,
            borderColor: primaryColor,
            minWidth: isPhone ? 78 : isTablet ? 95 : 130,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.7 : isTablet ? 1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          طباعة
        </Button>

        <Button
          onClick={onClose}
          disabled={saving}
          sx={uiLayout.withUiSx({
            color: accentColor,
            fontWeight: 900,
            minHeight: isPhone ? 30 : isTablet ? 34 : undefined,
            px: isPhone ? 0.7 : isTablet ? 1 : undefined,
            fontSize: isPhone ? "0.75rem" : isTablet ? "0.75rem" : undefined
          }, uiLayout.buttonSx)}
        >
          إغلاق
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default StudyApprovalDialog;

