  return (
    <motion.div
      initial={{ opacity: 0, y: 14 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.28 }}
    >
      <Card
        sx={{
          p: { xs: 0.9, sm: 1.2, md: 1.4 },
          mb: { xs: 1.4, md: 1.8 },
          borderRadius: { xs: "13px", sm: "16px", md: "18px" },
          border: `1px solid ${COLORS.border}`,
          background: `linear-gradient(135deg, ${COLORS.white}, ${COLORS.soft})`,
          boxShadow: "0 9px 28px rgba(4, 90, 56, 0.07)",
        }}
      >
        <Box
          sx={uiLayout.withUiSx({
            display: "grid",
            gridTemplateColumns: { xs: "1fr 1fr", sm: "auto 140px 140px" },
            alignItems: "center",
            justifyContent: "center",
            gap: { xs: 0.7, sm: 0.9 },
          }, uiLayout.formGridSx)}
        >
          <Typography
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: { xs: "center", sm: "flex-start" },
              gap: 0.8,
              fontSize: { xs: 12.5, sm: 14, md: 16 },
              fontWeight: 1000,
              color: COLORS.text,
              px: 0.5,
              whiteSpace: "nowrap",
              gridColumn: { xs: "1 / -1", sm: "auto" },
            }}
          >
            <AnalyticsRounded sx={{ color: COLORS.primary }} />
            فترة تقييم الأداء
          </Typography>

          <FormControl size="small" sx={uiLayout.withUiSx(selectSx, uiLayout.formFieldSx)}>
            <InputLabel>السنة</InputLabel>
            <Select
              value={selectedYear}
              label="السنة"
              onChange={(event) => setSelectedYear(event.target.value)}
            >
              {availableYears.map((year) => (
                <MenuItem key={year} value={year} sx={{ fontWeight: 800 }}>
                  {year}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <FormControl size="small" sx={uiLayout.withUiSx(selectSx, uiLayout.formFieldSx)}>
            <InputLabel>الشهر</InputLabel>
            <Select
              value={selectedMonth}
              label="الشهر"
              onChange={(event) => setSelectedMonth(event.target.value)}
            >
              <MenuItem value="كل السنة" sx={{ fontWeight: 800 }}>
                كل السنة
              </MenuItem>
              {MONTHS.map((month) => (
                <MenuItem key={month} value={month} sx={{ fontWeight: 800 }}>
                  {month}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>
      </Card>

      <Typography
        sx={{
          mb: { xs: 1.4, md: 1.8 },
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 0.8,
          color: COLORS.text,
          fontSize: { xs: 16, sm: 19, md: 23 },
          fontWeight: 1000,
          textAlign: "center",
        }}
      >
        <AutoAwesomeRounded sx={{ color: COLORS.gold }} />
        نظرة عامة على الأداء
      </Typography>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "minmax(0, 1fr)",
            sm: "repeat(2, minmax(0, 1fr))",
          },
          gap: { xs: 0.9, sm: 1.1, md: 1.4 },
          mb: { xs: 0.9, sm: 1.1, md: 1.4 },
        }}
      >
        <TaskMetricCard
          icon={<InboxRounded sx={{ fontSize: 25 }} />}
          title="المهام المستلمة"
          stats={receivedStats}
          variant="received"
        />
        <TaskMetricCard
          icon={<SendRounded sx={{ fontSize: 25 }} />}
          title="المهام المرسلة"
          stats={sentStats}
          variant="sent"
        />
      </Box>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "minmax(0, 1fr)",
            sm: "repeat(2, minmax(0, 1fr))",
            lg: "repeat(3, minmax(0, 1fr))",
          },
          gap: { xs: 0.9, sm: 1.1, md: 1.4 },
          alignItems: "stretch",
        }}
      >
        {lockedServices.map((service) => (
          <LockedServiceCard
            key={service.title}
            title={service.title}
            description={service.description}
          />
        ))}
      </Box>
    </motion.div>
  );
}

