          }}
        >
          {/* Header Section */}
          <Card sx={{ mb: 3, boxShadow: 3, borderRadius: 2 }}>
            <CardContent>
              <Typography 
                variant="h5" 
                fontWeight="bold" 
                gutterBottom
                sx={{ color: PRIMARY_COLOR }}
              >
                قائمة الطلاب
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                إدارة ومتابعة طلاب المدرب
              </Typography>

              {/* Statistics Cards */}
              <Box display="flex" gap={2} flexWrap="wrap" sx={{ mb: 3 }}>
