const getCommissionYearMonth = () => {
  // شهر العمولة = شهر بداية الفترة
  // من 15/05 إلى 14/06 => عمولة شهر 5
  // من 15/06 إلى 14/07 => عمولة شهر 6
  return {
    allowYear: Number(fromDate.year()),
