    { label: 'الملف التدريبي', icon: <FolderIcon /> },
    { label: 'آخر طلب سداد', icon: <PendingActionsIcon /> },
    { label: 'سجل المتابعات', icon: <HistoryIcon /> },
  ];

  return showSpecial ? (
    <SpecialComponent onBack={() => setShowSpecial(false)} />
