                bgcolor: PRIMARY_COLOR,
                color: 'white',
                py: isDesktop ? 3 : { xs: 0.55, sm: 0.75, md: 0.95 },
                px: isDesktop ? 3 : { xs: 0.75, sm: 1.05, md: 1.5 },
                textAlign: 'center',
                fontSize: isDesktop ? '1.5rem' : { xs: "0.75rem", sm: '0.78rem', md: '0.9rem' },
                lineHeight: 1.35,
                fontWeight: 'bold',
                flexShrink: 0,
