                  إجراءات الطالب - {currentActionRow?.studentName}
                </Box>
              </Box>
            </DialogTitle>

            <DialogContent
              sx={{
                p: 0,
                display: 'flex',
                flexDirection: 'column',
                flex: 1,
                minHeight: 0,
                overflow: 'hidden',
              }}
