                      fontSize: isDesktop
                        ? '1rem'
                        : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },

                      fontWeight: 'bold',

                      py: isDesktop
                        ? 2
                        : { xs: 0.22, sm: 0.3, md: 0.4 },

                      px: isDesktop
                        ? undefined
                        : { xs: 0.35, sm: 0.5, md: 0.65 },

                      minWidth: isDesktop
                        ? undefined
                        : { xs: 62, sm: 74, md: 84 },

                      minHeight: isDesktop
