                  }}
                >
                  {tabs.map((tab, index) => (
                    <Tab 
                      key={index}
                      icon={tab.icon} 
                      iconPosition="start"
                      label={tab.label} 
                    />
                  ))}
                </Tabs>
              </Box>

              {/* محتوى التبويبات */}
              <Box
