                    borderRadius: isDesktop ? undefined : { xs: 1.5, sm: 1.8, md: 2 },
                    boxShadow: isDesktop ? undefined : '0 2px 8px rgba(15,23,42,0.08)',
                  },

                  '& .MuiCardContent-root': {
                    p: isDesktop
