                  },

                  '& .MuiTypography-caption': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },
                  },

                  '& .MuiButton-root': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },

                    minHeight: isDesktop
                      ? undefined
                      : { xs: 25, sm: 28, md: 31 },

                    py: isDesktop
                      ? undefined
                      : { xs: 0.35, sm: 0.45, md: 0.6 },
                  },

                  '& .MuiChip-root': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },

                    height: isDesktop
                      ? undefined
                      : { xs: 19, sm: 22, md: 24 },
                  },

                  '& .MuiInputBase-root, & .MuiInputLabel-root': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },
                  },

                  '& .MuiInputBase-input': {
                    py: isDesktop
                      ? undefined
                      : { xs: 0.75, sm: 0.9, md: 1 },
                  },

                  '& .MuiSvgIcon-root': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: 16, sm: 18, md: 20 },
                  },

                  // الجداول داخل التابات تبقى مضغوطة على الموبايل/التابلت.
                  '& table': {
                    width: '100%',
                    tableLayout: isDesktop ? 'auto' : 'fixed',
