                  '& th, & td': {
                    fontSize: isDesktop
                      ? undefined
                      : { xs: "0.75rem", sm: "0.75rem", md: "0.75rem" },

                    p: isDesktop ? undefined : 0.5,
                    wordBreak: 'break-word',
                  },
                }}
