                        : { xs: '1fr', md: '1fr 1fr' },
                      gap: isDesktop ? 4 : { xs: 0.4, sm: 0.6, md: 0.85 },
                    }}
                  >
                    {/* Left Column - Student Info and Actions */}
                    <Box
                      display="flex"
                      flexDirection="column"
                      gap={isDesktop ? 3 : { xs: 0.4, sm: 0.6, md: 0.85 }}
                    >
                      {/* Student Info Card */}
                      <Card
                        sx={{
                          boxShadow: 3,
                          borderRadius: 3,
                          background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
