                                البرنامج
                              </Typography>
                              <Typography variant="h6" fontWeight="bold" sx={{ color: PRIMARY_COLOR }}>
                                {currentActionRow?.diplomName || '-'}
                              </Typography>
                            </Box>
                          </Box>
                        </CardContent>
                      </Card>

