      showWarning("الطلب غير نشط لا يمكن إلغائه");
      return;
    }

    if (Number(row?.status) === 1) {
      showWarning("الطلب مؤكد لا يمكن إلغائه");
      return;
    }

    if (Number(row?.status) !== 0) {
      showWarning("لا يمكن إلغاء هذا الطلب حسب حالته الحالية");
      return;
