        cancelButtonText: "إلغاء",
        confirmButtonColor: "#057546",
        denyButtonColor: "#ae1e21",
        reverseButtons: true,
        allowOutsideClick: false
      });

    if (callResult.isDismissed) {
      return;
    }

    if (callResult.isDenied) {
      const noAnswer =
        await Swal.fire({
          title:
