          confirmButtonColor:
            "#057546",
          cancelButtonColor:
            "#ae1e21",
          reverseButtons: true
        });

      if (!noAnswer.isConfirmed) {
        return;
      }

      await saveNotes(
        row.regDocGuid,
        {
          callAnswered: false,
          answers: [],
          rating: null,
          extraNotes:
            noAnswer.value || ""
        }
      );

      return;
    }

    const answers = [];

    for (
      let index = 0;
      index < questions.length;
      index++
    ) {
      const answerResult =
        await Swal.fire({
          icon: "question",
          title:
            `السؤال ${index + 1} من ${questions.length}`,
          text: questions[index],
          showDenyButton: true,
          showCancelButton: true,
          confirmButtonText: "نعم",
          denyButtonText: "لا",
          cancelButtonText: "إلغاء",
          confirmButtonColor:
            "#057546",
          denyButtonColor:
            "#ae1e21",
          reverseButtons: true,
          allowOutsideClick: false
        });

      if (answerResult.isDismissed) {
        return;
      }

      if (
        answerResult.isConfirmed
      ) {
        answers.push({
          answer: true,
          reason: ""
        });

        continue;
      }

      const reasonResult =
        await Swal.fire({
          icon: "warning",
          title:
            "سبب اختيار لا",
          input: "textarea",
          inputLabel:
            questions[index],
          inputPlaceholder:
            "اكتب السبب...",
          inputValidator: (
            value
          ) => {
            if (
              !String(value || "")
                .trim()
            ) {
              return "برجاء كتابة السبب";
            }

            return undefined;
          },
          showCancelButton: true,
          confirmButtonText:
            "متابعة",
          cancelButtonText: "إلغاء",
          confirmButtonColor:
            "#057546",
          cancelButtonColor:
            "#ae1e21",
          reverseButtons: true,
          allowOutsideClick: false
        });

      if (!reasonResult.isConfirmed) {
        return;
      }

      answers.push({
        answer: false,
        reason:
          reasonResult.value || ""
      });
    }

    const ratingResult =
      await Swal.fire({
        title:
          "تقييم خدمة القبول والتسجيل",
        html:
          '<div id="after-sales-rating-root"></div>',
        showCancelButton: true,
        confirmButtonText: "متابعة",
        cancelButtonText: "إلغاء",
        confirmButtonColor: "#057546",
        cancelButtonColor: "#ae1e21",
        reverseButtons: true,
        didOpen: () => {
          const root =
            document.getElementById(
              "after-sales-rating-root"
            );

          if (!root) return;

          root.innerHTML = `
            <div style="font-family:Cairo;margin-bottom:12px">
              اختر تقييمًا من 1 إلى 5
            </div>
            <select id="after-sales-rating"
              style="
                width:100%;
                padding:10px;
                border:1px solid #ccc;
                border-radius:8px;
                font-size:16px;
              ">
              <option value="">اختر التقييم</option>
              <option value="1">1 - ضعيف</option>
              <option value="2">2</option>
              <option value="3">3 - جيد</option>
              <option value="4">4</option>
              <option value="5">5 - ممتاز</option>
            </select>
          `;
        },
        preConfirm: () => {
          const element =
            document.getElementById(
              "after-sales-rating"
            );

          const value =
            Number(element?.value);

          if (
            !Number.isInteger(value) ||
            value < 1 ||
            value > 5
          ) {
            Swal.showValidationMessage(
              "برجاء اختيار التقييم"
            );

            return false;
          }

          return value;
        }
      });

    if (!ratingResult.isConfirmed) {
      return;
    }

    const notesResult =
      await Swal.fire({
        title: "ملاحظة إضافية",
        input: "textarea",
        inputPlaceholder:
          "اكتب ملاحظة اختيارية...",
