      const response = await fetch(
        `${API_BASE_URL}/api/after-sales-follow/${encodeURIComponent(regDocGuid)}/notes`,
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            Accept:
              "application/json"
          },
          body: JSON.stringify({
            userGuid,
            ...formData
