  const filteredStats = useMemo(() => {
    const rated =
      filteredRows.filter(
        (row) =>
          Number(row.rating) > 0
      );

    const average =
      rated.length === 0
        ? 0
        : rated.reduce(
            (sum, row) =>
              sum +
              Number(
                row.rating || 0
              ),
            0
          ) / rated.length;

    const rounded =
      average > 0
        ? Math.max(
            1,
            Math.min(
              5,
              Math.round(average)
            )
          )
        : 0;

    const grades = {
      5: "ممتاز",
      4: "جيد جدًا",
      3: "جيد",
      2: "مقبول",
      1: "ضعيف",
      0: "غير متاح"
    };

    return {
      count:
        filteredRows.length,

      ratedCount:
        rated.length,

      average,

      grade:
        grades[rounded] ||
        "غير متاح"
    };
  }, [filteredRows]);


  const loadData = async () => {
    if (!userGuid) {
      await showError(
        "بيانات المستخدم غير موجودة"
      );
      return;
    }

    if (!fromDate || !toDate) {
      await showError(
        "برجاء تحديد الفترة"
      );
      return;
    }

    if (fromDate > toDate) {
      await showError(
        "تاريخ البداية يجب ألا يتجاوز تاريخ النهاية"
      );
      return;
    }

    setLoading(true);

    try {
      const params =
        new URLSearchParams({
          userGuid,
          fromDate,
          toDate
        });

      const response =
        await fetch(
          `${API_BASE_URL}/api/after-sales-report?${params.toString()}`,
          {
            headers: {
              Accept:
                "application/json"
            }
          }
        );

      const responseText =
        await response.text();

      let result = {};

      try {
        result = responseText
          ? JSON.parse(responseText)
          : {};
      } catch {
        throw new Error(
          "الخادم لم يرجع استجابة JSON صحيحة"
        );
      }

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر تحميل تقرير متابعة العملاء"
        );
      }

      setRows(
        Array.isArray(
          result?.data?.rows
        )
          ? result.data.rows
          : []
      );

      setServerFilters({
        batches:
          result?.data?.filters
            ?.batches || [],

        followUsers:
          result?.data?.filters
            ?.followUsers || [],

        salesmen:
          result?.data?.filters
            ?.salesmen || [],

        callStatuses:
          result?.data?.filters
            ?.callStatuses || []
      });

    } catch (error) {
      setRows([]);

      await showError(
        error?.message ||
          "حدث خطأ أثناء تحميل التقرير"
      );
    } finally {
      setLoading(false);
    }
  };

