  const viewNotes = async (
    row
  ) => {
    const notes =
      String(
        row?.notes || ""
      ).trim();

    if (!notes) {
      await Swal.fire({
        icon: "info",
        title: "الملاحظات",
        text:
          "لا توجد ملاحظات لهذا الصف",
        confirmButtonText: "حسنًا",
        confirmButtonColor: "#057546"
      });

      return;
    }

    const lines =
      notes
        .replaceAll("\r\n", "\n")
        .replaceAll("\r", "\n")
        .split("\n")
        .filter((line) =>
          line.trim() !== ""
        );

    const prettyLines =
      lines.map((line) => {
        const clean =
          escapeHtml(
            line.trim()
          );

        if (
          clean.includes(
            "نموذج متابعة ما بعد البيع"
          )
        ) {
          return `
            <div style="
              font-size:20px;
              font-weight:900;
              color:#034d31;
              margin-bottom:12px;
            ">
              ${clean}
            </div>
          `;
        }

        if (
          clean.includes(
            "التقييم"
          )
        ) {
          return `
            <div style="
              padding:10px 12px;
              margin:7px 0;
              border-radius:10px;
              background:#fff7cc;
              color:#735c00;
              font-weight:900;
            ">
              ${clean}
            </div>
          `;
        }

        if (
          clean.includes(
            "ملاحظة إضافية"
          )
        ) {
          return `
            <div style="
              padding:10px 12px;
              margin:7px 0;
              border-radius:10px;
              background:#eef4ff;
              color:#184f90;
              font-weight:700;
            ">
              ${clean}
            </div>
          `;
        }

        return `
          <div style="
            padding:8px 10px;
            margin:5px 0;
            border-radius:9px;
            background:#f7faf8;
            border:1px solid #e5ece8;
          ">
            ${clean}
          </div>
        `;
      }).join("");

    const result =
      await Swal.fire({
        title:
          "تفاصيل الملاحظات",
        html: `
          <div style="
            direction:rtl;
            text-align:right;
            font-family:Cairo,Arial,sans-serif;
            max-height:60vh;
            overflow:auto;
            padding:4px;
          ">
            ${prettyLines}
          </div>
        `,
        width: 850,
        showCancelButton: true,
        confirmButtonText: "نسخ",
        cancelButtonText: "إغلاق",
        confirmButtonColor: "#057546",
        cancelButtonColor: "#6c757d",
        reverseButtons: true
      });

    if (result.isConfirmed) {
      try {
        await navigator.clipboard
          .writeText(notes);

        await Swal.fire({
          icon: "success",
          title: "تم النسخ",
          text:
            "تم نسخ تفاصيل الملاحظات",
          timer: 1300,
          showConfirmButton: false
        });
      } catch {
        await showError(
          "تعذر نسخ الملاحظات"
        );
      }
    }
  };

  const exportToExcel = async () => {
    if (
