        text:
          "لا توجد بيانات متاحة للتصدير",
        confirmButtonText: "حسنًا",
        confirmButtonColor: "#057546"
      });

      return;
    }

    try {
      const headers = [
        "التاريخ",
        "رقم",
        "اسم الطالب",
        "رقم الجوال",
        "الدبلوم/الدورة",
        "الدفعة",
