      setLoadingDetails(true);

      try {
        const params =
          new URLSearchParams({
            programType:
              String(programType),

            branchGuid:
              selectedBranch.guid,

            batchGuid:
              batchRow.batchGuid
          });

        const response = await fetch(
          `${API_BASE_URL}/api/batch-seats-counter/details?${params.toString()}`,
          {
            headers: {
              Accept:
                "application/json"
            }
          }
        );

        const result =
          await readJson(response);

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر تحميل تفاصيل المقاعد"
          );
