         */
        const previousBatch =
          selectedBatchRef.current;

        const currentBatch =
          previousBatch
            ? values.find((row) => {
                if (
                  previousBatch.batchGuid &&
                  row.batchGuid
                ) {
                  return (
                    row.batchGuid ===
                    previousBatch.batchGuid
                  );
                }

                return (
                  String(row.code) ===
                    String(
                      previousBatch.code
                    ) &&
                  row.batchName ===
                    previousBatch.batchName
                );
              })
            : null;

        if (currentBatch) {
          setSelectedBatch(currentBatch);
          await loadDetails(currentBatch);
        } else {
          setSelectedBatch(null);
          setDetailsRows([]);
        }
      } catch (error) {
        setSummaryRows([]);
        setDetailsRows([]);

        await showError(
          error?.message ||
          "حدث خطأ أثناء تحميل الدفعات"
        );
      } finally {
        setLoadingSummary(false);
      }
