    theme.breakpoints.down("sm")
  );

  const isTablet = useMediaQuery(
    "(min-width:600px) and (max-width:1599px)"
  );

  const isDesktop = useMediaQuery(
    `(min-width:${DESKTOP_BREAKPOINT}px)`,
    { noSsr: true }
  );

  const [mobileSidebarOpen, setMobileSidebarOpen] =
    useState(false);

  const [detailsOpen, setDetailsOpen] =
    useState(false);

  const [detailsRow, setDetailsRow] =
    useState(null);

  useEffect(() => {
    if (isDesktop) {
      setMobileSidebarOpen(false);
    }
  }, [isDesktop]);

  const openDetails = (row) => {
    setDetailsRow(row);
    setDetailsOpen(true);
  };

  const closeDetails = () => {
    setDetailsOpen(false);
    setDetailsRow(null);
  };

  const user = useMemo(
    () => JSON.parse(localStorage.getItem("user") || "{}"),
    []
  );

  const userGuid = String(user?.guid || user?.Guid || "").trim();

  const [batches, setBatches] = useState([]);
  const [selectedBatch, setSelectedBatch] = useState(null);
  const [rows, setRows] = useState([]);
  const [loadingBatches, setLoadingBatches] = useState(false);
  const [loading, setLoading] = useState(false);
  const [branchGenderFilter, setBranchGenderFilter] = useState("all");

  const loadBatches = useCallback(async () => {
    if (!userGuid) {
      return;
    }

    setLoadingBatches(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/batch-statistics/batches?userGuid=${encodeURIComponent(userGuid)}`,
        {
          headers: {
            Accept: "application/json"
          }
        }
      );

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result?.message || "تعذر تحميل الدفعات");
      }

      const values = Array.isArray(result?.data) ? result.data : [];
      setBatches(values);

      setSelectedBatch((current) => {
        if (current?.guid) {
          return (
            values.find((item) => item.guid === current.guid) || current
          );
        }

        return null;
      });
    } catch (error) {
      await showError(
        error?.message || "حدث خطأ أثناء تحميل الدفعات"
      );
    } finally {
      setLoadingBatches(false);
    }
  }, [userGuid]);

  const loadReport = useCallback(async () => {
    if (!selectedBatch?.guid) {
      setRows([]);
      return;
    }

    setLoading(true);

    try {
      const params = new URLSearchParams({
        userGuid,
        batchGuid: selectedBatch.guid
      });

      const response = await fetch(
        `${API_BASE_URL}/api/batch-statistics?${params.toString()}`,
        {
          headers: {
            Accept: "application/json"
          }
        }
      );

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result?.message || "تعذر تحميل إحصائيات الدفعة"
        );
      }

      const normalized = Array.isArray(result?.data)
        ? result.data.map((row) => {
            const output = {};

            Object.entries(row || {}).forEach(([key, value]) => {
              output[key] = unwrapValue(value);
            });

            return output;
          })
        : [];

      setRows(normalized);
    } catch (error) {
      setRows([]);

      await showError(
        error?.message || "حدث خطأ أثناء تحميل الإحصائيات"
      );
    } finally {
      setLoading(false);
    }
  }, [userGuid, selectedBatch]);

  useEffect(() => {
    loadBatches();
  }, [loadBatches]);

  useEffect(() => {
    if (selectedBatch?.guid) {
      loadReport();
    }
  }, [selectedBatch, loadReport]);

  const isTotalField = useCallback((field) => {
    const normalizedField = String(field || "").trim();

    return (
      normalizedField === "إجمالي" ||
      normalizedField === "الاجمالي" ||
      normalizedField === "الإجمالي"
    );
  }, []);

  const isDiplomaField = useCallback((field) => {
    const normalizedField = String(field || "").trim();

    return (
      normalizedField === "اسم الدبلوم" ||
      normalizedField === "الدبلوم" ||
      normalizedField.toLowerCase() === "diplomname"
    );
  }, []);

  const isFemaleBranchField = useCallback(
    (field) => String(field || "").trim().includes("نسا"),
    []
  );

  const allFields = useMemo(() => {
    const fields = [];

    rows.forEach((row) => {
      Object.keys(row || {}).forEach((field) => {
        if (!fields.includes(field)) {
          fields.push(field);
        }
      });
    });

    const diplomaField = fields.find((field) => isDiplomaField(field));

    if (diplomaField) {
      const index = fields.indexOf(diplomaField);
      fields.splice(index, 1);
      fields.unshift(diplomaField);
    }

    return fields;
  }, [rows, isDiplomaField]);

  const diplomaFieldName = useMemo(
    () => allFields.find((field) => isDiplomaField(field)) || null,
    [allFields, isDiplomaField]
  );

  const originalTotalFieldName = useMemo(
    () => allFields.find((field) => isTotalField(field)) || null,
    [allFields, isTotalField]
  );

  const maleBranchFields = useMemo(
    () =>
      allFields.filter(
        (field) =>
          field !== diplomaFieldName &&
          !isTotalField(field) &&
          !isFemaleBranchField(field)
      ),
    [
      allFields,
      diplomaFieldName,
      isTotalField,
      isFemaleBranchField
    ]
  );

  const femaleBranchFields = useMemo(
    () =>
      allFields.filter(
        (field) =>
          field !== diplomaFieldName &&
          !isTotalField(field) &&
          isFemaleBranchField(field)
      ),
    [
      allFields,
      diplomaFieldName,
      isTotalField,
      isFemaleBranchField
    ]
  );

  const visibleFields = useMemo(() => {
    const fields = diplomaFieldName ? [diplomaFieldName] : [];

    if (branchGenderFilter === "male") {
      return [...fields, ...maleBranchFields, "__maleTotal"];
    }

    if (branchGenderFilter === "female") {
      return [...fields, ...femaleBranchFields, "__femaleTotal"];
    }

    return allFields;
  }, [
    branchGenderFilter,
    diplomaFieldName,
    maleBranchFields,
    femaleBranchFields,
    allFields
  ]);

  const filteredRows = useMemo(
    () =>
      rows.map((row) => {
        const maleTotal = maleBranchFields.reduce(
          (sum, field) => sum + Number(numberValue(row?.[field]) || 0),
          0
        );

        const femaleTotal = femaleBranchFields.reduce(
          (sum, field) => sum + Number(numberValue(row?.[field]) || 0),
          0
        );

        return {
          ...row,
          __maleTotal: maleTotal,
          __femaleTotal: femaleTotal
        };
      }),
    [rows, maleBranchFields, femaleBranchFields]
  );

  const columns = useMemo(
    () =>
      visibleFields.map((field) => {
        const isCalculatedMaleTotal = field === "__maleTotal";
        const isCalculatedFemaleTotal = field === "__femaleTotal";
        const isCalculatedTotal =
          isCalculatedMaleTotal || isCalculatedFemaleTotal;

        const sample = filteredRows.find(
          (row) =>
            row?.[field] !== null &&
            row?.[field] !== undefined &&
            row?.[field] !== ""
        )?.[field];

        const numeric = isCalculatedTotal || numberValue(sample) !== null;
        const isDiploma = isDiplomaField(field);
        const isTextColumn = isDiploma;

        const headerName = isCalculatedMaleTotal
          ? "إجمالي الرجال"
          : isCalculatedFemaleTotal
            ? "إجمالي النساء"
            : field;

        return {
          field,
          headerName,
          type: numeric ? "number" : "string",
          flex: isDiploma ? 2.4 : 1,
          width: isDiploma ? 360 : isCalculatedTotal ? 145 : 135,
          minWidth: isDiploma ? 320 : isCalculatedTotal ? 135 : 110,
          maxWidth: isDiploma ? 560 : isCalculatedTotal ? 180 : 250,
          align: "center",
          headerAlign: "center",
          sortable: true,
          renderCell: (params) => {
            const value = params?.row?.[field] ?? params?.value;

            if (isTextColumn) {
              const textValue = String(unwrapValue(value) ?? "");

              return (
                <Tooltip title={textValue} arrow placement="top">
                  <Typography
                    component="span"
                    sx={{
                      width: "100%",
                      px: 0.5,
                      whiteSpace: "normal",
                      wordBreak: "break-word",
                      overflowWrap: "anywhere",
                      lineHeight: 1.65,
                      textAlign: "start",
                      direction: "rtl",
                      fontFamily: "Cairo",
                      fontWeight: 800,
                      color: COLORS.text
                    }}
                  >
                    {textValue}
                  </Typography>
                </Tooltip>
              );
            }

            return (
              <Typography
                component="span"
                sx={{
                  fontFamily: "Cairo",
                  fontWeight: numeric ? 800 : 600,
                  color: isCalculatedTotal
                    ? COLORS.danger
                    : numeric
                      ? COLORS.primaryDark
                      : COLORS.text
                }}
              >
                {numeric
                  ? formatNumber(value)
                  : String(unwrapValue(value) ?? "")}
              </Typography>
            );
          }
        };
      }),
    [visibleFields, filteredRows, isDiplomaField]
  );

  const compactColumns = useMemo(() => {
    const diplomaField =
      diplomaFieldName ||
      visibleFields.find((field) =>
        isDiplomaField(field)
      );

    const totalField =
      visibleFields.find((field) =>
        isTotalField(field)
      ) ||
      originalTotalFieldName;

    const importantFields = [
      diplomaField,
      totalField,
      "__maleTotal",
      "__femaleTotal"
    ].filter(Boolean);

    const fallbackFields =
      visibleFields.filter(
        (field) =>
          !importantFields.includes(field) &&
          !isDiplomaField(field)
      );

    const desiredCount =
      isPhone ? 4 : 5;

    const chosenFields = [
      ...importantFields,
      ...fallbackFields
    ]
      .filter(
        (field, index, array) =>
          field &&
          array.indexOf(field) === index
      )
      .slice(0, desiredCount);

    const getHeaderName = (field) => {
      if (field === diplomaField) {
        return "الدبلوم";
      }

      if (field === "__maleTotal") {
        return isPhone
          ? "رجال"
          : "إجمالي الرجال";
      }

      if (field === "__femaleTotal") {
        return isPhone
          ? "نساء"
          : "إجمالي النساء";
      }

      if (
        field === totalField ||
        isTotalField(field)
      ) {
        return "الإجمالي";
      }

      return field;
    };

    const dataColumns =
      chosenFields.map((field) => {
        const isCalculatedMale =
          field === "__maleTotal";

        const isCalculatedFemale =
          field === "__femaleTotal";

        const isCalculated =
          isCalculatedMale ||
          isCalculatedFemale;

        const sample =
          filteredRows.find(
            (row) =>
              row?.[field] !== null &&
              row?.[field] !== undefined &&
              row?.[field] !== ""
          )?.[field];

        const numeric =
          isCalculated ||
          numberValue(sample) !== null;

        const isDiploma =
          field === diplomaField ||
          isDiplomaField(field);

        return {
          field,
          headerName: getHeaderName(field),
          sortable: false,
          filterable: false,
          disableColumnMenu: true,
          resizable: false,
          align: "center",
          headerAlign: "center",
          type: numeric ? "number" : "string",

          ...(isPhone
            ? {
                flex: isDiploma
                  ? 1.7
                  : 1,
                minWidth: 0
              }
            : {
                flex: isDiploma
                  ? 1.7
                  : 1,
                minWidth: isDiploma
                  ? 165
                  : 95
              }),

          renderCell: (params) => {
            const value =
              params?.row?.[field] ??
              params?.value;

            if (isDiploma) {
              return (
                <Typography
                  component="span"
                  sx={{
                    width: "100%",
                    fontFamily: "Cairo",
                    fontWeight: 800,
                    fontSize: isPhone
                      ? "0.75rem"
                      : "0.75rem",
                    lineHeight: 1.35,
                    textAlign: "center",
                    whiteSpace: "normal",
                    overflow: "hidden",
                    display: "-webkit-box",
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: "vertical"
                  }}
                >
                  {String(
                    unwrapValue(value) ?? ""
                  )}
                </Typography>
              );
            }

            return (
              <Typography
                component="span"
                sx={{
                  fontFamily: "Cairo",
                  fontWeight: 900,
                  fontSize: isPhone
                    ? "0.75rem"
                    : "0.75rem",
                  color: isCalculated
                    ? COLORS.danger
                    : COLORS.primaryDark
                }}
              >
                {numeric
                  ? formatNumber(value)
                  : String(
                      unwrapValue(value) ?? ""
                    )}
              </Typography>
            );
          }
        };
      });

    return [
      ...dataColumns,
      {
        field: "__details",
        headerName: "",
        sortable: false,
        filterable: false,
        disableColumnMenu: true,
        resizable: false,
        width: isPhone ? 34 : 44,
        minWidth: isPhone ? 34 : 44,
        maxWidth: isPhone ? 34 : 44,
        align: "center",
        headerAlign: "center",

        renderCell: (params) => (
          <IconButton
            size="small"
            title="عرض التفاصيل"
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              openDetails(params.row);
            }}
            sx={{
              width: isPhone ? 24 : 30,
              height: isPhone ? 24 : 30,
              p: 0,
              color: COLORS.primary,
              border:
                "1px solid rgba(11,107,70,.28)",
              backgroundColor:
                COLORS.primarySoft
            }}
          >
            <VisibilityOutlinedIcon
              sx={{
                fontSize: isPhone
                  ? 14
                  : 18
              }}
            />
          </IconButton>
        )
      }
    ];
  }, [
    visibleFields,
    filteredRows,
    diplomaFieldName,
    originalTotalFieldName,
    isDiplomaField,
    isTotalField,
    isPhone,
    isTablet
  ]);

  const dataGridRows = useMemo(
    () =>
      filteredRows.map((row, index) => ({
        id: `${
          diplomaFieldName ? row?.[diplomaFieldName] : "diploma"
        }-${index}`,
        ...row
      })),
    [filteredRows, diplomaFieldName]
  );

  const totals = useMemo(() => {
    const result = {};

    allFields.forEach((field) => {
      if (isDiplomaField(field)) {
        return;
      }

      const values = rows
        .map((row) => numberValue(row?.[field]))
        .filter((value) => value !== null);

      if (rows.length > 0 && values.length === rows.length) {
        result[field] = values.reduce((sum, value) => sum + value, 0);
      }
    });

    return result;
  }, [rows, allFields, isDiplomaField]);

  const grandTotal =
    (originalTotalFieldName
      ? totals[originalTotalFieldName]
      : null) ??
    Object.values(totals).reduce(
      (sum, value) => sum + Number(value || 0),
      0
    );

  const groupedBranchTotals = useMemo(() => {
    const female = [];
    const male = [];

    Object.entries(totals).forEach(([field, value]) => {
      const normalizedField = String(field || "").trim();

      if (isTotalField(normalizedField)) {
        return;
      }

      const item = {
        field: normalizedField,
        value
      };

      if (isFemaleBranchField(normalizedField)) {
        female.push(item);
      } else {
        male.push(item);
      }
    });

    return {
      female,
      male,
      femaleTotal: female.reduce(
        (sum, item) => sum + Number(item.value || 0),
        0
      ),
      maleTotal: male.reduce(
        (sum, item) => sum + Number(item.value || 0),
        0
      )
    };
  }, [totals, isTotalField, isFemaleBranchField]);

  const visibleReportTotal = useMemo(() => {
    if (branchGenderFilter === "male") {
      return groupedBranchTotals.maleTotal;
    }

    if (branchGenderFilter === "female") {
      return groupedBranchTotals.femaleTotal;
    }

    return grandTotal;
  }, [
    branchGenderFilter,
    groupedBranchTotals,
    grandTotal
  ]);

  const exportCsv = () => {
    if (filteredRows.length === 0) {
      return;
    }

    const escapeValue = (value) =>
      `"${String(unwrapValue(value) ?? "").replaceAll('"', '""')}"`;

    const exportHeaders = visibleFields.map((field) => {
      if (field === "__maleTotal") {
        return "إجمالي الرجال";
      }

      if (field === "__femaleTotal") {
        return "إجمالي النساء";
      }

      return field;
    });

    const csv = [
      exportHeaders.map(escapeValue).join(","),
      ...filteredRows.map((row) =>
        visibleFields
          .map((field) => escapeValue(row?.[field]))
          .join(",")
      )
    ].join("\r\n");

    const blob = new Blob(["\uFEFF", csv], {
      type: "text/csv;charset=utf-8;"
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    const filterName =
      branchGenderFilter === "male"
        ? "فروع الرجال"
        : branchGenderFilter === "female"
          ? "فروع النساء"
          : "كل الفروع";

    link.href = url;
    link.download = `إحصائيات الدفعات - ${
      selectedBatch?.name || "دفعة"
    } - ${filterName}.csv`;

    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  return (
    isDesktop ? (
    <NavigationShell variant="standard" ><Box
      sx={{
        minHeight: "100vh",
        background: COLORS.background,
        direction: "rtl"
      }}
    >


      <PageContainer
        component="main"
        sx={{
          minHeight: "100vh",

          direction: "rtl",
          ...navigationContentSx
        }}
      >
        <Paper
          elevation={0}
          sx={{
            borderRadius: { xs: 3, md: 4 },
            overflow: "hidden",
            border: `1px solid ${COLORS.border}`,
            background: "#fff",
            boxShadow: "0 18px 48px rgba(14, 66, 47, 0.06)"
          }}
        >
          <Box
            sx={{
              px: { xs: 2, md: 3.5 },
              py: { xs: 2.5, md: 3.25 },
              position: "relative",
              overflow: "hidden",
              background:
                "linear-gradient(125deg, #064b33 0%, #0b6b46 52%, #19855f 100%)",
              color: "#fff",
              "&::before": {
                content: '""',
                position: "absolute",
                width: 220,
                height: 220,
                borderRadius: "50%",
                top: -120,
                left: -50,
                background: "rgba(255,255,255,0.07)"
              },
              "&::after": {
                content: '""',
                position: "absolute",
                width: 180,
                height: 180,
                borderRadius: "50%",
                bottom: -115,
                right: 80,
                background: "rgba(255,255,255,0.05)"
              }
            }}
          >
            <Stack
              direction={{ xs: "column", sm: "row" }}
              alignItems={{ xs: "flex-start", sm: "center" }}
              justifyContent="space-between"
              spacing={2}
              sx={{ position: "relative", zIndex: 1 }}
            >
              <Stack direction="row" spacing={1.5} alignItems="center">
                <Avatar
                  variant="rounded"
                  sx={{
                    width: 60,
                    height: 60,
                    borderRadius: 3,
                    background: "rgba(255,255,255,0.14)",
                    color: "#fff",
                    border: "1px solid rgba(255,255,255,0.18)"
                  }}
                >
                  <QueryStatsIcon sx={{ fontSize: 34 }} />
                </Avatar>

                <Box>
                  <Typography
                    variant="h5"
                    sx={{
                      fontFamily: "Cairo",
                      fontWeight: 900,
                      fontSize: { xs: 22, md: 28 }
                    }}
                  >
                    إحصائيات الدفعات
                  </Typography>

                </Box>
              </Stack>

              <Chip
                icon={<CalendarMonthOutlinedIcon />}
                label="تقرير الدفعات"
                sx={{
                  fontFamily: "Cairo",
                  fontWeight: 800,
                  color: "#fff",
                  background: "rgba(255,255,255,0.12)",
                  border: "1px solid rgba(255,255,255,0.18)",
                  "& .MuiChip-icon": { color: "#fff" }
                }}
              />
            </Stack>
          </Box>

          <Box sx={{ p: { xs: 1.5, sm: 2.25, md: 3 } }}>
            <Paper
              elevation={0}
              sx={{
                p: { xs: 1.5, md: 2 },
                mb: 2.25,
                borderRadius: 3,
                border: `1px solid ${COLORS.border}`,
                background: "linear-gradient(180deg,#ffffff 0%,#fbfdfc 100%)"
              }}
            >
              <Stack
                direction={{ xs: "column", lg: "row" }}
                spacing={1.25}
                alignItems={{ xs: "stretch", lg: "center" }}
              >
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography
                    sx={{
                      mb: 0.75,
                      fontFamily: "Cairo",
                      fontSize: 12,
                      fontWeight: 900,
                      color: COLORS.text
                    }}
                  >
                    اختر الدفعة
                  </Typography>

                  <Autocomplete
                    options={batches}
                    value={selectedBatch}
                    loading={loadingBatches}
                    onChange={(_, value) => setSelectedBatch(value)}
                    isOptionEqualToValue={(option, value) =>
                      option.guid === value.guid
                    }
                    getOptionLabel={(option) => option?.name || ""}
                    popupIcon={<KeyboardArrowDownRoundedIcon />}
                    noOptionsText="لا توجد دفعات"
                    loadingText="جارٍ تحميل الدفعات..."
                    renderInput={(params) => (
                      <TextField InputLabelProps={{ shrink: true }}
                        {...params}
                        placeholder="ابحث باسم الدفعة أو الكود"
                        InputProps={{
                          ...params.InputProps,
                          startAdornment: (
                            <InputAdornment position="start">
                              <SearchIcon sx={{ color: COLORS.muted }} />
                            </InputAdornment>
                          ),
                          endAdornment: (
                            <>
                              {loadingBatches ? (
                                <CircularProgress size={18} />
                              ) : null}
                              {params.InputProps.endAdornment}
                            </>
                          )
                        }}
                        sx={uiLayout.withUiSx({
                          direction: "rtl",
                          "& .MuiOutlinedInput-root": {
                            height: 48,
                            borderRadius: 2.5,
                            fontFamily: "Cairo",
                            background: "#fff",
                            "& fieldset": { borderColor: COLORS.border },
                            "&:hover fieldset": { borderColor: COLORS.primary },
                            "&.Mui-focused fieldset": {
                              borderColor: COLORS.primary,
                              borderWidth: 1.5
                            }
                          }
                        }, uiLayout.formFieldSx)}
                      />
                    )}
                  />
                </Box>

                <Stack
                  direction={{ xs: "column", sm: "row" }}
                  spacing={1}
                  sx={uiLayout.withUiSx({ pt: { lg: 2.75 } }, uiLayout.actionBarSx)}
                >
                  <Button
                    variant="contained"
                    startIcon={<SearchIcon />}
                    onClick={loadReport}
                    disabled={loading || !selectedBatch?.guid}
                    sx={uiLayout.withUiSx({
                      minWidth: 120,
                      height: 48,
                      px: 2.5,
                      borderRadius: 2.5,
                      fontFamily: "Cairo",
                      fontWeight: 900,
                      background: COLORS.primary,
                      boxShadow: "none",
                      "&:hover": {
                        background: COLORS.primaryDark,
                        boxShadow: "none"
                      }
                    }, uiLayout.buttonSx)}
                  >
                    عرض التقرير
                  </Button>

                  <Button
                    variant="outlined"
                    startIcon={<RefreshIcon />}
                    onClick={async () => {
                      await loadBatches();
                      if (selectedBatch?.guid) {
                        await loadReport();
                      }
                    }}
                    disabled={loading || loadingBatches}
                    sx={uiLayout.withUiSx({
                      minWidth: 108,
                      height: 48,
                      borderRadius: 2.5,
