    useState({
      branchName: "",
      cashBoxName: "",
      cashBoxGuid: ""
    });

  const [statementRows, setStatementRows] =
    useState([]);

  const [payOrderRows, setPayOrderRows] =
    useState([]);

  const loadBranchInfo =
    useCallback(async () => {
      if (!userGuid || !branchGuid) {
        return;
      }

      try {
        setLoadingInfo(true);

        const params =
          new URLSearchParams({
            userGuid,
            branchGuid
          });

        const response = await fetch(
          `${API_BASE_URL}/api/branch-daily/info?${params.toString()}`,
          { cache: "no-store" }
        );

        const result =
          await readJson(response);

        setBranchInfo(
          result?.data || {}
        );
      } catch (error) {
        await showError(
          error?.message ||
          "تعذر تحميل بيانات الفرع والخزينة"
        );
      } finally {
        setLoadingInfo(false);
      }
    }, [userGuid, branchGuid]);

  useEffect(() => {
    loadBranchInfo();
  }, [loadBranchInfo]);

  const loadData =
    useCallback(async () => {
      if (!userGuid || !branchGuid) {
        await showError(
          "لا يوجد فرع عمل محدد للمستخدم"
        );
        return;
      }

      if (!fromDate || !toDate) {
        await showError(
          "برجاء تحديد الفترة"
        );
        return;
      }

      if (
        new Date(fromDate) >
        new Date(toDate)
      ) {
        await showError(
          "تاريخ البداية يجب ألا يتجاوز تاريخ النهاية"
        );
        return;
      }

      try {
        setLoadingData(true);

        const params =
          new URLSearchParams({
            userGuid,
            branchGuid,
            fromDate,
            toDate
          });

        const response = await fetch(
          `${API_BASE_URL}/api/branch-daily/report?${params.toString()}`,
          { cache: "no-store" }
        );

        const result =
          await readJson(response);

        setStatementRows(
          Array.isArray(
            result?.data?.cashStatement
          )
            ? result.data.cashStatement
            : []
        );

        setPayOrderRows(
          Array.isArray(
            result?.data?.payOrders
          )
            ? result.data.payOrders
            : []
        );

        if (result?.data?.branchInfo) {
          setBranchInfo(
            result.data.branchInfo
          );
        }
      } catch (error) {
        setStatementRows([]);
        setPayOrderRows([]);

        await showError(
          error?.message ||
          "تعذر تحميل يومية الفرع"
        );
      } finally {
        setLoadingData(false);
      }
    }, [
      userGuid,
      branchGuid,
      fromDate,
      toDate
    ]);

  const statementData = useMemo(
    () =>
      statementRows.map(
        normalizeStatementRow
      ),
    [statementRows]
  );

  const payOrderData = useMemo(
    () =>
      payOrderRows.map(
        normalizePayOrderRow
      ),
    [payOrderRows]
  );

  const totals = useMemo(() => {
    const totalMaden =
      statementData.reduce(
        (sum, row) =>
          sum + toNumber(row.maden),
        0
      );

    const totalDaen =
      statementData.reduce(
        (sum, row) =>
          sum + toNumber(row.daen),
        0
      );

    return {
      maden: totalMaden,
      daen: totalDaen,
      balance:
        totalMaden - totalDaen
    };
  }, [statementData]);

  const statementColumns = useMemo(
