        valueFormatter: (value) =>
          money(value)
      },
      {
        field: "cashName",
        headerName: "الخزينة/البنك",
        minWidth: 190,
        flex: 1.25
      }
    ],
    []
  );

  return (
    <NavigationShell variant="standard" ><Box
      sx={{
        minHeight: "100vh",
        direction: "rtl",
        background:
          "linear-gradient(135deg,#f5faf7 0%,#fff 55%,#eef8f3 100%)"
      }}
    >


      <PageContainer
        component="main"
