const parseNumericDate = (value) => {
  const text = String(value || "").trim();
  if (!text) return null;

  // yyyy-MM-dd أو yyyy/MM/dd
  let m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/.exec(text);
  if (m) {
