        </DialogContent><DialogActions sx={uiLayout.dialogActionsSx}><Button sx={uiLayout.buttonSx} onClick={() => setListOpen(false)}>إغلاق</Button></DialogActions>
      </Dialog>
    </Box></NavigationShell>
  );
