import React, {
  useCallback,
  useEffect,
  useMemo,
  useState
} from "react";
import {
  Autocomplete,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControlLabel,
  IconButton,
  InputAdornment,
  Paper,
  Stack,
  Switch,
  TextField,
  Tooltip,
  Typography
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";

import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import AccountBalanceWalletIcon from "@mui/icons-material/AccountBalanceWallet";
import BusinessIcon from "@mui/icons-material/Business";
import CalculateIcon from "@mui/icons-material/Calculate";
import CloseIcon from "@mui/icons-material/Close";
import LocalAtmIcon from "@mui/icons-material/LocalAtm";
import PrintIcon from "@mui/icons-material/Print";
import SaveIcon from "@mui/icons-material/Save";
import SearchIcon from "@mui/icons-material/Search";

import Swal from "sweetalert2";




const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  "https://api4.sstli.com";

const today = () => {
  const value = new Date();
  const year = value.getFullYear();
  const month = String(
    value.getMonth() + 1
  ).padStart(2, "0");
  const day = String(
    value.getDate()
  ).padStart(2, "0");

  return `${year}-${month}-${day}`;
};

const normalizeGuid = (value) =>
  String(value || "")
    .trim()
    .toLowerCase();

const readJson = async (response) => {
  const text = await response.text();

  let result = {};

  try {
    result = text
      ? JSON.parse(text)
      : {};
  } catch {
    result = {};
  }

  if (!response.ok) {
    throw new Error(
      result?.message ||
      result?.details ||
      text
        ?.replace(/<[^>]*>/g, " ")
        ?.replace(/\s+/g, " ")
        ?.trim()
        ?.slice(0, 700) ||
      `تعذر تنفيذ الطلب - HTTP ${response.status}`
    );
  }

  return result;
};

const fireError = (message) =>
  Swal.fire({
    icon: "error",
    title: "تنبيه",
    text: message,
    confirmButtonText: "حسنًا",
    confirmButtonColor: "#ae1e21"
  });

const fireSuccess = (message) =>
  Swal.fire({
    icon: "success",
    title: "تم بنجاح",
    text: message,
    confirmButtonText: "حسنًا",
    confirmButtonColor: "#057546"
  });

const money = (value) =>
  Number(value || 0).toLocaleString(
    "en-US",
    {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }
  );

const CashPaymentOrder = () => {
  const currentUser = useMemo(() => {
    try {
      return JSON.parse(
        localStorage.getItem("user") ||
        "{}"
      );
    } catch {
      return {};
    }
  }, []);

  const userGuid = String(
    currentUser?.guid ||
    currentUser?.Guid ||
    ""
  ).trim();

  const userName = String(
    currentUser?.fullName ||
    currentUser?.userName ||
    ""
  ).trim();

  const [branches, setBranches] =
    useState([]);

  const [branchesLoading, setBranchesLoading] =
    useState(false);

  const [saving, setSaving] =
    useState(false);

  const [tafkeetLoading, setTafkeetLoading] =
    useState(false);

  const [branchDialogOpen, setBranchDialogOpen] =
    useState(false);

  const [orderDialogOpen, setOrderDialogOpen] =
    useState(false);

  const [orderCodeSearch, setOrderCodeSearch] =
    useState("");

  const [form, setForm] = useState({
    code: "",
    guid: "",
    orderDate: today(),
    branchGuid: "",
    branchName: "",
    orderTo: "",
    amount: "",
    amountText: "",
    orderFor: "",
    isUse: true,
    createdByGuid: "",
    createdByName: ""
  });

  const isExisting =
    Boolean(form.guid);

  const updateForm = (
    field,
    value
  ) => {
    setForm((current) => ({
      ...current,
      [field]: value
    }));
  };

  const resetForm = useCallback(() => {
    setForm({
      code: "",
      guid: "",
      orderDate: today(),
      branchGuid: "",
      branchName: "",
      orderTo: "",
      amount: "",
      amountText: "",
      orderFor: "",
      isUse: true,
      createdByGuid: "",
      createdByName: ""
    });
  }, []);

  const loadBranches =
    useCallback(async () => {
      if (!userGuid) {
        return;
      }

      try {
        setBranchesLoading(true);

        const response = await fetch(
          `${API_BASE_URL}/api/cash-payment-orders/branches?userGuid=${encodeURIComponent(userGuid)}`,
          {
            cache: "no-store",
            headers: {
              Accept: "application/json"
            }
          }
        );

        const result =
          await readJson(response);

        const values =
          Array.isArray(result?.data)
            ? result.data
            : [];

        setBranches(values);

        if (
          values.length === 1 &&
          !form.branchGuid
        ) {
          updateForm(
            "branchGuid",
            values[0].guid
          );
          updateForm(
            "branchName",
            values[0].name
          );
        }
      } catch (error) {
        setBranches([]);
        await fireError(
          error?.message ||
          "تعذر تحميل الفروع"
        );
      } finally {
        setBranchesLoading(false);
      }
    }, [
      userGuid,
      form.branchGuid
    ]);

  useEffect(() => {
    loadBranches();
  }, [loadBranches]);

  useEffect(() => {
    const numericAmount =
      Number(form.amount || 0);

    if (
      !numericAmount ||
      numericAmount <= 0
    ) {
      updateForm(
        "amountText",
        ""
      );
      return;
    }

    const timer = setTimeout(
      async () => {
        try {
          setTafkeetLoading(true);

          const response =
            await fetch(
              `${API_BASE_URL}/api/cash-payment-orders/tafkeet?userGuid=${encodeURIComponent(userGuid)}&total=${encodeURIComponent(numericAmount)}`,
              {
                cache: "no-store"
              }
            );

          const result =
            await readJson(response);

          updateForm(
            "amountText",
            String(
              result?.data?.text ||
              result?.data ||
              ""
            )
          );
        } catch (error) {
          updateForm(
            "amountText",
            ""
          );
        } finally {
          setTafkeetLoading(false);
        }
      },
      450
    );

    return () =>
      clearTimeout(timer);
  }, [
    form.amount,
    userGuid
  ]);

  const validate = () => {
    if (!form.branchGuid) {
      fireError(
        "برجاء اختيار الفرع أولًا"
      );
      return false;
    }

    if (!form.orderTo.trim()) {
      fireError(
        "برجاء إدخال اسم المستفيد أولًا"
      );
      return false;
    }

    if (
      !Number(form.amount) ||
      Number(form.amount) <= 0
    ) {
      fireError(
        "برجاء إدخال قيمة صحيحة"
      );
      return false;
    }

    if (!form.orderFor.trim()) {
      fireError(
        "برجاء تحديد الغرض من الصرف"
      );
      return false;
    }

    return true;
  };

  const save = async () => {
    if (!validate()) {
      return;
    }

    if (isExisting) {
      await fireError(
        "الأمر الحالي محفوظ بالفعل، اضغط جديد لإنشاء أمر آخر"
      );
      return;
    }

    try {
      setSaving(true);

      const response = await fetch(
        `${API_BASE_URL}/api/cash-payment-orders`,
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body: JSON.stringify({
            userGuid,
            orderDate:
              form.orderDate,
            branchGuid:
              form.branchGuid,
            orderTo:
              form.orderTo.trim(),
            orderAmount:
              Number(form.amount),
            orderAmountText:
              form.amountText,
            orderFor:
              form.orderFor.trim(),
            isUse:
              form.isUse
          })
        }
      );

      const result =
        await readJson(response);

      const data =
        result?.data || {};

      setForm((current) => ({
        ...current,
        code:
          String(data.code || ""),
        guid:
          String(data.guid || ""),
        orderDate:
          String(
            data.orderDate ||
            current.orderDate
          ).slice(0, 10),
        branchGuid:
          String(
            data.branchGuid ||
            current.branchGuid
          ),
        branchName:
          String(
            data.branchName ||
            current.branchName
          ),
        orderTo:
          String(
            data.orderTo ||
            current.orderTo
          ),
        amount:
          String(
            data.orderAmount ??
            current.amount
          ),
        amountText:
          String(
            data.orderAmountText ||
            current.amountText
          ),
        orderFor:
          String(
            data.orderFor ||
            current.orderFor
          ),
        isUse:
          data.isUse !== false,
        createdByGuid:
          String(
            data.userGuid ||
            userGuid
          ),
        createdByName:
          String(
            data.userName ||
            userName
          )
      }));

      await fireSuccess(
        result?.message ||
        "تم حفظ بيانات أمر صرف النقدية بنجاح"
      );
    } catch (error) {
      await fireError(
        error?.message ||
        "تعذر حفظ أمر الصرف"
      );
    } finally {
      setSaving(false);
    }
  };

  const loadOrderByCode =
    async () => {
      const code =
        String(
          orderCodeSearch || ""
        ).trim();

      if (!code) {
        await fireError(
          "برجاء إدخال رقم الأمر"
        );
        return;
      }

      try {
        const params =
          new URLSearchParams({
            userGuid,
            code
          });

        const response =
          await fetch(
            `${API_BASE_URL}/api/cash-payment-orders/by-code?${params.toString()}`,
            {
              cache: "no-store"
            }
          );

        const result =
          await readJson(response);

        const data =
          result?.data || {};

        setForm({
          code:
            String(data.code || code),
          guid:
            String(data.guid || ""),
          orderDate:
            String(
              data.orderDate || today()
            ).slice(0, 10),
          branchGuid:
            String(
              data.branchGuid || ""
            ),
          branchName:
            String(
              data.branchName || ""
            ),
          orderTo:
            String(
              data.orderTo || ""
            ),
          amount:
            String(
              data.orderAmount ?? ""
            ),
          amountText:
            String(
              data.orderAmountText || ""
            ),
          orderFor:
            String(
              data.orderFor || ""
            ),
          isUse:
            data.isUse !== false,
          createdByGuid:
            String(
              data.userGuid || ""
            ),
          createdByName:
            String(
              data.userName || ""
            )
        });

        setOrderDialogOpen(false);
      } catch (error) {
        await fireError(
          error?.message ||
          "تعذر تحميل أمر الصرف"
        );
      }
    };

  const printOrder = async () => {
    if (!form.guid) {
      await fireError(
        "برجاء اختيار أمر صرف أو حفظ الأمر الحالي"
      );
      return;
    }

    const params =
      new URLSearchParams({
        userGuid,
        guid: form.guid
      });

    window.open(
      `${API_BASE_URL}/api/cash-payment-orders/print?${params.toString()}`,
      "_blank",
      "noopener,noreferrer"
    );
  };

  const branchColumns = [
    {
      field: "code",
      headerName: "كود",
      width: 100
    },
    {
      field: "name",
      headerName: "اسم الفرع",
      flex: 1,
      minWidth: 250
    }
  ];

  return (
    <NavigationShell variant="standard" ><Box
      sx={{
        minHeight: "100vh",
        direction: "rtl",
        background:
          "linear-gradient(135deg,#f5faf7 0%,#ffffff 55%,#eef8f3 100%)"
      }}
    >


      <PageContainer
        component="main"
        sx={{

          ...navigationContentSx
        }}
      >
        <Paper
          elevation={0}
          sx={{
            p: 2,
            mb: 1.5,
            borderRadius: 4,
