            </Button>

            <Button
              variant="outlined"
              startIcon={
                <SearchIcon />
              }
              onClick={() => {
                setOrderCodeSearch(
                  form.code || ""
                );
                setOrderDialogOpen(true);
              }}
              sx={uiLayout.withUiSx({
                fontFamily: "Cairo",
                fontWeight: 900
              }, uiLayout.buttonSx)}
            >
              بحث
            </Button>

            <Button
              variant="contained"
