                saving
                  ? (
                    <CircularProgress
                      size={17}
                      color="inherit"
                    />
                  )
                  : <SaveIcon />
              }
              onClick={save}
              disabled={
                saving ||
                isExisting
              }
              sx={uiLayout.withUiSx({
                fontFamily: "Cairo",
                fontWeight: 900,
                background:
                  "linear-gradient(135deg,#057546,#034d31)"
              }, uiLayout.buttonSx)}
            >
              حفظ
            </Button>

            <Button
              variant="outlined"
              startIcon={
                <PrintIcon />
              }
