                      form.branchGuid
                    )
                ) || (
                  form.branchGuid
                    ? {
                        guid:
                          form.branchGuid,
                        name:
                          form.branchName,
                        code: ""
                      }
                    : null
                )
              }
              isOptionEqualToValue={(
                option,
                value
              ) =>
                normalizeGuid(
                  option?.guid
                ) ===
                normalizeGuid(
                  value?.guid
                )
              }
              getOptionLabel={(option) =>
                option?.name || ""
              }
              onChange={(
                _event,
                value
              ) => {
                updateForm(
                  "branchGuid",
                  value?.guid || ""
                );
                updateForm(
                  "branchName",
                  value?.name || ""
                );
              }}
              disabled={isExisting}
              renderInput={(params) => (
