                    )
                  }
                  disabled={isExisting}
                  color="success"
                />
              }
              label="حالة الأمر نشط"
              sx={uiLayout.withUiSx({
                fontFamily: "Cairo"
              }, uiLayout.checkboxFieldSx)}
            />
          </Box>

          {isExisting && (
            <>
              <Divider sx={{ my: 2 }} />

              <Stack
                direction={{
                  xs: "column",
                  sm: "row"
                }}
                spacing={1}
              >
                <Chip
                  label={`رقم الأمر: ${form.code}`}
                  sx={{
                    fontFamily: "Cairo",
                    fontWeight: 900
                  }}
                />

                <Chip
                  label={`المبلغ: ${money(form.amount)}`}
                  sx={{
                    fontFamily: "Cairo",
                    fontWeight: 900
                  }}
                />

                <Chip
                  label={`أنشئ بواسطة: ${form.createdByName || "-"}`}
                  sx={{
                    fontFamily: "Cairo",
                    fontWeight: 900
                  }}
                />
              </Stack>
            </>
          )}
        </Paper>
      </PageContainer>

      <Dialog sx={uiLayout.dialogLayoutSx}
        open={orderDialogOpen}
        onClose={() =>
          setOrderDialogOpen(false)
        }
        fullWidth
        maxWidth="xs"
        PaperProps={{
          sx: {
            direction: "rtl",
            borderRadius: 4
          }
        }}
      >
        <DialogTitle
          sx={{
            fontFamily: "Cairo",
            fontWeight: 900
          }}
        >
          البحث عن أمر صرف
        </DialogTitle>

        <DialogContent dividers>
          <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
            autoFocus
            fullWidth
            label="رقم أمر الصرف"
            value={orderCodeSearch}
            onChange={(event) =>
              setOrderCodeSearch(
                event.target.value
              )
            }
            onKeyDown={(event) => {
              if (
                event.key === "Enter"
              ) {
                loadOrderByCode();
              }
            }}
          />
        </DialogContent>

        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx}
            onClick={() =>
              setOrderDialogOpen(false)
            }
          >
            إلغاء
          </Button>

          <Button
            variant="contained"
            onClick={loadOrderByCode}
            startIcon={<SearchIcon />}
            sx={uiLayout.withUiSx({
              backgroundColor:
                "#057546"
            }, uiLayout.buttonSx)}
          >
            عرض
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog sx={uiLayout.dialogLayoutSx}
        open={branchDialogOpen}
        onClose={() =>
          setBranchDialogOpen(false)
        }
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>
          قائمة الفروع
        </DialogTitle>

        <DialogContent
          sx={{
            height: 520
          }}
        >
          <DataGrid sx={uiLayout.dataGridSx}
            rows={branches}
            columns={branchColumns}
            loading={branchesLoading}
            disableRowSelectionOnClick
            onRowDoubleClick={(params) => {
              updateForm(
                "branchGuid",
                params.row.guid
              );
              updateForm(
                "branchName",
                params.row.name
              );
              setBranchDialogOpen(false);
            }}
          />
        </DialogContent>

        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx}
            startIcon={<CloseIcon />}
            onClick={() =>
              setBranchDialogOpen(false)
            }
          >
            إغلاق
          </Button>
        </DialogActions>
      </Dialog>
    </Box></NavigationShell>
  );
};

export default CashPaymentOrder;

