              onClick={() => window.open(message.file_url, '_blank')}
            >
              Download {fileExtension?.toUpperCase() || 'File'}
            </Button>
          </>
        )}

        {message.content && (
          <Typography variant="body2" mt={1}>
            {message.content}
          </Typography>
        )}
      </Box>
    );
  };

if (loading) {
