                    multiple
                  />
                  <IconButton sx={{ color: colorPalette.primary }} onClick={(e) => setEmojiAnchor(e.currentTarget)}>
                    <EmojiIcon />
                  </IconButton>
                  <Popover
                    open={Boolean(emojiAnchor)}
                    anchorEl={emojiAnchor}
                    onClose={() => setEmojiAnchor(null)}
                    anchorOrigin={{
                      vertical: 'top',
