                    multiline
                    maxRows={4}
                    sx={uiLayout.withUiSx({
                      mx: 1,
                      '& .MuiOutlinedInput-root': {
                        borderRadius: '24px',
                        bgcolor: colorPalette.background,
                        textAlign: 'right',
                        borderColor: colorPalette.primaryLight,
                        '&:hover fieldset': {
                          borderColor: colorPalette.primary,
                        },
                        '&.Mui-focused fieldset': {
                          borderColor: colorPalette.primary,
                        }
                      }
                    }, uiLayout.formFieldSx)}
                  />
                 {isRecording ? (
  <Box display="flex" alignItems="center">
    <IconButton 
      onClick={stopRecording} 
      sx={{
        color: colorPalette.error,
        animation: 'pulse 1.5s infinite',
        '@keyframes pulse': {
          '0%': { transform: 'scale(1)' },
          '50%': { transform: 'scale(1.2)' },
          '100%': { transform: 'scale(1)' }
        }
      }}
    >
      <MicIcon />
    </IconButton>
    <Typography variant="caption" sx={{ ml: 1, color: colorPalette.error }}>
      {formatTime(recordingTime)}
    </Typography>
  </Box>
) : (
  <IconButton 
    onClick={startRecording}
    sx={{
      color: colorPalette.primary,
      '&:hover': { backgroundColor: colorPalette.primaryLighter }
    }}
  >
    <MicIcon />
  </IconButton>
)}
                  <IconButton 
                    sx={{ 
                      color: colorPalette.primary,
                      '&:hover': { backgroundColor: colorPalette.primaryLighter }
                    }}
                    onClick={handleSendMessage}
                    disabled={message.trim() === '' && attachments.length === 0 && audioChunks.length === 0}
                  >
                    <SendIcon />
                  </IconButton>
                </Box>
              </Box>
            </>
          ) : (
            <Box 
              display="flex" 
              justifyContent="center" 
              alignItems="center" 
              height="100%"
              bgcolor={colorPalette.background}
            >
              <Typography variant="h6" sx={{ color: colorPalette.textLight }}>
                اختر مستخدمًا لبدء المحادثة
              </Typography>
            </Box>
          )}
        </Box>
      </Box>
    </Box></NavigationShell>
  );
};

export default Chats;

