                            minWidth:
                              i === 0
                                ? 80
                                : i === 1
                                ? 220
                                : 120,
                            maxWidth:
                              i === 1
                                ? 260
                                : 160,
                            whiteSpace: "normal",
                            lineHeight: 1.3
                          }}
                        >
                          {getColumnCaption(c)}
                        </TableCell>
                      ))}
                    </TableRow>
                  </TableHead>

                  <TableBody>
                    {rows.map((row, rowIndex) => {
                      const summary =
                        rowIndex >= rows.length - 3;

                      return (
                        <TableRow
                          key={rowIndex}
                          hover
                          sx={{
                            bgcolor: summary
                              ? "#eef9f1"
                              : rowIndex % 2
                              ? "#fff"
                              : "#fbfdfc"
                          }}
                        >
                          {columns.map((c, colIndex) => (
                            <TableCell
                              key={c}
                              align="center"
                              sx={{
                                fontWeight:
