                                whiteSpace:
                                  colIndex === 1
                                    ? "normal"
                                    : "nowrap",
                                textAlign: "center",
                                direction:
                                  colIndex > 1
                                    ? "ltr"
                                    : "rtl"
                              }}
                            >
                              {colIndex > 1
                                ? money(row?.[c])
                                : row?.[c] ?? ""}
                            </TableCell>
                          ))}
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </>
        )}
      </Paper>
    </Box>
  );

  return (
    <NavigationShell variant="standard" mobileOpen={mobileSidebarOpen} onMobileClose={() =>
            setMobileSidebarOpen(false)
          }><Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        bgcolor: soft
      }}
    >




      <Box
        sx={{
          flex: 1,
          minWidth: 0,
          ...navigationContentSx
        }}
      >
        {content}
      </Box>
    </Box></NavigationShell>
  );
}

