            }
            if (!isValidGuid(finishRow?.studentLevelGuid)) {
              await alertError("تعذر قراءة قيد دراسة الطالب من الصف المحدد");
              return;
            }

            const ok = await postJson("/api/course-students/finish-study", {
              userGuid,
              accountGuid: finishRow.accountGuid,
              studentLevelGuid: finishRow.studentLevelGuid,
              statusGuid: finishStatusGuid,
              levelMark: mark,
              levelNotes: finishNotes
            }, "جاري إنهاء دراسة الطالب");
            if (ok) setFinishOpen(false);
          }}>حفظ</Button>
        </DialogActions>
      </Dialog>

      <Dialog sx={uiLayout.dialogLayoutSx}
        open={ahliOpen}
        onClose={() => setAhliOpen(false)}
        fullWidth
        fullScreen={isPhone}
        maxWidth="sm"
        dir="rtl"
      >
        <DialogTitle>موقف الطالب من التدريب الأهلي</DialogTitle>
        <DialogContent>
          <Stack sx={uiLayout.formGridSx} spacing={1.5} mt={1}>
            <Typography fontWeight={900} textAlign="left">هل تم رفع الطالب على التدريب الأهلي؟</Typography>
            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }} select fullWidth label="اختر الحالة" value={ahliStatus}
              onChange={(event) => setAhliStatus(event.target.value)}>
              <MenuItem value="1">نعم - تم الرفع</MenuItem>
              <MenuItem value="2">لا - لم يتم الرفع</MenuItem>
              <MenuItem value="3">مؤجل</MenuItem>
            </TextField>
            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              multiline minRows={4}
              label={String(ahliStatus) === "1" ? "رقم الدورة" : String(ahliStatus) === "3" ? "سبب التأجيل" : "سبب عدم الرفع"}
              value={ahliDetails}
              onChange={(event) => setAhliDetails(event.target.value)}
            />
          </Stack>
        </DialogContent>
        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx} color="error" onClick={() => setAhliOpen(false)}>إلغاء</Button>
          <Button sx={uiLayout.buttonSx} variant="contained" onClick={async () => {
            if (!isValidGuid(ahliRow?.studentLevelGuid)) {
              await alertError("تعذر قراءة قيد دراسة الطالب من الصف المحدد");
              return;
            }
            if (![1, 2, 3].includes(Number(ahliStatus))) {
              await alertError("برجاء اختيار موقف التدريب الأهلي");
              return;
            }
            if (!String(ahliDetails || "").trim()) {
              await alertError("برجاء كتابة رقم الدورة أو السبب");
              return;
            }

            const ok = await postJson("/api/course-students/ahli-training", {
              userGuid,
              studentLevelGuid: ahliRow.studentLevelGuid,
              accountGuid: ahliRow.accountGuid,
              courseGuid: ahliRow.courseGuid,
              branchGuid: ahliRow.studyBranchGuid || branchGuid,
              status: Number(ahliStatus),
              details: String(ahliDetails).trim()
            }, "جاري حفظ موقف التدريب الأهلي");
            if (ok) setAhliOpen(false);
          }}>حفظ</Button>
        </DialogActions>
      </Dialog>

      <Dialog sx={uiLayout.dialogLayoutSx}
        open={passwordOpen}
        onClose={() => setPasswordOpen(false)}
        fullWidth
        maxWidth="xs"
        dir="rtl"
        PaperProps={{
          sx: {
            width: isPhone ? "88vw" : undefined,
            m: isPhone ? 1 : undefined
          }
        }}
      >
        <DialogTitle>التحقق من كلمة المرور</DialogTitle>
        <DialogContent>
          <TextField InputLabelProps={{ shrink: true }}
            autoFocus fullWidth type="password" label="كلمة المرور"
            value={password} onChange={(event) => setPassword(event.target.value)}
            onKeyDown={(event) => { if (event.key === "Enter") confirmPassword(); }}
            sx={uiLayout.withUiSx({ mt: 1 }, uiLayout.formFieldSx)}
          />
        </DialogContent>
        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx} color="error" onClick={() => setPasswordOpen(false)}>إلغاء</Button>
          <Button sx={uiLayout.buttonSx} variant="contained" onClick={confirmPassword}>تأكيد</Button>
        </DialogActions>
      </Dialog>

      <Dialog sx={uiLayout.dialogLayoutSx}
        open={transferOpen}
        onClose={() => setTransferOpen(false)}
        fullWidth
        fullScreen={isPhone}
        maxWidth="md"
        dir="rtl"
      >
        <DialogTitle>
          {pendingTransferRows.length > 1
            ? `نقل كل الطلاب المحددين (${pendingTransferRows.length})`
            : `نقل الطالب ${pendingTransferRows[0]?.studentName || ""}`}
        </DialogTitle>
        <DialogContent>
          <Stack spacing={1.2} mt={1}>
            {[
              ["updateRegistrationBranch", "newRegistrationBranchGuid", "فرع التسجيل", transferLookups.branches, "branchName"],
              ["updateStudyBranch", "newStudyBranchGuid", "فرع الدراسة", transferLookups.branches, "branchName"],
              ["updateCourse", "newCourseGuid", "الدورة", transferLookups.courses, "Name"],
              ["updateBatch", "newBatchGuid", "الدفعة", transferLookups.batches, "Name"]
            ].map(([checkKey, valueKey, label, items, nameKey]) => (
              <Box key={checkKey}>
                <FormControlLabel sx={uiLayout.checkboxFieldSx}
                  control={
                    <Checkbox
                      checked={Boolean(transferForm[checkKey])}
                      onChange={(event) => setTransferForm((current) => ({
                        ...current,
                        [checkKey]: event.target.checked,
                        [valueKey]: event.target.checked ? current[valueKey] : ""
                      }))}
                    />
                  }
                  label={`تغيير ${label}`}
                />
                <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                  select fullWidth size="small" label={`${label} الجديد`}
                  disabled={!transferForm[checkKey]}
                  value={transferForm[valueKey]}
                  onChange={(event) => setTransferForm((current) => ({
                    ...current, [valueKey]: event.target.value
                  }))}
                >
                  {items.map((item, index) => {
                    const guid = String(item.guid || item.Guid || "");
                    const name = String(item[nameKey] || item.name || item.Name || "");
                    return <MenuItem key={`${guid}-${index}`} value={guid}>{name}</MenuItem>;
                  })}
                </TextField>
              </Box>
            ))}
            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              multiline minRows={3} label="سبب النقل — اختياري"
              value={transferForm.reason}
              onChange={(event) => setTransferForm((current) => ({
                ...current, reason: event.target.value
              }))}
            />
          </Stack>
        </DialogContent>
        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx} color="error" onClick={() => setTransferOpen(false)}>إلغاء</Button>
          <Button sx={uiLayout.buttonSx} variant="contained" onClick={saveTransfer}>حفظ النقل</Button>
        </DialogActions>
      </Dialog>

      <StudentStatementDialog2
        open={statementOpen}
        onClose={() => {
          setStatementOpen(false);
          setStatementStudent(null);
        }}
        student={statementStudent}
        apiBaseUrl={API_BASE_URL}
        onOpenStatementDocument={openStatementDocument}
      />

      <EditStudentDialog
        open={editOpen}
        onClose={() => setEditOpen(false)}
        student={editStudent}
      />

      <RegisterDocumentDialog
        open={registerDocumentOpen}
        onClose={() => {
          setRegisterDocumentOpen(false);
          setRegisterDocumentRow(null);
        }}
        docGuid={
          registerDocumentRow?.actionGuid ||
          registerDocumentRow?.ActionGuid ||
          registerDocumentRow?.docGuid ||
          registerDocumentRow?.DocGuid ||
          ""
        }
        documentNo={
          registerDocumentRow?.documentNo ||
          registerDocumentRow?.DocumentNo ||
          registerDocumentRow?.code ||
          registerDocumentRow?.Code ||
          ""
        }
        apiBaseUrl={API_BASE_URL}
      />

      <Backdrop open={Boolean(workingText)} sx={{ zIndex: 1600, color: "#fff" }}>
        <Stack alignItems="center" spacing={2}>
          <CircularProgress color="inherit" />
          <Typography fontWeight={900}>{workingText}</Typography>
        </Stack>
      </Backdrop>
    </Box></NavigationShell>
  );
}

src\\pages\\create-exam.css:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700&display=swap');

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Cairo', sans-serif;
  line-height: 1.6;
  color: #333;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
}

.page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

.page-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 30px;
  padding: 25px;
  background: white;
  border-radius: 15px;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
  border: 1px solid #e1e5e9;
}

.page-head h1 {
  font-size: 32px;
  font-weight: 700;
  color: #2c3e50;
  margin-bottom: 8px;
  background: linear-gradient(135deg, #667eea, #764ba2);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.sub {
  color: #7f8c8d;
  font-size: 16px;
  font-weight: 500;
}

.exam-status {
  display: flex;
  align-items: center;
  gap: 10px;
}

.card {
  background: white;
  border-radius: 15px;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
  padding: 28px;
  margin-bottom: 25px;
  border: 1px solid #e1e5e9;
  transition: all 0.3s ease;
}

.card:hover {
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.15);
  transform: translateY(-2px);
}

.card-title {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 20px;
  color: #2c3e50;
  border-bottom: 2px solid #667eea;
  padding-bottom: 10px;
}

.grid {
  display: grid;
  gap: 18px;
}

.g1 { grid-template-columns: 1fr; }
.g2 { grid-template-columns: repeat(2, 1fr); }
.g3 { grid-template-columns: repeat(3, 1fr); }
.g4 { grid-template-columns: repeat(4, 1fr); }

.col-span-3 {
  grid-column: span 3;
}

.field {
  margin-bottom: 18px;
}

.field-label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  color: #2c3e50;
  font-size: 14px;
}

.req {
  color: #e74c3c;
}

input, select, textarea {
  width: 100%;
  padding: 12px 15px;
  border: 2px solid #e1e5e9;
  border-radius: 8px;
  font-family: 'Cairo', sans-serif;
  font-size: 14px;
  transition: all 0.3s;
  background: #f8f9fa;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: #667eea;
  background: white;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

textarea {
  resize: vertical;
  min-height: 100px;
}

.hint {
  font-size: 12px;
  color: #7f8c8d;
  margin-top: 6px;
}

.bar {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid #e1e5e9;
}

.btn {
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  font-family: 'Cairo', sans-serif;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.3s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn.primary {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.3);
}

.btn.primary:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(102, 126, 234, 0.4);
}

.btn.success {
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
  box-shadow: 0 4px 15px rgba(40, 167, 69, 0.3);
}

.btn.success:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(40, 167, 69, 0.4);
}

.btn.danger {
  background: linear-gradient(135deg, #e74c3c, #c0392b);
  color: white;
  box-shadow: 0 4px 15px rgba(231, 76, 60, 0.3);
}

.btn.danger:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(231, 76, 60, 0.4);
}

.btn.outline {
  background: transparent;
  border: 2px solid #667eea;
  color: #667eea;
}

.btn.outline:hover {
  background: #667eea;
  color: white;
  transform: translateY(-2px);
}

.btn.small {
  padding: 8px 15px;
  font-size: 13px;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none !important;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 8px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  gap: 6px;
}

.badge.neutral {
  background-color: #ecf0f1;
  color: #7f8c8d;
}

.badge.blue {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  box-shadow: 0 2px 8px rgba(102, 126, 234, 0.3);
}

.badge.green {
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
  box-shadow: 0 2px 8px rgba(40, 167, 69, 0.3);
}

.badge.orange {
  background: linear-gradient(135deg, #fd7e14, #e8590c);
  color: white;
  box-shadow: 0 2px 8px rgba(253, 126, 20, 0.3);
}

.badge.purple {
  background: linear-gradient(135deg, #6f42c1, #e83e8c);
  color: white;
  box-shadow: 0 2px 8px rgba(111, 66, 193, 0.3);
}

.muted {
  color: #95a5a6;
  font-size: 13px;
}

.err {
  color: #e74c3c;
  font-size: 13px;
  font-weight: 500;
}

.toast {
  color: #28a745;
  font-size: 14px;
  font-weight: 600;
}

/* Mode Toggle */
.mode-toggle {
  margin-bottom: 25px;
  padding: 20px;
  background: linear-gradient(135deg, #f8f9fa, #e9ecef);
  border-radius: 12px;
  border: 1px solid #dee2e6;
}

.seg {
  display: flex;
  background: #f8f9fa;
  border-radius: 10px;
  padding: 4px;
  border: 1px solid #e9ecef;
  gap: 2px;
}

.seg-btn {
  flex: 1;
  padding: 12px 20px;
  border: none;
  background: transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-family: 'Cairo', sans-serif;
  font-weight: 600;
  font-size: 14px;
}

.seg-btn.active {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.3);
}

/* Shared Combinations */
.shared-combinations {
  margin: 25px 0;
  padding: 25px;
  background: linear-gradient(135deg, #f8f9fa, #e9ecef);
  border-radius: 12px;
  border: 1px solid #dee2e6;
}

.combinations-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.combinations-header h4 {
  margin: 0;
  color: #2c3e50;
  font-size: 18px;
  font-weight: 600;
}

.combinations-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 20px;
}

.combination-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 20px;
  background: white;
  border-radius: 10px;
  border: 1px solid #dee2e6;
  transition: all 0.3s ease;
}

.combination-item:hover {
  transform: translateX(5px);
  border-color: #667eea;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.1);
}

.combination-info {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.course-name {
  font-weight: 600;
  color: #2c3e50;
}

/* MCQ Styles */
.mcq-box {
  margin-top: 15px;
}

.mcq-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 15px;
}

.mcq-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border-radius: 8px;
  background: #f8f9fa;
  border: 1px solid #e1e5e9;
  transition: all 0.3s;
}

.mcq-item:hover {
  background: #e9ecef;
  border-color: #667eea;
}

.flag {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #ddd;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s;
  font-size: 14px;
  font-weight: bold;
}

.flag.on {
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
  border-color: #28a745;
  transform: scale(1.1);
}

.icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid #ddd;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s;
  font-size: 14px;
}

.icon.danger {
  color: #e74c3c;
  border-color: #e74c3c;
}

.icon.danger:hover {
  background: #e74c3c;
  color: white;
  transform: scale(1.1);
}

.empty {
  text-align: center;
  padding: 50px 25px;
  color: #95a5a6;
  font-size: 16px;
}

.empty-icon {
  font-size: 64px;
  margin-bottom: 20px;
  color: #bdc3c7;
}

/* Exam Paper Styles */
.exam-paper {
  background: white;
  border: 1px solid #e0e0e0;
  border-radius: 15px;
  padding: 30px;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
}

.exam-header {
  text-align: center;
  margin-bottom: 35px;
  padding-bottom: 25px;
  border-bottom: 3px solid #667eea;
  background: linear-gradient(135deg, #f8f9fa, #ffffff);
  border-radius: 12px;
  padding: 25px;
}

.exam-title {
  font-size: 28px;
  font-weight: 700;
  color: #2c3e50;
  margin-bottom: 15px;
}

.exam-meta {
  display: flex;
  justify-content: center;
  gap: 25px;
  color: #7f8c8d;
  font-size: 16px;
  font-weight: 500;
}

.questions-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 25px;
  padding: 20px;
  background: linear-gradient(135deg, #f8f9fa, #e9ecef);
  border-radius: 12px;
}

.questions-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.total-score {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

/* Order Controls */
.order-controls {
  background: linear-gradient(135deg, #f8f9fa, #e9ecef);
  border-radius: 12px;
  padding: 22px;
  margin-bottom: 30px;
  border: 1px solid #dee2e6;
}

.order-controls h4 {
  margin: 0 0 15px 0;
  color: #2c3e50;
  font-size: 18px;
  font-weight: 600;
}

.order-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* Question Sections */
.question-section {
  margin-bottom: 35px;
}

.section-title {
  font-size: 22px;
  font-weight: 600;
  color: #2c3e50;
  margin-bottom: 22px;
  padding-bottom: 12px;
  border-bottom: 3px solid #667eea;
  display: flex;
  align-items: center;
  gap: 10px;
}

.questions-list {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.question-item {
  border: 1px solid #e1e5e9;
  border-radius: 12px;
  padding: 22px;
  background: white;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.question-item::before {
  content: '';
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 5px;
  background: #667eea;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.question-item:hover::before {
  opacity: 1;
}

.question-item:hover {
  border-color: #667eea;
  transform: translateY(-3px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
}

.question-item.tf-type {
  border-right: 5px solid #667eea;
}

.question-item.mcq-type {
  border-right: 5px solid #6f42c1;
}

.question-content {
  flex: 1;
}

.question-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 15px;
  padding-bottom: 12px;
  border-bottom: 2px dashed #e1e5e9;
}

.question-number {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  padding: 8px 15px;
  border-radius: 20px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.3);
}

.question-actions {
  display: flex;
  gap: 8px;
}

.question-text {
  font-size: 16px;
  line-height: 1.7;
  color: #2c3e50;
  margin-bottom: 18px;
  font-weight: 500;
  padding: 10px 0;
}

/* Question Options */
.question-options {
  margin-right: 18px;
}

.tf-options,
.mcq-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.option {
  display: flex;
  align-items: flex-start;
  padding: 12px 18px;
  border-radius: 10px;
  background-color: #f8f9fa;
  border: 1px solid #e1e5e9;
  transition: all 0.3s ease;
  font-size: 15px;
  position: relative;
  overflow: hidden;
}

.option::before {
  content: '';
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: #28a745;
  opacity: 0;
