const handleCreateCourse = async () => {
  if (!courseForm.diploma_name || !courseForm.level_name || !courseForm.course_name) {
    Swal.fire({
      title: 'تنبيه',
      text: 'يرجى ملء جميع الحقول',
      icon: 'warning',
      confirmButtonText: 'موافق',
      confirmButtonColor: '#80b49e'
    });
