        <DialogContent>
          <Stack spacing={3} sx={{ mt: 2 }}>
            {/* نموذج إضافة مقرر جديد */}
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: '#80b49e' }}>
