        type: qType,
        text: qText.trim(),
        score: Number(score) || 1,
        order_no: questions.length + 1,
      });

      let qid = addQRes.ok ? addQRes.question_id : null;

      if (qType === "TF") {
        const tfOptions = [
          { text: "صح", correct: tfCorrect === "صح" },
