                تحديث جماعي
              </Typography>

              <Box display="flex" alignItems="center" gap={2} mb={3}>
                <FormControl sx={uiLayout.formFieldSx} fullWidth size="small">
                  <InputLabel>حالة الحضور</InputLabel>
