                )}</span>
                <br/>
                <b>آخر موقع:</b> ${escapeHtml(item.location_text || "غير متاح")}
              </div>`
          )
          .join('<hr style="border:none;border-top:1px solid rgba(174,30,33,.18);" />')}
      </div>`
    );
  }

  return {
    hasSuspicion,
