          const discountStatusName = String(
            pick(row, [
              "DiscountStatusName",
              "discountStatusName",
              "STAUT__",
              "statusName"
            ])
          );

          const requestStatusName = String(
            pick(row, [
              "RequestStatusName",
              "requestStatusName",
              "ORDERSTAUT_",
              "orderStatusName"
            ])
          );

          const discountStatus =
            numberValue(
              pick(
                row,
                [
                  "DiscountStatusCode",
                  "discountStatusCode",
                  "OrderStaut",
                  "orderStaut"
                ],
                discountStatusName.includes(
                  "تم تأكيد"
                )
                  ? 3
                  : discountStatusName ===
                      "تم التنفيذ"
                    ? 1
                    : discountStatusName ===
                        "مرفوض"
                      ? 2
                      : 0
              )
            );

          return {
            id: String(
              pick(
                row,
                [
                  "Guid",
                  "guid",
                  "DiscountOrderGuid"
