      } catch {
        if (alive) {
          setAuthorized(false);
        }
      } finally {
        if (alive) {
          setPermissionLoading(false);
        }
      }
    };

    checkPermission();

    return () => {
      alive = false;
    };
  }, [userGuid]);

  // =========================================================
  // Load account list - server search only.
  // Same desktop logic:
  // IsUse = 1, AccountType2 = 2 => AccountType <> 2
  // =========================================================
  const loadAccounts =
    useCallback(
      async (query = "") => {
        if (!authorized || !userGuid) {
          return;
        }

        if (accountRequestRef.current) {
          accountRequestRef.current.abort();
        }

        const controller =
          new AbortController();

        accountRequestRef.current =
          controller;

        try {
          setAccountsLoading(true);

          const params =
            new URLSearchParams({
              userGuid,
              q: String(query || "").trim(),
              limit: "100"
            });

          const response =
            await fetch(
              `${API_BASE_URL}/api/general-account-statement/accounts?${params.toString()}`,
              {
                cache: "no-store",
                headers: {
                  Accept:
                    "application/json"
                },
                signal:
                  controller.signal
              }
            );

          const result =
            await response
              .json()
              .catch(() => null);

          if (!response.ok) {
            throw new Error(
              result?.message ||
              "تعذر تحميل الحسابات"
            );
          }

          setAccounts(
            Array.isArray(result?.data)
              ? result.data
              : []
          );
        } catch (e) {
          if (e?.name !== "AbortError") {
            setAccounts([]);
          }
        } finally {
          if (
            accountRequestRef.current ===
            controller
          ) {
            setAccountsLoading(false);
            accountRequestRef.current =
              null;
          }
        }
      },
      [authorized, userGuid]
    );

