      async (accountOverride = null) => {
        const account =
          accountOverride ||
          selectedAccount;

        if (!authorized || !userGuid) {
          return;
        }

        if (!account?.guid) {
          setError(
            "برجاء اختيار الحساب أولاً"
          );
          return;
        }

        if (!fromDate || !toDate) {
          setError(
            "برجاء اختيار الفترة من وإلى"
          );
          return;
        }

        if (fromDate > toDate) {
          setError(
            "تاريخ البداية لا يمكن أن يكون بعد تاريخ النهاية"
          );
          return;
        }

        if (activeRequestRef.current) {
          activeRequestRef.current.abort();
        }

        const controller =
          new AbortController();

        activeRequestRef.current =
          controller;

        const requestId =
          ++requestSequenceRef.current;

        try {
          setLoading(true);
          setError("");

          const params =
            new URLSearchParams({
              userGuid,
              accountGuid:
                account.guid,
              fromDate,
              toDate
            });

          const response =
            await fetch(
              `${API_BASE_URL}/api/general-account-statement?${params.toString()}`,
              {
                cache: "no-store",
                headers: {
                  Accept:
                    "application/json"
                },
                signal:
                  controller.signal
              }
            );

          const result =
            await response
              .json()
              .catch(() => null);

          if (
            requestId !==
            requestSequenceRef.current
          ) {
            return;
          }

          if (!response.ok) {
            throw new Error(
              result?.message ||
              result?.error ||
              "تعذر تحميل كشف الحساب"
            );
          }

          setRows(
            Array.isArray(result?.data)
              ? result.data
              : []
          );
        } catch (e) {
          if (e?.name === "AbortError") {
            return;
          }

          if (
            requestId !==
            requestSequenceRef.current
          ) {
            return;
          }

          setRows([]);
          setError(
            e?.message ||
            "تعذر تحميل كشف الحساب"
          );
        } finally {
          if (
            requestId ===
            requestSequenceRef.current
          ) {
            setLoading(false);

            if (
              activeRequestRef.current ===
              controller
            ) {
              activeRequestRef.current =
                null;
            }
          }
        }
      },
      [
        authorized,
        userGuid,
        selectedAccount,
        fromDate,
        toDate
      ]
    );

