      }

      const result = [];

      for (const item of preparedRows) {
        if (
          q &&
          !item.searchText.includes(q)
        ) {
          continue;
        }

        let matches = true;

        for (let i = 0; i < activeKeys.length; i += 1) {
          const key =
            activeKeys[i];

          if (
            !selectedSets[key].has(
              item.filterValues[key]
