  /*
   * في الديسكتوب يتم تشغيل:
   * FormTypeGuid("salesinvoice")
   * ثم AutoGetInvoiceType للنوع 1 والنوع 2.
   *
   * لذلك لا نفتح شاشة طلب السداد بالبيانات المختصرة
   * القادمة من تقرير الخريجين فقط، بل نطلب Payment Context
   * الكامل من الباك إند أولًا حتى تصل بيانات دفتر السداد:
   * payDocGuid / payDocCode / payDocName
   * payFeesDocGuid / payFeesDocCode / payFeesDocName
   */
  const openPaymentOrder = async (row) => {
    if (!row?.accountGuid) {
      await showError(
        "لا يمكن قراءة حساب الطالب"
      );
      return;
    }

    if (!row?.branchGuid) {
      await showError(
        "لا يمكن قراءة فرع الطالب"
      );
      return;
    }

    if (!row?.diplomGuid) {
      await showError(
        "لا يمكن قراءة تخصص الطالب"
      );
      return;
    }

    try {
      setPaymentContextLoading(true);
      setPaymentContext(null);

      const params = new URLSearchParams({
        accountGuid:
          row.accountGuid,
        studentName:
          row.studentName || "",
        nationalId:
          row.nationalId || "",
        tel:
          row.studentTel || "",
        diplomName:
          row.diplomName || "",
        diplomGuid:
          row.diplomGuid,
        branchGuid:
          row.branchGuid,
        branchName:
          row.branchName || "",
        regDocGuid:
          row.regDocGuid || ""
      });

      const response = await fetch(
        `${API_BASE_URL}/api/reception-office/payment/context?${params.toString()}`,
        {
          method: "GET",
          headers: {
            Accept:
              "application/json"
          },
          cache: "no-store"
        }
      );

      const result =
        await readJson(response);

      const readyContext = {
        ...result,

        accountGuid:
          result?.accountGuid ||
          row.accountGuid,

        studentName:
          result?.studentName ||
          row.studentName,

        nationalId:
          result?.nationalId ||
          row.nationalId,

        tel:
          result?.tel ||
          row.studentTel,

        studentNational:
          row.studentNational ??
          "0",

        diplomName:
          result?.diplomName ||
          row.diplomName,

        diplomGuid:
          result?.diplomGuid ||
          row.diplomGuid,

        branchGuid:
          result?.branchGuid ||
          row.branchGuid,

        branchName:
          result?.branchName ||
          row.branchName,

        regDocGuid:
          result?.regDocGuid ||
          row.regDocGuid
      };

      if (
        !readyContext.payDocGuid
      ) {
        throw new Error(
          "لم يرجع الباك إند دفتر سداد القسط الشهري"
        );
      }

      if (
        !readyContext.payFeesDocGuid
      ) {
        throw new Error(
          "لم يرجع الباك إند دفتر سداد الرسوم"
        );
      }

      setPaymentContext(
        readyContext
      );

      setPaymentOpen(true);
    } catch (error) {
      setPaymentContext(null);

      await showError(
        error?.message ||
        "تعذر تجهيز بيانات طلب السداد"
      );
    } finally {
      setPaymentContextLoading(false);
    }
  };

