      "نوع الطالب"
    ];

    const values = filteredGridRows.map((row) => [
      row.regTypeName,
      row.diplomName,
      row.studentName,
      row.studentTel,
      row.nationalId,
      row.preBalance,
      row.debit,
      row.startPay,
      row.monthPay,
      row.feesPay,
      row.mDaily,
      row.dDaily,
      row.balance,
      row.trainerName,
      row.studentType
    ]);

    const escape = (value) =>
      `"${String(value ?? "")
        .replace(/"/g, '""')}"`;

    const csv =
      "\uFEFF" +
      [headers, ...values]
        .map((row) =>
          row.map(escape).join(",")
        )
        .join("\n");

    const blob = new Blob([csv], {
      type:
        "text/csv;charset=utf-8;"
    });

    const url =
      URL.createObjectURL(blob);

    const anchor =
      document.createElement("a");

    anchor.href = url;
    anchor.download =
      `متابعة-الخريجين-${today()}.csv`;

    anchor.click();
    URL.revokeObjectURL(url);
  };


