                value={bioBulkSearch}
                onChange={(e) =>
                  setBioBulkSearch(e.target.value)
                }
                placeholder="بحث في موظفي النظام بالاسم أو الكود..."
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchRoundedIcon />
                    </InputAdornment>
                  )
                }}
              />

              <FormControl
                size="small"
                sx={uiLayout.withUiSx({ minWidth: { md: 260 } }, uiLayout.formFieldSx)}
              >
                <InputLabel>الفرع</InputLabel>
                <Select
                  MenuProps={RTL_MENU_PROPS}
                  label="الفرع"
                  value={bioBulkBranchGuid}
                  onChange={(e) => {
                    setBioBulkBranchGuid(
                      e.target.value
                    );
                    setBioBulkPage(1);
                  }}
                >
                  <MenuItem value="">
                    كل الفروع
                  </MenuItem>
                  {(lookups.branches || []).map(
                    (branch) => (
                      <MenuItem
                        key={
                          branch.guid ||
                          branch.branchGuid
                        }
                        value={
                          branch.guid ||
                          branch.branchGuid
                        }
                      >
                        {branch.name ||
                          branch.branchName ||
                          branch.brEName ||
                          branch.brName ||
                          "-"}
                      </MenuItem>
                    )
                  )}
                </Select>
              </FormControl>

              <FormControl
                size="small"
                sx={uiLayout.withUiSx({ minWidth: 120 }, uiLayout.formFieldSx)}
              >
                <InputLabel>الصفوف</InputLabel>
                <Select
                  MenuProps={RTL_MENU_PROPS}
                  label="الصفوف"
                  value={bioBulkPageSize}
                  onChange={(e) => {
                    const value = Number(
                      e.target.value
                    );
                    setBioBulkPageSize(value);
                    setBioBulkPage(1);
                    loadBioBulkWorkspace({
                      pageValue: 1,
                      pageSizeValue: value
                    });
                  }}
                >
                  {[20, 30, 50, 100].map((value) => (
                    <MenuItem
                      key={value}
                      value={value}
                    >
                      {value}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Stack>

            <Alert
              severity={
                bioBulkApprovedLinks.length
                  ? "success"
                  : "info"
              }
              variant="outlined"
            >
              تم اعتماد{" "}
              <strong>
                {bioBulkApprovedLinks.length}
              </strong>{" "}
              ربط في الصفحة الحالية. اختيار الاقتراح
              وحده لا يكفي؛ لازم تحدد
              <strong> اعتماد</strong>.
            </Alert>

            {bioBulkLoading ? (
              <Box
                sx={{
                  minHeight: 320,
                  display: "grid",
                  placeItems: "center"
                }}
              >
                <CircularProgress />
              </Box>
            ) : (
              <Box
                sx={{
                  border: `1px solid ${border}`,
                  borderRadius: 2.2,
                  overflow: "hidden"
                }}
              >
                <Box
                  sx={{
                    display: "grid",
                    gridTemplateColumns:
                      "48px minmax(220px,1.1fr) minmax(360px,1.8fr) 120px",
                    gap: 1,
                    p: 1,
                    bgcolor: "#f5f8f6",
                    borderBottom: `1px solid ${border}`,
                    fontWeight: 950,
                    fontSize: 12
                  }}
                >
                  <Box>اعتماد</Box>
                  <Box>موظف النظام</Box>
                  <Box>موظف BioTime</Box>
                  <Box>المراجعة</Box>
                </Box>

                <Stack spacing={0}>
                  {bioBulkEmployees.map((employee) => {
                    const selected =
                      bioBulkSelections[
                        employee.employeeGuid
                      ] || null;

                    const approved =
                      Boolean(
                        bioBulkApproved[
                          employee.employeeGuid
                        ]
                      );

                    const suggestionScore =
                      Number(selected?.score || 0);

                    const rowOptions = [
                      ...(employee?.suggestions || [])
                        .map((item) => ({
                          bioTimeEmployeeId:
                            Number(
                              item.bioTimeEmployeeId
                            ),
                          bioTimeEmpCode:
                            String(
                              item.bioTimeEmpCode || ""
                            ),
                          fullName:
                            item.fullName || "",
                          departmentName:
                            item.departmentName || "",
                          areasText:
                            item.areasText || "",
                          score:
                            Number(item.score || 0),
                          label:
                            item.label || "",
                          reasons:
                            Array.isArray(
                              item.reasons
                            )
                              ? item.reasons
                              : []
                        })),
                      ...bioBulkCandidates
                        .filter(
                          (candidate) =>
                            !(employee?.suggestions || [])
                              .some(
                                (suggestion) =>
                                  Number(
                                    suggestion
                                      .bioTimeEmployeeId
                                  ) ===
                                  Number(
                                    candidate
                                      .bioTimeEmployeeId
                                  )
                              )
                        )
                        .map((candidate) => ({
                          bioTimeEmployeeId:
                            Number(
                              candidate
                                .bioTimeEmployeeId
                            ),
                          bioTimeEmpCode:
                            String(
                              candidate
                                .bioTimeEmpCode || ""
                            ),
                          fullName:
                            candidate.fullName || "",
                          departmentName:
                            candidate.departmentName ||
                            "",
                          areasText:
                            candidate.areasText || "",
                          score: 0,
                          label: "",
                          reasons: []
                        }))
                    ];

                    return (
                      <Box
                        key={employee.employeeGuid}
                        sx={{
                          display: "grid",
                          gridTemplateColumns:
                            "48px minmax(220px,1.1fr) minmax(360px,1.8fr) 120px",
                          gap: 1,
                          alignItems: "center",
                          p: 1,
                          borderBottom:
                            `1px solid ${border}`,
                          bgcolor: approved
                            ? "#f3fff8"
                            : "#fff"
                        }}
                      >
                        <Checkbox
                          checked={approved}
                          disabled={!selected}
                          onChange={(e) =>
                            setBioBulkApproved(
                              (current) => ({
                                ...current,
                                [employee.employeeGuid]:
                                  e.target.checked
                              })
                            )
                          }
                        />

                        <Box>
                          <Typography
                            sx={{
                              fontWeight: 950,
                              fontSize: 12.5
                            }}
                          >
                            {employee.employeeName}
                          </Typography>
                          <Typography
                            color="text.secondary"
                            sx={{ fontSize: 12 }}
                          >
                            #{employee.employeeCode || "-"}
                            {" • "}
                            {employee.branchName ||
                              "بدون فرع"}
                          </Typography>
                        </Box>

                        <Autocomplete
              ListboxProps={RTL_AUTOCOMPLETE_LISTBOX_PROPS}
                          size="small"
                          options={rowOptions}
                          value={selected}
                          isOptionEqualToValue={(
                            option,
                            value
                          ) =>
                            Number(
                              option.bioTimeEmployeeId
                            ) ===
                            Number(
                              value?.bioTimeEmployeeId
                            )
                          }
                          getOptionLabel={(option) =>
                            `${
                              option?.fullName ||
                              "بدون اسم"
                            } • ${
                              option?.bioTimeEmpCode ||
                              "-"
                            }`
                          }
                          filterOptions={(
                            options,
                            state
                          ) => {
                            const term =
                              state.inputValue
                                .trim()
                                .toLowerCase();

                            if (!term) {
                              return options.slice(
                                0,
                                30
                              );
                            }

                            return options
                              .filter((option) =>
                                [
                                  option.fullName,
                                  option.bioTimeEmpCode,
                                  option.departmentName,
                                  option.areasText
                                ]
                                  .filter(Boolean)
                                  .join(" ")
                                  .toLowerCase()
                                  .includes(term)
                              )
                              .slice(0, 40);
                          }}
                          onChange={(_, value) => {
                            setBioBulkSelections(
                              (current) => ({
                                ...current,
                                [employee.employeeGuid]:
                                  value || null
                              })
                            );

                            setBioBulkApproved(
                              (current) => ({
                                ...current,
                                [employee.employeeGuid]:
                                  false
                              })
                            );
                          }}
                          renderOption={(
                            props,
                            option
                          ) => (
                            <li
                              {...props}
                              key={
                                option.bioTimeEmployeeId
                              }
                            >
                              <Box sx={{ width: "100%" }}>
                                <Stack
                                  direction="row"
                                  spacing={0.5}
                                  alignItems="center"
                                >
                                  <Typography
                                    sx={{
                                      fontWeight: 900,
                                      fontSize: 12
                                    }}
                                  >
                                    {option.fullName ||
                                      "بدون اسم"}
                                  </Typography>

                                  {Number(
                                    option.score || 0
                                  ) > 0 && (
                                    <Chip
                                      size="small"
                                      label={`${Number(
                                        option.score
                                      )}%`}
                                      color={
                                        Number(
                                          option.score
                                        ) >= 70
                                          ? "success"
                                          : Number(
                                                option.score
                                              ) >= 50
                                            ? "warning"
                                            : "default"
                                      }
                                      sx={{
                                        height: 19,
                                        fontSize: 12
                                      }}
                                    />
                                  )}
                                </Stack>

                                <Typography
                                  color="text.secondary"
                                  sx={{ fontSize: 12 }}
                                >
                                  BioTime #
                                  {
                                    option.bioTimeEmployeeId
                                  }
                                  {" • "}
                                  Code:{" "}
                                  {option.bioTimeEmpCode ||
                                    "-"}
                                  {" • "}
                                  {option.areasText ||
                                    option.departmentName ||
                                    "-"}
                                </Typography>
                              </Box>
                            </li>
                          )}
                          renderInput={(params) => (
                            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                              {...params}
                              placeholder="اختر أو اكتب اسم BioTime..."
                            />
                          )}
                        />

                        <Stack
                          spacing={0.35}
                          alignItems="flex-start"
                        >
                          {selected ? (
                            <>
                              <Chip
                                size="small"
                                color={
                                  suggestionScore >= 70
                                    ? "success"
                                    : suggestionScore >= 50
                                      ? "warning"
                                      : "default"
                                }
                                variant="outlined"
                                label={
                                  suggestionScore > 0
                                    ? `اقتراح ${suggestionScore}%`
                                    : "اختيار يدوي"
                                }
                                sx={{
                                  fontWeight: 850,
                                  fontSize: 12
                                }}
                              />
                              <Typography
                                color="text.secondary"
                                sx={{
                                  fontSize: 12,
                                  lineHeight: 1.35
                                }}
                              >
                                {selected.areasText ||
                                  selected.departmentName ||
                                  "راجع الاسم والكود"}
                              </Typography>
                            </>
                          ) : (
                            <Chip
                              size="small"
                              label="غير محدد"
                              variant="outlined"
                            />
                          )}
                        </Stack>
                      </Box>
                    );
                  })}

                  {!bioBulkEmployees.length && (
                    <Alert
                      severity="success"
                      sx={{ m: 1 }}
                    >
                      لا يوجد موظفون غير مربوطين ضمن
                      الفلتر الحالي.
                    </Alert>
                  )}
                </Stack>
              </Box>
            )}

            {bioBulkPageCount > 1 && (
              <Stack
                direction="row"
                justifyContent="center"
              >
                <Pagination
                  count={bioBulkPageCount}
                  page={bioBulkPage}
                  onChange={(_, value) => {
                    setBioBulkPage(value);
                    loadBioBulkWorkspace({
                      pageValue: value
                    });
                  }}
                  color="primary"
                />
              </Stack>
            )}
          </Stack>
        </DialogContent>

        <DialogActions
          sx={uiLayout.withUiSx({
            justifyContent: "space-between",
            px: 2
          }, uiLayout.dialogActionsSx)}
        >
          <Button sx={uiLayout.buttonSx}
            onClick={() => setBioBulkOpen(false)}
            disabled={
              bioBulkSaving || bioBulkRefreshing
            }
          >
            إغلاق
          </Button>

          <Button
            variant="contained"
            startIcon={<GroupWorkRoundedIcon />}
            disabled={
              bioBulkSaving ||
              !bioBulkApprovedLinks.length
            }
            onClick={saveBioBulkLinks}
            sx={uiLayout.withUiSx({
              bgcolor: primary,
              fontWeight: 950,
              minWidth: 190
            }, uiLayout.buttonSx)}
          >
            {bioBulkSaving
              ? "جاري اعتماد الربط..."
              : `اعتماد المحدد (${bioBulkApprovedLinks.length})`}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        sx={uiLayout.withUiSx(RTL_DIALOG_SX, uiLayout.dialogLayoutSx)}
        open={bioDialogOpen}
        onClose={() =>
          !bioSavingId &&
          setBioDialogOpen(false)
        }
        fullWidth
        maxWidth="md"
        dir={DIALOG_DIRECTION}
      >
        <DialogTitle sx={{ fontWeight: 950 }}>
          ربط موظف BioTime
        </DialogTitle>

        <DialogContent dividers>
          <Stack spacing={1.2}>
            <Alert severity="info">
              سيتم ربط موظف النظام {" "}
              <strong>
                {bioEmployee?.employeeName || "-"}
              </strong>
              {" "}بموظف واحد من BioTime.
              اكتب الاسم الإنجليزي أو كود BioTime للبحث السريع.
              لا يوجد تحميل تلقائي ولا مقارنة أسماء.
              <br />
              الفرع في النظام:{" "}
              <strong>
                {bioEmployee?.branchName ||
                  "غير محدد"}
              </strong>
            </Alert>

            {bioEmployee?.bioTimeEmployeeId && (
              <Alert severity="success">
                الربط الحالي: BioTime ID {" "}
                {bioEmployee.bioTimeEmployeeId}
                {" "}/ كود {" "}
                {bioEmployee.bioTimeEmpCode || "-"}
              </Alert>
            )}

            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              size="small"
              fullWidth
              value={bioSearch}
              onChange={(e) =>
                setBioSearch(e.target.value)
              }
              placeholder="اكتب الاسم الإنجليزي أو كود BioTime (حرفان على الأقل)..."
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchRoundedIcon />
                  </InputAdornment>
                )
              }}
            />


            {bioSearch.trim().length < 2 && (
              <Alert severity="info" variant="outlined">
                اكتب حرفين على الأقل من الاسم الإنجليزي أو كود BioTime.
                لن يتم الاتصال بـ BioTime قبل ذلك، وده يسرّع فتح نافذة الربط جدًا.
              </Alert>
            )}

            {!bioLoading &&
              bioSearch.trim().length >= 2 &&
              bioRows.length === 0 && (
                <Alert severity="warning" variant="outlined">
                  لا توجد نتائج مطابقة. جرّب جزءًا آخر من الاسم أو كود BioTime.
                </Alert>
              )}

            {bioLoading ? (
              <Box
                sx={{
                  minHeight: 180,
                  display: "grid",
                  placeItems: "center"
                }}
              >
                <CircularProgress size={32} />
              </Box>
            ) : (
              <Stack
                spacing={0.7}
                sx={{
                  maxHeight: 460,
                  overflowY: "auto"
                }}
              >
                {bioRows.map((bio) => (
                  <Paper
                    key={bio.id}
                    variant="outlined"
                    sx={{
                      p: 1,
                      borderRadius: 2
                    }}
                  >
                    <Stack
                      direction={{
                        xs: "column",
                        sm: "row"
                      }}
                      alignItems={{
                        xs: "stretch",
                        sm: "center"
                      }}
                      justifyContent="space-between"
                      spacing={1}
                    >
                      <Box>
                        <Typography
                          sx={{
                            fontWeight: 950,
                            fontSize: 13
                          }}
                        >
                          {bio.fullName ||
                            "بدون اسم"}
                        </Typography>

                        <Stack
                          direction="row"
                          spacing={0.4}
                          alignItems="center"
                          flexWrap="wrap"
                          useFlexGap
                          sx={{ mt: 0.35 }}
                        >


                          {bio.isLinkedToAnother && (
                            <Chip
                              size="small"
                              color="error"
                              variant="outlined"
                              label={`مرتبط بـ ${
                                bio.linkedEmployeeName ||
                                "موظف آخر"
                              }`}
                              sx={{
                                height: 22,
                                fontSize: 12,
                                fontWeight: 850
                              }}
                            />
                          )}
                        </Stack>

                        <Typography
                          color="text.secondary"
                          sx={{
                            mt: 0.25,
                            fontSize: 12
                          }}
                        >
                          BioTime ID: {bio.id}
                          {" • "}
                          Code: {bio.empCode || "-"}
                          {" • "}
                          {bio.department ||
                            "بدون قسم"}
                        </Typography>

                        {!!bio.areas?.length && (
                          <Typography
                            color="text.secondary"
                            sx={{
                              mt: 0.2,
                              fontSize: 12
                            }}
                          >
                            {bio.areas.join(" • ")}
                          </Typography>
                        )}

                      </Box>

                      <Button
                        variant="contained"
                        size="small"
                        startIcon={
                          <FingerprintRoundedIcon />
                        }
                        disabled={
                          Boolean(bioSavingId) ||
                          Boolean(bio.isLinkedToAnother)
                        }
                        onClick={() =>
                          linkBioEmployee(bio)
                        }
                        sx={uiLayout.withUiSx({
                          minWidth: 110,
                          bgcolor: primary,
                          fontWeight: 900
                        }, uiLayout.buttonSx)}
                      >
                        {bioSavingId === bio.id
                          ? "جاري الربط..."
                          : "ربط"}
                      </Button>
                    </Stack>
                  </Paper>
                ))}

                {!bioRows.length && (
                  <Alert severity="warning">
                    لا توجد نتائج من BioTime.
                  </Alert>
                )}
              </Stack>
            )}
          </Stack>
        </DialogContent>

        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx}
            onClick={() =>
              setBioDialogOpen(false)
            }
            disabled={Boolean(bioSavingId)}
          >
            إغلاق
          </Button>
        </DialogActions>
      </Dialog>
    </></NavigationShell>
  );
}

