const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL ||
  process.env.REACT_APP_API_URL ||
  "https://api4.sstli.com";




const PAGE_DIRECTION = "rtl";
const PAGE_TEXT_ALIGN = "right";
const DIALOG_DIRECTION = "rtl";

const primary = "#057546";
const primaryDark = "#034d31";
const border = "#dce8e2";
const bg = "#f5f8f6";

const emptyForm = () => ({
  contractNumber: "",
  startDate: "",
  endDate: "",
  basicSalary: "",
  contractType: 1,
  probationDays: "",
  autoRenew: false,
  notes: "",
  editReason: "",
  file: null
});

const getActor = () => {
  try {
    const user = JSON.parse(
      localStorage.getItem("user") || "{}"
    );

    return {
      changedByUserGuid:
        user?.guid ||
        user?.Guid ||
        user?.userGuid ||
        user?.UserGuid ||
        null,
      changedByName:
        user?.fullName ||
        user?.FullName ||
        user?.userName ||
        user?.UserName ||
        "مستخدم النظام"
    };
  } catch {
    return {
      changedByUserGuid: null,
      changedByName: "مستخدم النظام"
    };
  }
};

const formatDate = (value) => {
  if (!value) return "-";
  return new Date(value).toLocaleDateString("ar-SA");
};

const formatMoney = (value) => {
  if (value === null || value === undefined) return "-";

  return Number(value).toLocaleString("ar-SA", {
    maximumFractionDigits: 2
  });
};

const getStatusMeta = (status) => {
  const map = {
    Active: ["ساري", "success"],
    ExpiringSoon: ["ينتهي قريبًا", "warning"],
    Expired: ["منتهي", "error"],
    Upcoming: ["لم يبدأ بعد", "info"],
    Terminated: ["تم إنهاؤه", "default"],
    NoContract: ["بدون عقد", "default"]
  };

  const [label, color] =
    map[status] || ["بدون عقد", "default"];

  return { label, color };
};

const getContractTypeName = (value) => {
  if (Number(value) === 1) return "محدد المدة";
  if (Number(value) === 2) return "غير محدد المدة";
  return "غير محدد";
};

const toDateInputValue = (value) => {
  if (!value) return "";

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
};

const getRemainingText = (row) => {
  if (!row?.contractGuid) return "لا يوجد عقد";
  if (row?.isTerminated) return "تم إنهاء العقد";

  const days = Number(row?.daysToExpiry);

  if (
    row?.daysToExpiry === null ||
    row?.daysToExpiry === undefined ||
    Number.isNaN(days)
  ) {
    return "بدون تاريخ نهاية";
  }

  if (days < 0) {
    return `منتهي منذ ${Math.abs(days)} يوم`;
  }

  if (days === 0) {
    return "ينتهي اليوم";
  }

  return `متبقي ${days} يوم`;
};

export default function HrContractsPage() {
  const isDesktop = useMediaQuery(
    `(min-width:${DESKTOP_BREAKPOINT}px)`,
    { noSsr: true }
  );

  const [mobileSidebarOpen, setMobileSidebarOpen] =
    useState(false);

  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);

  const [stats, setStats] = useState({
    activeContracts: 0,
    expiringWithin7Days: 0,
    expiringWithin30Days: 0,
    expiredContracts: 0,
    withoutContract: 0,
    terminatedContracts: 0
  });

  const [lookups, setLookups] = useState({
    branches: [],
    departments: []
  });

  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("all");
  const [branchGuid, setBranchGuid] = useState("");
  const [departmentGuid, setDepartmentGuid] = useState("");
  const [pageNumber, setPageNumber] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [totalCount, setTotalCount] = useState(0);

  const [contractOpen, setContractOpen] =
    useState(false);
  const [contractMode, setContractMode] =
    useState("create");
  const [selectedEmployee, setSelectedEmployee] =
    useState(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);

  const [historyOpen, setHistoryOpen] =
    useState(false);
  const [historyEmployee, setHistoryEmployee] =
    useState(null);
  const [history, setHistory] = useState([]);
  const [historyLoading, setHistoryLoading] =
    useState(false);


  const [previewOpen, setPreviewOpen] =
    useState(false);
  const [previewRow, setPreviewRow] =
    useState(null);
  const [previewUrl, setPreviewUrl] =
    useState("");
  const [previewLoading, setPreviewLoading] =
    useState(false);
  const [previewError, setPreviewError] =
    useState("");


  const [alertsOpen, setAlertsOpen] =
    useState(false);
  const [alerts, setAlerts] = useState([]);
  const [alertsLoading, setAlertsLoading] =
    useState(false);
  const [alertLevel, setAlertLevel] =
    useState("all");
  const [alertSearch, setAlertSearch] =
    useState("");
  const [notificationCount, setNotificationCount] =
    useState(0);

  const loadLookups = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/employees/lookups`,
        {
          headers: {
            Accept: "application/json"
          },
          cache: "no-store"
        }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) return;

      setLookups({
        branches: Array.isArray(
          result?.data?.branches
        )
          ? result.data.branches
          : [],
        departments: Array.isArray(
          result?.data?.departments
        )
          ? result.data.departments
          : []
      });
    } catch {
      setLookups({
        branches: [],
        departments: []
      });
    }
  }, []);

  const loadStats = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/contracts/stats`,
        { cache: "no-store" }
      );

      const result = await response.json();

      if (response.ok && result?.data) {
        setStats(result.data);
      }
    } catch {
      // لا نوقف الصفحة لو الإحصائيات فقط فشلت.
    }
  }, []);

  const loadRows = useCallback(async () => {
    setLoading(true);

    try {
      const params = new URLSearchParams({
        page: String(pageNumber),
        pageSize: String(pageSize)
      });

      if (search.trim()) {
        params.set("search", search.trim());
      }

      if (status !== "all") {
        params.set("status", status);
      }

      if (branchGuid) {
        params.set("branchGuid", branchGuid);
      }

      if (departmentGuid) {
        params.set(
          "departmentGuid",
          departmentGuid
        );
      }

      const response = await fetch(
        `${API_BASE_URL}/api/hr/contracts?${params.toString()}`,
        { cache: "no-store" }
      );

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result?.message ||
          "تعذر تحميل العقود الوظيفية"
        );
      }

      setRows(
        Array.isArray(result?.data)
          ? result.data
          : []
      );

      setTotalCount(
        Number(result?.totalCount || 0)
      );
    } catch (error) {
      setRows([]);
      setTotalCount(0);

      await Swal.fire({
        icon: "error",
        title: "تعذر التحميل",
        text:
          error?.message ||
          "حدث خطأ أثناء تحميل العقود"
      });
    } finally {
      setLoading(false);
    }
  }, [
    search,
    status,
    branchGuid,
    departmentGuid,
    pageNumber,
    pageSize
  ]);

  useEffect(() => {
    const timer = setTimeout(
      loadRows,
      search.trim() ? 300 : 0
    );

    return () => clearTimeout(timer);
  }, [loadRows, search]);

  useEffect(() => {
    loadStats();
  }, [loadStats]);

  useEffect(() => {
    loadLookups();
  }, [loadLookups]);


  const pageCount = useMemo(
    () =>
      totalCount > 0
        ? Math.ceil(totalCount / pageSize)
        : 0,
    [totalCount, pageSize]
  );

  const openContract = useCallback((row) => {
    setSelectedEmployee(row);
    setContractMode(
      row?.contractGuid ? "renew" : "create"
    );

    setForm({
      ...emptyForm(),
      contractType: row?.contractType || 1,
      probationDays:
        row?.probationDays ?? "",
      autoRenew: Boolean(row?.autoRenew),
      basicSalary:
        row?.basicSalary ?? ""
    });

    setContractOpen(true);
  }, []);

  const openEditContract = useCallback((row) => {
    if (!row?.contractGuid) return;

    setSelectedEmployee(row);
    setContractMode("edit");

    setForm({
      ...emptyForm(),
      contractNumber:
        row?.contractNumber || "",
      startDate: toDateInputValue(row?.startDate),
      endDate: toDateInputValue(row?.endDate),
      basicSalary:
        row?.basicSalary ?? "",
      contractType: row?.contractType || 1,
      probationDays:
        row?.probationDays ?? "",
      autoRenew: Boolean(row?.autoRenew),
      notes: row?.notes || "",
      editReason: "",
      file: null
    });

    setContractOpen(true);
  }, []);

  const saveContract = useCallback(async () => {
    if (!selectedEmployee?.employeeGuid) return;

    const isEdit = contractMode === "edit";

    if (!isEdit && !form.file) {
      await Swal.fire({
        icon: "warning",
        title: "ملف العقد مطلوب",
        text: "اختر ملف العقد قبل الحفظ"
      });
      return;
    }

    if (isEdit && !form.editReason.trim()) {
      await Swal.fire({
        icon: "warning",
        title: "سبب التعديل مطلوب",
        text: "اكتب سبب تعديل بيانات العقد الحالي"
      });
      return;
    }

    if (
      form.startDate &&
      form.endDate &&
      new Date(form.endDate) <
        new Date(form.startDate)
    ) {
      await Swal.fire({
        icon: "warning",
        title: "راجع التواريخ",
        text:
          "تاريخ نهاية العقد يجب أن يكون بعد تاريخ البداية"
      });
      return;
    }

    setSaving(true);

    try {
      const actor = getActor();
      const data = new FormData();

      if (form.file) {
        data.append("file", form.file);
      }

      data.append(
        "contractNumber",
        form.contractNumber.trim()
      );

      if (form.startDate) {
        data.append("startDate", form.startDate);
      }

      if (
        Number(form.contractType) === 1 &&
        form.endDate
      ) {
        data.append("endDate", form.endDate);
      }

      if (form.basicSalary !== "") {
        data.append(
          "basicSalary",
          String(form.basicSalary)
        );
      }

      data.append(
        "contractType",
        String(form.contractType)
      );

      if (form.probationDays !== "") {
        data.append(
          "probationDays",
          String(form.probationDays)
        );
      }

      data.append(
        "autoRenew",
        String(form.autoRenew)
      );

      data.append(
        "notes",
        form.notes.trim()
      );

      if (isEdit) {
        data.append(
          "editReason",
          form.editReason.trim()
        );
      }

      if (actor.changedByUserGuid) {
        data.append(
          "changedByUserGuid",
          actor.changedByUserGuid
        );
      }

      data.append(
        "changedByName",
        actor.changedByName
      );

      const url = isEdit
        ? `${API_BASE_URL}/api/hr/contracts/${encodeURIComponent(
            selectedEmployee.contractGuid
          )}`
        : `${API_BASE_URL}/api/hr/contracts/employee/${encodeURIComponent(
            selectedEmployee.employeeGuid
          )}`;

      const response = await fetch(url, {
        method: isEdit ? "PUT" : "POST",
        body: data
      });

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            (isEdit
              ? "تعذر تعديل العقد"
              : "تعذر حفظ العقد")
        );
      }

      setContractOpen(false);

      await Swal.fire({
        icon: "success",
        title: isEdit
          ? "تم تعديل العقد"
          : contractMode === "renew"
            ? "تم تجديد العقد"
            : "تم إنشاء العقد",
        text: result?.message || "تم الحفظ"
      });

      await Promise.all([
        loadRows(),
        loadStats()
      ]);
    } catch (error) {
      await Swal.fire({
        icon: "error",
        title: "تعذر الحفظ",
        text:
          error?.message ||
          "حدث خطأ أثناء حفظ العقد"
      });
    } finally {
      setSaving(false);
    }
  }, [
    selectedEmployee,
    contractMode,
    form,
    loadRows,
    loadStats
  ]);

  const terminate = useCallback(
    async (row) => {
      if (!row?.contractGuid) return;

      const prompt = await Swal.fire({
        title: "إنهاء العقد الوظيفي",
        input: "textarea",
        inputPlaceholder:
          "اكتب سبب إنهاء العقد...",
        showCancelButton: true,
        confirmButtonText: "إنهاء العقد",
        cancelButtonText: "رجوع",
        confirmButtonColor: "#ae1e21",
        inputValidator: (value) =>
          !String(value || "").trim()
            ? "سبب الإنهاء مطلوب"
            : undefined
      });

      if (!prompt.isConfirmed) return;

      try {
        const response = await fetch(
          `${API_BASE_URL}/api/hr/contracts/${encodeURIComponent(
            row.contractGuid
          )}/terminate`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json"
            },
            body: JSON.stringify({
              terminationReason:
                String(prompt.value).trim(),
              terminatedAt:
                new Date().toISOString(),
              ...getActor()
            })
          }
        );

        const result = await response.json();

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر إنهاء العقد"
          );
        }

        await Promise.all([
          loadRows(),
          loadStats()
        ]);
      } catch (error) {
        await Swal.fire({
          icon: "error",
          title: "تعذر الإنهاء",
          text:
            error?.message ||
            "حدث خطأ أثناء إنهاء العقد"
        });
      }
    },
    [loadRows, loadStats]
  );

  const openHistory = useCallback(async (row) => {
    setHistoryEmployee(row);
    setHistory([]);
    setHistoryOpen(true);
    setHistoryLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/contracts/employee/${encodeURIComponent(
          row.employeeGuid
        )}/history`,
        { cache: "no-store" }
      );

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result?.message ||
          "تعذر تحميل سجل العقود"
        );
      }

      setHistory(
        Array.isArray(result?.data)
          ? result.data
          : []
      );
    } finally {
      setHistoryLoading(false);
    }
  }, []);


  const loadAutomaticContractNotifications =
    useCallback(async () => {
      try {
        const response = await fetch(
          `${API_BASE_URL}/api/hr/contracts/alerts`,
          { cache: "no-store" }
        );

        const result = await response
          .json()
          .catch(() => null);

        if (!response.ok) return;

        const items = Array.isArray(result?.data)
          ? result.data
          : [];

        setNotificationCount(items.length);

        const expired = items.filter(
          (item) => item?.alertLevel === "Expired"
        ).length;

        const critical = items.filter(
          (item) => item?.alertLevel === "Critical"
        ).length;

        const warning = items.filter(
          (item) => item?.alertLevel === "Warning"
        ).length;

        if (!items.length) return;

        const todayKey =
          new Date().toISOString().slice(0, 10);
        const storageKey =
          "hr_contract_alerts_last_seen";
        const lastSeen =
          sessionStorage.getItem(storageKey);

        if (lastSeen !== todayKey) {
          sessionStorage.setItem(
            storageKey,
            todayKey
          );

          await Swal.fire({
            icon:
              expired > 0 || critical > 0
                ? "warning"
                : "info",
            title: "تنبيهات العقود",
            html: `
              <div style="text-align:right;line-height:1.9">
                ${expired ? `<div><b>${expired}</b> عقد منتهي</div>` : ""}
                ${critical ? `<div><b>${critical}</b> عقد ينتهي خلال 7 أيام</div>` : ""}
                ${warning ? `<div><b>${warning}</b> عقد ينتهي خلال 8 إلى 30 يوم</div>` : ""}
              </div>
            `,
            confirmButtonText:
              "عرض تنبيهات العقود",
            showCancelButton: true,
            cancelButtonText: "لاحقًا"
          }).then((result) => {
            if (result.isConfirmed) {
              setAlertLevel("all");
              setAlertSearch("");
              setAlertsOpen(true);
            }
          });
        }

        if (
          typeof window !== "undefined" &&
          "Notification" in window &&
          window.Notification.permission ===
            "granted"
        ) {
          const browserKey =
            `hr_contract_browser_alert_${todayKey}`;

          if (
            localStorage.getItem(browserKey) !==
            "1"
          ) {
            localStorage.setItem(
              browserKey,
              "1"
            );

            new window.Notification(
              "تنبيهات العقود الوظيفية",
              {
                body: `لديك ${items.length} عقد يحتاج متابعة.`,
                tag: "hr-contract-alerts"
              }
            );
          }
        }
      } catch {
        // التنبيهات لا توقف الصفحة لو حصل خطأ.
      }
    }, []);

  const enableBrowserNotifications =
    useCallback(async () => {
      if (!("Notification" in window)) {
        await Swal.fire({
          icon: "info",
          title: "غير مدعوم",
          text:
            "المتصفح الحالي لا يدعم إشعارات سطح المكتب."
        });
        return;
      }

      const permission =
        await window.Notification.requestPermission();

      if (permission === "granted") {
        await Swal.fire({
          icon: "success",
          title: "تم تفعيل الإشعارات",
          text:
            "ستظهر لك تنبيهات العقود عند فتح النظام طالما الإذن مفعل."
        });

        await loadAutomaticContractNotifications();
      } else {
        await Swal.fire({
          icon: "info",
          title: "لم يتم التفعيل",
          text:
            "يمكنك السماح بالإشعارات لاحقًا من إعدادات المتصفح."
        });
      }
    }, [loadAutomaticContractNotifications]);

  useEffect(() => {
    loadAutomaticContractNotifications();
  }, [loadAutomaticContractNotifications]);

  const loadAlerts = useCallback(async () => {
    setAlertsLoading(true);

    try {
      const params = new URLSearchParams();

      if (alertSearch.trim()) {
        params.set(
          "search",
          alertSearch.trim()
        );
      }

      if (branchGuid) {
        params.set("branchGuid", branchGuid);
      }

      if (departmentGuid) {
        params.set(
          "departmentGuid",
          departmentGuid
        );
      }

      if (alertLevel !== "all") {
        params.set(
          "alertLevel",
          alertLevel
        );
      }

      const query = params.toString();

      const response = await fetch(
        `${API_BASE_URL}/api/hr/contracts/alerts${
          query ? `?${query}` : ""
        }`,
        { cache: "no-store" }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر تحميل تنبيهات العقود"
        );
      }

      setAlerts(
        Array.isArray(result?.data)
          ? result.data
          : []
      );
    } catch (error) {
      setAlerts([]);

      await Swal.fire({
        icon: "error",
        title: "تعذر تحميل التنبيهات",
        text:
          error?.message ||
