                }}
              >
                تنبيهات العقود
              </Typography>

              <Typography
                color="text.secondary"
                sx={{
                  mt: 0.2,
                  fontSize: 12
                }}
              >
                العقود المنتهية أو التي تنتهي خلال 30 يومًا
              </Typography>
            </Box>

            <IconButton
              onClick={() =>
                setAlertsOpen(false)
              }
            >
              <CloseRoundedIcon />
            </IconButton>
          </Stack>
        </DialogTitle>

        <DialogContent dividers>
          <Box
            sx={uiLayout.withUiSx({
              display: "grid",
              gridTemplateColumns: {
                xs: "1fr",
                sm: "minmax(240px,1fr) 190px"
              },
              gap: 1,
              mb: 1.2
            }, uiLayout.formGridSx)}
          >
            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              size="small"
              value={alertSearch}
              onChange={(e) =>
                setAlertSearch(
                  e.target.value
                )
              }
              placeholder="بحث باسم الموظف أو رقم العقد..."
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchRoundedIcon />
                  </InputAdornment>
                )
              }}
            />

            <FormControl sx={uiLayout.formFieldSx} size="small">
              <Select
                  MenuProps={RTL_MENU_PROPS}
                value={alertLevel}
                onChange={(e) =>
                  setAlertLevel(
                    e.target.value
                  )
                }
              >
                <MenuItem value="all">
                  كل التنبيهات
                </MenuItem>
                <MenuItem value="Expired">
                  عقود منتهية
                </MenuItem>
                <MenuItem value="Critical">
                  عاجل - 7 أيام
                </MenuItem>
                <MenuItem value="Warning">
                  تنبيه - 8 إلى 30 يوم
                </MenuItem>
              </Select>
            </FormControl>
          </Box>

          <Box
            sx={{
              mb: 1.2,
              display: "flex",
              justifyContent: "flex-end"
            }}
          >
            <Button
              size="small"
              variant="text"
              startIcon={
                <NotificationsActiveRoundedIcon />
              }
              onClick={enableBrowserNotifications}
              sx={uiLayout.withUiSx({ fontWeight: 850 }, uiLayout.buttonSx)}
            >
              تفعيل إشعارات المتصفح
            </Button>
          </Box>

          {alertsLoading ? (
            <Box
              sx={{
                py: 7,
                display: "grid",
                placeItems: "center"
              }}
            >
              <CircularProgress />
            </Box>
          ) : (
            <Stack spacing={0.8}>
              {alerts.map((item) => {
                const expired =
                  item.alertLevel ===
                  "Expired";

                const critical =
                  item.alertLevel ===
                  "Critical";

                return (
                  <Paper
                    key={item.contractGuid}
                    elevation={0}
                    sx={{
                      p: 1.1,
                      borderRadius: 2.3,
                      border:
                        expired ||
                        critical
                          ? "1px solid #efaaaa"
                          : "1px solid #f0cf8c",
                      bgcolor:
                        expired ||
                        critical
                          ? "#fff6f6"
                          : "#fffaf1"
                    }}
                  >
                    <Box
                      sx={{
                        display: "grid",
                        gridTemplateColumns: {
                          xs: "1fr",
                          md:
                            "minmax(220px,1.4fr) minmax(180px,1fr) 140px 130px auto"
                        },
                        gap: 1,
                        alignItems: "center"
                      }}
                    >
                      <Box>
                        <Typography
                          fontWeight={950}
                        >
                          {item.employeeName}
                        </Typography>

                        <Typography
                          color="text.secondary"
                          sx={{
                            mt: 0.2,
                            fontSize: 12
                          }}
                        >
                          #{item.employeeCode ||
                            "-"}
                          {" • "}
                          {item.jobTitle ||
                            "غير محدد"}
                          {" • "}
                          {item.departmentName ||
                            "غير محدد"}
                        </Typography>
                      </Box>

                      <Box>
                        <Typography
                          color="text.secondary"
                          sx={{ fontSize: 12 }}
                        >
                          العقد / الفرع
                        </Typography>

                        <Typography
                          fontWeight={850}
                          sx={{ fontSize: 12 }}
                        >
                          {item.contractNumber ||
                            "بدون رقم"}
                        </Typography>

                        <Typography
                          color="text.secondary"
                          sx={{ fontSize: 12 }}
                        >
                          {item.branchName ||
                            "غير محدد"}
                        </Typography>
                      </Box>

                      <Box>
                        <Typography
                          color="text.secondary"
                          sx={{ fontSize: 12 }}
                        >
                          تاريخ الانتهاء
                        </Typography>

                        <Typography
                          fontWeight={850}
                          sx={{ fontSize: 12 }}
                        >
                          {formatDate(
                            item.endDate
                          )}
                        </Typography>
                      </Box>

                      <Chip
                        size="small"
                        color={
                          expired ||
                          critical
                            ? "error"
                            : "warning"
                        }
                        label={
                          expired
                            ? `منتهي منذ ${Math.abs(
                                Number(
                                  item.daysToExpiry ||
                                    0
                                )
                              )} يوم`
                            : critical
                              ? `عاجل - متبقي ${Number(
                                  item.daysToExpiry ||
                                    0
                                )} يوم`
                              : `متبقي ${Number(
                                  item.daysToExpiry ||
                                    0
                                )} يوم`
                        }
                        sx={{
                          fontWeight: 900
                        }}
                      />

                      <Stack
                        direction="row"
                        spacing={0.4}
                        justifyContent="flex-end"
                      >
                        <Button
                          size="small"
                          variant="contained"
                          startIcon={
                            <UpdateRoundedIcon />
                          }
                          onClick={() => {
                            setAlertsOpen(
                              false
                            );
                            openContract(
                              item
                            );
                          }}
                          sx={uiLayout.withUiSx({
                            bgcolor: primary,
                            fontWeight: 900,
                            whiteSpace:
                              "nowrap",
                            "&:hover": {
                              bgcolor:
                                primaryDark
                            }
                          }, uiLayout.buttonSx)}
                        >
                          تجديد
                        </Button>

                        <Tooltip title="تعديل بيانات العقد">
                          <IconButton
                            size="small"
                            onClick={() => {
                              setAlertsOpen(false);
                              openEditContract(item);
                            }}
                          >
                            <EditRoundedIcon />
                          </IconButton>
                        </Tooltip>

                        <Tooltip title="معاينة العقد">
                          <IconButton
                            size="small"
                            onClick={() =>
                              previewContract(
                                item
                              )
                            }
                          >
                            <VisibilityRoundedIcon />
                          </IconButton>
                        </Tooltip>
                      </Stack>
                    </Box>
                  </Paper>
                );
              })}

              {!alerts.length && (
                <Alert severity="success">
                  لا توجد عقود تحتاج إجراء ضمن الفلاتر الحالية.
                </Alert>
              )}
            </Stack>
          )}
        </DialogContent>
      </Dialog>

      <Dialog
        sx={uiLayout.withUiSx(RTL_DIALOG_SX, uiLayout.dialogLayoutSx)}
        open={previewOpen}
        onClose={closePreview}
        fullWidth
        maxWidth="lg"
        dir={DIALOG_DIRECTION}
        PaperProps={{
          sx: {
            height: {
              xs: "92vh",
              md: "88vh"
            },
            borderRadius: 3,
            overflow: "hidden"
          }
        }}
      >
        <DialogTitle
          sx={{
            py: 1.1,
            px: 1.5,
            borderBottom: `1px solid ${border}`
          }}
        >
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            spacing={1}
          >
            <Box sx={{ minWidth: 0 }}>
              <Typography
                sx={{
                  fontWeight: 950,
                  fontSize: 16
                }}
              >
                معاينة العقد الوظيفي
              </Typography>

              <Typography
                color="text.secondary"
                sx={{
                  mt: 0.15,
                  fontSize: 12,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis"
                }}
              >
                {previewRow?.employeeName || ""}
                {previewRow?.contractNumber
                  ? ` • عقد رقم ${previewRow.contractNumber}`
                  : ""}
              </Typography>
            </Box>

            <Stack
              direction="row"
              spacing={0.5}
            >
              {previewRow?.contractGuid && (
                <Button sx={uiLayout.buttonSx}
                  size="small"
                  variant="outlined"
                  startIcon={
                    <DownloadRoundedIcon />
                  }
                  onClick={() =>
                    openFile(
                      previewRow.contractGuid
                    )
                  }
                >
                  فتح / تحميل
                </Button>
              )}

              <IconButton
                onClick={closePreview}
              >
                <CloseRoundedIcon />
              </IconButton>
            </Stack>
          </Stack>
        </DialogTitle>

        <DialogContent
          sx={{
            p: 0,
            bgcolor: "#edf3f0",
            display: "flex",
            minHeight: 0
          }}
        >
          {previewLoading ? (
            <Box
              sx={{
                width: "100%",
                display: "grid",
                placeItems: "center"
              }}
            >
              <Box sx={{ textAlign: "center" }}>
                <CircularProgress />
                <Typography
                  sx={{
                    mt: 1,
                    fontWeight: 800,
                    fontSize: 12
                  }}
                >
                  جاري تجهيز المعاينة...
                </Typography>
              </Box>
            </Box>
          ) : previewError ? (
            <Box
              sx={{
                width: "100%",
                display: "grid",
                placeItems: "center",
                p: 3
              }}
            >
              <Box
                sx={{
                  maxWidth: 520,
                  textAlign: "center"
                }}
              >
                <DescriptionRoundedIcon
                  sx={{
                    fontSize: 64,
                    color: "#98ada2"
                  }}
                />

                <Typography
                  sx={{
                    mt: 0.8,
                    fontWeight: 950
                  }}
                >
                  المعاينة غير متاحة
                </Typography>

                <Typography
                  color="text.secondary"
                  sx={{
                    mt: 0.5,
                    fontSize: 12,
                    lineHeight: 1.8
                  }}
                >
                  {previewError}
                </Typography>
              </Box>
            </Box>
          ) : previewUrl ? (
            String(
              previewRow?.originalFileName || ""
            )
              .toLowerCase()
              .match(/\.(jpg|jpeg|png|webp)$/) ? (
              <Box
                component="img"
                src={previewUrl}
                alt="معاينة العقد"
                onError={() =>
                  setPreviewError(
                    "تعذر عرض صورة العقد داخل الصفحة."
                  )
                }
                sx={{
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                  bgcolor: "#1d2421"
                }}
              />
            ) : (
              <Box
                component="iframe"
                title="معاينة العقد الوظيفي"
                src={previewUrl}
                onLoad={() =>
                  setPreviewLoading(false)
                }
                sx={{
                  width: "100%",
                  height: "100%",
                  minHeight: "72vh",
                  border: 0,
                  bgcolor: "#fff"
                }}
              />
            )
          ) : null}
        </DialogContent>
      </Dialog>

      <Dialog
        sx={uiLayout.withUiSx(RTL_DIALOG_SX, uiLayout.dialogLayoutSx)}
        open={contractOpen}
        onClose={() => {
          if (!saving) {
            setContractOpen(false);
          }
        }}
        fullWidth
        maxWidth="md"
        dir={DIALOG_DIRECTION}
      >
        <DialogTitle sx={{ fontWeight: 950 }}>
          {contractMode === "edit"
            ? "تعديل بيانات العقد الحالي"
            : contractMode === "renew"
              ? "تجديد العقد الوظيفي"
              : "إضافة عقد وظيفي"}
        </DialogTitle>

        <DialogContent dividers>
          <Stack sx={uiLayout.filterBarSx} spacing={1.2}>
            <Paper
              variant="outlined"
              sx={{
                p: 1,
                borderRadius: 2,
                borderColor: border
              }}
            >
              <Typography fontWeight={950}>
                {selectedEmployee?.employeeName ||
                  "-"}
              </Typography>

              <Typography
                color="text.secondary"
                sx={{ fontSize: 12 }}
              >
                {selectedEmployee?.jobTitle ||
                  "غير محدد"}
                {" • "}
                {selectedEmployee?.branchName ||
                  "غير محدد"}
              </Typography>
            </Paper>

            <Box
              sx={uiLayout.withUiSx({
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  sm: "repeat(2,minmax(0,1fr))"
                },
                gap: 1
              }, uiLayout.formGridSx)}
            >
              <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }} inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }}
                label="رقم العقد"
                value={form.contractNumber}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    contractNumber:
                      e.target.value
                  }))
                }
              />

              <FormControl sx={uiLayout.formFieldSx}>
                <InputLabel>نوع العقد</InputLabel>
                <Select
                  MenuProps={RTL_MENU_PROPS}
                  label="نوع العقد"
                  value={form.contractType}
                  onChange={(e) =>
                    setForm((x) => ({
                      ...x,
                      contractType:
                        Number(e.target.value)
                    }))
                  }
                >
                  <MenuItem value={1}>
                    محدد المدة
                  </MenuItem>
                  <MenuItem value={2}>
                    غير محدد المدة
                  </MenuItem>
                </Select>
              </FormControl>

              <TextField sx={uiLayout.formFieldSx}
                type="date"
                label="تاريخ بداية العقد"
                value={form.startDate}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    startDate: e.target.value
                  }))
                }
                InputLabelProps={{
                  shrink: true
                }}
               inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />

              <TextField sx={uiLayout.formFieldSx}
                type="date"
                label="تاريخ نهاية العقد"
                value={form.endDate}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    endDate: e.target.value
                  }))
                }
                InputLabelProps={{
                  shrink: true
                }}
                disabled={
                  Number(form.contractType) === 2
                }
               inputProps={{ dir: "ltr", style: { direction: "ltr", unicodeBidi: "isolate" } }} />

              <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                type="number"
                label="الراتب الأساسي"
                value={form.basicSalary}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    basicSalary:
                      e.target.value
                  }))
                }
                inputProps={{ min: 0 , dir: "ltr" , style: { direction: "ltr", unicodeBidi: "isolate" } }}
              />

              <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                type="number"
                label="فترة التجربة - يوم"
                value={form.probationDays}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    probationDays:
                      e.target.value
                  }))
                }
                inputProps={{
                  min: 0,
                  max: 365
                , dir: "ltr" , style: { direction: "ltr", unicodeBidi: "isolate" } }}
              />
            </Box>

            <FormControlLabel sx={uiLayout.checkboxFieldSx}
              control={
                <Checkbox
                  checked={form.autoRenew}
                  onChange={(e) =>
                    setForm((x) => ({
                      ...x,
                      autoRenew:
                        e.target.checked
                    }))
                  }
                />
              }
              label="تجديد تلقائي"
            />

            <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
              label="ملاحظات"
              value={form.notes}
              onChange={(e) =>
                setForm((x) => ({
                  ...x,
                  notes: e.target.value
                }))
              }
              multiline
              minRows={2}
            />

            {contractMode === "edit" && (
              <TextField sx={uiLayout.formFieldSx} InputLabelProps={{ shrink: true }}
                label="سبب التعديل"
                value={form.editReason}
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    editReason: e.target.value
                  }))
                }
                placeholder="مثال: تصحيح تاريخ نهاية العقد أو الراتب"
                multiline
                minRows={2}
                required
              />
            )}

            <Button
              component="label"
              variant="outlined"
              startIcon={
                <ArticleOutlinedIcon />
              }
              sx={uiLayout.withUiSx({
                            fontWeight: 850
              }, uiLayout.buttonSx)}
            >
              {form.file
                ? form.file.name
                : contractMode === "edit"
                  ? "استبدال ملف العقد - اختياري"
                  : "اختر ملف العقد"}

              <input
                hidden
                type="file"
                accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx"
                onChange={(e) =>
                  setForm((x) => ({
                    ...x,
                    file:
                      e.target.files?.[0] ||
                      null
                  }))
                }
              />
            </Button>
          </Stack>
        </DialogContent>

        <DialogActions sx={uiLayout.dialogActionsSx}>
          <Button sx={uiLayout.buttonSx}
            onClick={() =>
              setContractOpen(false)
            }
            disabled={saving}
          >
            إلغاء
          </Button>

          <Button
            variant="contained"
            onClick={saveContract}
            disabled={saving}
            sx={uiLayout.withUiSx({
              bgcolor: primary,
              "&:hover": {
                bgcolor: primaryDark
              }
            }, uiLayout.buttonSx)}
          >
            {saving
              ? "جاري الحفظ..."
              : contractMode === "edit"
                ? "حفظ التعديلات"
                : contractMode === "renew"
                  ? "تجديد العقد"
                  : "حفظ العقد"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        sx={uiLayout.withUiSx(RTL_DIALOG_SX, uiLayout.dialogLayoutSx)}
        open={historyOpen}
        onClose={() => setHistoryOpen(false)}
        fullWidth
        maxWidth="md"
        dir={DIALOG_DIRECTION}
      >
        <DialogTitle>
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
          >
            <Box>
              <Typography fontWeight={950}>
                سجل العقود
              </Typography>

              <Typography
                color="text.secondary"
                sx={{ fontSize: 12 }}
              >
                {historyEmployee?.employeeName ||
                  ""}
              </Typography>
            </Box>

            <IconButton
              onClick={() =>
                setHistoryOpen(false)
              }
            >
              <CloseRoundedIcon />
            </IconButton>
          </Stack>
        </DialogTitle>

        <DialogContent dividers>
          {historyLoading ? (
            <Box
              sx={{
                py: 5,
                display: "grid",
                placeItems: "center"
              }}
            >
              <CircularProgress />
            </Box>
          ) : (
            <Stack spacing={0.8}>
              {history.map((item) => (
                <Paper
                  key={item.contractGuid}
                  variant="outlined"
                  sx={{
                    p: 1,
                    borderRadius: 2,
                    borderColor: border
                  }}
                >
                  <Stack
                    direction={{
                      xs: "column",
                      sm: "row"
                    }}
                    justifyContent="space-between"
                    spacing={1}
                    alignItems={{
                      xs: "stretch",
                      sm: "center"
                    }}
                  >
                    <Box>
                      <Typography fontWeight={900}>
                        {item.contractNumber ||
                          "بدون رقم"}
                      </Typography>

                      <Typography
                        color="text.secondary"
                        sx={{ fontSize: 12 }}
                      >
                        {item.isCurrent
                          ? "العقد الحالي"
                          : "عقد سابق"}
                        {" • "}
                        {formatDate(item.startDate)}
                        {" ← "}
                        {formatDate(item.endDate)}
                      </Typography>
                    </Box>

                    <Stack
                      direction="row"
                      spacing={0.4}
                      alignItems="center"
                    >
                      {item.isTerminated && (
                        <Chip
                          size="small"
                          label="تم إنهاؤه"
                        />
                      )}

                      <Typography fontWeight={900}>
                        {formatMoney(
                          item.basicSalary
                        )}
                      </Typography>

                      <IconButton
                        size="small"
                        onClick={() =>
                          openFile(
                            item.contractGuid
                          )
                        }
                      >
                        <DownloadRoundedIcon />
                      </IconButton>
                    </Stack>
                  </Stack>

                  {item.terminationReason && (
                    <Typography
                      color="error"
                      sx={{
                        mt: 0.6,
                        fontSize: 12
                      }}
                    >
                      سبب الإنهاء:{" "}
                      {item.terminationReason}
                    </Typography>
                  )}
                </Paper>
              ))}

              {!history.length && (
                <Alert severity="info">
                  لا يوجد سجل عقود لهذا الموظف.
                </Alert>
              )}
            </Stack>
          )}
        </DialogContent>
      </Dialog>
    </></NavigationShell>
  );
}

