                              {employee?.fullName || "بدون اسم"}
                            </Typography>
                            <Typography sx={{ fontFamily: "Cairo", fontSize: "0.75rem", color: "#728078" }}>
                              {employee?.jobTitle || "غير محدد"}
                            </Typography>
                          </Box>

                          <Chip
                            size="small"
                            label={employee?.isActive ? "نشط" : "غير نشط"}
                            color={employee?.isActive ? "success" : "default"}
                          />
                        </Stack>
                      </Paper>
                    );
                  })}
                </Box>
              )}
            </Stack>
          )}
        </DialogContent>
