          </Alert>
        </DialogContent>
        <DialogActions sx={uiLayout.withUiSx({ direction: DIALOG_DIRECTION }, uiLayout.dialogActionsSx)}>
          <Button
            onClick={() => setTransferConfirmOpen(false)}
