          </Button>
        </Box>
      </Paper>

      <Paper
        elevation={0}
        sx={{
          p: { xs: 0.65, sm: 0.85, md: 1 },
          mb: { xs: 0.85, sm: 1, md: 1.25 },
          borderRadius: 2.7,
          border: `1px solid ${border}`,
          background: "rgba(255,255,255,.86)"
        }}
      >
        <Box
          sx={uiLayout.withUiSx({
            display: "grid",
            gridTemplateColumns: {
              xs: "repeat(2,minmax(0,1fr))",
              sm: "repeat(5,minmax(0,auto))"
            },
            gap: { xs: 0.45, sm: 0.7 },
            "& .MuiButton-root": {
              minHeight: { xs: 32, sm: 35 },
              px: { xs: 0.55, sm: 0.9 },
