            مرفقاتي ({documents?.count || 0})
          </Button>
        </Box>
      </Paper>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "repeat(2,minmax(0,1fr))",
            md: "repeat(4,minmax(0,1fr))"
          },
          gap: { xs: 0.55, sm: 0.8, md: 1 },
          mb: { xs: 0.9, sm: 1.1, md: 1.4 }
