const EmployeeAvatar = ({
  employee,
  size = 40,
  ring = false
}) => {
  const [imageUrl, setImageUrl] =
    useState(null);
  const [directUrl, setDirectUrl] =
    useState(null);
  const [imageFailed, setImageFailed] =
    useState(false);
  const [imageLoading, setImageLoading] =
    useState(true);

  const employeeGuid = String(
    employee?.employeeGuid ||
    employee?.EmployeeGuid ||
    employee?.guid ||
    employee?.Guid ||
    ""
  ).trim();

  const displayName =
    employee?.fullName ||
    employee?.FullName ||
    "موظف";

  useEffect(() => {
    let mounted = true;
    let objectUrl = null;

    setImageUrl(null);
    setDirectUrl(null);
    setImageFailed(false);
    setImageLoading(Boolean(employeeGuid));

    if (!employeeGuid) {
      setImageLoading(false);
      return () => {};
    }

    const loadImage = async () => {
      const timestamp = Date.now();

      const url =
        `${EMPLOYEE_IMAGE_API}?action=get&userGuid=${encodeURIComponent(employeeGuid)}&t=${timestamp}`;

      try {
        const response = await fetch(
          url,
          {
            method: "GET",
            cache: "no-store"
          }
        );

        if (!response.ok) {
          throw new Error(
            `Image HTTP ${response.status}`
          );
        }

        const blob =
          await response.blob();

        if (!blob || blob.size <= 0) {
          throw new Error(
            "Empty image"
          );
        }

        objectUrl =
          URL.createObjectURL(blob);

        if (mounted) {
          setImageUrl(objectUrl);
          setDirectUrl(null);
        }
      } catch {
        if (mounted) {
          setDirectUrl(url);
        }
      }
    };

    loadImage();

    return () => {
      mounted = false;

      if (objectUrl) {
        URL.revokeObjectURL(
          objectUrl
        );
      }
    };
  }, [employeeGuid]);

  const firstLetter =
    String(displayName)
      .trim()
      .charAt(0) || "م";

  const src =
    imageUrl ||
    (!imageFailed
      ? directUrl
      : undefined);

  return (
    <Box
      sx={{
        width: size,
        height: size,
        minWidth: size,
        position: "relative",
        borderRadius: "50%",
        p: ring ? "3px" : 0,
        background: ring
          ? "rgba(255,255,255,.25)"
          : "transparent",
        border: ring
          ? "1px solid rgba(255,255,255,.35)"
          : "none",
        display: "grid",
        placeItems: "center"
      }}
    >
      <Avatar
        key={`${employeeGuid}-${src || "fallback"}`}
        src={src || undefined}
        alt={displayName}
        imgProps={{
          onLoad: () => {
            setImageLoading(false);
          },
          onError: () => {
            if (
              imageUrl &&
              !directUrl
            ) {
              setImageUrl(null);
              setDirectUrl(
                `${EMPLOYEE_IMAGE_API}?action=get&userGuid=${encodeURIComponent(employeeGuid)}&t=${Date.now()}`
              );
              setImageLoading(true);
            } else {
              setImageFailed(true);
              setDirectUrl(null);
              setImageUrl(null);
              setImageLoading(false);
            }
          }
        }}
        sx={{
          width: ring
            ? size - 6
            : size,
          height: ring
            ? size - 6
            : size,
          bgcolor: "#e6f3ee",
          color: primaryColor,
          fontFamily: "Cairo",
          fontWeight: 900,
          fontSize:
            `${Math.max(
              14,
              size * .38
            )}px`,
          border: ring
            ? "2px solid rgba(255,255,255,.88)"
            : "1px solid rgba(5,117,70,.10)",
          overflow: "hidden",
          opacity:
            imageLoading && src
              ? .35
              : 1,
          transition:
            "opacity .25s ease, transform .25s ease",
          "& img": {
            width: "100%",
            height: "100%",
            objectFit: "cover"
          }
        }}
      >
        {!src && !imageLoading
          ? firstLetter
          : null}
      </Avatar>

      {imageLoading && (
        <Box
          sx={{
            position: "absolute",
            inset: ring
              ? 3
              : 0,
            borderRadius: "50%",
            display: "grid",
            placeItems: "center",
            bgcolor:
              "rgba(255,255,255,.68)",
            backdropFilter:
              "blur(2px)"
          }}
        >
          <CircularProgress
            size={Math.max(
              15,
              size * .32
            )}
            thickness={4.5}
            sx={{
              color: primaryColor
            }}
          />
        </Box>
      )}
    </Box>
  );
};

