export default function HrJobTitlesPage() {
  const isDesktop = useMediaQuery(
    `(min-width:${DESKTOP_BREAKPOINT}px)`,
    { noSsr: true }
  );

  const userGuid = useMemo(() => getUserGuid(), []);

  const [mobileSidebarOpen, setMobileSidebarOpen] =
    useState(false);

  const [permissionLoading, setPermissionLoading] =
    useState(true);
  const [authorized, setAuthorized] = useState(false);

  const [loading, setLoading] = useState(false);
  const [rows, setRows] = useState([]);
  const [departments, setDepartments] = useState([]);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState("all");

  const [editOpen, setEditOpen] = useState(false);
  const [editMode, setEditMode] = useState("create");
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);

  const [employeesOpen, setEmployeesOpen] =
    useState(false);
  const [employeesTitle, setEmployeesTitle] =
    useState(null);
  const [employees, setEmployees] = useState([]);
  const [employeeSearch, setEmployeeSearch] =
    useState("");
  const [employeePage, setEmployeePage] =
    useState(1);
  const [employeePageSize, setEmployeePageSize] =
    useState(20);
  const [employeeTotal, setEmployeeTotal] =
    useState(0);
  const [employeeLoading, setEmployeeLoading] =
    useState(false);

  const [jobMoveOpen, setJobMoveOpen] =
    useState(false);
  const [jobMoveEmployee, setJobMoveEmployee] =
    useState(null);
  const [jobMoveMode, setJobMoveMode] =
    useState("transfer");
  const [jobMoveTargetGuid, setJobMoveTargetGuid] =
    useState("");
  const [jobMoveDate, setJobMoveDate] =
    useState(() => new Date().toISOString().slice(0, 10));
  const [jobMoveReason, setJobMoveReason] =
    useState("");
  const [jobMoveNotes, setJobMoveNotes] =
    useState("");
  const [jobMoveSaving, setJobMoveSaving] =
    useState(false);

  const [promotionPlansOpen, setPromotionPlansOpen] =
    useState(false);
  const [promotionPlans, setPromotionPlans] =
    useState([]);
  const [promotionPlansLoading, setPromotionPlansLoading] =
    useState(false);
  const [promotionPlansStatus, setPromotionPlansStatus] =
    useState("Pending");
  const [promotionPlansSearch, setPromotionPlansSearch] =
    useState("");

  const [historyOpen, setHistoryOpen] =
    useState(false);
  const [historyTitle, setHistoryTitle] =
    useState(null);
  const [historyRows, setHistoryRows] = useState([]);
  const [historyLoading, setHistoryLoading] =
    useState(false);

  // ============================================================
  // Permission
  // ============================================================
  useEffect(() => {
    let alive = true;

    (async () => {
      try {
        if (!userGuid) {
          if (alive) {
            setAuthorized(false);
          }
          return;
        }

        const response = await fetch(
          `${API_BASE_URL}/api/user-permissions/${encodeURIComponent(
            userGuid
          )}`,
          { cache: "no-store" }
        );

        const result = await response
          .json()
          .catch(() => null);

        const data = result?.data || {};

        const direct =
          data?.humanResources?.canView === true &&
          data?.humanResources?.screens?.jobTitles ===
            true;

        const hasForm =
          Array.isArray(data?.forms) &&
          data.forms.some(
            (item) =>
              norm(item?.code) === "202" ||
              norm(item?.name) ===
                norm("الوظائف والمسميات الوظيفية")
          );

        if (alive) {
          setAuthorized(
            response.ok && (direct || hasForm)
          );
        }
      } catch {
        if (alive) setAuthorized(false);
      } finally {
        if (alive) setPermissionLoading(false);
      }
    })();

    return () => {
      alive = false;
    };
  }, [userGuid]);

  // ============================================================
  // Load departments
  // ============================================================
  const loadDepartments = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/job-titles/departments`,
        { cache: "no-store" }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message || "تعذر تحميل الأقسام"
        );
      }

      setDepartments(
        Array.isArray(result?.data)
          ? result.data
          : []
      );
    } catch {
      setDepartments([]);
    }
  }, []);

  // ============================================================
  // Main list
  // ============================================================
  const loadRows = useCallback(async () => {
    if (!authorized) return;

    setLoading(true);

    try {
      const params = new URLSearchParams();

      if (search.trim()) {
        params.set("search", search.trim());
      }

      if (statusFilter === "active") {
        params.set("isActive", "true");
      }

      if (statusFilter === "inactive") {
        params.set("isActive", "false");
      }

      const suffix = params.toString()
        ? `?${params.toString()}`
        : "";

      const response = await fetch(
        `${API_BASE_URL}/api/hr/job-titles${suffix}`,
        { cache: "no-store" }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر تحميل الوظائف والمسميات الوظيفية"
        );
      }

      setRows(
        Array.isArray(result?.data)
          ? result.data
          : []
      );
    } catch (e) {
      setRows([]);

      await Swal.fire({
        icon: "error",
        title: "تعذر التحميل",
        text:
          e?.message ||
          "تعذر تحميل الوظائف والمسميات الوظيفية"
      });
    } finally {
      setLoading(false);
    }
  }, [authorized, search, statusFilter]);

  useEffect(() => {
    if (!authorized) return;

    const timer = setTimeout(() => {
      loadRows();
    }, search.trim() ? 300 : 0);

    return () => clearTimeout(timer);
  }, [authorized, search, statusFilter, loadRows]);

  useEffect(() => {
    if (!authorized) return;
    loadDepartments();
  }, [authorized, loadDepartments]);

  // ============================================================
  // Statistics
  // ============================================================
  // Legacy index 12 محفوظ للتوافق مع النظام القديم فقط،
  // ولا يظهر في شاشة الموارد البشرية.
  const visibleRows = useMemo(
    () =>
      rows.filter(
        (item) => Number(item?.legacyJobCode) !== 12
      ),
    [rows]
  );

  const stats = useMemo(() => {
    const total = visibleRows.length;

    const active = visibleRows.filter(
      (item) => item.isActive
    ).length;

    const inactive = visibleRows.filter(
      (item) => !item.isActive
    ).length;

    const employees = visibleRows.reduce(
      (sum, item) =>
        sum + Number(item.employeeCount || 0),
      0
    );

    return {
      total,
      active,
      inactive,
      employees
    };
  }, [visibleRows]);

  // ============================================================
  // Create / Edit
  // ============================================================
  const openCreate = useCallback(() => {
    setEditMode("create");
    setForm(emptyForm());
    setEditOpen(true);
  }, []);

  const openEdit = useCallback((row) => {
    setEditMode("edit");
    setForm(normalizeJobTitle(row));
    setEditOpen(true);
  }, []);

  const closeEdit = useCallback(() => {
    if (saving) return;
    setEditOpen(false);
  }, [saving]);

  const setFormField = useCallback((field, value) => {
    setForm((current) => ({
      ...current,
      [field]: value
    }));
  }, []);

  const save = useCallback(async () => {
    const name = String(
      form.jobTitleName || ""
    ).trim();

    if (!name) {
      await Swal.fire({
        icon: "warning",
        title: "راجع البيانات",
        text: "اسم المسمى الوظيفي مطلوب"
      });
      return;
    }

    let reason = "";

    if (editMode === "edit") {
      const result = await Swal.fire({
        title: "سبب التعديل",
        input: "textarea",
        inputPlaceholder:
          "اكتب سبب تعديل المسمى الوظيفي...",
        inputAttributes: {
          dir: "rtl",
          rows: "5"
        },
        showCancelButton: true,
        confirmButtonText: "حفظ التعديل",
        cancelButtonText: "رجوع",
        focusConfirm: false,
        didOpen: () => {
          const input = Swal.getInput();
          if (input) {
            input.style.direction = "rtl";
            input.style.textAlign = "right";
            input.style.position = "relative";
            input.style.zIndex = "1";
            setTimeout(() => input.focus(), 0);
          }
        },
        inputValidator: (value) =>
          !String(value || "").trim()
            ? "سبب التعديل مطلوب"
            : undefined
      });

      if (!result.isConfirmed) return;

      reason = String(
        result.value || ""
      ).trim();
    }

    const payload = {
      jobTitleName: name,
      departmentGuid:
        form.departmentGuid &&
        form.departmentGuid !== ZERO_GUID
          ? form.departmentGuid
          : null,
      jobLevel:
        form.jobLevel === "" ||
        form.jobLevel === null ||
        form.jobLevel === undefined
          ? null
          : Number(form.jobLevel),
      description:
        String(form.description || "").trim() ||
        null,
      responsibilities:
        String(
          form.responsibilities || ""
        ).trim() || null,
      requirements:
        String(form.requirements || "").trim() ||
        null,
      isManager: Boolean(form.isManager),
      showInUserSelection:
        Number(form.legacyJobCode) === 12
          ? false
          : Boolean(form.showInUserSelection),
      actorUserGuid: userGuid || null
    };

    if (editMode === "edit") {
      payload.isActive = Boolean(form.isActive);

      /*
       * Legacy 12 is always hidden.
       * Non-legacy titles cannot be exposed to UserJop until a safe
       * migration gives them a supported legacy index.
       */
      payload.showInUserSelection =
        Number(form.legacyJobCode) === 12
          ? false
          : Boolean(form.showInUserSelection);

      payload.reason = reason;
    }

    setSaving(true);

    try {
      const url =
        editMode === "edit"
          ? `${API_BASE_URL}/api/hr/job-titles/${encodeURIComponent(
              form.jobTitleGuid
            )}`
          : `${API_BASE_URL}/api/hr/job-titles`;

      const response = await fetch(url, {
        method:
          editMode === "edit" ? "PUT" : "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(payload)
      });

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر حفظ المسمى الوظيفي"
        );
      }

      setEditOpen(false);

      await Swal.fire({
        icon: "success",
        title:
          editMode === "edit"
            ? "تم تعديل المسمى"
            : "تم إنشاء المسمى",
        text:
          editMode === "edit"
            ? "تم حفظ التعديلات بنجاح"
            : "تم إنشاء المسمى الوظيفي بنجاح"
      });

      await loadRows();
    } catch (e) {
      await Swal.fire({
        icon: "error",
        title: "تعذر الحفظ",
        text:
          e?.message ||
          "تعذر حفظ المسمى الوظيفي"
      });
    } finally {
      setSaving(false);
    }
  }, [
    form,
    editMode,
    userGuid,
    loadRows
  ]);

  // ============================================================
  // Employees
  // ============================================================
  const openEmployees = useCallback((row) => {
    setEmployeesTitle(row);
    setEmployeeSearch("");
    setEmployeePage(1);
    setEmployeePageSize(20);
    setEmployeeTotal(0);
    setEmployees([]);
    setEmployeesOpen(true);
  }, []);

  const loadEmployees = useCallback(async () => {
    if (
      !employeesOpen ||
      !employeesTitle?.jobTitleGuid
    ) {
      return;
    }

    setEmployeeLoading(true);

    try {
      const params = new URLSearchParams({
        page: String(employeePage),
        pageSize: String(employeePageSize)
      });

      if (employeeSearch.trim()) {
        params.set(
          "search",
          employeeSearch.trim()
        );
      }

      const response = await fetch(
        `${API_BASE_URL}/api/hr/job-titles/${encodeURIComponent(
          employeesTitle.jobTitleGuid
        )}/employees?${params.toString()}`,
        { cache: "no-store" }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر تحميل الموظفين"
        );
      }

      setEmployees(
        Array.isArray(result?.data)
          ? result.data
          : []
      );

      setEmployeeTotal(
        Number(result?.totalCount || 0)
      );
    } catch (e) {
      setEmployees([]);
      setEmployeeTotal(0);

      await Swal.fire({
        icon: "error",
        title: "تعذر تحميل الموظفين",
        text:
          e?.message ||
          "حدث خطأ أثناء تحميل الموظفين"
      });
    } finally {
      setEmployeeLoading(false);
    }
  }, [
    employeesOpen,
    employeesTitle,
    employeeSearch,
    employeePage,
    employeePageSize
  ]);

  useEffect(() => {
    if (!employeesOpen) return;

    const timer = setTimeout(() => {
      loadEmployees();
    }, employeeSearch.trim() ? 350 : 0);

    return () => clearTimeout(timer);
  }, [
    employeesOpen,
    employeeSearch,
    employeePage,
    employeePageSize,
    loadEmployees
  ]);

  const employeePageCount =
    employeeTotal > 0
      ? Math.ceil(
          employeeTotal / employeePageSize
