          item?.isActive === true &&
          item?.showInUserSelection === true &&
          item?.legacyJobCode !== null &&
          item?.legacyJobCode !== undefined &&
          Number(item?.legacyJobCode) !== 12 &&
          Number(item?.legacyJobCode) !==
