      setJobMoveReason("");
      setJobMoveNotes("");
      setJobMoveOpen(true);
    },
    []
  );

  const saveJobMove = useCallback(async () => {
    if (!jobMoveEmployee?.employeeGuid) {
      await Swal.fire({
        icon: "warning",
        title: "راجع البيانات",
        text: "تعذر تحديد الموظف"
      });
      return;
    }

    if (!jobMoveTargetGuid) {
      await Swal.fire({
        icon: "warning",
        title: "راجع البيانات",
        text: "اختر المسمى الوظيفي المستهدف"
      });
      return;
    }

    if (!jobMoveReason.trim()) {
      await Swal.fire({
        icon: "warning",
        title: "راجع البيانات",
        text:
          jobMoveMode === "plan"
            ? "سبب خطة الترقية مطلوب"
            : "سبب النقل أو الترقية مطلوب"
      });
      return;
    }

    setJobMoveSaving(true);

    try {
      const isPlan = jobMoveMode === "plan";

      const response = await fetch(
        isPlan
          ? `${API_BASE_URL}/api/hr/job-titles/promotion-plans`
          : `${API_BASE_URL}/api/hr/job-titles/change-employee-job`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify(
            isPlan
              ? {
                  employeeGuid:
                    jobMoveEmployee.employeeGuid,
                  targetJobTitleGuid:
                    jobMoveTargetGuid,
                  plannedDate: jobMoveDate,
                  reason: jobMoveReason.trim(),
                  notes:
                    jobMoveNotes.trim() || null,
                  actorUserGuid:
                    userGuid || null
                }
              : {
                  employeeGuid:
                    jobMoveEmployee.employeeGuid,
                  targetJobTitleGuid:
                    jobMoveTargetGuid,
                  movementType:
                    jobMoveMode === "promotion"
                      ? "Promotion"
                      : "Transfer",
                  effectiveDate: jobMoveDate,
                  reason: jobMoveReason.trim(),
                  notes:
                    jobMoveNotes.trim() || null,
                  actorUserGuid:
                    userGuid || null
                }
          )
        }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر حفظ العملية"
        );
      }

      setJobMoveOpen(false);

      await Swal.fire({
        icon: "success",
        title:
          isPlan
            ? "تمت إضافة خطة الترقية"
            : jobMoveMode === "promotion"
              ? "تمت الترقية"
              : "تم النقل",
        text:
          result?.message || "تمت العملية بنجاح"
      });

      if (!isPlan) {
        const remainingAfterMove =
          Math.max(0, employeeTotal - 1);

        if (
          remainingAfterMove > 0 &&
          employees.length === 1 &&
          employeePage > 1
        ) {
          setEmployeePage((current) =>
            Math.max(1, current - 1)
          );
        } else {
          await loadEmployees();
        }

        await loadRows();
      }
    } catch (error) {
      await Swal.fire({
        icon: "error",
        title: "تعذر تنفيذ العملية",
        text:
          error?.message ||
          "حدث خطأ أثناء حفظ العملية"
      });
    } finally {
      setJobMoveSaving(false);
    }
  }, [
    jobMoveEmployee,
    jobMoveMode,
    jobMoveTargetGuid,
    jobMoveDate,
    jobMoveReason,
    jobMoveNotes,
    userGuid,
    employeeTotal,
    employees.length,
    employeePage,
    loadEmployees,
    loadRows
  ]);

  const loadPromotionPlans =
    useCallback(async () => {
      setPromotionPlansLoading(true);

      try {
        const params = new URLSearchParams();

        if (
          promotionPlansStatus &&
          promotionPlansStatus !== "all"
        ) {
          params.set(
            "status",
            promotionPlansStatus
          );
        }

        if (promotionPlansSearch.trim()) {
          params.set(
            "search",
            promotionPlansSearch.trim()
          );
        }

        const query = params.toString();

        const response = await fetch(
          `${API_BASE_URL}/api/hr/job-titles/promotion-plans${
            query ? `?${query}` : ""
          }`,
          { cache: "no-store" }
        );

        const result = await response
          .json()
          .catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
              "تعذر تحميل خطط الترقيات"
          );
        }

        setPromotionPlans(
          Array.isArray(result?.data)
            ? result.data
            : []
        );
      } catch (error) {
        setPromotionPlans([]);

        await Swal.fire({
          icon: "error",
          title: "تعذر التحميل",
          text:
            error?.message ||
            "تعذر تحميل خطط الترقيات"
        });
      } finally {
        setPromotionPlansLoading(false);
      }
    }, [
      promotionPlansStatus,
      promotionPlansSearch
    ]);

