          title: "تنفيذ الترقية الآن؟",
          html: `
            <div style="font-family:Cairo;text-align:right">
              <b>${plan?.employeeName || ""}</b><br/>
              ${plan?.fromJobTitleName || "غير محدد"}
              ←
              ${plan?.toJobTitleName || "غير محدد"}
            </div>
          `,
          showCancelButton: true,
          confirmButtonText: "تنفيذ الترقية",
          cancelButtonText: "إلغاء"
        });

        if (!confirm.isConfirmed) return;

        try {
          const response = await fetch(
            `${API_BASE_URL}/api/hr/job-titles/promotion-plans/${encodeURIComponent(
              plan.planGuid
            )}/execute`,
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                actorUserGuid:
                  userGuid || null
              })
            }
          );

          const result = await response
            .json()
            .catch(() => null);

          if (!response.ok) {
            throw new Error(
              result?.message ||
                "تعذر تنفيذ خطة الترقية"
            );
          }

          await Swal.fire({
            icon: "success",
            title: "تم التنفيذ",
            text:
              result?.message ||
              "تم تنفيذ خطة الترقية"
          });

          await Promise.all([
            loadPromotionPlans(),
            loadRows()
          ]);

          if (employeesOpen) {
            await loadEmployees();
          }
        } catch (error) {
          await Swal.fire({
            icon: "error",
            title: "تعذر التنفيذ",
            text:
              error?.message ||
              "حدث خطأ أثناء تنفيذ خطة الترقية"
          });
        }
      },
      [
        userGuid,
        loadPromotionPlans,
        loadRows,
        employeesOpen,
        loadEmployees
      ]
    );

  const cancelPromotionPlan =
    useCallback(
      async (plan) => {
        const result = await Swal.fire({
          title: "إلغاء خطة الترقية",
          input: "textarea",
          inputPlaceholder:
            "اكتب سبب إلغاء الخطة...",
          showCancelButton: true,
          confirmButtonText: "إلغاء الخطة",
          cancelButtonText: "رجوع",
          inputValidator: (value) =>
            !String(value || "").trim()
              ? "سبب الإلغاء مطلوب"
              : undefined
        });

        if (!result.isConfirmed) return;

        try {
          const response = await fetch(
            `${API_BASE_URL}/api/hr/job-titles/promotion-plans/${encodeURIComponent(
              plan.planGuid
            )}/cancel`,
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                cancelReason:
                  String(result.value).trim(),
                actorUserGuid:
                  userGuid || null
              })
            }
          );

          const data = await response
            .json()
            .catch(() => null);

          if (!response.ok) {
            throw new Error(
              data?.message ||
                "تعذر إلغاء خطة الترقية"
            );
          }

          await loadPromotionPlans();
        } catch (error) {
          await Swal.fire({
            icon: "error",
            title: "تعذر الإلغاء",
            text:
              error?.message ||
              "حدث خطأ أثناء إلغاء الخطة"
