      );
      form.append(
        "leaveTypeGuid",
        requestForm.leaveTypeGuid
      );
      form.append(
        "fromDate",
        requestForm.fromDate
      );
      form.append(
        "toDate",
        requestForm.toDate
      );
      form.append(
        "dayPart",
        String(requestForm.dayPart)
      );

      if (requestForm.reason.trim()) {
        form.append(
          "reason",
          requestForm.reason.trim()
        );
      }

      if (requestForm.attachment) {
        form.append(
          "attachment",
          requestForm.attachment
        );
      }

      if (actor.actorUserGuid) {
        form.append(
          "actorUserGuid",
          actor.actorUserGuid
        );
      }

      form.append(
        "actorName",
        actor.actorName
      );

      const response = await fetch(
        `${API_BASE_URL}/api/hr/leaves/request`,
        {
          method: "POST",
          body: form
        }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
          "تعذر إنشاء الطلب"
        );
      }

      setRequestOpen(false);
      setRequestForm(emptyRequest());
      setCalculation(null);
      setRequestPage(1);
      await loadRequests();

      await Swal.fire({
        icon: "success",
        title: "تم إرسال الطلب",
        text:
          `رقم الطلب: ${result?.data?.requestNumber ?? "-"} • الأيام: ${result?.data?.requestedDays ?? "-"}`
      });
    } catch (error) {
      await Swal.fire({
        icon: "error",
        title: "تعذر إرسال الطلب",
        text: error?.message || "حدث خطأ"
      });
    } finally {
      setRequestSaving(false);
