            ? "رفض طلب الإجازة"
            : "إلغاء طلب الإجازة",
        input: "textarea",
        inputPlaceholder:
          action === "reject"
            ? "اكتب سبب الرفض..."
            : "اكتب سبب الإلغاء...",
        showCancelButton: true,
        confirmButtonText:
          action === "reject"
            ? "رفض الطلب"
            : "إلغاء الطلب",
        cancelButtonText: "رجوع",
        inputValidator: (value) =>
          !String(value || "").trim()
            ? "السبب مطلوب"
            : undefined
      });

      if (!result.isConfirmed) return;
      notes = String(result.value).trim();
    } else {
      const result = await Swal.fire({
        icon: "question",
        title: "اعتماد الإجازة؟",
        text:
          `${row.employeeName} • ${row.leaveTypeName} • ${row.requestedDays} يوم`,
        input: "textarea",
