        showCancelButton: true,
        confirmButtonText: "اعتماد",
        cancelButtonText: "رجوع"
      });

      if (!result.isConfirmed) return;
      notes = String(result.value || "");
    }

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/leaves/${row.leaveRequestGuid}/${action}`,
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body: JSON.stringify({
            notes,
            ...getActor()
          })
        }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
          "تعذر تنفيذ العملية"
        );
      }

      await loadRequests();

      await Swal.fire({
        icon: "success",
        title: "تم",
        text: result?.message || "تمت العملية"
      });
    } catch (error) {
      await Swal.fire({
        icon: "error",
        title: "تعذر التنفيذ",
