const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  "https://api4.sstli.com";

const pad2 = (value) =>
  String(value).padStart(2, "0");

const toIsoDate = (date) =>
  `${date.getFullYear()}-${pad2(
    date.getMonth() + 1
  )}-${pad2(date.getDate())}`;

const getMonthStart = () => {
  const now = new Date();

  return toIsoDate(
    new Date(
      now.getFullYear(),
      now.getMonth(),
      1
    )
  );
};

const getToday = () =>
  toIsoDate(new Date());

const normalizeKey = (value) =>
  String(value ?? "")
    .trim()
    .toLowerCase();

const isGuidColumn = (field) => {
  const normalized =
    normalizeKey(field);

  return (
    normalized === "sellerguid" ||
    normalized === "userguid" ||
    normalized.endsWith("guid")
  );
};

const unwrapValue = (value) => {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  if (
    typeof value !== "object" ||
    value instanceof Date
  ) {
    return value;
  }

  const candidates = [
    value.value,
    value.Value,
    value.data,
    value.Data,
    value.amount,
    value.Amount,
    value.number,
    value.Number,
    value.decimal,
    value.Decimal,
    value.int32,
    value.Int32,
    value.int64,
    value.Int64,
    value.double,
    value.Double,
    value.single,
    value.Single,
    value.string,
    value.String
  ];

  for (const candidate of candidates) {
    if (
      candidate !== undefined &&
      candidate !== null &&
      candidate !== value
    ) {
      return unwrapValue(candidate);
    }
  }

  return "";
};

const displayValue = (value) => {
  const unwrapped =
    unwrapValue(value);

  if (
    unwrapped === null ||
    unwrapped === undefined
  ) {
    return "";
  }

  return String(unwrapped);
};

const numberValue = (value) => {
  const unwrapped =
    unwrapValue(value);

  if (
    unwrapped === null ||
    unwrapped === undefined ||
    unwrapped === ""
  ) {
    return null;
  }

  const result = Number(unwrapped);

  return Number.isFinite(result)
    ? result
    : null;
};

const isNumericValue = (value) =>
  numberValue(value) !== null;

const formatNumber = (value) => {
  const number =
    numberValue(value);

  if (number === null) {
    return displayValue(value);
  }

  return new Intl.NumberFormat(
    "en-US",
    {
      minimumFractionDigits:
        Number.isInteger(number)
          ? 0
          : 2,
      maximumFractionDigits: 2
    }
  ).format(number);
};

const showError = async (message) => {
  await Swal.fire({
    icon: "error",
    title: "حدث خطأ",
    text: message,
    confirmButtonText: "حسنًا",
    confirmButtonColor: "#ae1e21"
  });
};

