                  justifyContent: "space-between",
                  gap: 0.6,
                  fontFamily: "Cairo",
                  fontWeight: 950,
                  color: "#057546",
                  fontSize: isPhone
                    ? "0.78rem"
                    : "0.96rem"
                }}
              >
                <span>تفاصيل الموظف</span>

                <IconButton
                  onClick={closeDetails}
                  sx={{
                    width: isPhone ? 30 : 34,
                    height: isPhone ? 30 : 34,
                    color: "#ae1e21"
                  }}
                >
                  <CloseIcon
                    sx={{
                      fontSize: isPhone
                        ? 18
                        : 20
                    }}
                  />
                </IconButton>
              </DialogTitle>

              <DialogContent
                dividers
                sx={{
                  p: isPhone ? 0.8 : 1.1,
                  overflowY: "auto"
                }}
              >
                {detailsRow ? (
                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: isPhone
                        ? "repeat(2,minmax(0,1fr))"
                        : "repeat(3,minmax(0,1fr))",
                      gap: isPhone ? 0.45 : 0.65
                    }}
                  >
                    {visibleFields.map((field) => {
                      const rawValue =
                        detailsRow?.[field];

                      const numeric =
                        isNumericValue(rawValue);

                      return (
                        <Box
                          key={field}
                          sx={{
                            minWidth: 0,
                            p: isPhone
                              ? 0.55
                              : 0.72,
                            border:
                              "1px solid rgba(5,117,70,.14)",
                            borderRadius: 1.3,
                            backgroundColor:
                              "#fbfdfc"
                          }}
                        >
                          <Typography
                            sx={{
                              mb: 0.25,
                              fontFamily: "Cairo",
                              fontWeight: 900,
                              color: "#60756d",
                              fontSize: isPhone
                                ? "0.75rem"
                                : "0.75rem"
                            }}
                          >
                            {field}
                          </Typography>

                          <Typography
                            sx={{
                              fontFamily: "Cairo",
                              fontWeight: 800,
                              color: "#1f2d3d",
                              fontSize: isPhone
                                ? "0.75rem"
                                : "0.75rem",
                              wordBreak: "break-word"
                            }}
                          >
                            {numeric
                              ? formatNumber(rawValue)
                              : displayValue(rawValue) || "-"}
                          </Typography>
                        </Box>
                      );
                    })}
                  </Box>
                ) : null}
              </DialogContent>

              <DialogActions
                sx={uiLayout.withUiSx({
                  px: isPhone ? 1 : 1.5,
                  py: isPhone ? 0.7 : 1
                }, uiLayout.dialogActionsSx)}
              >
                <Button
                  variant="contained"
                  onClick={closeDetails}
                  sx={uiLayout.withUiSx({
                    backgroundColor: "#057546",
                    fontFamily: "Cairo",
                    fontWeight: 900,
                    fontSize: isPhone
                      ? "0.75rem"
                      : "0.75rem"
                  }, uiLayout.buttonSx)}
                >
                  إغلاق
                </Button>
              </DialogActions>
            </Dialog>
          </Box>
        </Paper>
      </PageContainer>
    </Box></NavigationShell>
    )
  );
};

export default MarketersReport;

