const VideoTile = ({ name, avatar, stream, isAudioOn, isVideoOn, isSelf = false }) => {
  const videoRef = useRef(null);

  // إعادة attach وتشغيل الفيديو عند تفعيل الكاميرا، وإيقاف العرض عند إطفائها
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;

    if (stream && isVideoOn) {
      if (v.srcObject !== stream) v.srcObject = stream;
      const playSafe = async () => {
        try {
          await v.play();
        } catch {
          // المتصفح ممكن يمنع بدون تفاعل، نطنّش
        }
      };
      playSafe();
    } else {
      try { v.pause(); } catch {}
    }
  }, [stream, isVideoOn]);

  return (
    <Card
      sx={{
        bgcolor: "#2d2d2d",
        borderRadius: 2,
        position: "relative",
        overflow: "hidden",
        border: "1px solid #404040",
        transition: "all 0.3s ease",
        "&:hover": { transform: "translateY(-2px)" },
      }}
    >
      <CardContent sx={{ p: 0, height: 260, position: "relative" }}>
        {stream && isVideoOn ? (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted={isSelf}
            style={{ width: "100%", height: "100%", objectFit: "cover", background: "#000" }}
          />
        ) : (
          <Box
            sx={{
              width: "100%",
              height: "100%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: "#2d2d2d",
            }}
          >
            <Avatar
              sx={{
                width: 80,
                height: 80,
                bgcolor: COLOR_SCHEME.primary,
                fontSize: "2rem",
              }}
            >
              {avatar}
            </Avatar>
          </Box>
        )}
        <Box
          sx={{
            position: "absolute",
            bottom: 0,
            left: 0,
            right: 0,
            bgcolor: "rgba(0,0,0,0.8)",
            px: 2,
            py: 1,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <Typography variant="body2" sx={{ color: "white", fontWeight: 600 }}>
            {name} {isSelf ? "(أنا)" : ""}
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            {!isAudioOn && (
              <MicOff sx={{ fontSize: 16, color: COLOR_SCHEME.error }} />
