  "https://api4.sstli.com";

const ATTACHMENTS_BASE_URL =
  "https://sstli.com/arc-api/images_view.php";

const ZERO_GUID =
  "00000000-0000-0000-0000-000000000000";

const TYPE_TABS = [
  { value: 0, label: "طلاب الدبلومات" },
  { value: 1, label: "الدورات التأهيلية" },
  { value: 2, label: "الدورات التطويرية" }
];

const unwrap = (value) => {
  if (value === null || value === undefined) return value;
  if (typeof value !== "object") return value;

  for (const key of [
    "value", "Value", "data", "Data",
    "string", "String", "number", "Number",
    "boolean", "Boolean"
  ]) {
    if (
      value[key] !== undefined &&
      value[key] !== null &&
      value[key] !== value
    ) {
      return unwrap(value[key]);
    }
  }

  return "";
};

const pick = (row, names, fallback = "") => {
  for (const name of names) {
    const key =
      Object.keys(row || {}).find(
        (item) =>
          item.toLowerCase() ===
          String(name).toLowerCase()
      );

    if (key) {
      const value = unwrap(row[key]);

      if (
        value !== undefined &&
        value !== null &&
        String(value).trim() !== ""
      ) {
        return value;
      }
    }
  }

  return fallback;
};

const toBoolean = (value) => {
  if (typeof value === "boolean") return value;

  return [
    "1", "true", "yes", "نعم"
  ].includes(
    String(unwrap(value) ?? "")
      .trim()
      .toLowerCase()
  );
};

const toGuid = (value) => {
  const text =
    String(unwrap(value) ?? "").trim();

  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    .test(text)
      ? text
      : ZERO_GUID;
};

const readJson = async (response) => {
  const text = await response.text();

  let result = {};

  try {
    result = text ? JSON.parse(text) : {};
  } catch {
    result = {};
  }

  if (!response.ok) {
    throw new Error(
      result?.details
        ? `${result?.message || "حدث خطأ"}: ${result.details}`
        : (
            result?.message ||
            text ||
            `HTTP ${response.status}`
          )
    );
  }

  return result;
};

const showError = async (message) => {
  await Swal.fire({
    icon: "error",
    title: "تنبيه",
    text: message,
    confirmButtonText: "حسنًا",
    confirmButtonColor: "#ae1e21"
  });
};

const shortStudentName = (value) => {
  const parts = String(value || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);

  if (parts.length <= 2) {
    return parts.join(" ");
  }

  return `${parts[0]} ${parts[parts.length - 1]}`;
};


const normalizeStudentRow = (item, index) => {
  const regType = Number(
    pick(item, ["RegType", "REGTYPE", "regType"], 0)
  );

  return {
    ...item,

    id: `${regType}-${String(
      pick(
        item,
        [
          "RegDocGuid",
          "REGDOCGUID",
          "Guid",
          "AccountGuid"
        ],
        index + 1
      )
    )}-${index}`,

    regType,

    regTypeName:
      pick(
        item,
        [
          "REGTYPENAME",
          "RegTypeName",
          "TYPESTUDENT",
          "TypeName"
        ],
        regType === 0
          ? "دبلوم"
          : regType === 1
            ? "دورة تأهيلية"
            : "دورة تطويرية"
      ),

    code:
      pick(
        item,
        ["Code", "RegDocCode", "CODE"]
      ),

    regDate:
      pick(
        item,
        [
          "RegDate",
          "RegisterDate",
          "DocDate",
          "Date_",
          "REGDATE"
        ]
      ),

    studentName:
      pick(
        item,
        [
          "StudentName",
          "Name",
          "FullName",
          "STUDENTNAME"
        ]
      ),

    studentNameEn:
      pick(
        item,
        [
          "StudentNameEn",
          "StudentNameEN",
          "NameEn",
          "EnglishName"
        ]
      ),

    studentTel:
      pick(
        item,
        [
          "StudentTel",
          "PhoneNumber",
          "Mobile",
          "Phone",
          "STUDENTTEL"
        ]
      ),

    nationalId:
      pick(
        item,
        [
          "NationalId",
          "NationalIdNumber",
          "IdentityNo",
          "NATIONALID"
        ]
      ),

    diplomName:
      pick(
        item,
        [
          "DiplomName",
          "DiplomaName",
          "CourseName",
          "DIPLOMNAME"
        ]
      ),

    batchOrDate:
      pick(
        item,
        [
          "BatchOrDate",
          "BatchName",
