          "BATCHORDATE"
        ]
      ),

    manFullName:
      pick(
        item,
        [
          "ManFullName",
          "SellerName",
          "RegisterBy",
          "CreatedByName",
          "MANFULLNAME"
        ]
      ),

    email:
      pick(
        item,
        ["Email", "StudentEmail", "EMAIL"]
      )
  };
};

