  );

  const isMediumScreen = useMediaQuery(
    theme.breakpoints.up("lg")
  );

  const [mobileSidebarOpen, setMobileSidebarOpen] =
    useState(false);

  useEffect(() => {
    if (isDesktop) {
      setMobileSidebarOpen(false);
    }
  }, [isDesktop]);

  const user = useMemo(() => {
    try {
      return JSON.parse(
        localStorage.getItem("user") || "{}"
      );
    } catch {
      return {};
    }
  }, []);

  const savedBranch = useMemo(() => {
    try {
      return JSON.parse(
        localStorage.getItem("user_branch") || "{}"
      );
    } catch {
      return {};
    }
  }, []);

  const userGuid =
    String(user?.guid || user?.Guid || "").trim();

  const defaultBranchGuid =
    String(
      user?.branchForWork ||
      user?.BranchForWork ||
      savedBranch?.guid ||
      savedBranch?.Guid ||
      ""
    ).trim();

  const [branches, setBranches] = useState([]);
  const [branchGuid, setBranchGuid] =
    useState(defaultBranchGuid);
  const [rows, setRows] = useState([]);
  const [typeTab, setTypeTab] = useState(0);
  const [loading, setLoading] = useState(false);
  const [acceptingId, setAcceptingId] = useState("");
  const [
    acceptingStudentName,
    setAcceptingStudentName
  ] = useState("");

  const loadRequestIdRef = useRef(0);

  const [anchorEl, setAnchorEl] = useState(null);
  const [menuRow, setMenuRow] = useState(null);
  const [statementOpen, setStatementOpen] = useState(false);
  const [statementStudent, setStatementStudent] = useState(null);

  const [
    registerDocumentOpen,
    setRegisterDocumentOpen
  ] = useState(false);

  const [
    registerDocumentRow,
    setRegisterDocumentRow
  ] = useState(null);

  const loadBranches = useCallback(async () => {
    try {
      const params =
        new URLSearchParams({ userGuid });

      const response = await fetch(
        `${API_BASE_URL}/api/new-students/branches?${params}`,
        { cache: "no-store" }
      );

      const result = await readJson(response);
      const items =
        Array.isArray(result?.data)
          ? result.data
          : [];

      setBranches(items);

      const currentBranchIsAllowed =
        items.some(
          (item) =>
            String(item?.guid || "") ===
            String(branchGuid || "")
        );

      if (
        items.length > 0 &&
        !currentBranchIsAllowed
      ) {
        setBranchGuid(
          String(items[0]?.guid || "")
        );
      }

      if (items.length === 0) {
        setBranchGuid("");
        setRows([]);
      }
    } catch (error) {
      await showError(
        error?.message || "تعذر تحميل الفروع"
      );
    }
  }, [userGuid, branchGuid]);

  const loadStudents = useCallback(async () => {
    const requestId =
      ++loadRequestIdRef.current;

    if (!branchGuid) {
      setRows([]);
      return;
    }

    try {
      setLoading(true);

      const params =
        new URLSearchParams({
          userGuid,
          branchGuid,
          _: String(Date.now())
        });

      const response = await fetch(
        `${API_BASE_URL}/api/new-students?${params}`,
        {
          cache: "no-store",
          headers: {
            "Cache-Control":
              "no-cache, no-store, must-revalidate",
            Pragma: "no-cache",
            Expires: "0"
          }
        }
      );

      const result = await readJson(response);

      /*
       * لو طلب قديم رجع بعد طلب أحدث، نتجاهله.
       * ده يمنع بيانات فرع/تاب قديم إنها تظهر فوق البيانات الحالية.
       */
      if (
        requestId !==
        loadRequestIdRef.current
      ) {
        return;
      }

      const items =
        Array.isArray(result?.data)
          ? result.data
          : [];

      setRows(
        items.map((item, index) =>
          normalizeStudentRow(item, index)
        )
