    const headers = [
      "نوع التسجيل",
      "كود",
      "التاريخ",
      "اسم الطالب",
      "الاسم بالإنجليزية",
      "رقم الجوال",
      "رقم الهوية",
      "الدبلوم/الدورة",
      "الدفعة",
      "مسئول التسجيل",
      "البريد الإلكتروني"
    ];

    const data = filteredRows.map((row) => [
      row.regTypeName,
      row.code,
      row.regDate,
      row.studentName,
      row.studentNameEn,
      row.studentTel,
      row.nationalId,
      row.diplomName,
      row.batchOrDate,
      row.manFullName,
      row.email
    ]);

    const csv =
      "\uFEFF" +
      [headers, ...data]
        .map((line) =>
          line
            .map((value) =>
              `"${String(value ?? "")
                .replaceAll('"', '""')}"`
            )
            .join(",")
        )
        .join("\r\n");

    const blob = new Blob(
      [csv],
      { type: "text/csv;charset=utf-8" }
    );

    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");

    anchor.href = url;
    anchor.download =
      `قائمة_الطلاب_الجدد_${new Date()
        .toISOString()
        .slice(0, 10)}.csv`;

    anchor.click();
    URL.revokeObjectURL(url);
  };

