            statusText: "لم يعد مسجلاً",
            statusUpdateNote: updateNote,
            statusUpdatedAt: new Date().toISOString(),
            statusUpdatedByGuid: userGuid
          };
        })
      );

      setSuccessMessage("تم تحديث الحالة بنجاح");
      closeConfirm();
    } catch (err) {
