const unwrap = (value) => {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  if (typeof value !== "object") {
    return value;
  }

  const keys = [
    "value",
    "Value",
    "data",
    "Data",
    "amount",
    "Amount",
    "number",
    "Number",
    "decimal",
    "Decimal",
    "int32",
    "Int32",
    "int64",
    "Int64",
    "string",
    "String"
  ];

  for (const key of keys) {
    if (
      value[key] !== null &&
      value[key] !== undefined &&
      value[key] !== value
    ) {
      return unwrap(value[key]);
    }
  }

  return "";
};

const pick = (
  row,
  names,
  fallback = ""
) => {
  for (const name of names) {
    const value = unwrap(row?.[name]);

    if (
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ""
    ) {
      return value;
    }
  }

  return fallback;
};

const toNumber = (value) => {
  const result = Number(
    unwrap(value)
  );

  return Number.isFinite(result)
    ? result
    : 0;
};

const money = (value) =>
