const readJson = async (response) => {
  const text =
    await response.text();

  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {
    json = null;
  }

  if (!response.ok) {
    const validationMessage =
      json?.errors
        ? Object.entries(
            json.errors
          )
            .flatMap(
              ([field, messages]) =>
                (Array.isArray(messages)
                  ? messages
                  : [messages]
                ).map(
                  (message) =>
                    `${field}: ${message}`
                )
            )
            .join("\n")
        : "";

    const message =
      validationMessage ||
      json?.details ||
      json?.message ||
      json?.title ||
      text
        ?.replace(/<[^>]*>/g, " ")
        ?.replace(/\s+/g, " ")
        ?.trim()
        ?.slice(0, 700);

    throw new Error(
      message ||
      `تعذر تنفيذ الطلب - HTTP ${response.status}`
    );
  }

  if (!json) {
    throw new Error(
      `الخادم لم يرجع JSON صحيحًا - HTTP ${response.status}`
    );
  }

  return json;
};

