        noOptionsText="لا توجد نتائج"
        renderOption={(props, option, state) => (
          <li {...props}>
            <Checkbox
              checked={state.selected}
              sx={{
                mr: 1,
                color: "#6f8b7d",
                "&.Mui-checked": {
                  color: "#057546"
                }
              }}
            />
            <Typography
              sx={{
                fontFamily: "Cairo",
                fontSize: "0.82rem",
                fontWeight: 700
              }}
            >
              {option}
            </Typography>
          </li>
        )}
        renderTags={(tagValue, getTagProps) =>
          tagValue.map((option, index) => (
            <Chip
              {...getTagProps({ index })}
              key={option}
              label={option}
              size="small"
              sx={{
                fontFamily: "Cairo",
                fontWeight: 700
              }}
            />
          ))
        }
        renderInput={(params) => (
          <TextField InputLabelProps={{ shrink: true }}
            {...params}
            size="small"
            placeholder="ابحث وحدد أكثر من قيمة"
            helperText={
              selected.length
                ? `تم اختيار ${selected.length} من ${options.length}`
                : `الكل ظاهر (${options.length})`
            }
            sx={uiLayout.withUiSx({
              "& .MuiInputBase-root": {
                fontFamily: "Cairo"
              },
              "& .MuiFormHelperText-root": {
                fontFamily: "Cairo",
                textAlign: "right"
              }
            }, uiLayout.formFieldSx)}
          />
        )}
      />
    </Paper>
  );
};

