      Number(totals.mDaily || 0),
      Number(totals.dDaily || 0),
      Number(totals.balance || 0),
      "",
      ""
    ];

    const worksheet = XLSX.utils.aoa_to_sheet([
      headers,
      ...dataRows,
      totalsRow
    ]);

    // تحديد عرض الأعمدة
    worksheet["!cols"] = [
      { wch: 16 }, // نوع التسجيل
      { wch: 34 }, // الدبلوم
      { wch: 18 }, // الدفعة
      { wch: 30 }, // الطالب
      { wch: 16 }, // الجوال
