          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userGuid })
        }
      );

      const result = await response.json().catch(() => null);

      Swal.close();

      if (!response.ok) {
        if (
          response.status === 409 &&
          (result?.busy || result?.code === "ACCOUNTING_BUSY")
