          await fireSweetAlert({
            icon: "info",
            title: "جاري تنفيذ قيد آخر",
            html: `
              <div style="direction:rtl;line-height:1.9;text-align:center">
                ${result?.message || "يوجد ترحيل محاسبي آخر يتم تنفيذه حاليًا."}
                <br/>
                <small style="color:#666">
