     */
    setMenuAnchor(null);
    setMenuRow(null);

    // نسمح لـ MUI Menu/Popover أن يعمل unmount كامل.
    await new Promise((resolve) => setTimeout(resolve, 250));

    if (Number(row?.status) !== 0) {
      await fireSweetAlert({
        icon: "warning",
        title: "لا يمكن تغيير الحالة",
