    width: `${value}%`,
    backgroundColor: value >= 80 ? colorPalette.success :
                   value >= 60 ? colorPalette.warning :
                   colorPalette.error,
    transition: 'width 0.5s ease',
    borderRadius: '4px'
  }
}));

