  const attendanceDistributionChartData = {
    labels: ['ممتاز (80%+)', 'جيد (60-79%)', 'ضعيف (<60%)', 'لم يحضر'],
    datasets: [
      {
        data: analytics ? [
          analytics.attendanceDistribution.excellent,
          analytics.attendanceDistribution.good,
