                    </StyledTableCell>
                    <StyledTableCell>
                      {student.firstAttendance ? format(parseISO(student.firstAttendance), 'yyyy/MM/dd') : '-'}
                    </StyledTableCell>
                    <StyledTableCell>
                      {student.lastAttendance ? format(parseISO(student.lastAttendance), 'yyyy/MM/dd') : '-'}
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        ) : (
          <Paper elevation={0} sx={{ 
            p: 6, 
            textAlign: 'center',
            border: `2px dashed ${colorPalette.primaryLight}`,
            borderRadius: '16px',
            backgroundColor: colorPalette.background
          }}>
            <GroupsIcon sx={{ fontSize: 80, mb: 2, color: colorPalette.primaryLight }} />
            <Typography variant="h5" sx={{ 
              fontFamily: '"Cairo", sans-serif', 
              color: colorPalette.textLight,
              fontWeight: 600,
              mb: 1
            }}>
              لا توجد بيانات للطلاب
            </Typography>
          </Paper>
        )}
      </DialogContent>

      <DialogActions sx={uiLayout.withUiSx({ p: 3 }, uiLayout.dialogActionsSx)}>
        <Button 
          onClick={onClose}
          variant="outlined"
          sx={uiLayout.withUiSx({
            fontFamily: '"Cairo", sans-serif',
            borderColor: colorPalette.primary,
            color: colorPalette.primary,
            borderRadius: '10px',
            px: 3
          }, uiLayout.buttonSx)}
        >
          إغلاق
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default AdminBranchesReports;

