  .tf-density-roomy .tf-section .one-line {
    margin: 10px 0;
    line-height: 2.2;
  }

  .english-exam.tf-density-roomy .tf-section .one-line {
    margin: 4px 0;
    line-height: 1.4;
  }
}

/* === التجاوب === */
@media (max-width: 1200px) {
  .control-area {
    grid-template-columns: 1fr;
  }

  .control-panel {
    position: static;
  }
}

@media (max-width: 768px) {
  .main-header {
    padding: 1rem;
  }

  .header-content {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }

  .control-area,
  .preview-area {
    padding: 0 1rem;
  }

  .filters-grid {
    grid-template-columns: 1fr;
  }

  .preview-header {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }

  .info-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .exam-paper {
    margin: 10px auto;
    padding: 2mm;
  }
}

@media (max-width: 480px) {
  .header-title h1 {
    font-size: 1.5rem;
  }

  .filters-container,
  .control-panel {
    padding: 1rem;
  }

  .actions-grid {
    grid-template-columns: 1fr;
  }

  .action-btn {
    padding: 0.875rem 1rem;
  }
}

/* === تحسينات إضافية للواجهة === */
.no-print {
  /* إبقاء العناصر غير المطبوعة مرئية على الشاشة */
}

.hint {
  color: var(--text-light);
  font-style: italic;
  text-align: center;
  padding: 1rem;
}

/* تحسين المظهر على الشاشة للانجليزي */
@media screen {
  .english-score-container {
    right: 15mm;
  }
}

/* === إخفاء العناصر غير الضرورية === */
.score-inline,
.english-score-container {
  display: none !important;
}

.nav, .nav-active {
  padding: 6px 10px;
  border: 1px solid #243a52;
  border-radius: 10px;
  text-decoration: none;
  color: #243a52;
  font-weight: 700;
}

.nav-active {
  background: #243a52;
  color: #fff;
}

/* تخطيط التطبيق مع Sidebar */
.app-layout {
  display: flex;
  min-height: 100vh;
  direction: rtl;
}

.main-content-with-sidebar {
  flex: 1;
  margin-right: 280px; /* نفس عرض الـ Sidebar */
  transition: margin-right 0.3s ease;
  min-height: 100vh;
  background-color: #f8f9fa;
}

/* إذا كان الـ Sidebar قابل للطي/التوسيع */
.sidebar-collapsed .main-content-with-sidebar {
  margin-right: 80px; /* أو أي عرض تريده للـ Sidebar المضغوط */
}

/* تحسينات للطباعة */
@media print {
  .app-layout {
    display: block;
  }
  
  .main-content-with-sidebar {
    margin-right: 0;
  }
}

/* تحسينات للاستجابة */
@media (max-width: 768px) {
  .main-content-with-sidebar {
    margin-right: 0;
    margin-top: 60px; /* إذا كان الـ Sidebar يصبح هيدر في الجوال */
  }
}

