const readJson = async (response) => {
  const text = await response.text();

  let result = {};
  try {
    result = text ? JSON.parse(text) : {};
  } catch {
    result = {};
  }

  if (!response.ok) {
    throw new Error(
      result?.message ||
      result?.details ||
      text ||
      `HTTP ${response.status}`
    );
  }

  return result;
};

