const exportPdfDirect = async () => {
  if (!form.documentGuid) {
    await showError("احفظ النموذج أولًا قبل التصدير");
    return;
  }

  const sourceNode = printRef.current;

  if (!sourceNode) {
    await showError("تعذر تجهيز نموذج الطباعة");
    return;
  }

  const popup = window.open(
    "",
    "_blank",
    "width=1050,height=1350"
  );

  if (!popup) {
    await showError(
      "تعذر فتح نافذة الطباعة. برجاء السماح بالنوافذ المنبثقة."
    );
    return;
  }

  try {
    /*
      نعمل Clone للنموذج، ثم ننقل الـ computed styles
      بدل الاعتماد على كلاسات MUI بعد الـ production build.
    */
    const clonedNode = sourceNode.cloneNode(true);

    const sourceElements = [
      sourceNode,
      ...sourceNode.querySelectorAll("*")
    ];

    const clonedElements = [
      clonedNode,
      ...clonedNode.querySelectorAll("*")
    ];

    sourceElements.forEach((sourceElement, index) => {
      const clonedElement = clonedElements[index];

      if (!clonedElement) {
        return;
      }

      const computedStyle =
        window.getComputedStyle(sourceElement);

      let inlineStyle = "";

      for (
        let styleIndex = 0;
        styleIndex < computedStyle.length;
        styleIndex += 1
      ) {
        const propertyName =
          computedStyle[styleIndex];

        const propertyValue =
          computedStyle.getPropertyValue(propertyName);

        const propertyPriority =
          computedStyle.getPropertyPriority(propertyName);

        inlineStyle += `${propertyName}:${propertyValue}${
          propertyPriority ? " !important" : ""
        };`;
      }

      clonedElement.setAttribute(
        "style",
        `${clonedElement.getAttribute("style") || ""};${inlineStyle}`
      );
    });

    /*
      نحول مسارات الصور إلى روابط كاملة.
      هذا يمنع أي اختلاف في تفسير /image.png داخل about:blank.
    */
    clonedNode
      .querySelectorAll("img")
      .forEach((image) => {
        const source = image.getAttribute("src");

        if (!source) {
          return;
        }

        try {
          image.src = new URL(
            source,
            window.location.origin
          ).href;
        } catch {
          // نترك المسار كما هو عند تعذر تحويله.
        }
      });

    /*
      تحويل روابط ملفات CSS إلى absolute URLs.
    */
    const externalStyles = Array.from(
      document.querySelectorAll(
        'link[rel="stylesheet"]'
      )
    )
      .map((link) => {
        const href = link.getAttribute("href");

        if (!href) {
          return "";
        }

        const absoluteHref = new URL(
          href,
          window.location.href
        ).href;

        return `<link rel="stylesheet" href="${absoluteHref}" />`;
      })
      .join("\n");

    const baseUrl =
      `${window.location.origin}/`;

    popup.document.open();

    popup.document.write(`
      <!doctype html>
      <html lang="ar" dir="rtl">
        <head>
          <meta charset="utf-8" />

          <base href="${baseUrl}" />

          <meta
            name="viewport"
            content="width=device-width, initial-scale=1"
          />

          <title>
            ${selected?.name || "نموذج جودة"}
            ${form.documentNo || ""}
          </title>

          ${externalStyles}

          <style>
            @page {
              size: A4 portrait;
              margin: 0;
            }

            html,
            body {
              width: 210mm !important;
              min-width: 210mm !important;
              max-width: 210mm !important;

              margin: 0 !important;
              padding: 0 !important;

              background: #ffffff !important;
              overflow: visible !important;

              font-family:
                Cairo,
                Tahoma,
                Arial,
                sans-serif !important;

              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }

            *,
            *::before,
            *::after {
              box-sizing: border-box !important;

              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }

            body {
              display: block !important;
            }

            .print-sheet,
            .print-page {
              width: 210mm !important;
              min-width: 210mm !important;
              max-width: 210mm !important;

              height: 297mm !important;
              min-height: 297mm !important;
              max-height: 297mm !important;

              margin: 0 !important;
              padding: 0 !important;

              overflow: hidden !important;
              box-shadow: none !important;

              page-break-inside: avoid !important;
              break-inside: avoid-page !important;
            }

            .print-document {
              width: 210mm !important;
              min-width: 210mm !important;
              max-width: 210mm !important;

              margin: 0 !important;
              padding: 0 !important;
            }

            .print-page {
              page-break-after: always !important;
              break-after: page !important;
            }

            .print-page:last-child {
              page-break-after: auto !important;
              break-after: auto !important;
            }

            img {
              print-color-adjust: exact !important;
              -webkit-print-color-adjust: exact !important;
            }

            @media print {
              html,
              body {
                width: 210mm !important;
                margin: 0 !important;
                padding: 0 !important;
              }
            }
          </style>
        </head>

        <body>
          ${clonedNode.outerHTML}

          <script>
            const waitForImages = async () => {
              const images = Array.from(
                document.images || []
              );

              await Promise.all(
                images.map((image) => {
                  if (
                    image.complete &&
                    image.naturalWidth > 0
                  ) {
                    return Promise.resolve();
                  }

                  return new Promise((resolve) => {
                    const finish = () => resolve();

                    image.addEventListener(
                      "load",
                      finish,
                      { once: true }
                    );

                    image.addEventListener(
                      "error",
                      finish,
                      { once: true }
                    );

                    setTimeout(finish, 5000);
                  });
                })
              );
            };

            window.addEventListener(
              "load",
              async () => {
                await waitForImages();

                if (document.fonts?.ready) {
                  try {
                    await document.fonts.ready;
                  } catch {}
                }

                setTimeout(() => {
                  window.focus();
                  window.print();
                }, 700);
              }
            );
          </script>
        </body>
      </html>
    `);

    popup.document.close();
  } catch (error) {
    popup.close();

    await showError(
      error?.message ||
      "حدث خطأ أثناء تجهيز نافذة الطباعة"
    );
  }
};


const exportPdfMobile = async () => {
  if (!form.documentGuid) {
    await showError("احفظ النموذج أولًا قبل التصدير");
    return;
  }

  const sourceNode = printRef.current;

  if (!sourceNode) {
    await showError("تعذر تجهيز نموذج PDF");
    return;
  }

  let exportHost = null;

  try {
    setExportingPdf(true);

    if (document.fonts?.ready) {
      try {
        await document.fonts.ready;
      } catch {}
    }

    exportHost = document.createElement("div");
    exportHost.setAttribute("data-quality-pdf-host", "true");

    Object.assign(exportHost.style, {
      position: "fixed",
      top: "0",
      left: "0",
      width: "210mm",
      background: "#fff",
      opacity: "1",
      pointerEvents: "none",
      zIndex: "-10000",
      overflow: "visible"
    });

    const clonedNode = sourceNode.cloneNode(true);

    clonedNode.style.opacity = "1";
    clonedNode.style.visibility = "visible";
    clonedNode.style.pointerEvents = "none";
    clonedNode.style.transform = "none";
    clonedNode.style.margin = "0";

    clonedNode
      .querySelectorAll("img")
      .forEach((image) => {
        const value = image.getAttribute("src");

        if (!value) return;

        try {
          image.src = new URL(
            value,
            window.location.origin
          ).href;
          image.crossOrigin = "anonymous";
        } catch {}
      });

    exportHost.appendChild(clonedNode);
    document.body.appendChild(exportHost);

    const images = Array.from(
      clonedNode.querySelectorAll("img")
    );

    await Promise.all(
      images.map(
        (image) =>
          new Promise((resolve) => {
            if (
              image.complete &&
              image.naturalWidth > 0
            ) {
              resolve();
              return;
            }

            const finish = () => resolve();

            image.addEventListener(
              "load",
              finish,
              { once: true }
            );

            image.addEventListener(
              "error",
              finish,
              { once: true }
            );

            window.setTimeout(finish, 5000);
          })
      )
    );

    const explicitPages = Array.from(
      clonedNode.querySelectorAll(".print-page")
    );

    const pages =
      explicitPages.length > 0
        ? explicitPages
        : [clonedNode];

    const pdf = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
      compress: true
    });

    for (
      let index = 0;
      index < pages.length;
      index += 1
    ) {
      const pageNode = pages[index];

      const canvas = await html2canvas(
        pageNode,
        {
          scale: isPhone ? 2 : 2.25,
          useCORS: true,
          allowTaint: false,
          backgroundColor: "#ffffff",
          logging: false,
          imageTimeout: 7000,
          width: pageNode.scrollWidth,
          height: pageNode.scrollHeight,
          windowWidth: Math.max(
            pageNode.scrollWidth,
            794
          ),
          windowHeight: Math.max(
            pageNode.scrollHeight,
            1123
          ),
          scrollX: 0,
          scrollY: 0
        }
      );

      const imageData =
        canvas.toDataURL(
          "image/jpeg",
          0.96
        );

      if (index > 0) {
        pdf.addPage("a4", "portrait");
      }

      pdf.addImage(
        imageData,
        "JPEG",
        0,
        0,
        210,
        297,
        undefined,
        "FAST"
      );
    }

    const safeName = String(
      selected?.name || "نموذج جودة"
    )
      .replace(/[\\/:*?"<>|]+/g, "-")
      .trim();

    const fileName =
      `${safeName}${
        form.documentNo
          ? `-${form.documentNo}`
          : ""
      }.pdf`;

    pdf.save(fileName);
  } catch (error) {
    await showError(
      error?.message ||
        "تعذر إنشاء ملف PDF مباشرة"
    );
  } finally {
    if (
      exportHost &&
      exportHost.parentNode
    ) {
      exportHost.parentNode.removeChild(
        exportHost
      );
    }

    setExportingPdf(false);
  }
};

