const formatExamHijriDate = (gregorianValue) => {
  if (!gregorianValue) return "";

  try {
    const [year, month, day] = String(gregorianValue)
      .split("-")
      .map(Number);

    if (!year || !month || !day) return "";

    const date = new Date(
      year,
      month - 1,
      day,
      12,
      0,
      0
    );

    const weekday = new Intl.DateTimeFormat(
      "ar-SA",
      {
        weekday: "long"
      }
    ).format(date);

    const hijriDate = new Intl.DateTimeFormat(
      "ar-SA-u-ca-islamic-umalqura",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
      }
    ).format(date);

    return `${weekday} ${hijriDate}`;
  } catch {
    return "";
  }
};

const formatExamTime = (timeValue) => {
  if (!timeValue) return "";

  try {
    const [hour, minute] = String(timeValue)
      .split(":")
      .map(Number);

    if (
      Number.isNaN(hour) ||
      Number.isNaN(minute)
    ) {
      return "";
    }

    const date = new Date(
      2000,
      0,
      1,
      hour,
      minute,
      0
    );

    return new Intl.DateTimeFormat(
      "ar-SA",
      {
        hour: "numeric",
        minute: "2-digit",
        hour12: true
      }
    ).format(date);
  } catch {
    return "";
  }
};

