    .filter(Boolean);

  const commit = (nextCourses) => {
    setForm((current) => ({
      ...current,
      courses: nextCourses.join("، "),
      documentGuid: "",
      documentNo: "",
      verificationUrl: ""
    }));
  };

  const addCourse = () => {
    const cleanValue = newCourse.trim();

    if (!cleanValue) return;

    commit([...courses, cleanValue]);
    setNewCourse("");
  };

  const removeCourse = (index) => {
    commit(
      courses.filter(
        (_, courseIndex) =>
          courseIndex !== index
      )
    );
  };

  return (
    <Paper
      variant="outlined"
      sx={uiLayout.withUiSx({
        p: 2,
        mb: 2,
        borderRadius: 3,

        "@media (max-width:1599px)": {
          p: 0.75,
          mb: 0.85,
          borderRadius: 2
        },

        "@media (max-width:599px)": {
          p: 0.55,
          mb: 0.65,
          borderRadius: 1.5
        }
      }, uiLayout.pageHeaderSx)}
    >
      <Typography
        sx={{
          fontFamily: "Cairo",
          color: "#057546",
          fontWeight: 900,
          mb: 1,

          "@media (max-width:1599px)": {
            mb: 0.55,
            fontSize: "0.75rem"
          },

          "@media (max-width:599px)": {
            mb: 0.4,
            fontSize: "0.75rem"
          }
        }}
      >
        المقررات
      </Typography>

      <Stack
        direction="row"
        spacing={{
          xs: 0.45,
          sm: 0.65,
          md: 1
        }}
        alignItems="center"
        sx={uiLayout.withUiSx({ mb: courses.length ? 0.6 : 0 }, uiLayout.filterBarSx)}
      >
        <TextField InputLabelProps={{ shrink: true }}
          fullWidth
          size="small"
          label="اسم المقرر"
          placeholder="اكتب المقرر"
          value={newCourse}
          onChange={(event) =>
            setNewCourse(event.target.value)
          }
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              addCourse();
            }
          }}
          sx={uiLayout.withUiSx(fieldSx, uiLayout.formFieldSx)}
        />

        <Button
          variant="contained"
          onClick={addCourse}
          startIcon={<AddCircleOutlineIcon />}
          sx={uiLayout.withUiSx({
            flexShrink: 0,
            minWidth: {
              xs: 72,
              sm: 86,
              md: 105
            },
            minHeight: {
              xs: 31,
              sm: 34
            },
            fontFamily: "Cairo",
            fontWeight: 900,
            background:
              "linear-gradient(135deg,#057546,#034d31)",
            fontSize: {
              xs: "0.75rem",
              sm: "0.75rem",
              md: "0.75rem"
            }
          }, uiLayout.buttonSx)}
        >
          إضافة
        </Button>
      </Stack>

      {courses.length > 0 && (
        <Box
          sx={{
            display: "flex",
            flexWrap: "wrap",
            gap: {
              xs: 0.4,
              sm: 0.55,
              md: 0.75
            }
          }}
        >
          {courses.map((course, index) => (
            <Box
              key={`${course}-${index}`}
              sx={{
                display: "inline-flex",
                alignItems: "center",
                gap: 0.25,
                border: "1px solid #cfe7dc",
                background: "#f4fbf7",
                borderRadius: 999,
                py: {
                  xs: 0.2,
                  sm: 0.3
                },
                pr: {
                  xs: 0.55,
                  sm: 0.7
                },
                pl: {
                  xs: 0.25,
                  sm: 0.35
                },
                maxWidth: "100%"
              }}
            >
              <Typography
                sx={{
                  fontFamily: "Cairo",
                  fontWeight: 800,
                  color: "#17372b",
                  fontSize: {
                    xs: "0.75rem",
                    sm: "0.75rem",
                    md: "0.75rem"
                  },
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  maxWidth: {
                    xs: 150,
                    sm: 220,
                    md: 320
                  }
                }}
              >
                {course}
              </Typography>

              <IconButton
                size="small"
                color="error"
                onClick={() =>
                  removeCourse(index)
                }
                sx={{
                  width: {
                    xs: 21,
                    sm: 24
                  },
                  height: {
                    xs: 21,
                    sm: 24
                  },
                  p: 0
                }}
              >
                <DeleteOutlineIcon
                  sx={{
                    fontSize: {
                      xs: 13,
                      sm: 15
                    }
                  }}
                />
              </IconButton>
            </Box>
          ))}
        </Box>
      )}
    </Paper>
  );
};

