          "& td": { borderBottom: "1px solid #e7efeb", p: 0.9, textAlign: "center", fontWeight: 800 }
        }}>
          <thead>
            <tr>
              <th>التاريخ</th>
              {type !== "cash" ? <th>نوع المستند</th> : null}
              <th>رقم المستند</th>
              <th>مدين</th>
              <th>دائن</th>
              <th>البيان</th>
              {type === "cash" ? <th>المرجع</th> : null}
              <th>{type === "cash" ? "البنك / الخزينة" : "مندوب البيع"}</th>
            </tr>
          </thead>
          <tbody>
            {(rows || []).length ? (rows || []).map((row) => (
              <tr key={row.id}>
