      }

      if (!selectedMonth) {
        await showError(
          "برجاء تحديد الشهر"
        );
        return;
      }

      setLoading(true);

      try {
        const [yearText, monthText] =
          selectedMonth.split("-");

        const params =
          new URLSearchParams({
            userGuid,
            year: yearText,
            month: monthText
          });

        const response = await fetch(
          `${API_BASE_URL}/api/rewards-list?${params.toString()}`,
          {
            headers: {
              Accept: "application/json"
            }
          }
        );

        const result =
          await response.json();

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر تحميل قائمة المكافآت"
          );
        }

        const normalizedRows =
          Array.isArray(result?.data)
            ? result.data.map((row) => {
                const normalized = {};

                Object.entries(
                  row || {}
                ).forEach(
                  ([key, value]) => {
                    normalized[key] =
                      unwrapValue(value);
                  }
                );

                return normalized;
              })
            : [];

        setRows(normalizedRows);
      } catch (error) {
        setRows([]);

        await showError(
          error?.message ||
          "حدث خطأ أثناء تحميل قائمة المكافآت"
        );
      } finally {
        setLoading(false);
      }
    },
    [
      userGuid,
      selectedMonth
    ]
  );

  useEffect(() => {
    loadData();
  }, [loadData]);

  const visibleFields = useMemo(() => {
    const fields = [];

    rows.forEach((row) => {
      Object.keys(row || {})
        .forEach((field) => {
          if (
            !fields.includes(field) &&
            !isGuidColumn(field)
          ) {
            fields.push(field);
          }
        });
    });

    const preferredOrder = [
      "FullName",
      "USERSTAUT",
      "Registration",
      "Collection",
      "Marriage",
      "Newborn",
      "Housing",
      "Transport",
      "Vacation",
      "Other",
      "OtherReward1",
      "OtherReward2",
      "OtherReward",
      "Total",
      "EmpIbn",
      "BrEName",
      "OtherAllowancesNote"
    ];

    return [
      ...preferredOrder.filter(
        (field) =>
          fields.includes(field)
      ),
      ...fields.filter(
        (field) =>
          !preferredOrder.includes(field)
      )
    ];
  }, [rows]);

  const columns = useMemo(
