const todayForInput = () => {
  const now = new Date();

  const year = now.getFullYear();
  const month =
    String(now.getMonth() + 1)
      .padStart(2, "0");

  const day =
    String(now.getDate())
      .padStart(2, "0");

  return `${year}-${month}-${day}`;
};

const formatDate = (value) => {
  if (!value) return "-";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return new Intl.DateTimeFormat(
    "en-GB-u-ca-gregory",
    {
      calendar: "gregory",
      day: "2-digit",
      month: "2-digit",
      year: "numeric"
    }
  ).format(date);
};

const money = (value) =>
  Number(value || 0).toLocaleString(
    "en-US",
    {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    }
  );

const safeText = (value) =>
  String(value ?? "").trim();

const uniqueOptions = (
  rows,
  valueField,
  labelField = valueField
) => {
  const map = new Map();

  rows.forEach((row) => {
    const value =
      safeText(row?.[valueField]);

    const label =
      safeText(row?.[labelField]);

    if (!value || !label) return;

    if (!map.has(value)) {
      map.set(value, {
        value,
        label
      });
    }
  });

  return Array.from(
    map.values()
  ).sort((a, b) =>
    a.label.localeCompare(
      b.label,
      "ar"
    )
  );
};

const escapeCsv = (value) =>
  `"${String(value ?? "")
    .replace(/"/g, '""')}"`;

const getInvoiceField = (
  invoice,
  ...keys
) => {
  for (const key of keys) {
    const match =
      Object.keys(invoice || {})
        .find(
          (existing) =>
            existing.toLowerCase() ===
            key.toLowerCase()
        );

    if (match) {
      return invoice[match];
    }
  }

  return "";
};

function CreditNoteDialog({
  open,
  onClose,
  row,
  details,
  userGuid
}) {
  const theme = useTheme();
  const isPhone =
    useMediaQuery(
      theme.breakpoints.down("sm")
    );

  const [reason, setReason] =
    useState("");

  const [items, setItems] =
    useState([]);

  const [saving, setSaving] =
    useState(false);

  useEffect(() => {
    if (!open) {
      setReason("");
      setItems([]);
      return;
    }

    const source =
      Array.isArray(details?.items)
        ? details.items
        : [];

    setItems(
      source.map((item) => ({
        ...item,
        quantity:
          Number(item?.quantity || 1),
        cost:
          Number(item?.cost || 0),
        taxRate:
          Number(item?.taxRate || 0),
        tax:
          Number(item?.tax || 0),
        subTotal:
          Number(item?.subTotal || 0)
      }))
    );
  }, [open, details]);

  const totals = useMemo(
    () =>
      items.reduce(
        (acc, item) => {
          acc.total +=
            Number(item?.quantity || 0) *
            Number(item?.cost || 0);

          acc.tax +=
            Number(item?.tax || 0);

          acc.subTotal +=
            Number(item?.subTotal || 0);

          return acc;
        },
        {
          total: 0,
          tax: 0,
          subTotal: 0
        }
      ),
    [items]
  );

  const updateItem = (
    index,
    field,
    rawValue
  ) => {
    setItems((previous) =>
      previous.map(
        (item, itemIndex) => {
          if (itemIndex !== index) {
            return item;
          }

          let next = {
            ...item,
            [field]:
              Math.abs(
                Number(rawValue || 0)
              )
          };

          let qty =
            Math.abs(
              Number(
                next.quantity || 0
              )
            );

          if (!qty) qty = 1;

          let cost =
            Math.abs(
              Number(
                next.cost || 0
              )
            );

          let taxRate =
            Math.abs(
              Number(
                next.taxRate || 0
              )
            );

          let tax =
            Math.abs(
              Number(
                next.tax || 0
              )
            );

          let subTotal =
            Math.abs(
              Number(
                next.subTotal || 0
              )
