          // تعديل الصافي مباشرة يعيد استخراج التكلفة والضريبة.
          if (field === "subTotal") {
            const divisor =
              1 + taxRate / 100;

            const beforeTax =
              divisor > 0
                ? subTotal / divisor
                : subTotal;

            tax =
              subTotal -
              beforeTax;

            cost =
              qty > 0
                ? beforeTax / qty
                : beforeTax;
          }

          next = {
            ...next,
            quantity:
              Number(qty.toFixed(2)),
            cost:
              Number(cost.toFixed(2)),
            taxRate:
              Number(taxRate.toFixed(2)),
            tax:
