          )
        );

      const typeSet =
        new Set(
          selectedTypes.map(
            (item) => item.value
          )
        );

      const userSet =
        new Set(
          selectedUsers.map(
            (item) => item.value
          )
        );

      return rows.filter((row) => {
        if (
          branchSet.size &&
          !branchSet.has(
            safeText(
              row.branchName
            )
          )
        ) {
          return false;
        }

        if (
          typeSet.size &&
          !typeSet.has(
            safeText(
              row.typeName
            )
          )
        ) {
          return false;
        }

        if (
          userSet.size &&
          !userSet.has(
            safeText(
              row.userName
            )
          )
        ) {
          return false;
        }

        if (!query) {
          return true;
        }

        const haystack =
          [
            row.code,
            row.studentName,
            row.studentTel,
            row.nationalId,
            row.notes,
            row.branchName,
            row.userName,
            row.typeName
          ]
            .join(" ")
            .toLowerCase();

        return haystack.includes(
          query
