/* تنسيقات المواد المشتركة */
.shared-courses-manager {
  margin: 20px 0;
  min-width: 0;
  text-align: start;
  overflow-wrap: anywhere;
}

.shared-courses-manager .card-title,
.shared-courses-manager .exam-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.shared-courses-manager .btn { min-height: 44px; white-space: normal; }

.shared-course-item {
  border: 1px solid #eaeaea;
  border-radius: 8px;
  padding: 15px;
  margin-bottom: 15px;
  background: white;
}

.course-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.course-header h4 {
  margin: 0;
