              field.key
            ] || [];

          if (values.length) {
            result[field.key] =
              new Set(values);
          }
        }
      );

      return result;
    }, [advancedFilters]);

  const clearAdvancedFilters =
    useCallback(() => {
      setAdvancedFilters(
        emptyFilters()
      );
    }, []);

  const openFilterPicker =
    useCallback(
      (field) => {
        setFilterPickerSearch("");
