        }

        let matches = true;

        for (
          let i = 0;
          i < activeKeys.length;
          i += 1
        ) {
          const key =
            activeKeys[i];

          if (
            !selectedSets[key]
              .has(
                item.filterValues[
                  key
                ]
              )
          ) {
            matches = false;
            break;
          }
        }

        if (matches) {
          result.push(
            item.row
          );
        }
      }

      return result;
    }, [
      rows,
