import FilterAltOutlinedIcon from "@mui/icons-material/FilterAltOutlined";
import ExpandMoreRoundedIcon from "@mui/icons-material/ExpandMoreRounded";
import ExpandLessRoundedIcon from "@mui/icons-material/ExpandLessRounded";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import PercentIcon from "@mui/icons-material/Percent";
import CloseIcon from "@mui/icons-material/Close";


import SalesInvoiceDialog from "../components/SalesInvoiceDialog";




const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  "https://api4.sstli.com";

const primaryColor = "#057546";
const primaryDark = "#034d31";
const accentColor = "#ae1e21";
const textColor = "#1f2d3d";
const mutedColor = "#6f8a81";
const borderColor = "#dfe9e4";

const localDate = () => {
  const d = new Date();
  const offset = d.getTimezoneOffset();

  return new Date(
    d.getTime() - offset * 60000
  )
    .toISOString()
    .slice(0, 10);
};

const currentUser = () => {
  try {
    return JSON.parse(
      localStorage.getItem("user") || "{}"
    );
  } catch {
    return {};
  }
};

const getUserGuid = (user) =>
  user?.userGuid ||
  user?.guid ||
  user?.Guid ||
  user?.USER_GUID ||
  "";

const num = (value) => {
  const n = Number(value || 0);
  return Number.isFinite(n) ? n : 0;
};

const money = (value) =>
  num(value).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });

const shortMoney = (value) =>
  num(value).toLocaleString("en-US", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2
  });

const dateOnly = (value) => {
  if (!value) return "";

  const text = String(value);

  if (/^\d{4}-\d{2}-\d{2}/.test(text)) {
    const [y, m, d] =
      text.slice(0, 10).split("-");

    return `${d}/${m}/${y}`;
  }

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return text;
  }

  return parsed.toLocaleDateString("en-GB");
};

const FILTER_FIELDS = [
  {
    key: "billDate",
    label: "تاريخ الفاتورة",
    formatter: dateOnly
  },
  {
    key: "code",
    label: "رقم الفاتورة"
  },
  {
    key: "docName",
    label: "نوع المستند"
  },
  {
    key: "studentName",
    label: "اسم الطالب"
  },
  {
    key: "nationalId",
    label: "رقم الهوية"
  },
  {
    key: "cost",
    label: "الصافي",
    formatter: shortMoney
  },
  {
    key: "tax",
    label: "الضريبة",
    formatter: shortMoney
  },
  {
    key: "subTotal",
    label: "الإجمالي",
    formatter: shortMoney
  },
  {
    key: "branchName",
    label: "الفرع"
  },
  {
    key: "diplomName",
    label: "الخدمة المقدمة"
  },
  {
    key: "times",
    label: "المدة"
  }
];

const emptyFilters = () =>
  FILTER_FIELDS.reduce(
    (result, field) => {
      result[field.key] = [];
      return result;
    },
    {}
  );

const filterText = (row, field) => {
  const value = row?.[field.key];

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return "";
  }

  return field.formatter
    ? String(field.formatter(value))
    : String(value).trim();
};

const csvCell = (value) =>
  `"${String(value ?? "")
    .replace(/"/g, '""')}"`;


export default function TaxSalesReport() {
  const theme = useTheme();

  const isDesktop =
    useMediaQuery(
      `(min-width:${DESKTOP_BREAKPOINT}px)`,
      { noSsr: true }
    );

  const isPhone =
    useMediaQuery(
      theme.breakpoints.down("sm")
    );

  const isTablet =
    useMediaQuery(
      "(min-width:600px) and (max-width:1599px)"
    );

  const user =
    useMemo(
      () => currentUser(),
      []
    );

  const userGuid =
    useMemo(
      () =>
        String(
          getUserGuid(user)
        ).trim(),
      [user]
    );

  const [
    mobileSidebarOpen,
    setMobileSidebarOpen
  ] = useState(false);

  const [
    permissionLoading,
    setPermissionLoading
  ] = useState(true);

  const [
    authorized,
    setAuthorized
  ] = useState(false);

  const [fromDate, setFromDate] =
    useState(localDate());

  const [toDate, setToDate] =
    useState(localDate());

  const [rows, setRows] =
    useState([]);

  const [loading, setLoading] =
    useState(false);

  const [error, setError] =
    useState("");

  const [search, setSearch] =
    useState("");

  const [
    advancedOpen,
    setAdvancedOpen
  ] = useState(false);

  const [
    advancedFilters,
    setAdvancedFilters
  ] = useState(emptyFilters);

  // فلتر خفيف: نافذة واحدة فقط بدل إنشاء آلاف MenuItem.
  const [
    filterPickerField,
    setFilterPickerField
  ] = useState(null);

  const [
    filterPickerSearch,
    setFilterPickerSearch
  ] = useState("");

  const [
    detailRow,
    setDetailRow
  ] = useState(null);

  const [
    detailOpen,
    setDetailOpen
  ] = useState(false);

  const [
    invoiceDialogOpen,
    setInvoiceDialogOpen
  ] = useState(false);

  const [
    selectedInvoice,
    setSelectedInvoice
  ] = useState(null);

  const openInvoiceDialog = (row) => {
    // مهم:
    // ShowTaxReport / ShowReTaxReport أصبحا يرجعان BillGuid الحقيقي.
    // نفس استراتيجية كشف الحساب: نمرر BillGuid إلى SalesInvoiceDialog
    // بدون تغيير طريقة تحميل فاتورة المبيعات.
    const billGuid =
      row?.billGuid ||
      row?.BillGuid ||
      "";

    if (!billGuid) {
      setError(
        "الفاتورة لا تحتوي على BillGuid. تأكد أن الـ Stored Procedure والـ API يرجعان BillGuid."
      );
      return;
    }

    setError("");

    setSelectedInvoice({
      ...row,
      billGuid
    });

    setInvoiceDialogOpen(true);
  };

  const requestRef =
    useRef(null);

  const requestIdRef =
    useRef(0);

  // =========================================================
  // Permission
  // =========================================================
  useEffect(() => {
    let alive = true;

    const run = async () => {
      if (!userGuid) {
        if (alive) {
          setAuthorized(false);
          setPermissionLoading(false);
        }
        return;
      }

      try {
        setPermissionLoading(true);

        const response = await fetch(
          `${API_BASE_URL}/api/user-permissions/${encodeURIComponent(userGuid)}`,
          {
            cache: "no-store",
            headers: {
              Accept: "application/json"
            }
          }
        );

        const result =
          await response
            .json()
            .catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر تحميل الصلاحيات"
          );
        }

        const reports =
          result?.data?.reports || {};

        if (alive) {
          setAuthorized(
            reports?.canView === true &&
            reports?.screens
              ?.taxSalesReport === true
          );
        }
      } catch {
        if (alive) {
          setAuthorized(false);
        }
      } finally {
        if (alive) {
          setPermissionLoading(false);
        }
      }
    };

    run();

    return () => {
      alive = false;
    };
  }, [userGuid]);

  // =========================================================
  // نفس LOADREGDOC بتاع الديسكتوب:
  // Request واحد فقط -> ShowTaxReport مرة واحدة فقط
  // =========================================================
  const loadReport =
    useCallback(async () => {
      if (!authorized || !userGuid) {
        return;
      }

      if (!fromDate || !toDate) {
        setError(
          "برجاء اختيار الفترة من وإلى"
        );
        return;
      }

      if (fromDate > toDate) {
        setError(
          "تاريخ البداية لا يمكن أن يكون بعد تاريخ النهاية"
        );
        return;
      }

      requestRef.current?.abort?.();

      const controller =
        new AbortController();

      requestRef.current =
        controller;

      const requestId =
        ++requestIdRef.current;

      try {
        setLoading(true);
        setError("");

        const params =
          new URLSearchParams({
            userGuid,
            fromDate,
            toDate
          });

        const response =
          await fetch(
            `${API_BASE_URL}/api/tax-sales-report?${params.toString()}`,
            {
              cache: "no-store",
              headers: {
                Accept: "application/json"
              },
              signal:
                controller.signal
            }
          );

        const result =
          await response
            .json()
            .catch(() => null);

        if (
          requestId !==
          requestIdRef.current
        ) {
          return;
        }

        if (!response.ok) {
          throw new Error(
            result?.message ||
            result?.error ||
            "تعذر تحميل تقرير الضرائب"
          );
        }

        setRows(
          Array.isArray(result?.data)
            ? result.data
            : []
        );
      } catch (e) {
        if (e?.name === "AbortError") {
          return;
        }

        if (
          requestId !==
          requestIdRef.current
        ) {
          return;
        }

        setRows([]);

        setError(
          e?.message ||
          "تعذر تحميل تقرير الضرائب"
        );
      } finally {
        if (
          requestId ===
          requestIdRef.current
        ) {
          setLoading(false);
        }
      }
    }, [
      authorized,
      userGuid,
      fromDate,
      toDate
    ]);

  useEffect(() => {
    return () => {
      requestRef.current?.abort?.();
    };
  }, []);

  // =========================================================
  // الفلاتر كلها Client-side بعد تحميل نفس الداتا مرة واحدة.
  // لا يوجد أي Request للسيرفر عند البحث داخل الفلاتر.
  //
  // تحسين الأداء:
  // 1) تجهيز النصوص مرة واحدة فقط عند تغيّر rows.
  // 2) إنشاء Sets للقيم مرة واحدة.
  // 3) نافذة فلتر واحدة فقط، وبحد أقصى 80 نتيجة ظاهرة.
  // 4) البحث العام يستخدم searchText الجاهز بدل إعادة formatting لكل صف.
  // =========================================================
  const preparedRows =
    useMemo(() => {
      return rows.map((row) => {
        const filterValues = {};

        FILTER_FIELDS.forEach(
          (field) => {
            filterValues[field.key] =
              filterText(
                row,
                field
              );
          }
        );

        return {
          row,
          filterValues,
          searchText: [
            row?.billDate,
            row?.code,
            row?.docName,
            row?.studentName,
            row?.nationalId,
            row?.cost,
            row?.tax,
            row?.subTotal,
            row?.branchName,
            row?.diplomName,
            row?.times
          ]
            .filter(
              (value) =>
                value !== null &&
                value !== undefined
            )
            .join(" ")
            .toLowerCase()
        };
      });
    }, [rows]);

  const filterOptions =
    useMemo(() => {
      const sets = {};

      FILTER_FIELDS.forEach(
        (field) => {
          sets[field.key] =
            new Set();
        }
      );

      for (
        const item
        of preparedRows
      ) {
        for (
          const field
          of FILTER_FIELDS
        ) {
          const value =
            item.filterValues[
              field.key
            ];

          if (value) {
            sets[field.key]
              .add(value);
          }
        }
      }

      const result = {};

      FILTER_FIELDS.forEach(
        (field) => {
          result[field.key] =
            Array.from(
              sets[field.key]
            ).sort(
              (a, b) =>
                String(a)
                  .localeCompare(
                    String(b),
                    "ar",
                    {
                      numeric: true
                    }
                  )
            );
        }
      );

      return result;
    }, [preparedRows]);

  const activeFilterCount =
    useMemo(
      () =>
        Object.values(
          advancedFilters
        ).filter(
          (value) =>
            Array.isArray(value) &&
            value.length > 0
        ).length,
      [advancedFilters]
    );

  const selectedSets =
    useMemo(() => {
      const result = {};

      FILTER_FIELDS.forEach(
        (field) => {
          const values =
            advancedFilters[
              field.key
            ] || [];

          if (values.length) {
            result[field.key] =
              new Set(values);
          }
        }
      );

      return result;
    }, [advancedFilters]);

  const clearAdvancedFilters =
    useCallback(() => {
      setAdvancedFilters(
        emptyFilters()
      );
    }, []);

  const openFilterPicker =
    useCallback(
      (field) => {
        setFilterPickerSearch("");
        setFilterPickerField(
          field
        );
      },
      []
    );

  const closeFilterPicker =
    useCallback(() => {
      setFilterPickerField(
        null
      );

      setFilterPickerSearch("");
    }, []);

  const toggleFilterValue =
    useCallback(
      (key, value) => {
        setAdvancedFilters(
          (current) => {
            const oldValues =
              current[key] || [];

            const exists =
              oldValues.includes(
                value
              );

            return {
              ...current,
              [key]: exists
                ? oldValues.filter(
                    (item) =>
                      item !== value
                  )
                : [
                    ...oldValues,
                    value
                  ]
            };
          }
        );
      },
      []
    );

  const pickerOptions =
    useMemo(() => {
      if (!filterPickerField) {
        return [];
      }

      const all =
        filterOptions[
          filterPickerField.key
        ] || [];

      const q =
        filterPickerSearch
          .trim()
          .toLowerCase();

      if (!q) {
        return all.slice(
          0,
          80
        );
      }

      const result = [];

      for (
        let i = 0;
        i < all.length;
        i += 1
      ) {
        const value =
          all[i];

        if (
          String(value)
            .toLowerCase()
            .includes(q)
        ) {
          result.push(value);

          if (
            result.length >= 80
          ) {
            break;
          }
        }
      }

      return result;
    }, [
