      if (
        !q &&
        activeKeys.length === 0
      ) {
        return rows;
      }

      const result = [];

      for (
        const item
        of preparedRows
      ) {
        if (
          q &&
          !item.searchText
            .includes(q)
        ) {
          continue;
        }

        let matches = true;

        for (
          let i = 0;
          i < activeKeys.length;
          i += 1
        ) {
          const key =
            activeKeys[i];

          if (
            !selectedSets[key]
              .has(
                item.filterValues[
                  key
                ]
              )
          ) {
            matches = false;
            break;
          }
        }

        if (matches) {
          result.push(
            item.row
          );
        }
      }

      return result;
    }, [
      rows,
      preparedRows,
      search,
      selectedSets
