        "رقم الهوية",
        "تسجيل منذ",
        "الدفعة",
        "مندوب البيع"
      ];

      const csvRows = [
        headers
          .map(escapeCsvValue)
          .join(","),

        ...filteredRows.map(
          (row) =>
            [
              row.regDocCode,
              formatGregorianDate(
