  const changeStatus =
    async (
      status,
      requireReason = false
    ) => {
      closeMenu();

      if (!menuRow?.requestGuid) {
        await showError(
          "رقم الطلب غير موجود"
        );
        return;
      }

      let reason = "";

      if (requireReason) {
        const result =
          await Swal.fire({
            icon: "warning",
            title: "سبب الإلغاء",
            input: "textarea",
            inputLabel:
              "اكتب سبب إلغاء الطلب",
            inputPlaceholder:
              "سبب الإلغاء...",
            showCancelButton: true,
            confirmButtonText:
              "تأكيد الإلغاء",
            cancelButtonText: "رجوع",
            confirmButtonColor:
              "#ae1e21",
            inputValidator: (
              value
            ) =>
              !value?.trim()
                ? "لازم تكتب سبب الإلغاء"
                : undefined
          });

        if (!result.isConfirmed) {
          return;
        }

        reason =
          String(
            result.value || ""
          ).trim();
      } else {
        const label =
          status === 1
            ? "تأكيد الطلب"
            : "إرجاع الطلب إلى معلق";

        const result =
          await Swal.fire({
            icon:
              status === 1
                ? "question"
                : "info",
            title: label,
            text:
              `الطالب: ${menuRow.studentName}`,
            showCancelButton: true,
            confirmButtonText:
              "تنفيذ",
            cancelButtonText:
              "إلغاء",
            confirmButtonColor:
              "#057546"
          });

        if (!result.isConfirmed) {
          return;
        }
      }

      try {
        const response = await fetch(
          `${API_BASE_URL}/api/transfer-requests/status`,
          {
            method: "POST",
            headers: {
              "Content-Type":
                "application/json"
            },
            body: JSON.stringify({
              userGuid,
              requestGuid:
                menuRow.requestGuid,
              requestType:
                menuRow.type,
              status,
              reason
            })
          }
        );

        const result =
          await readJson(response);

        await showSuccess(
          result?.message ||
          "تم تحديث حالة الطلب"
        );

        await loadData();
      } catch (error) {
        await showError(
          error?.message ||
          "تعذر تحديث حالة الطلب"
        );
      }
    };

  const exportCsv = () => {
    if (!filteredRows.length) {
      showError(
