      return;
    }

    const headers = [
      "تاريخ الطلب",
      "اسم الطالب",
      "رقم الهوية",
      "الفرع",
      activeTab === 0
        ? "الفرع الحالي"
        : "التخصص القديم",
      activeTab === 0
        ? "الفرع المطلوب"
        : "التخصص الجديد",
      "مقدم الطلب",
      "الحالة",
      "الرد",
      "منفذ الإجراء"
    ];

    const values =
      filteredRows.map((row) => [
        row.createdAt,
        row.studentName,
        row.nationalId,
        row.oldBranchName,
        row.oldValue,
        row.newValue,
        row.actorUserName,
        row.statusName,
        row.response,
        row.confirmedByName
      ]);

    const escape = (value) =>
      `"${String(value ?? "")
        .replace(/"/g, '""')}"`;

    const csv =
      "\uFEFF" +
      [headers, ...values]
        .map((row) =>
          row.map(escape).join(",")
        )
        .join("\n");

    const blob =
      new Blob([csv], {
        type:
          "text/csv;charset=utf-8;"
      });

    const url =
      URL.createObjectURL(blob);

    const anchor =
      document.createElement("a");

    anchor.href = url;
    anchor.download =
      activeTab === 0
        ? `طلبات-النقل-${today()}.csv`
        : `طلبات-تغيير-التخصص-${today()}.csv`;

    anchor.click();
    URL.revokeObjectURL(url);
  };

