  TableRow,
  TextField,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme
} from "@mui/material";

import AssessmentIcon from "@mui/icons-material/Assessment";
import CloseIcon from "@mui/icons-material/Close";
import ExpandLessIcon from "@mui/icons-material/ExpandLess";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import FileDownloadIcon from "@mui/icons-material/FileDownload";
import MenuRoundedIcon from "@mui/icons-material/MenuRounded";
import PictureAsPdfIcon from "@mui/icons-material/PictureAsPdf";
import RefreshIcon from "@mui/icons-material/Refresh";
import SearchIcon from "@mui/icons-material/Search";

import Swal from "sweetalert2";




const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL ||
  process.env.REACT_APP_API_URL ||
  "https://api4.sstli.com";




const primary = "#057546";
const primaryDark = "#034d31";
const soft = "#f7faf8";
const border = "#dce8e2";
const headerBg = "#e9f3ef";
const totalBg = "#f2f2f2";

const today = () => {
  const d = new Date();

  return [
    d.getFullYear(),
    String(d.getMonth() + 1).padStart(2, "0"),
    String(d.getDate()).padStart(2, "0")
  ].join("-");
};

const getUser = () => {
  try {
    return JSON.parse(
      localStorage.getItem("user") || "{}"
    );
  } catch {
    return {};
  }
};

const getUserGuid = (u) =>
  u?.guid ||
  u?.Guid ||
  u?.userGuid ||
  u?.UserGuid ||
  u?.USER_GUID ||
  u?.USER_GUID____ ||
  "";

const n = (v) => {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
};

const money = (v) =>
  n(v).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });

const keyOf = (v) =>
  String(v || "").toLowerCase();

function buildVisibleRows(
  roots,
  expanded,
  childrenMap
) {
  const out = [];

  const walk = (row, depth) => {
    const key = keyOf(row.guid);

    out.push({
      ...row,
      depth
    });

    if (!key || !expanded.has(key)) {
      return;
    }

    const children =
      childrenMap[key] || [];

    children.forEach((child) =>
      walk(child, depth + 1)
    );
  };

  roots.forEach((root) =>
    walk(root, 0)
  );

  return out;
}

export default function TrialBalance() {
  const theme = useTheme();

  const isMobile =
    useMediaQuery(
      theme.breakpoints.down("sm")
    );

  const isTablet =
    useMediaQuery(
      theme.breakpoints.between("sm", "lg")
    );

  const isDesktop =
    useMediaQuery(
      `(min-width:${DESKTOP_BREAKPOINT}px)`,
      { noSsr: true }
    );

  const user = useMemo(
    () => getUser(),
    []
  );

  const userGuid = useMemo(
    () =>
      String(
        getUserGuid(user)
      ).trim(),
    [user]
  );

  const [authorized,
    setAuthorized] =
    useState(false);

  const [permissionLoading,
    setPermissionLoading] =
    useState(true);

  const [mobileSidebarOpen,
    setMobileSidebarOpen] =
    useState(false);

  const [fromDate,
    setFromDate] =
    useState(today());

  const [toDate,
    setToDate] =
    useState(today());

  const [branchGuid,
    setBranchGuid] =
    useState("");

  const [branchName,
    setBranchName] =
    useState("");

  const [branchOpen,
    setBranchOpen] =
    useState(false);

  const [branchSearch,
    setBranchSearch] =
    useState("");

  const [branches,
    setBranches] =
    useState([]);

  const [branchesLoading,
    setBranchesLoading] =
    useState(false);

  const [loading,
    setLoading] =
    useState(false);

  const [loadedOnce,
    setLoadedOnce] =
    useState(false);

  const [error,
    setError] =
    useState("");

  /*
   * أهم تعديل للأداء:
   * roots = الحسابات الرئيسية فقط.
   * الأطفال لا يدخلون React state إلا عندما يفتح المستخدم حسابًا بعينه.
   */
  const [roots,
    setRoots] =
    useState([]);

  const [snapshotId,
    setSnapshotId] =
    useState("");

  const [totalRowCount,
    setTotalRowCount] =
    useState(0);

  const [childrenMap,
    setChildrenMap] =
    useState({});

  const [expanded,
    setExpanded] =
    useState(new Set());

  const [loadingChildren,
    setLoadingChildren] =
    useState(new Set());

  const [totals,
    setTotals] =
    useState({
      openingMaden: 0,
      openingDaen: 0,
      transMaden: 0,
      transDaen: 0,
      finalMaden: 0,
      finalDaen: 0
    });

  useEffect(() => {
    let alive = true;

    const norm = (v) =>
      String(v ?? "")
        .trim()
        .toLowerCase();

    (async () => {
      try {
        if (!userGuid) return;

        const res = await fetch(
          `${API_BASE_URL}/api/user-permissions/${encodeURIComponent(userGuid)}`,
          { cache: "no-store" }
        );

        const result =
          await res
            .json()
            .catch(() => null);

        const data =
          result?.data || {};

        const direct =
          data?.generalAccounts?.canView === true &&
          data?.generalAccounts?.screens?.trialBalance === true;

        const menu =
          Array.isArray(data?.menus) &&
          data.menus.some(
            (x) =>
              norm(x?.code) === "account" ||
              norm(x?.name) ===
                norm("الحسابات العامة")
          );

        const form =
          Array.isArray(data?.forms) &&
          data.forms.some(
            (x) =>
              norm(x?.code) === "20" ||
              norm(x?.name) ===
                norm("ميزان المراجعة") ||
              norm(x?.guid) ===
                "5f295004-6841-4a45-93d0-28dd2310ea65"
          );

        if (alive) {
          setAuthorized(
            res.ok &&
              (direct ||
                (menu && form))
          );
        }
      } catch {
        if (alive) {
          setAuthorized(false);
        }
      } finally {
        if (alive) {
          setPermissionLoading(false);
        }
      }
    })();

    return () => {
      alive = false;
    };
  }, [userGuid]);

  const visibleRows =
    useMemo(
      () =>
        buildVisibleRows(
          roots,
          expanded,
          childrenMap
        ),
      [
        roots,
        expanded,
        childrenMap
      ]
    );

  const loadData =
    useCallback(async () => {
      if (!userGuid) return;

      if (!fromDate || !toDate) {
        await Swal.fire({
          icon: "warning",
          title: "راجع الفترة",
          text:
            "حدد تاريخ البداية وتاريخ النهاية"
        });
        return;
      }

      if (fromDate > toDate) {
        await Swal.fire({
          icon: "warning",
          title: "راجع الفترة",
          text:
            "تاريخ البداية يجب ألا يكون بعد تاريخ النهاية"
        });
        return;
      }

      setLoading(true);
      setError("");

      /*
       * كل عرض جديد يبدأ مطوي بالكامل.
       */
      setExpanded(new Set());
      setChildrenMap({});
      setLoadingChildren(new Set());

      try {
        const p =
          new URLSearchParams({
            userGuid,
            fromDate,
            toDate
          });

        if (branchGuid) {
          p.set(
            "branchGuid",
            branchGuid
          );
        }

        const res =
          await fetch(
            `${API_BASE_URL}/api/trial-balance?${p}`,
            {
              method: "GET",
              cache: "no-store"
            }
          );

        const raw =
          await res.text();

        let result = null;

        if (raw) {
          try {
            result =
              JSON.parse(raw);
          } catch {
            result = null;
          }
        }

        if (!res.ok) {
          throw new Error(
            result?.message ||
              result?.error ||
              raw ||
              `تعذر تحميل ميزان المراجعة (HTTP ${res.status})`
          );
        }

        const data =
          result?.data || {};

        setRoots(
          Array.isArray(data?.rows)
            ? data.rows
            : []
        );

        setSnapshotId(
          String(
            data?.snapshotId || ""
          )
        );

        setTotalRowCount(
          n(data?.rowCount)
        );

        setTotals({
          openingMaden:
            n(
              data?.totals
                ?.openingMaden
            ),

          openingDaen:
            n(
              data?.totals
                ?.openingDaen
            ),

          transMaden:
            n(
              data?.totals
                ?.transMaden
            ),

          transDaen:
            n(
              data?.totals
                ?.transDaen
            ),

          finalMaden:
            n(
              data?.totals
                ?.finalMaden
            ),

          finalDaen:
            n(
              data?.totals
                ?.finalDaen
            )
        });

        setLoadedOnce(true);
      } catch (e) {
        setRoots([]);
        setSnapshotId("");
        setTotalRowCount(0);

        setError(
          e?.message ||
            "تعذر تحميل ميزان المراجعة"
        );

        setLoadedOnce(true);
      } finally {
        setLoading(false);
      }
    }, [
      userGuid,
      fromDate,
      toDate,
      branchGuid
    ]);

  const toggleRow =
    useCallback(async (row) => {
      const key =
        keyOf(row?.guid);

      if (!key ||
          !row?.hasChildren) {
        return;
      }

      if (expanded.has(key)) {
        setExpanded(
          (current) => {
            const next =
              new Set(current);

            next.delete(key);
            return next;
          }
        );

        return;
      }

      /*
       * لو الأطفال اتحملوا قبل كده:
       * افتح فورًا بدون API.
       */
      if (childrenMap[key]) {
        setExpanded(
          (current) => {
            const next =
              new Set(current);

            next.add(key);
            return next;
          }
        );

        return;
      }

      if (!snapshotId) {
        return;
      }

      setLoadingChildren(
        (current) => {
          const next =
            new Set(current);

          next.add(key);
          return next;
        }
      );

      try {
        const p =
          new URLSearchParams({
            userGuid,
            snapshotId,
            parentGuid:
              String(row.guid)
          });

        const res =
          await fetch(
            `${API_BASE_URL}/api/trial-balance/children?${p}`,
            {
              cache: "no-store"
            }
          );

        const result =
          await res
            .json()
            .catch(() => null);

        if (!res.ok) {
          throw new Error(
            result?.message ||
              "تعذر تحميل الحسابات الفرعية"
          );
        }

        const children =
          Array.isArray(
            result?.data
          )
            ? result.data
            : [];

        setChildrenMap(
          (current) => ({
            ...current,
            [key]: children
          })
        );

        setExpanded(
          (current) => {
            const next =
              new Set(current);

            next.add(key);
            return next;
          }
        );
      } catch (e) {
        await Swal.fire({
          icon: "error",
          title:
            "تعذر فتح الحساب",
          text:
            e?.message ||
            "حدث خطأ"
        });
      } finally {
        setLoadingChildren(
          (current) => {
            const next =
              new Set(current);

            next.delete(key);
            return next;
          }
        );
      }
    }, [
      expanded,
      childrenMap,
      snapshotId,
      userGuid
    ]);

