            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            )
          }}
          sx={uiLayout.withUiSx({
            mb: { xs: 0.7, sm: 1 },
            "& .MuiInputBase-root": {
              minHeight: { xs: 34, sm: 38 }
            },
            "& input": {
              fontSize: { xs: 12, sm: 13 }
            }
          }, uiLayout.formFieldSx)}
        />

        {loading ? (
          <Box sx={{ py: 5, textAlign: "center" }}>
            <CircularProgress />
          </Box>
        ) : error ? (
          <Alert severity="error">{error}</Alert>
        ) : (
          <Box
            sx={{
              display: "grid",
              gap: 0.7
            }}
          >
            {rows.map((row, index) => (
              <Paper
                key={row.guid || row.code || index}
                variant="outlined"
                onDoubleClick={() => onPick(row)}
                sx={{
                  px: { xs: 0.7, sm: 1 },
                  py: { xs: 0.5, sm: 0.7 },
                  cursor: "pointer",
                  borderColor: border,
                  "&:hover": {
                    bgcolor: "#eef8f3",
                    borderColor: primary
                  }
                }}
              >
                <Box
                  sx={{
                    display: "grid",
                    gridTemplateColumns: {
                      xs: "52px minmax(0,1fr) 58px",
                      sm: "70px minmax(0,1fr) 90px 60px"
                    },
                    alignItems: "center",
                    gap: { xs: 0.45, sm: 0.8 }
                  }}
                >
                  <Box>
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      sx={{ fontSize: { xs: 12, sm: 12 } }}
                    >
                      {columns[0]?.label || "الكود"}
                    </Typography>
                    <Typography
                      sx={{
                        fontWeight: 800,
                        fontSize: { xs: 12, sm: 13 }
                      }}
                    >
                      {row[columns[0]?.key] ?? "-"}
                    </Typography>
                  </Box>

                  <Box sx={{ minWidth: 0 }}>
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      sx={{ fontSize: { xs: 12, sm: 12 } }}
                    >
                      {columns[1]?.label || "الاسم"}
                    </Typography>
                    <Typography
                      noWrap
                      sx={{
                        fontWeight: 800,
                        fontSize: { xs: 12, sm: 13 }
                      }}
                    >
                      {row[columns[1]?.key] ?? "-"}
                    </Typography>
                  </Box>

                  <Box sx={{ display: { xs: "none", sm: "block" } }}>
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      sx={{ fontSize: 12 }}
                    >
                      {columns[2]?.label || "الحالة"}
                    </Typography>
                    <Typography sx={{ fontWeight: 800, fontSize: 13 }}>
                      {row[columns[2]?.key] ?? "-"}
                    </Typography>
                  </Box>

                  <Button
                    size="small"
                    onClick={() => onPick(row)}
                    sx={uiLayout.withUiSx({
                      minWidth: 0,
                      px: { xs: 0.4, sm: 0.7 },
                      fontSize: { xs: 12, sm: 12 }
                    }, uiLayout.buttonSx)}
                  >
                    اختيار
                  </Button>
                </Box>
              </Paper>
            ))}

            {!rows.length && (
              <Alert severity="info">
                لا توجد نتائج.
              </Alert>
            )}
          </Box>
        )}
      </DialogContent>

      <DialogActions sx={uiLayout.dialogActionsSx}>
        <Button sx={uiLayout.buttonSx} onClick={onClose}>إغلاق</Button>
      </DialogActions>
    </Dialog>
  );
}

export default function UserManagement() {
  const theme = useTheme();
  const isDesktop = useMediaQuery(
    `(min-width:${DESKTOP_BREAKPOINT}px)`,
    { noSsr: true }
  );
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const userGuid = useMemo(() => getUserGuid(), []);

  const [mobileSidebarOpen, setMobileSidebarOpen] =
    useState(false);

  const [permissionLoading, setPermissionLoading] =
    useState(true);
  const [authorized, setAuthorized] = useState(false);

  const [tab, setTab] = useState(0);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [model, setModel] = useState(emptyUser());

  const [menus, setMenus] = useState([]);
  const [forms, setForms] = useState([]);
  const [permissions, setPermissions] = useState([]);
  const [availableBranches, setAvailableBranches] = useState([]);
  const [selectedBranches, setSelectedBranches] = useState([]);

  const [jobTitles, setJobTitles] = useState([]);
  const [jobTitlesLoading, setJobTitlesLoading] = useState(false);

  const [lookup, setLookup] = useState({
    open: false,
    type: "",
    title: "",
    rows: [],
    loading: false,
    search: ""
  });

  const isEdit = Boolean(model.guid);

  const setField = useCallback((field, value) => {
    setModel((current) => ({
      ...current,
      [field]: value
    }));
  }, []);

  // ============================================================
  // Permission - one source: Form_Name + User_Premision
  // ============================================================
  useEffect(() => {
    let alive = true;

    (async () => {
      try {
        const token = String(localStorage.getItem("token") || "").trim();
        if (!token) {
          if (alive) setAuthorized(false);
          return;
        }

        const response = await fetch(
          `${API_BASE_URL}/api/screen-access/me?key=user-management`,
          {
            cache: "no-store",
            headers: { Authorization: `Bearer ${token}`, Accept: "application/json" }
          }
        );
        const result = await response.json().catch(() => null);
        if (alive) setAuthorized(response.ok && result?.allowed === true);
      } catch {
        if (alive) setAuthorized(false);
      } finally {
        if (alive) setPermissionLoading(false);
      }
    })();

    return () => { alive = false; };
  }, []);

  // ============================================================
  // Bootstrap: menus + forms + branches
  // ============================================================
  const loadBootstrap = useCallback(async () => {
    if (!authorized || !userGuid) return;

    setLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/user-management/bootstrap?userGuid=${encodeURIComponent(userGuid)}`,
        { cache: "no-store" }
      );

      const result = await response
        .json()
        .catch(() => null);

      if (!response.ok) {
        throw new Error(
          [
            result?.message,
            result?.error,
            result?.detail
          ]
            .filter(Boolean)
            .join(" — ") ||
          "تعذر تحميل إعدادات شاشة المستخدم"
        );
      }

      const data = result?.data || {};

      const loadedMenus =
        Array.isArray(data?.menus)
          ? data.menus
          : [];

      const loadedForms =
        Array.isArray(data?.forms)
          ? data.forms
          : [];

      const loadedBranches =
        Array.isArray(data?.branches)
          ? data.branches
          : [];

      setMenus(
        loadedMenus.map((item) => ({
          ...item,
          view: false
        }))
      );

      setForms(loadedForms);

      // مطابق للديسكتوب: FormGrid يبدأ فارغًا،
      // ولا نضيف الشاشة إلا عند اختيارها.
      setPermissions([]);

      setAvailableBranches(loadedBranches);
    } catch (e) {
      await Swal.fire({
        icon: "error",
        title: "تعذر التحميل",
        text:
          e?.message ||
          "تعذر تحميل إعدادات شاشة المستخدم"
      });
    } finally {
      setLoading(false);
    }
  }, [authorized, userGuid]);

  useEffect(() => {
    if (authorized) {
      loadBootstrap();
    }
  }, [authorized, loadBootstrap]);

  // ============================================================
  // HR Job Titles
  // UserJop remains the legacy code/index stored in User_Info.
  // Legacy code 12 is kept in DB but hidden for new selections.
  // ============================================================
  const loadJobTitles = useCallback(async () => {
    if (!authorized) return;

    setJobTitlesLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/hr/job-titles/lookups`,
        { cache: "no-store" }
      );

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "تعذر تحميل الوظائف والمسميات الوظيفية"
        );
      }

      const rows = Array.isArray(result?.data)
        ? result.data
        : [];

      setJobTitles(
        rows
          .filter(
            (job) =>
              job?.isActive === true &&
              Number.isInteger(Number(job?.legacyJobCode))
          )
          .sort(
            (a, b) =>
              Number(a.legacyJobCode) -
              Number(b.legacyJobCode)
          )
      );
    } catch (e) {
      console.error("Failed to load HR job titles:", e);
      setJobTitles([]);
    } finally {
      setJobTitlesLoading(false);
    }
  }, [authorized]);

  useEffect(() => {
    if (authorized) {
      loadJobTitles();
    }
  }, [authorized, loadJobTitles]);

  // ============================================================
  // New
  // ============================================================
  const newUser = useCallback(() => {
    setModel(emptyUser());
    setSelectedBranches([]);

    setMenus((current) =>
      current.map((item) => ({
        ...item,
        view: false
      }))
    );

    // مطابق CMDNew في الديسكتوب: FormGrid.Rows.Clear()
    setPermissions([]);

    setTab(0);
  }, [forms]);

  // ============================================================
  // Lookups
  // ============================================================
  const openLookup = useCallback((type, title) => {
    setLookup({
      open: true,
      type,
      title,
      rows: [],
      loading: true,
      error: "",
      search: ""
    });
  }, []);

  const closeLookup = useCallback(() => {
    setLookup((current) => ({
      ...current,
      open: false
    }));
  }, []);

  useEffect(() => {
    if (!lookup.open || !authorized) return;

    let cancelled = false;
    const timer = setTimeout(async () => {
      setLookup((current) => ({
        ...current,
        loading: true,
        error: ""
      }));

      try {
        const params =
          new URLSearchParams({
            userGuid,
            q: lookup.search || ""
          });

        let url = "";

        if (lookup.type === "users") {
          url = `${API_BASE_URL}/api/user-management/users?${params}`;
        } else if (lookup.type === "branchForWork") {
          url = `${API_BASE_URL}/api/user-management/branches?${params}`;
        } else if (lookup.type === "seller") {
          url = `${API_BASE_URL}/api/user-management/salesmen?${params}`;
        } else if (lookup.type === "trainer") {
          if (
            model.branchForWork &&
            model.branchForWork !== ZERO_GUID
          ) {
            params.set(
              "branchGuid",
              model.branchForWork
            );
          }

          url = `${API_BASE_URL}/api/user-management/trainers?${params}`;
        } else if (lookup.type === "department") {
          url = `${API_BASE_URL}/api/user-management/departments?${params}`;
        }

        if (!url) return;

        const response = await fetch(url, {
          cache: "no-store"
        });

        const result = await response
          .json()
          .catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر تحميل القائمة"
          );
        }

        if (cancelled) return;
        setLookup((current) => ({
          ...current,
          rows:
            Array.isArray(result) ? result : Array.isArray(result?.data)
              ? result.data
              : []
        }));
      } catch (e) {
        if (cancelled) return;
        setLookup((current) => ({
          ...current,
          rows: [],
          error: e?.message || "تعذر تحميل القائمة. يرجى المحاولة مرة أخرى."
        }));
      } finally {
        if (!cancelled) setLookup((current) => ({
          ...current,
          loading: false
        }));
      }
    }, 250);

    return () => { cancelled = true; clearTimeout(timer); };
  }, [
    lookup.open,
    lookup.type,
    lookup.search,
    authorized,
    userGuid,
    model.branchForWork
  ]);

  const loadUser = useCallback(
    async (code) => {
      closeLookup();
      setLoading(true);

      try {
        const response = await fetch(
          `${API_BASE_URL}/api/user-management/users/${encodeURIComponent(code)}?userGuid=${encodeURIComponent(userGuid)}`,
          { cache: "no-store" }
        );

        const result = await response
          .json()
          .catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.message ||
            "تعذر تحميل بيانات المستخدم"
          );
        }

        const data = result?.data || {};

        setModel({
          ...emptyUser(),
          ...(data?.user || {})
        });

        const userMenus =
          Array.isArray(data?.menus)
            ? data.menus
            : [];

        const menuMap =
          new Map(
            userMenus.map((item) => [
              norm(item.guid),
              Boolean(item.view)
            ])
          );

        setMenus((current) =>
          current.map((item) => ({
            ...item,
            view:
              menuMap.get(norm(item.guid)) ||
              false
          }))
        );

        const userPermissions =
          Array.isArray(data?.permissions)
            ? data.permissions
            : [];

        const permissionMap =
          new Map(
            userPermissions.map((item) => [
              norm(item.guid),
              item
            ])
          );

        setPermissions(
          userPermissions.map((p) => {
            const form =
              forms.find(
                (f) =>
                  norm(f.guid) === norm(p.guid)
              );

            return {
              name:
                p.name ||
                form?.name ||
                "",
              guid: p.guid,
              add: Boolean(p.add),
              edit: Boolean(p.edit),
              del: Boolean(p.del),
              print: Boolean(p.print),
              find: Boolean(p.find),
              view: Boolean(p.view)
            };
          })
        );

        setSelectedBranches(
          Array.isArray(data?.branches)
            ? data.branches
            : []
        );

        setTab(0);
      } catch (e) {
        await Swal.fire({
          icon: "error",
          title: "تعذر التحميل",
          text:
            e?.message ||
            "تعذر تحميل بيانات المستخدم"
        });
      } finally {
        setLoading(false);
      }
    },
    [closeLookup, forms, userGuid]
  );

  const pickLookup = useCallback(
    (row) => {
      if (lookup.type === "users") {
        loadUser(row.code);
        return;
      }

      if (lookup.type === "branchForWork") {
        setModel((current) => ({
          ...current,
          branchForWork: row.guid || ZERO_GUID,
          branchForWorkName: row.name || "",
          // تغيير الفرع يلغي المدرب لو كان تابعًا لفرع آخر
          trainerGuid: ZERO_GUID,
          trainerName: ""
        }));
      }

      if (lookup.type === "seller") {
        setModel((current) => ({
          ...current,
          sellerGuid: row.guid || ZERO_GUID,
          sellerName: row.name || ""
        }));
      }

      if (lookup.type === "trainer") {
        setModel((current) => ({
          ...current,
          trainerGuid: row.guid || ZERO_GUID,
          trainerName: row.name || ""
        }));
      }

      if (lookup.type === "department") {
        setModel((current) => ({
          ...current,
          departmentGuid:
            row.guid || ZERO_GUID,
          departmentName: row.name || ""
        }));
      }

      closeLookup();
    },
    [lookup.type, closeLookup, loadUser]
  );

  // ============================================================
  // Permissions editing
  // ============================================================
  const updatePermission = useCallback(
    (index, field, value) => {
      setPermissions((current) => {
        const next = current.slice();
        next[index] = {
          ...next[index],
          [field]: value
        };
        return next;
      });
    },
    []
  );

  const fullControl = useCallback(() => {
    setMenus((current) =>
      current.map((item) => ({
        ...item,
        view: true
      }))
    );

    setPermissions(
      forms.map((form) => ({
        name: form.name,
        guid: form.guid,
        add: true,
        edit: true,
        del: true,
        print: true,
        find: true,
        view: true
      }))
    );
  }, [forms]);

  const deleteAllPermissions = useCallback(() => {
    setMenus((current) =>
      current.map((item) => ({
        ...item,
        view: false
      }))
    );

    // مطابق CmdDelAll: FormGrid.Rows.Clear()
    setPermissions([]);
  }, []);

  const addFormToPermissions = useCallback(
    (form) => {
      setPermissions((current) => {
        const existing = current.find(
          (item) =>
            norm(item.guid) === norm(form.guid)
        );

        if (existing) return current;

        return [
          ...current,
          emptyPermission(form)
        ];
      });
    },
    []
  );

  // ============================================================
  // Branch assignment dual list
  // ============================================================
  const selectedBranchGuids =
    useMemo(
      () =>
        new Set(
          selectedBranches.map((b) =>
            norm(b.guid)
          )
        ),
      [selectedBranches]
    );

  const unselectedBranches =
    useMemo(
      () =>
        availableBranches.filter(
          (b) =>
            !selectedBranchGuids.has(
              norm(b.guid)
            )
        ),
      [
        availableBranches,
        selectedBranchGuids
      ]
    );

  const addAllowedBranch = useCallback((branch) => {
    setSelectedBranches((current) => {
      if (
        current.some(
          (item) =>
            norm(item.guid) ===
            norm(branch.guid)
        )
      ) {
        return current;
      }

      return [...current, branch];
    });
  }, []);

  const removeAllowedBranch = useCallback(
    (guid) => {
      setSelectedBranches((current) =>
        current.filter(
          (item) =>
            norm(item.guid) !== norm(guid)
        )
      );
    },
    []
  );

  // ============================================================
  // Save / Update
  // ============================================================
  const validate = useCallback(() => {
    if (!model.fullName.trim())
      return "برجاء إدخال اسم الموظف";

    if (!model.userName.trim())
      return "برجاء إدخال اسم المستخدم";

    if (!model.password.trim())
      return "برجاء إدخال كلمة المرور";

    // مطابق للديسكتوب: مندوب البيع مطلوب.
    if (
      !model.sellerGuid ||
      model.sellerGuid === ZERO_GUID
    ) {
      return "برجاء اختيار حساب مندوب البيع أولاً";
    }

    if (
      model.chkTrainer &&
      (
        !model.trainerGuid ||
        model.trainerGuid === ZERO_GUID
      )
    ) {
      return "المستخدم محدد كمدرب؛ برجاء اختيار المدرب";
    }

    return "";
  }, [model]);

  const save = useCallback(async () => {
    const validation = validate();

    if (validation) {
      await Swal.fire({
        icon: "warning",
        title: "راجع البيانات",
        text: validation
      });
      return;
    }

    let reason = "";

    if (isEdit) {
      const result = await Swal.fire({
        title: "سبب التعديل",
        input: "textarea",
        inputPlaceholder:
          "اكتب سبب تعديل بيانات المستخدم...",
        showCancelButton: true,
        confirmButtonText: "حفظ التعديل",
        cancelButtonText: "رجوع",
        inputValidator: (value) =>
          !String(value || "").trim()
            ? "سبب التعديل مطلوب"
            : undefined
      });

      if (!result.isConfirmed) return;
      reason = String(result.value || "").trim();
    }

    const payload = {
      actorUserGuid: userGuid,
      reason,
      user: {
        ...model,

        // الـ API يعرف Code و Guid كنصوص.
        // ShowUserInfo/قائمة المستخدمين قد يعيدان Code كرقم،
        // لذلك نحوله صراحةً قبل JSON.stringify حتى لا يفشل Model Binding.
        code: String(model.code ?? ""),
        guid: String(model.guid ?? ""),

        userJop:
          Number.isFinite(Number(model.userJop))
            ? Number(model.userJop)
            : -1
      },
      menus: menus.map((item) => ({
        guid: item.guid,
        view: Boolean(item.view)
      })),
      permissions: permissions.map((p) => ({
        guid: p.guid,
        add: Boolean(p.add),
        edit: Boolean(p.edit),
        del: Boolean(p.del),
        print: Boolean(p.print),
        find: Boolean(p.find),
        view: Boolean(p.view)
      })),
      branches: selectedBranches.map(
        (item) => item.guid
      )
    };

    setSaving(true);

    try {
      const response = await fetch(
        isEdit
          ? `${API_BASE_URL}/api/user-management/${encodeURIComponent(model.guid)}`
          : `${API_BASE_URL}/api/user-management`,
        {
          method: isEdit ? "PUT" : "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify(payload)
        }
      );

      const raw = await response.text();
      let result = null;

      try {
        result = raw ? JSON.parse(raw) : null;
      } catch {
        result = null;
      }

      if (!response.ok) {
        throw new Error(
          [
            result?.message,
            result?.error,
            result?.detail
          ]
            .filter(Boolean)
            .join(" — ") ||
          raw ||
          "تعذر حفظ المستخدم"
        );
      }

      const saved = result?.data || {};

      setModel((current) => ({
        ...current,
        guid: saved.guid || current.guid,
        code: saved.code || current.code
      }));

      await Swal.fire({
        icon: "success",
        title: isEdit
          ? "تم تعديل المستخدم"
          : "تم حفظ المستخدم",
        text:
          result?.message ||
          "تمت العملية بنجاح"
      });
    } catch (e) {
      await Swal.fire({
        icon: "error",
        title: "تعذر الحفظ",
        text:
          e?.message ||
          "تعذر حفظ بيانات المستخدم"
      });
    } finally {
      setSaving(false);
    }
  }, [
    validate,
    isEdit,
    userGuid,
    model,
    menus,
    permissions,
    selectedBranches
  ]);

  // ============================================================
  // Render states
  // ============================================================
  if (permissionLoading) {
    return (
      <Box
        sx={{
          height: "100vh",
          display: "grid",
          placeItems: "center"
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  if (!authorized) {
    return (
      <Box sx={{ p: 2 }}>
        <Alert severity="error">
          لا توجد لديك صلاحية إضافة مستخدم ضمن قائمة ملف.
        </Alert>
      </Box>
    );
  }

  const lookupColumns =
    lookup.type === "users"
      ? [
          { key: "code", label: "الكود" },
          { key: "name", label: "اسم المستخدم" },
          { key: "status", label: "الحالة" }
        ]
      : [
          { key: "code", label: "الكود" },
          { key: "name", label: "البيان" },
          { key: "status", label: "الحالة" }
        ];

  const content = (
    <PageContainer
      dir="rtl"
      sx={{
        minHeight: "100vh",
        width: "100%",
        maxWidth: "100vw",
        overflowX: "hidden",
        bgcolor: soft,

      }}
    >
